    @staticmethod
    def onchain_primary_scalar_gate_reasons(
        *, pool_age_seconds: float | None, queue_delay_seconds: float | None,
        total_delay_seconds: float | None, quoted_recovery_ratio: float | None,
        stress_recovery_ratio: float | None, open_positions: int,
        daily_exposure_usd: float, new_exposure_usd: float, exit_alert_pending: bool,
    ) -> list[str]:
        reasons: list[str] = []
        if pool_age_seconds is None:
            reasons.append("exact_pool_age_missing")
        elif pool_age_seconds < 0:
            reasons.append("exact_pool_age_future")
        elif pool_age_seconds > 600:
            reasons.append("exact_pool_age_over_600s")
        if queue_delay_seconds is None or queue_delay_seconds > 5.0:
            reasons.append("entry_queue_over_5s")
        if total_delay_seconds is None or total_delay_seconds > 10.0:
            reasons.append("final_preflight_over_10s")
        if quoted_recovery_ratio is None or stress_recovery_ratio is None:
            reasons.append("roundtrip_recovery_ratio_missing")
        elif quoted_recovery_ratio < 0.90 or stress_recovery_ratio < 0.85:
            reasons.append(
                "excessive_immediate_roundtrip_loss:"
                f"quoted={quoted_recovery_ratio:.6f}:stress={stress_recovery_ratio:.6f}"
            )
        if open_positions >= 5:
            reasons.append("primary_open_position_cap_5")
        if daily_exposure_usd + new_exposure_usd > 100.0:
            reasons.append("primary_daily_new_exposure_cap_100")
        if exit_alert_pending:
            reasons.append("primary_exit_alert_pending")
        return reasons

    def register_route_surface_observations(self) -> None:
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO market_surface_safety_registrations("
                "definition_version,registered_at,activation_snapshot_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM token_snapshots),0),?)",
                (
                    self.MARKET_SURFACE_SAFETY_VERSION, iso(),
                    self._json({
                        "chain": "solana", "holding_surface": "canonical_pumpswap",
                        "excludes": "router_availability", "no_historical_backfill": True,
                    }),
                ),
            )
            self.db.execute(
                "INSERT OR IGNORE INTO execution_route_observation_registrations("
                "definition_version,registered_at,activation_quote_result_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM onchain_only_jupiter_quote_results),0),?)",
                (
                    self.EXECUTION_ROUTE_OBSERVATION_VERSION, iso(),
                    self._json({
                        "router": "jupiter", "directions": ["BUY", "SELL"],
                        "does_not_imply_holding_surface": True, "no_historical_backfill": True,
                    }),
                ),
            )

    def record_market_surface_safety(
        self, *, lane: str, quote_key: str, token_id: str,
        trigger_snapshot_id: int, assessed_snapshot_id: int,
        assessment: Mapping[str, Any], observed_at: Any,
    ) -> int | None:
        status = str(assessment.get("status") or "WAIT").upper()
        if status not in {"PASS", "WAIT", "REJECT"}:
            raise ValueError("invalid market surface safety status")
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM market_surface_safety_registrations WHERE definition_version=?",
                (self.MARKET_SURFACE_SAFETY_VERSION,),
            ).fetchone()
            if registration is None or int(assessed_snapshot_id) <= int(registration["activation_snapshot_id"]):
                return None
            lineage = self.db.execute(
                "SELECT COUNT(*) FROM token_snapshots WHERE id IN (?,?) AND token_id=?",
                (int(trigger_snapshot_id), int(assessed_snapshot_id), str(token_id)),
            ).fetchone()[0]
            if int(lineage) != (1 if int(trigger_snapshot_id) == int(assessed_snapshot_id) else 2):
                raise ValueError("invalid market surface snapshot lineage")
            cursor = self.db.execute(
                "INSERT OR IGNORE INTO market_surface_safety_observations("
                "definition_version,lane,quote_key,token_id,trigger_snapshot_id,assessed_snapshot_id,"
                "status,reasons_json,facts_json,observed_at,recorded_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (
                    self.MARKET_SURFACE_SAFETY_VERSION, str(lane), str(quote_key), str(token_id),
                    int(trigger_snapshot_id), int(assessed_snapshot_id), status,
                    self._json(assessment.get("reasons") or []),
                    self._json(assessment.get("facts") or {}),
                    iso(parse_time(observed_at)), iso(),
                ),
            )
            return int(cursor.lastrowid) if cursor.rowcount == 1 else None

    def record_execution_route_observation(
        self, *, lane: str, quote_key: str, token_id: str, direction: str,
        classification: Mapping[str, Any], observed_at: Any,
    ) -> int | None:
        side = str(direction).upper()
        if side not in {"BUY", "SELL"}:
            raise ValueError("invalid execution route direction")
        verifiability = str(classification.get("route_verifiability") or "unsupported")
        relation = str(classification.get("surface_relation") or "opaque_router")
        status = (
            "PASS" if verifiability == "exact_onchain_legs" and relation in {"contains_surface", "multi_surface"}
            else "WAIT" if verifiability == "meta_aggregator_opaque" or relation in {"opaque_router", "multi_surface"}
            else "REJECT"
        )
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT 1 FROM execution_route_observation_registrations WHERE definition_version=?",
                (self.EXECUTION_ROUTE_OBSERVATION_VERSION,),
            ).fetchone()
            if registration is None:
                return None
            cursor = self.db.execute(
                "INSERT OR IGNORE INTO execution_route_observations("
                "definition_version,lane,quote_key,token_id,direction,status,classification_json,"
                "observed_at,recorded_at) VALUES(?,?,?,?,?,?,?,?,?)",
                (
                    self.EXECUTION_ROUTE_OBSERVATION_VERSION, str(lane), str(quote_key),
                    str(token_id), side, status, self._json(dict(classification)),
                    iso(parse_time(observed_at)), iso(),
                ),
            )
            return int(cursor.lastrowid) if cursor.rowcount == 1 else None

    def record_pretrade_rug_safety_assessment(
        self,
        *,
        lane: str,
        quote_key: str,
        token_id: str,
        trigger_snapshot_id: int,
        assessed_snapshot_id: int,
        assessment: Mapping[str, Any],
        observed_at: Any,
        assessed_at: Any = None,
    ) -> int | None:
        status = str(assessment.get("status") or "WAIT").upper()
        if status not in {"PASS", "WAIT", "REJECT"}:
            raise ValueError("invalid pretrade rug safety status")
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM pretrade_rug_safety_registrations WHERE definition_version=?",
                (self.PRETRADE_RUG_SAFETY_VERSION,),
            ).fetchone()
            if registration is None:
                return None
            trigger = self.db.execute(
                "SELECT token_id FROM token_snapshots WHERE id=?",
                (int(trigger_snapshot_id),),
            ).fetchone()
            assessed = self.db.execute(
                "SELECT token_id FROM token_snapshots WHERE id=?",
                (int(assessed_snapshot_id),),
            ).fetchone()
            if (
                trigger is None or assessed is None
                or str(trigger["token_id"]) != str(token_id)
                or str(assessed["token_id"]) != str(token_id)
                or int(assessed_snapshot_id) <= int(registration["activation_snapshot_id"])
            ):
                raise ValueError("invalid pretrade rug safety snapshot lineage")
            cursor = self.db.execute(
                """
                INSERT OR IGNORE INTO pretrade_rug_safety_assessments(
                    definition_version,lane,quote_key,token_id,trigger_snapshot_id,
                    assessed_snapshot_id,status,reasons_json,facts_json,observed_at,assessed_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    self.PRETRADE_RUG_SAFETY_VERSION, str(lane), str(quote_key),
                    str(token_id), int(trigger_snapshot_id), int(assessed_snapshot_id), status,
                    self._json(assessment.get("reasons") or []),
                    self._json(assessment.get("facts") or {}),
                    iso(parse_time(observed_at)), iso(parse_time(assessed_at or utcnow())),
                ),
            )
            if cursor.rowcount != 1:
                return None
            return int(cursor.lastrowid)

    def pretrade_rug_safety_for_quote(self, lane: str, quote_key: str) -> sqlite3.Row | None:
        return self.db.execute(
            "SELECT * FROM pretrade_rug_safety_assessments "
            "WHERE definition_version=? AND lane=? AND quote_key=?",
            (self.PRETRADE_RUG_SAFETY_VERSION, str(lane), str(quote_key)),
        ).fetchone()

    def register_route_preflight_deferred_retry_shadow(self) -> sqlite3.Row:
        """Freeze a future-only denominator for one-shot deferred SELL preflights."""
        version = self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION
        definition = {
            "version": version,
            "source_assessment_version": self.PRETRADE_RUG_SAFETY_VERSION,
            "source_quote_version": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
            "source_strategy_version": self.CHAIN_MEME_TRADER_VERSION,
            "source_stage": "stage_02_jupiter_v1",
            "source_reason": "exact_size_sell_preflight_deferred",
            "max_stage2_delay_seconds": 45.0,
            "focus_delay_seconds": 10.0,
            "minimum_quoted_recovery_ratio": 0.90,
            "minimum_stress_recovery_ratio": 0.85,
            "attempts_per_case": 1,
            "scheduling": "after_all_exit_execution_and_valuation_before_discovery_buy",
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO route_preflight_deferred_retry_shadow_registrations("
                "definition_version,registered_at,activation_pretrade_assessment_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM pretrade_rug_safety_assessments),0),?)",
                (version, iso(), self._json(definition)),
            )
            return self.db.execute(
                "SELECT * FROM route_preflight_deferred_retry_shadow_registrations "
                "WHERE definition_version=?", (version,),
            ).fetchone()

    def enroll_route_preflight_deferred_retry_shadow(self) -> dict[str, int]:
        """Append post-frontier cases; non-defer safety reasons remain hard blockers."""
        version = self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION
        enrolled = blocked = 0
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM route_preflight_deferred_retry_shadow_registrations "
                "WHERE definition_version=?", (version,),
            ).fetchone()
            if registration is None:
                return {"enrolled": 0, "blocked": 0}
            rows = self.db.execute(
                """
                SELECT p.*,q.id AS source_quote_result_id,q.attempt_id AS source_quote_attempt_id,
                       q.shadow_cohort_id,q.anchor_at,q.input_mint AS entry_input_mint,
                       q.output_mint AS token_mint,q.input_amount_raw AS entry_input_amount_raw,
                       q.other_amount_threshold_raw AS acquired_amount_raw,q.slippage_bps,
                       q.validity_status AS buy_validity_status,
                       q.quote_terminal_status AS buy_terminal_status,q.completed_at AS buy_completed_at,
                       a.requested_at AS buy_requested_at,d2.id AS source_entry_decision_id,
                       buy.status AS buy_route_status,surface.status AS surface_status
                FROM pretrade_rug_safety_assessments p
                JOIN onchain_only_jupiter_quote_results q
                  ON q.quote_key=p.quote_key AND q.phase='baseline_buy'
                JOIN onchain_only_jupiter_quote_attempts a ON a.id=q.attempt_id
                JOIN chain_meme_trader_entry_decisions d1
                  ON d1.definition_version=? AND d1.arm_id='stage_01_shadow_v1'
                 AND d1.shadow_cohort_id=q.shadow_cohort_id AND d1.status='admitted'
                JOIN chain_meme_trader_entry_decisions d2
                  ON d2.definition_version=? AND d2.arm_id='stage_02_jupiter_v1'
                 AND d2.shadow_cohort_id=q.shadow_cohort_id AND d2.status='rejected'
                LEFT JOIN execution_route_observations buy
                  ON buy.definition_version=? AND buy.lane=? AND buy.quote_key=p.quote_key
                 AND buy.direction='BUY'
                LEFT JOIN market_surface_safety_observations surface
                  ON surface.definition_version=? AND surface.lane=?
                 AND surface.quote_key=p.quote_key
                LEFT JOIN route_preflight_deferred_retry_shadow_cases c
                  ON c.source_assessment_id=p.id
                WHERE p.id>? AND p.definition_version=? AND p.lane=?
                  AND p.status='WAIT' AND c.id IS NULL
                ORDER BY p.id
                """,
                (
                    self.CHAIN_MEME_TRADER_VERSION, self.CHAIN_MEME_TRADER_VERSION,
                    self.EXECUTION_ROUTE_OBSERVATION_VERSION,
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                    self.MARKET_SURFACE_SAFETY_VERSION,
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                    int(registration["activation_pretrade_assessment_id"]),
                    self.PRETRADE_RUG_SAFETY_VERSION,
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                ),
            ).fetchall()
            for row in rows:
                source_reasons = [str(value) for value in self._json_list(row["reasons_json"])]
                if "exact_size_sell_preflight_deferred" not in source_reasons:
                    continue
                facts = self._json_object(row["facts_json"])
                preflight = facts.get("exact_sell_preflight")
                preflight = preflight if isinstance(preflight, Mapping) else {}
                acquired_raw = str(row["acquired_amount_raw"] or "")
                blockers = [
                    reason for reason in source_reasons
                    if reason != "exact_size_sell_preflight_deferred"
                ]
                if str(preflight.get("status") or "") != "budget_deferred":
                    blockers.append("source_preflight_not_budget_deferred")
                if str(preflight.get("input_amount_raw") or "") != acquired_raw:
                    blockers.append("source_exact_amount_mismatch")
                if (
                    str(row["buy_terminal_status"]) != "quoted"
                    or str(row["buy_validity_status"]) != "valid"
                ):
                    blockers.append("source_buy_not_valid")
                if str(row["buy_route_status"] or "") != "PASS":
                    blockers.append("source_buy_route_not_pass")
                if str(row["surface_status"] or "") != "PASS":
                    blockers.append("source_surface_not_pass")
                blockers = list(dict.fromkeys(blockers))
                enrollment_status = "other_gate_blocked" if blockers else "eligible"
                completed = parse_time(row["buy_completed_at"])
                cursor = self.db.execute(
                    "INSERT OR IGNORE INTO route_preflight_deferred_retry_shadow_cases("
                    "definition_version,source_assessment_id,source_quote_result_id,"
                    "source_quote_attempt_id,source_entry_decision_id,shadow_cohort_id,token_id,"
                    "quote_key,original_anchor_at,original_buy_requested_at,"
                    "original_buy_completed_at,entry_input_amount_raw,input_mint,output_mint,"
                    "input_amount_raw,slippage_bps,selected_surface_pool,deadline_at,"
                    "enrollment_status,source_reasons_json,blocking_reasons_json,recorded_at,"
                    "decision_eligible,affects) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')",
                    (
                        version, int(row["id"]), int(row["source_quote_result_id"]),
                        int(row["source_quote_attempt_id"]), int(row["source_entry_decision_id"]),
                        int(row["shadow_cohort_id"]), str(row["token_id"]), str(row["quote_key"]),
                        str(row["anchor_at"]), str(row["buy_requested_at"]),
                        str(row["buy_completed_at"]), str(row["entry_input_amount_raw"]),
                        str(row["token_mint"]), str(row["entry_input_mint"]), acquired_raw,
                        int(row["slippage_bps"] or 400), str(facts.get("pool_address") or ""),
                        iso(completed + timedelta(seconds=45)), enrollment_status,
                        self._json(source_reasons), self._json(blockers), iso(),
                    ),
                )
                if int(cursor.rowcount or 0) != 1:
                    continue
                case_id = int(cursor.lastrowid)
                if enrollment_status == "eligible":
                    enrolled += 1
                else:
                    blocked += 1
                    self._record_route_preflight_deferred_retry_shadow_result_locked(
                        case_id, attempt_id=None,
                        status="not_dispatched_other_gate_blocked",
                        result={}, route_classification={}, error_type="",
                        completed_at=utcnow(),
                    )
        return {"enrolled": enrolled, "blocked": blocked}

    def due_route_preflight_deferred_retry_shadow(
        self, *, now: Any = None, limit: int = 1
    ) -> list[dict[str, Any]]:
        current = parse_time(now or utcnow())
        with self._lock:
            rows = self.db.execute(
                """
                SELECT c.* FROM route_preflight_deferred_retry_shadow_cases c
                LEFT JOIN route_preflight_deferred_retry_shadow_attempts a ON a.case_id=c.id
                LEFT JOIN route_preflight_deferred_retry_shadow_results r ON r.case_id=c.id
                WHERE c.definition_version=? AND c.enrollment_status='eligible'
                  AND a.id IS NULL AND r.id IS NULL
                ORDER BY c.deadline_at,c.id LIMIT ?
                """,
                (self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION, max(1, int(limit))),
            ).fetchall()
            return [{**dict(row), "evaluated_at": iso(current)} for row in rows]

    def start_route_preflight_deferred_retry_shadow_attempt(
        self, case: Mapping[str, Any], *, requested_at: Any = None
    ) -> int | None:
        requested = parse_time(requested_at or utcnow())
        case_id = int(case["id"])
        version = self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION
        with self._lock, self.db:
            current = self.db.execute(
                "SELECT * FROM route_preflight_deferred_retry_shadow_cases WHERE id=? "
                "AND definition_version=?", (case_id, version),
            ).fetchone()
            if (
                current is None or str(current["enrollment_status"]) != "eligible"
                or requested < parse_time(current["original_buy_completed_at"])
                or requested > parse_time(current["deadline_at"])
            ):
                return None
            cursor = self.db.execute(
                "INSERT OR IGNORE INTO route_preflight_deferred_retry_shadow_attempts("
                "definition_version,case_id,request_key,requested_at,decision_eligible,affects) "
                "VALUES(?,?,?,?,0,'none')",
                (version, case_id, f"{version}:{case_id}", iso(requested)),
            )
            return int(cursor.lastrowid) if int(cursor.rowcount or 0) == 1 else None

    @staticmethod
    def _route_preflight_retry_route_status(classification: Mapping[str, Any]) -> str:
        verifiability = str(classification.get("route_verifiability") or "unsupported")
        relation = str(classification.get("surface_relation") or "opaque_router")
        if verifiability == "exact_onchain_legs" and relation in {"contains_surface", "multi_surface"}:
            return "PASS"
        if verifiability == "meta_aggregator_opaque" or relation in {"opaque_router", "multi_surface"}:
            return "WAIT"
        return "REJECT"

    def _record_route_preflight_deferred_retry_shadow_result_locked(
        self, case_id: int, *, attempt_id: int | None, status: str,
        result: Mapping[str, Any], route_classification: Mapping[str, Any],
        error_type: str, completed_at: Any,
    ) -> int | None:
        version = self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION
        case = self.db.execute(
            "SELECT * FROM route_preflight_deferred_retry_shadow_cases WHERE id=? "
            "AND definition_version=?", (int(case_id), version),
        ).fetchone()
        if case is None or self.db.execute(
            "SELECT 1 FROM route_preflight_deferred_retry_shadow_results WHERE case_id=?",
            (int(case_id),),
        ).fetchone() is not None:
            return None
        attempt = None
        if attempt_id is not None:
            attempt = self.db.execute(
                "SELECT * FROM route_preflight_deferred_retry_shadow_attempts "
                "WHERE id=? AND case_id=? AND definition_version=?",
                (int(attempt_id), int(case_id), version),
            ).fetchone()
            if attempt is None:
                return None
        allowed = {
            "quoted", "no_route", "error", "quote_only_protocol_invalid",
            "expired_before_request", "interrupted_after_request",
            "not_dispatched_other_gate_blocked",
        }
        terminal = str(status)
        if terminal not in allowed:
            raise ValueError("invalid deferred retry terminal status")
        completed = parse_time(completed_at)
        original_completed = parse_time(case["original_buy_completed_at"])
        requested = parse_time(attempt["requested_at"]) if attempt is not None else None
        output_raw = result.get("output_amount_raw")
        minimum_raw = result.get("other_amount_threshold")
        if minimum_raw is None:
            minimum_raw = result.get("minimum_output_raw")
        if terminal == "quoted" and (
            int(output_raw or 0) <= 0 or int(minimum_raw or 0) <= 0
            or int(minimum_raw or 0) > int(output_raw or 0)
        ):
            terminal = "quote_only_protocol_invalid"
            error_type = error_type or "invalid_quote_amounts"
        route_status = (
            self._route_preflight_retry_route_status(route_classification)
            if terminal == "quoted" else "NOT_APPLICABLE"
        )
        entry_raw = int(case["entry_input_amount_raw"] or 0)
        quoted_ratio = (
            int(output_raw) / entry_raw
            if terminal == "quoted" and output_raw is not None and entry_raw > 0 else None
        )
        stress_ratio = (
            int(minimum_raw) / entry_raw
            if terminal == "quoted" and minimum_raw is not None and entry_raw > 0 else None
        )
        total_delay = max(0.0, (completed - original_completed).total_seconds())
        stage2_window_met = int(total_delay <= 45.0)
        focus_10s_met = int(
            completed <= parse_time(case["original_anchor_at"]) + timedelta(seconds=10)
        )
        recovered = int(terminal == "quoted" and int(minimum_raw or 0) > 0)
        full_pass = int(bool(
            recovered and route_status == "PASS" and stage2_window_met
            and quoted_ratio is not None and quoted_ratio >= 0.90
            and stress_ratio is not None and stress_ratio >= 0.85
            and not self._json_list(case["blocking_reasons_json"])
        ))
        validity = {
            "quoted": "route_recovered",
            "no_route": "no_route",
            "error": "provider_error",
            "quote_only_protocol_invalid": "protocol_invalid",
            "expired_before_request": "stage2_window_expired",
            "interrupted_after_request": "request_evidence_missing",
            "not_dispatched_other_gate_blocked": "other_gate_blocked",
        }[terminal]
        cursor = self.db.execute(
            "INSERT OR IGNORE INTO route_preflight_deferred_retry_shadow_results("
            "definition_version,case_id,attempt_id,quote_terminal_status,validity_status,"
            "input_amount_raw,output_amount_raw,minimum_output_raw,requested_at,completed_at,"
            "queue_delay_seconds,request_duration_seconds,total_delay_seconds,"
            "stage2_window_met,focus_10s_met,route_status,route_recovered,"
            "quoted_net_recovery_ratio,stress_min_recovery_ratio,full_envelope_pass,"
            "router,route_json,classification_json,error_type,recorded_at,decision_eligible,affects) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')",
            (
                version, int(case_id), int(attempt_id) if attempt_id is not None else None,
                terminal, validity, str(case["input_amount_raw"]),
                str(output_raw) if output_raw is not None else None,
                str(minimum_raw) if minimum_raw is not None else None,
                iso(requested) if requested is not None else None, iso(completed),
                (requested - original_completed).total_seconds() if requested is not None else None,
                (completed - requested).total_seconds() if requested is not None else None,
                total_delay, stage2_window_met, focus_10s_met, route_status, recovered,
                quoted_ratio, stress_ratio, full_pass, str(result.get("router") or ""),
                self._json(result.get("route_plan") or []),
                self._json(dict(route_classification or {})), str(error_type or "")[:160], iso(),
            ),
        )
        return int(cursor.lastrowid) if int(cursor.rowcount or 0) == 1 else None

    def record_route_preflight_deferred_retry_shadow_result(
        self, case_id: int, *, attempt_id: int | None = None, status: str,
        result: Mapping[str, Any] | None = None,
        route_classification: Mapping[str, Any] | None = None,
        error_type: str = "", completed_at: Any = None,
    ) -> int | None:
        with self._lock, self.db:
            return self._record_route_preflight_deferred_retry_shadow_result_locked(
                int(case_id), attempt_id=attempt_id, status=status,
                result=dict(result or {}), route_classification=dict(route_classification or {}),
                error_type=error_type, completed_at=completed_at or utcnow(),
            )

    def recover_interrupted_route_preflight_deferred_retry_shadow(self) -> int:
        """Close attempt-first crash gaps without ever issuing a second request."""
        with self._lock:
            rows = self.db.execute(
                "SELECT a.case_id,a.id FROM route_preflight_deferred_retry_shadow_attempts a "
                "LEFT JOIN route_preflight_deferred_retry_shadow_results r ON r.case_id=a.case_id "
                "WHERE a.definition_version=? AND r.id IS NULL ORDER BY a.id",
                (self.ROUTE_PREFLIGHT_DEFERRED_RETRY_SHADOW_VERSION,),
            ).fetchall()
        recovered = 0
        for row in rows:
            recovered += int(self.record_route_preflight_deferred_retry_shadow_result(
                int(row["case_id"]), attempt_id=int(row["id"]),
                status="interrupted_after_request", completed_at=utcnow(),
            ) is not None)
        return recovered

    def post_entry_context_snapshot(
        self,
        token_id: str,
        *,
        opened_at: Any,
        at_or_before: Any = None,
        snapshot_id: int | None = None,
        entry_snapshot_id: int | None = None,
    ) -> tuple[int, TokenSnapshot] | None:
        """Return a post-entry snapshot, or the exact snapshot available at entry."""
        opened = iso(parse_time(opened_at))
        cutoff = iso(parse_time(at_or_before or utcnow()))
        exact = " AND id=?" if snapshot_id is not None else ""
        params: list[Any] = [str(token_id), opened, cutoff, cutoff]
        if snapshot_id is not None:
            params.append(int(snapshot_id))
        row = self.db.execute(
            f"""
            SELECT * FROM token_snapshots
            WHERE token_id=? AND observed_at>=? AND observed_at<=?
              AND ingested_at IS NOT NULL AND recorded_at IS NOT NULL
              AND observed_at<=ingested_at AND ingested_at<=recorded_at
              AND recorded_at<=?{exact}
            ORDER BY recorded_at DESC,id DESC LIMIT 1
            """,
            params,
        ).fetchone()
        if row is None and snapshot_id is None and entry_snapshot_id is not None:
            row = self.db.execute(
                """
                SELECT * FROM token_snapshots
                WHERE id=? AND token_id=?
                  AND ingested_at IS NOT NULL AND recorded_at IS NOT NULL
                  AND observed_at<=ingested_at AND ingested_at<=recorded_at
                  AND recorded_at<=? AND recorded_at<=?
                LIMIT 1
                """,
                (int(entry_snapshot_id), str(token_id), opened, cutoff),
            ).fetchone()
        if row is None:
            return None
        chain, address = str(token_id).split(":", 1)
        snapshot = TokenSnapshot(
            chain=chain, address=address, price_usd=row["price_usd"],
            liquidity_usd=row["liquidity_usd"], market_cap_usd=row["market_cap_usd"],
            volume_5m_usd=row["volume_5m_usd"], buys_5m=row["buys_5m"],
            sells_5m=row["sells_5m"], buyers_5m=row["buyers_5m"], holders=row["holders"],
            buy_tax_pct=row["buy_tax_pct"], sell_tax_pct=row["sell_tax_pct"],
            honeypot=None if row["honeypot"] is None else bool(row["honeypot"]),
            sellable=None if row["sellable"] is None else bool(row["sellable"]),
            observed_at=parse_time(row["observed_at"]),
            ingested_at=parse_time(row["ingested_at"]), provider=row["provider"],
            raw=json.loads(row["raw_json"]),
        )
        return int(row["id"]), snapshot

    def add_decision(self, decision: CandidateDecision) -> int:
        with self._lock, self.db:
            cur = self.db.execute(
                """
                INSERT INTO decisions(event_id,token_id,action,score,match_score,canonical_margin,reasons_json,
                    rejected_reasons_json,position_usd,created_at,route_probe_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    decision.event_id, decision.token_id, decision.action, decision.score, decision.match_score,
                    decision.canonical_margin, self._json(decision.reasons), self._json(decision.rejected_reasons),
                    decision.position_usd, iso(decision.created_at), decision.route_probe_id,
                ),
            )
            decision_id = int(cur.lastrowid)
            if decision.route_probe_id is not None:
                linked = self.db.execute(
                    "UPDATE event_context_jupiter_route_probes SET decision_id=?,updated_at=? "
                    "WHERE id=? AND event_id=? AND token_id=? AND status='valid' "
                    "AND decision_eligible=1 AND decision_id IS NULL",
                    (
                        decision_id, iso(), int(decision.route_probe_id),
                        int(decision.event_id), str(decision.token_id),
                    ),
                )
                if linked.rowcount != 1:
                    raise ValueError("event-context Jupiter route probe cannot bind to decision")
            if decision.token_id:
                self.record_token_universe_funnel_transition(
                    decision.token_id,
                    stage="decision_final",
                    status=str(decision.action).lower(),
                    reason_code=(
                        str(decision.rejected_reasons[0])
                        if decision.rejected_reasons else str(decision.action).lower()
                    ),
                    evaluation_key=f"decision:{decision_id}",
                    observed_at=decision.created_at,
                    ingested_at=utcnow(),
                    source_table="decisions",
                    source_record_ids={
                        "decision_id": decision_id, "event_id": int(decision.event_id)
                    },
                    event_id=int(decision.event_id),
                    decision_id=decision_id,
                    metadata={
                        "action": str(decision.action),
                        "candidate_score": float(decision.score),
                        "match_score": float(decision.match_score),
                        "canonical_margin": float(decision.canonical_margin),
                        "position_usd": float(decision.position_usd),
                    },
                )
            return decision_id

    def start_event_context_jupiter_route_probe(
        self,
        *,
        event_id: int,
        token_id: str,
        source_snapshot_id: int,
        anchor_at: Any,
        input_notional_usd: float,
        buy_input_amount_raw: int,
        slippage_bps: int,
        max_total_delay_seconds: float,
    ) -> int:
        anchor = parse_time(anchor_at)
        started_at = utcnow()
        with self._lock, self.db:
            snapshot = self.db.execute(
                "SELECT token_id,observed_at,ingested_at,recorded_at FROM token_snapshots WHERE id=?",
                (int(source_snapshot_id),),
            ).fetchone()
            if snapshot is None or str(snapshot["token_id"]) != str(token_id):
                raise ValueError("route probe snapshot token mismatch")
            observed = parse_time(snapshot["observed_at"])
            ingested = parse_time(snapshot["ingested_at"])
            recorded = parse_time(snapshot["recorded_at"])
            if not (observed <= ingested <= recorded <= anchor <= started_at):
                raise ValueError("route probe snapshot time invalid")
            cursor = self.db.execute(
                """
                INSERT INTO event_context_jupiter_route_probes(
                    definition_version,event_id,token_id,source_snapshot_id,status,anchor_at,
                    started_at,input_notional_usd,buy_input_amount_raw,slippage_bps,
                    max_total_delay_seconds,recorded_at,updated_at
                ) VALUES(?,?,?,?,'pending',?,?,?,?,?,?,?,?)
                """,
                (
                    self.EVENT_CONTEXT_JUPITER_ROUTE_VERSION, int(event_id), str(token_id),
                    int(source_snapshot_id), iso(anchor), iso(started_at),
                    float(input_notional_usd), str(int(buy_input_amount_raw)), int(slippage_bps),
                    float(max_total_delay_seconds), iso(started_at), iso(started_at),
                ),
            )
            return int(cursor.lastrowid)

    def recover_interrupted_event_context_route_probes(self, *, now: Any = None) -> int:
        current = parse_time(now or utcnow())
        recovered = 0
        with self._lock, self.db:
            rows = list(self.db.execute(
                "SELECT id,started_at,max_total_delay_seconds "
                "FROM event_context_jupiter_route_probes WHERE status='pending'"
            ))
            for row in rows:
                expires = parse_time(row["started_at"]) + timedelta(
                    seconds=float(row["max_total_delay_seconds"])
                )
                if expires >= current:
                    continue
                cursor = self.db.execute(
                    "UPDATE event_context_jupiter_route_probes SET status='stale',"
                    "reason='interrupted_or_expired',updated_at=? WHERE id=? AND status='pending'",
                    (iso(current), int(row["id"])),
                )
                recovered += int(cursor.rowcount)
        return recovered

    def finish_event_context_jupiter_route_probe(
        self,
        probe_id: int,
        *,
        status: str,
        reason: str = "",
        buy_quote: Mapping[str, Any] | None = None,
        sell_quote: Mapping[str, Any] | None = None,
        round_trip_min_return: float | None = None,
        decision_eligible: bool = False,
    ) -> None:
        allowed = {"valid", "no_route", "error", "invalid", "stale", "poor_roundtrip"}
        if status not in allowed:
            raise ValueError("invalid event-context Jupiter route status")
        buy = dict(buy_quote or {})
        sell = dict(sell_quote or {})
        now = utcnow()
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                UPDATE event_context_jupiter_route_probes SET
                    status=?,reason=?,buy_requested_at=?,buy_completed_at=?,sell_requested_at=?,
                    sell_completed_at=?,buy_output_amount_raw=?,buy_min_output_amount_raw=?,
                    sell_input_amount_raw=?,sell_output_amount_raw=?,sell_min_output_amount_raw=?,
                    round_trip_min_return=?,buy_quote_json=?,sell_quote_json=?,decision_eligible=?,
                    updated_at=?
                WHERE id=? AND status='pending'
                """,
                (
                    status, str(reason)[:240], buy.get("requested_at"), buy.get("completed_at"),
                    sell.get("requested_at"), sell.get("completed_at"),
                    buy.get("out_amount") or buy.get("output_amount_raw"),
                    buy.get("other_amount_threshold"), sell.get("in_amount"),
                    sell.get("out_amount") or sell.get("output_amount_raw"),
                    sell.get("other_amount_threshold"), round_trip_min_return,
                    self._bounded_json(buy), self._bounded_json(sell),
                    int(bool(decision_eligible)), iso(now), int(probe_id),
                ),
            )
            if cursor.rowcount != 1:
                raise ValueError("event-context Jupiter route probe is not pending")

    def event_context_jupiter_route_probe(self, probe_id: int) -> sqlite3.Row | None:
        return self.db.execute(
            "SELECT * FROM event_context_jupiter_route_probes WHERE id=?", (int(probe_id),)
        ).fetchone()

    def register_event_route_execution_challenger(self) -> sqlite3.Row:
        definition = {
            "version": self.EVENT_ROUTE_EXECUTION_CHALLENGER_VERSION,
            "scope": "future_route_backed_event_decisions_after_registration",
            "phase": "exact_final_size_buy_and_immediate_sell_preflight",
            "capacity_probe_is_not_fill": True,
            "buy_quantity_authority": "jupiter_other_amount_threshold_raw",
            "route_costs_and_slippage": "included_in_jupiter_minimum_output",
            "network_fee": "strict_cost_complete_required_before_any_fill_or_pnl",
            "paper_effect": "no_fill_research_only",
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "none",
            "simulated": True,
            "live_execution": False,
        }
        with self._lock, self.db:
            self.db.execute(
                """
                INSERT OR IGNORE INTO event_route_execution_challenger_registrations(
                    definition_version,registered_at,activation_decision_id,
                    activation_route_probe_id,definition_json
                ) VALUES(?, ?, COALESCE((SELECT MAX(id) FROM decisions),0),
                    COALESCE((SELECT MAX(id) FROM event_context_jupiter_route_probes),0), ?)
                """,
                (
                    self.EVENT_ROUTE_EXECUTION_CHALLENGER_VERSION,
                    iso(),
                    self._json(definition),
                ),
            )
            return self.db.execute(
                "SELECT * FROM event_route_execution_challenger_registrations "
                "WHERE definition_version=?",
                (self.EVENT_ROUTE_EXECUTION_CHALLENGER_VERSION,),
            ).fetchone()

    def start_event_route_execution_challenger_attempt(
        self,
        *,
        decision_id: int,
        event_id: int,
        token_id: str,
        capacity_probe_id: int,
        baseline_snapshot_id: int | None,
        intended_notional_usd: float,
        buy_input_amount_raw: int,
        slippage_bps: int,
        max_total_delay_seconds: float,
        baseline_quote_price: float | None,
        baseline_execution_price: float | None,
        baseline_fee_bps: float | None,
        baseline_buy_tax_pct: float | None,
        baseline_sell_tax_pct: float | None,
        frozen_at: Any = None,
    ) -> int | None:
        frozen = parse_time(frozen_at or utcnow())
        version = self.EVENT_ROUTE_EXECUTION_CHALLENGER_VERSION
        if intended_notional_usd <= 0 or int(buy_input_amount_raw) <= 0:
            raise ValueError("challenger notional and raw input must be positive")
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM event_route_execution_challenger_registrations "
                "WHERE definition_version=?", (version,),
            ).fetchone()
            if registration is None:
                return None
            decision = self.db.execute(
                "SELECT * FROM decisions WHERE id=?", (int(decision_id),)
            ).fetchone()
            probe = self.db.execute(
                "SELECT * FROM event_context_jupiter_route_probes WHERE id=?",
                (int(capacity_probe_id),),
            ).fetchone()
            if decision is None or probe is None:
                return None
            if (
                int(decision_id) <= int(registration["activation_decision_id"])
                or int(capacity_probe_id) <= int(registration["activation_route_probe_id"])
                or int(decision["event_id"]) != int(event_id)
                or str(decision["token_id"]) != str(token_id)
                or int(decision["route_probe_id"] or 0) != int(capacity_probe_id)
                or str(decision["action"]) != "WAIT"
                or "route_backed_paper_execution_not_implemented"
                not in set(self._json_list(decision["rejected_reasons_json"]))
                or str(probe["status"]) != "valid"
                or int(probe["decision_eligible"]) != 1
                or int(probe["decision_id"] or 0) != int(decision_id)
                or int(probe["event_id"]) != int(event_id)
                or str(probe["token_id"]) != str(token_id)
                or int(buy_input_amount_raw) > int(probe["buy_input_amount_raw"])
            ):
                return None
            source_snapshot_id = int(probe["source_snapshot_id"])
            source_snapshot = self.db.execute(
                "SELECT observed_at,ingested_at,recorded_at FROM token_snapshots WHERE id=?",
                (source_snapshot_id,),
            ).fetchone()
            if source_snapshot is None:
                return None
            source_times = [
                parse_time(source_snapshot["observed_at"]),
                parse_time(source_snapshot["ingested_at"]),
                parse_time(source_snapshot["recorded_at"]),
            ]
            decision_at = parse_time(decision["created_at"])
            if not (source_times[0] <= source_times[1] <= source_times[2] <= decision_at <= frozen):
                return None
            if baseline_snapshot_id is not None:
                baseline = self.db.execute(
                    "SELECT token_id,observed_at,ingested_at,recorded_at FROM token_snapshots WHERE id=?",
                    (int(baseline_snapshot_id),),
                ).fetchone()
                if baseline is None or str(baseline["token_id"]) != str(token_id):
                    return None
                baseline_times = [
                    parse_time(baseline["observed_at"]),
                    parse_time(baseline["ingested_at"]),
                    parse_time(baseline["recorded_at"]),
                ]
                if not (
                    baseline_times[0] <= baseline_times[1] <= baseline_times[2] <= frozen
                ):
                    return None
            existing = self.db.execute(
                "SELECT id FROM event_route_execution_challenger_attempts WHERE decision_id=?",
                (int(decision_id),),
            ).fetchone()
            if existing is not None:
                return None
            now = utcnow()
            cursor = self.db.execute(
                """
                INSERT INTO event_route_execution_challenger_attempts(
                    definition_version,decision_id,event_id,token_id,capacity_probe_id,
                    source_snapshot_id,baseline_snapshot_id,quote_terminal_status,
                    validity_status,economic_status,paper_effect,reason,frozen_at,started_at,
                    intended_notional_usd,buy_input_amount_raw,slippage_bps,
                    max_total_delay_seconds,baseline_quote_price,baseline_execution_price,
                    baseline_fee_bps,baseline_buy_tax_pct,baseline_sell_tax_pct,
                    recorded_at,updated_at
                ) VALUES(?,?,?,?,?,?,?,'pending','pending','pending','pending','',?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    version, int(decision_id), int(event_id), str(token_id),
                    int(capacity_probe_id), source_snapshot_id,
                    int(baseline_snapshot_id) if baseline_snapshot_id is not None else None,
                    iso(frozen), iso(now), float(intended_notional_usd),
                    str(int(buy_input_amount_raw)), int(slippage_bps),
                    float(max_total_delay_seconds), baseline_quote_price,
                    baseline_execution_price, baseline_fee_bps, baseline_buy_tax_pct,
                    baseline_sell_tax_pct, iso(now), iso(now),
                ),
            )
            return int(cursor.lastrowid)

    def finish_event_route_execution_challenger_attempt(
        self,
        attempt_id: int,
        *,
        quote_terminal_status: str,
        validity_status: str,
        economic_status: str,
        reason: str,
        buy_quote: Mapping[str, Any] | None = None,
        sell_quote: Mapping[str, Any] | None = None,
        round_trip_min_return: float | None = None,
        route_only_cost_usd: float | None = None,
        fee_completeness_status: str = "not_evaluated",
        network_fee_basis: str = "",
    ) -> None:
        terminals = {"quoted", "no_route", "error", "protocol_invalid", "interrupted"}
        validities = {"valid", "invalid", "expired", "mismatched"}
        economics = {"cost_unknown", "quoted_but_uneconomic", "economic", "not_applicable"}
        if quote_terminal_status not in terminals:
            raise ValueError("invalid challenger quote terminal status")
        if validity_status not in validities or economic_status not in economics:
            raise ValueError("invalid challenger validity/economic status")
        buy = dict(buy_quote or {})
        sell = dict(sell_quote or {})
        now = utcnow()
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                UPDATE event_route_execution_challenger_attempts SET
                    quote_terminal_status=?,validity_status=?,economic_status=?,
                    paper_effect='no_fill_research_only',reason=?,
                    buy_requested_at=?,buy_completed_at=?,sell_requested_at=?,
                    sell_completed_at=?,buy_output_amount_raw=?,buy_min_output_amount_raw=?,
                    sell_input_amount_raw=?,sell_output_amount_raw=?,
                    sell_min_output_amount_raw=?,round_trip_min_return=?,route_only_cost_usd=?,
                    fee_completeness_status=?,network_fee_basis=?,buy_quote_json=?,
                    sell_quote_json=?,updated_at=?
                WHERE id=? AND quote_terminal_status='pending'
                """,
                (
                    quote_terminal_status, validity_status, economic_status,
                    str(reason)[:240], buy.get("requested_at"), buy.get("completed_at"),
                    sell.get("requested_at"), sell.get("completed_at"),
                    buy.get("out_amount") or buy.get("output_amount_raw"),
                    buy.get("other_amount_threshold"), sell.get("in_amount"),
                    sell.get("out_amount") or sell.get("output_amount_raw"),
                    sell.get("other_amount_threshold"), round_trip_min_return,
                    route_only_cost_usd, str(fee_completeness_status)[:80],
                    str(network_fee_basis)[:160], self._bounded_json(buy),
                    self._bounded_json(sell), iso(now), int(attempt_id),
                ),
            )
            if cursor.rowcount != 1:
                raise ValueError("event route challenger attempt is not pending")

    def recover_interrupted_event_route_execution_challenger_attempts(
        self, *, now: Any = None
    ) -> int:
        current = parse_time(now or utcnow())
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                UPDATE event_route_execution_challenger_attempts SET
                    quote_terminal_status='interrupted',validity_status='invalid',
                    economic_status='not_applicable',paper_effect='no_fill_research_only',
                    reason='interrupted_before_terminal_result',updated_at=?
                WHERE quote_terminal_status='pending'
                """,
                (iso(current),),
            )
            return int(cursor.rowcount)

    @classmethod
    def event_route_execution_challenger_summary_from_connection(
        cls, connection: sqlite3.Connection, *, limit: int = 30
    ) -> dict[str, Any]:
        version = cls.EVENT_ROUTE_EXECUTION_CHALLENGER_VERSION
        registration = connection.execute(
            "SELECT * FROM event_route_execution_challenger_registrations "
            "WHERE definition_version=?", (version,),
        ).fetchone()
        if registration is None:
            return {"status": "not_enabled", "version": version, "attempts": [], "summary": {}}
        counts = {
            str(row["quote_terminal_status"]): int(row["count"])
            for row in connection.execute(
                "SELECT quote_terminal_status,COUNT(*) AS count "
                "FROM event_route_execution_challenger_attempts "
                "WHERE definition_version=? GROUP BY quote_terminal_status",
                (version,),
            )
        }
        economic_counts = {
            str(row["economic_status"]): int(row["count"])
            for row in connection.execute(
                "SELECT economic_status,COUNT(*) AS count "
                "FROM event_route_execution_challenger_attempts "
                "WHERE definition_version=? GROUP BY economic_status",
                (version,),
            )
        }
        attempts = [
            dict(row) for row in connection.execute(
                "SELECT * FROM event_route_execution_challenger_attempts "
                "WHERE definition_version=? ORDER BY id DESC LIMIT ?",
                (version, max(1, int(limit))),
            )
        ]
        return {
            "status": "active_forward_collection",
            "version": version,
            "registered_at": registration["registered_at"],
            "activation_decision_id": int(registration["activation_decision_id"]),
            "activation_route_probe_id": int(registration["activation_route_probe_id"]),
            "definition": cls._json_object(registration["definition_json"]),
            "summary": {
                "attempts": sum(counts.values()),
                "terminal_counts": counts,
                "economic_counts": economic_counts,
                "fills": 0,
                "affects": "none",
            },
            "attempts": attempts,
        }

    def decisions(self, limit: int = 30) -> list[sqlite3.Row]:
        return list(self.db.execute("SELECT * FROM decisions ORDER BY id DESC LIMIT ?", (limit,)))

    def token_context_decision_relation(
        self, token_id: str, decision_id: int
    ) -> sqlite3.Row | None:
        return self.db.execute(
            """
            SELECT d.id AS decision_id,d.event_id,d.token_id,d.action,d.match_score,d.score,d.created_at,
                   e.title AS event_title,e.attention AS event_attention,e.last_seen_at,e.status AS event_status
            FROM decisions d JOIN events e ON e.id=d.event_id
            WHERE d.id=? AND d.token_id=?
            """,
            (int(decision_id), str(token_id)),
        ).fetchone()

    def account(self) -> dict[str, float]:
        row = self.db.execute("SELECT cash_usd,realized_pnl_usd FROM paper_account WHERE singleton=1").fetchone()
        return {"cash_usd": float(row["cash_usd"]), "realized_pnl_usd": float(row["realized_pnl_usd"])}

    def start_simulation_fair_epoch(
        self,
        epoch_id: str,
        *,
        starting_cash_usd: float,
        started_at: Any = None,
    ) -> dict[str, Any]:
        """Start a fresh Paper comparison without deleting any earlier evidence."""
        key = str(epoch_id).strip()[:160]
        if not key:
            raise ValueError("epoch_id is required")
        cash = max(0.01, float(starting_cash_usd))
        started = parse_time(started_at or utcnow())
        with self._lock, self.db:
            existing = self.db.execute(
                "SELECT * FROM simulation_fair_start_epochs WHERE epoch_id=?", (key,)
            ).fetchone()
            if existing is not None:
                return {**dict(existing), "status": "already_started"}
            open_count = int(self.db.execute("SELECT COUNT(*) FROM positions").fetchone()[0])
            if open_count:
                return {
                    "epoch_id": key,
                    "status": "blocked_open_positions",
                    "open_position_count": open_count,
                }
            account = self.db.execute(
                "SELECT cash_usd,realized_pnl_usd FROM paper_account WHERE singleton=1"
            ).fetchone()
            trade_count = int(self.db.execute("SELECT COUNT(*) FROM trades").fetchone()[0])
            self.db.execute(
                """
                INSERT INTO simulation_fair_start_epochs(
                    epoch_id,started_at,starting_cash_usd,prior_cash_usd,
                    prior_realized_pnl_usd,prior_trade_count,exploration_version,
                    exit_challenger_version,affects
                ) VALUES(?,?,?,?,?,?,?,?, 'paper_only')
                """,
                (
                    key, iso(started), cash, float(account["cash_usd"]),
                    float(account["realized_pnl_usd"]), trade_count,
                    self.ONCHAIN_PAPER_EXPLORATION_VERSION,
                    self.ONCHAIN_PAPER_EXIT_CHALLENGER_VERSION,
                ),
            )
            self.db.execute(
                "UPDATE paper_account SET cash_usd=?,realized_pnl_usd=0,updated_at=? "
                "WHERE singleton=1",
                (cash, iso(started)),
            )
            self.db.execute(
                """
                INSERT INTO paper_account_snapshots(
                    recorded_at,cash_usd,marked_value_usd,equity_usd,
                    daily_exposure_usd,open_position_count,priced_position_count,quote_as_of
                ) VALUES(?,?,0,?,0,0,0,NULL)
                """,
                (iso(started), cash, cash),
            )
            return {
                **dict(self.db.execute(
                    "SELECT * FROM simulation_fair_start_epochs WHERE epoch_id=?", (key,)
                ).fetchone()),
                "status": "started",
            }

    def latest_simulation_fair_epoch(self) -> sqlite3.Row | None:
        return self.db.execute(
            "SELECT * FROM simulation_fair_start_epochs ORDER BY started_at DESC LIMIT 1"
        ).fetchone()

    def record_paper_account_snapshot(
        self,
        *,
        cash_usd: float,
        marked_value_usd: float,
        equity_usd: float | None,
        daily_exposure_usd: float,
        open_position_count: int,
        priced_position_count: int,
        quote_as_of: Any = None,
        observed_at: Any = None,
    ) -> int:
        observed = parse_time(observed_at) if observed_at is not None else utcnow()
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                INSERT INTO paper_account_snapshots(
                    recorded_at,cash_usd,marked_value_usd,equity_usd,
                    daily_exposure_usd,open_position_count,priced_position_count,quote_as_of
                ) VALUES(?,?,?,?,?,?,?,?)
                """,
                (
                    iso(observed), float(cash_usd), float(marked_value_usd),
                    None if equity_usd is None else float(equity_usd), float(daily_exposure_usd),
                    max(0, int(open_position_count)), max(0, int(priced_position_count)),
                    iso(parse_time(quote_as_of)) if quote_as_of else None,
                ),
            )
            return int(cursor.lastrowid)

    def latest_paper_account_snapshot_at(self):
        row = self.db.execute(
            "SELECT recorded_at FROM paper_account_snapshots ORDER BY id DESC LIMIT 1"
        ).fetchone()
        return parse_time(row["recorded_at"]) if row else None

    def _insert_paper_execution_attempt_locked(
        self,
        *,
        event_id: int,
        token_id: str,
        decision_id: int | None = None,
        cohort_id: int | None = None,
        side: str,
        status: str,
        reason: str,
        requested_at: Any,
        quote_observed_at: Any = None,
        quote_provider: str = "",
        quote_price: float | None = None,
        execution_price: float | None = None,
        gross_usd: float | None = None,
    ) -> int:
        cursor = self.db.execute(
            """
            INSERT INTO paper_execution_attempts(
                event_id,token_id,decision_id,cohort_id,side,status,reason,requested_at,
                quote_observed_at,quote_provider,quote_price,execution_price,gross_usd
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                int(event_id), str(token_id), decision_id, cohort_id,
                str(side).upper(), str(status), str(reason),
                iso(parse_time(requested_at)),
                iso(parse_time(quote_observed_at)) if quote_observed_at else None,
                str(quote_provider or ""), quote_price, execution_price, gross_usd,
            ),
        )
        return int(cursor.lastrowid)

    def record_paper_execution_attempt(
        self,
        *,
        event_id: int,
        token_id: str,
        decision_id: int | None = None,
        cohort_id: int | None = None,
        side: str,
        status: str,
        reason: str,
        requested_at: Any,
        quote_observed_at: Any = None,
        quote_provider: str = "",
        quote_price: float | None = None,
        execution_price: float | None = None,
        gross_usd: float | None = None,
    ) -> int:
        with self._lock, self.db:
            attempt_id = self._insert_paper_execution_attempt_locked(
                event_id=event_id,
                token_id=token_id,
                decision_id=decision_id,
                cohort_id=cohort_id,
                side=side,
                status=status,
                reason=reason,
                requested_at=requested_at,
                quote_observed_at=quote_observed_at,
                quote_provider=quote_provider,
                quote_price=quote_price,
                execution_price=execution_price,
                gross_usd=gross_usd,
            )
            if decision_id is not None:
                self.record_token_universe_funnel_transition(
                    str(token_id),
                    stage="paper_execution_attempt",
                    status=str(status).lower(),
                    reason_code=str(reason),
                    evaluation_key=f"paper_execution_attempt:{attempt_id}",
                    observed_at=requested_at,
                    ingested_at=utcnow(),
                    source_table="paper_execution_attempts",
                    source_record_ids={
                        "paper_execution_attempt_id": attempt_id,
                        "decision_id": int(decision_id),
                        "event_id": int(event_id),
                    },
                    event_id=int(event_id),
                    decision_id=int(decision_id),
                    paper_execution_attempt_id=attempt_id,
                    metadata={"side": str(side).upper(), "status": str(status)},
                )
            return attempt_id

    def paper_buy(
        self, *, event_id: int, token: TokenCandidate, price: float, gross_usd: float,
        fee_bps: float, reason: str, quote_price: float | None = None,
        fixed_fee_usd: float | None = None,
        tax_pct: float | None = None, quote_observed_at: Any = None,
        quote_provider: str = "", execution_attempted_at: Any = None,
        decision_id: int | None = None, cohort_id: int | None = None,
        paper_execution_attempt_id: int | None = None,
        record_execution_attempt: bool = False,
    ) -> Position:
        if price <= 0 or gross_usd <= 0:
            raise ValueError("price and gross_usd must be positive")
        fee = (
            max(0.0, float(fixed_fee_usd))
            if fixed_fee_usd is not None else gross_usd * fee_bps / 10_000
        )
        recorded_fee_bps = fee / gross_usd * 10_000
        debit = gross_usd + fee
        normalized_tax_pct = (
            min(100.0, max(0.0, float(tax_pct))) if tax_pct is not None else None
        )
        tax = gross_usd * normalized_tax_pct / 100 if normalized_tax_pct is not None else 0.0
        pre_tax_quantity = gross_usd / price
        quantity = (gross_usd - tax) / price
        if quantity <= 0:
            raise ValueError("paper buy tax leaves no quantity")
        slippage_rate = (
            max(0.0, (price - float(quote_price)) / float(quote_price))
            if quote_price is not None and float(quote_price) > 0 else None
        )
        slippage_usd = pre_tax_quantity * (price - float(quote_price)) if slippage_rate is not None else None
        with self._lock, self.db:
            account = self.account()
            if account["cash_usd"] + 1e-9 < debit:
                raise ValueError("insufficient paper cash")
            if self.db.execute("SELECT 1 FROM positions WHERE token_id=?", (token.token_id,)).fetchone():
                raise ValueError("position already exists")
            now = iso()
            if record_execution_attempt:
                if paper_execution_attempt_id is not None:
                    raise ValueError("paper execution attempt already supplied")
                paper_execution_attempt_id = self._insert_paper_execution_attempt_locked(
                    event_id=event_id,
                    token_id=token.token_id,
                    decision_id=decision_id,
                    cohort_id=cohort_id,
                    side="BUY",
                    status="filled",
                    reason=reason,
                    requested_at=execution_attempted_at or now,
                    quote_observed_at=quote_observed_at,
                    quote_provider=quote_provider,
                    quote_price=quote_price,
                    execution_price=price,
                    gross_usd=gross_usd,
                )
            self.db.execute("UPDATE paper_account SET cash_usd=cash_usd-?,updated_at=? WHERE singleton=1", (debit, now))
            self.db.execute(
                """
                INSERT INTO positions(token_id,event_id,decision_id,cohort_id,chain,address,symbol,quantity,entry_price,cost_usd,
                    remaining_cost_usd,highest_price,opened_at,realized_pnl_usd,take_profit_index)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)
                """,
                (
                    token.token_id,event_id,decision_id,cohort_id,token.chain,token.address,
                    token.symbol,quantity,price,debit,debit,price,now,0.0,
                ),
            )
            trade_cursor = self.db.execute(
                """
                INSERT INTO trades(
                    token_id,event_id,decision_id,cohort_id,side,quantity,price,quote_price,gross_usd,fee_usd,
                    fee_bps,slippage_rate,slippage_usd,tax_pct,tax_usd,quote_observed_at,
                    quote_provider,execution_attempted_at,reason,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (token.token_id,event_id,decision_id,cohort_id,"BUY",quantity,price,quote_price,gross_usd,fee,
                 recorded_fee_bps,slippage_rate,slippage_usd,normalized_tax_pct,
                 tax if normalized_tax_pct is not None else None,
                 iso(parse_time(quote_observed_at)) if quote_observed_at else None,
                 str(quote_provider or ""),
                 iso(parse_time(execution_attempted_at)) if execution_attempted_at else now,
                 reason,now),
            )
            trade_id = int(trade_cursor.lastrowid)
            if decision_id is not None:
                if paper_execution_attempt_id is not None:
                    self.record_token_universe_funnel_transition(
                        token.token_id,
                        stage="paper_execution_attempt",
                        status="filled",
                        reason_code=str(reason),
                        evaluation_key=f"paper_execution_attempt:{paper_execution_attempt_id}",
                        observed_at=execution_attempted_at or now,
                        ingested_at=utcnow(),
                        source_table="paper_execution_attempts",
                        source_record_ids={
                            "paper_execution_attempt_id": paper_execution_attempt_id,
                            "decision_id": int(decision_id),
                            "event_id": int(event_id),
                        },
                        event_id=int(event_id),
                        decision_id=int(decision_id),
                        paper_execution_attempt_id=paper_execution_attempt_id,
                        metadata={"side": "BUY", "status": "filled"},
                    )
                self.record_token_universe_funnel_transition(
                    token.token_id,
                    stage="paper_fill",
                    status="filled",
                    reason_code=str(reason),
                    evaluation_key=f"trade:{trade_id}",
                    observed_at=execution_attempted_at or now,
                    ingested_at=utcnow(),
                    source_table="trades",
                    source_record_ids={
                        "trade_id": trade_id,
                        "decision_id": int(decision_id),
                        "event_id": int(event_id),
                        "paper_execution_attempt_id": paper_execution_attempt_id,
                    },
                    event_id=int(event_id),
                    decision_id=int(decision_id),
                    paper_execution_attempt_id=paper_execution_attempt_id,
                    trade_id=trade_id,
                    metadata={"side": "BUY"},
                )
        return self.position(token.token_id)

    def position(self, token_id: str) -> Position | None:
        row = self.db.execute("SELECT * FROM positions WHERE token_id=?", (token_id,)).fetchone()
        if not row:
            return None
        return Position(
            token_id=row["token_id"], event_id=int(row["event_id"]), chain=row["chain"], address=row["address"],
            symbol=row["symbol"], quantity=float(row["quantity"]), entry_price=float(row["entry_price"]),
            cost_usd=float(row["cost_usd"]), remaining_cost_usd=float(row["remaining_cost_usd"]),
            highest_price=float(row["highest_price"]), opened_at=parse_time(row["opened_at"]),
            realized_pnl_usd=float(row["realized_pnl_usd"]), take_profit_index=int(row["take_profit_index"]),
            decision_id=int(row["decision_id"]) if row["decision_id"] is not None else None,
            cohort_id=int(row["cohort_id"]) if row["cohort_id"] is not None else None,
        )

    def open_positions(self) -> list[Position]:
        ids = [row["token_id"] for row in self.db.execute("SELECT token_id FROM positions ORDER BY opened_at")]
        return [p for token_id in ids if (p := self.position(token_id)) is not None]

    def update_position_peak(self, token_id: str, price: float) -> None:
        with self._lock, self.db:
            self.db.execute("UPDATE positions SET highest_price=MAX(highest_price,?) WHERE token_id=?", (price, token_id))

    def set_take_profit_index(self, token_id: str, index: int) -> None:
        with self._lock, self.db:
            self.db.execute("UPDATE positions SET take_profit_index=? WHERE token_id=?", (index, token_id))

    def paper_sell(
        self, token_id: str, *, price: float, fraction: float, fee_bps: float,
        reason: str, quote_price: float | None = None, tax_pct: float | None = None,
        fixed_fee_usd: float | None = None,
        quote_observed_at: Any = None, quote_provider: str = "",
        execution_attempted_at: Any = None,
        record_execution_attempt: bool = False,
    ) -> dict[str, float]:
        position = self.position(token_id)
        if not position:
            raise KeyError(token_id)
        fraction = min(1.0, max(0.0, fraction))
        if fraction <= 0 or price <= 0:
            raise ValueError("invalid sell")
        quantity = position.quantity * fraction
        gross = quantity * price
        fee = (
            max(0.0, float(fixed_fee_usd))
            if fixed_fee_usd is not None else gross * fee_bps / 10_000
        )
        recorded_fee_bps = fee / gross * 10_000
        normalized_tax_pct = (
            min(100.0, max(0.0, float(tax_pct))) if tax_pct is not None else None
        )
        tax = gross * normalized_tax_pct / 100 if normalized_tax_pct is not None else 0.0
        slippage_rate = (
            max(0.0, (float(quote_price) - price) / float(quote_price))
            if quote_price is not None and float(quote_price) > 0 else None
        )
        slippage_usd = quantity * (float(quote_price) - price) if slippage_rate is not None else None
        net = gross - fee - tax
        cost_released = position.remaining_cost_usd * fraction
        pnl = net - cost_released
        remaining_quantity = position.quantity - quantity
        remaining_cost = position.remaining_cost_usd - cost_released
        now = iso()
        with self._lock, self.db:
            paper_execution_attempt_id = None
            if record_execution_attempt:
                paper_execution_attempt_id = self._insert_paper_execution_attempt_locked(
                    event_id=position.event_id,
                    token_id=position.token_id,
                    decision_id=position.decision_id,
                    cohort_id=position.cohort_id,
                    side="SELL",
                    status="filled",
                    reason=reason,
                    requested_at=execution_attempted_at or now,
                    quote_observed_at=quote_observed_at,
                    quote_provider=quote_provider,
                    quote_price=quote_price,
                    execution_price=price,
                    gross_usd=gross,
                )
            self.db.execute(
                "UPDATE paper_account SET cash_usd=cash_usd+?,realized_pnl_usd=realized_pnl_usd+?,updated_at=? WHERE singleton=1",
                (net, pnl, now),
            )
            trade_cursor = self.db.execute(
                """
                INSERT INTO trades(
                    token_id,event_id,decision_id,cohort_id,side,quantity,price,quote_price,gross_usd,fee_usd,
                    fee_bps,slippage_rate,slippage_usd,tax_pct,tax_usd,quote_observed_at,
                    quote_provider,execution_attempted_at,reason,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                 token_id,position.event_id,position.decision_id,position.cohort_id,
                 "SELL",quantity,price,quote_price,gross,fee,
                 recorded_fee_bps,slippage_rate,slippage_usd,normalized_tax_pct,
                 tax if normalized_tax_pct is not None else None,
                 iso(parse_time(quote_observed_at)) if quote_observed_at else None,
                 str(quote_provider or ""),
                 iso(parse_time(execution_attempted_at)) if execution_attempted_at else now,
                 reason,now),
            )
            trade_id = int(trade_cursor.lastrowid)
            if remaining_quantity <= max(1e-12, position.quantity * 1e-8):
                self._record_source_utility_outcome_locked(position, closed_at=now)
                self.db.execute("DELETE FROM positions WHERE token_id=?", (token_id,))
            else:
                self.db.execute(
                    "UPDATE positions SET quantity=?,remaining_cost_usd=?,realized_pnl_usd=realized_pnl_usd+? WHERE token_id=?",
                    (remaining_quantity,remaining_cost,pnl,token_id),
                )
            if position.decision_id is not None:
                if paper_execution_attempt_id is not None:
                    self.record_token_universe_funnel_transition(
                        position.token_id,
                        stage="paper_execution_attempt",
                        status="filled",
                        reason_code=str(reason),
                        evaluation_key=f"paper_execution_attempt:{paper_execution_attempt_id}",
                        observed_at=execution_attempted_at or now,
                        ingested_at=utcnow(),
                        source_table="paper_execution_attempts",
                        source_record_ids={
                            "paper_execution_attempt_id": paper_execution_attempt_id,
                            "decision_id": int(position.decision_id),
                            "event_id": int(position.event_id),
                        },
                        event_id=int(position.event_id),
                        decision_id=int(position.decision_id),
                        paper_execution_attempt_id=paper_execution_attempt_id,
                        metadata={"side": "SELL", "status": "filled"},
                    )
                self.record_token_universe_funnel_transition(
                    position.token_id,
                    stage="paper_fill",
                    status="filled",
                    reason_code=str(reason),
                    evaluation_key=f"trade:{trade_id}",
                    observed_at=execution_attempted_at or now,
                    ingested_at=utcnow(),
                    source_table="trades",
                    source_record_ids={
                        "trade_id": trade_id,
                        "decision_id": int(position.decision_id),
                        "event_id": int(position.event_id),
                        "paper_execution_attempt_id": paper_execution_attempt_id,
                    },
                    event_id=int(position.event_id),
                    decision_id=int(position.decision_id),
                    paper_execution_attempt_id=paper_execution_attempt_id,
                    trade_id=trade_id,
                    metadata={"side": "SELL"},
                )
        return {
            "quantity": quantity, "gross_usd": gross, "fee_usd": fee, "net_usd": net,
            "pnl_usd": pnl, "quote_price": quote_price, "execution_price": price,
            "slippage_rate": slippage_rate, "slippage_usd": slippage_usd,
            "tax_pct": normalized_tax_pct,
            "tax_usd": tax if normalized_tax_pct is not None else None,
        }

    def trades(self, limit: int = 50) -> list[sqlite3.Row]:
        return list(self.db.execute("SELECT * FROM trades ORDER BY id DESC LIMIT ?", (limit,)))

    @staticmethod
    def _source_learning_labels(row: Mapping[str, Any]) -> list[tuple[str, str]]:
        def value(name: str, default: Any = "") -> Any:
            try:
                return row[name]
            except (KeyError, IndexError, TypeError):
                return default

        try:
            raw = json.loads(str(value("raw_json") or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            raw = {}
        if not isinstance(raw, dict):
            raw = {}
        browser = raw.get("browser") if isinstance(raw.get("browser"), dict) else {}
        source = str(value("source") or "").strip()[:160]
        source_kind = str(value("source_kind") or "unknown").strip().lower()[:80] or "unknown"
        platform = str(raw.get("platform") or browser.get("platform") or "").strip().lower()
        if not platform:
            prefix = source.split(":", 1)[0].strip().lower()
            if prefix in {"x", "truth", "bluesky", "reddit", "threads", "instagram", "tiktok", "youtube", "mastodon"}:
                platform = prefix
            elif source.startswith("autonomous-") or source_kind == "agent_search":
                platform = "agent_search"
            elif source_kind in {"news", "rss"}:
                platform = "rss_news"
            elif source_kind in {"onchain", "token", "new_pool"}:
                platform = "onchain"
        platform = re.sub(r"[^a-z0-9_-]", "", platform)[:80]
        entity_id = str(raw.get("source_entity_id") or "").strip().lower()
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9_-]{0,62}[a-z0-9])?", entity_id):
            entity_id = ""
        account_type = str(raw.get("account_type") or browser.get("account_type") or "").strip().lower()
        account_type = re.sub(r"[^a-z0-9_-]", "", account_type)[:80]
        trend_lane = str(raw.get("trend_lane_id") or "").strip().lower()
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9_-]{0,62}[a-z0-9])?", trend_lane):
            trend_lane = ""
        event_topic = str(value("event_topic") or "").strip().lower()
        if event_topic not in {
            "political_public_figure", "celebrity_entertainment", "animals_internet_culture",
            "sports", "ai_tech_gaming", "crypto_native", "other",
        }:
            event_topic = ""
        evidence_role = str(value("role") or "").strip().lower()
        if evidence_role not in {"feature", "confirmation", "identity", "promotion"}:
            evidence_role = ""
        labels = [("source_kind", source_kind)]
        if source:
            labels.append(("source", source))
        if platform:
            labels.append(("platform", platform))
        if entity_id:
            labels.append(("entity", entity_id))
        if account_type:
            labels.append(("account_type", account_type))
        if trend_lane:
            labels.append(("trend_lane", trend_lane))
        if event_topic:
            labels.append(("event_topic", event_topic))
        if evidence_role:
            labels.append(("evidence_role", evidence_role))
        return list(dict.fromkeys(labels))

    def _record_source_utility_outcome_locked(self, position: Position, *, closed_at: str) -> None:
        opened_at = iso(position.opened_at)
        if position.decision_id is not None:
            trade_rows = list(
                self.db.execute(
                    """
                    SELECT side,gross_usd,fee_usd,tax_usd FROM trades
                    WHERE decision_id=? AND event_id=? AND token_id=? AND created_at>=?
                    ORDER BY id
                    """,
                    (
                        int(position.decision_id), int(position.event_id),
                        str(position.token_id), opened_at,
                    ),
                )
            )
            outcome_key = hashlib.sha256(
                f"{self.PAPER_SOURCE_ATTRIBUTION_VERSION}\n{int(position.decision_id)}\n{opened_at}".encode(
                    "utf-8"
                )
            ).hexdigest()
        else:
            trade_rows = list(
                self.db.execute(
                    """
                    SELECT side,gross_usd,fee_usd,tax_usd FROM trades
                    WHERE event_id=? AND token_id=? AND created_at>=?
                    ORDER BY id
                    """,
                    (position.event_id, position.token_id, opened_at),
                )
            )
            outcome_key = hashlib.sha256(
                f"legacy\n{position.event_id}\n{position.token_id}\n{opened_at}".encode("utf-8")
            ).hexdigest()

        trade_rows = list(
            trade_rows
        )
        buy_cost = sum(
            float(row["gross_usd"] or 0) + float(row["fee_usd"] or 0)
            for row in trade_rows if str(row["side"]).upper() == "BUY"
        )
        sell_net = sum(
            float(row["gross_usd"] or 0)
            - float(row["fee_usd"] or 0)
            - float(row["tax_usd"] or 0)
            for row in trade_rows if str(row["side"]).upper() == "SELL"
        )

        def record_attempt(
            status: str,
            reason: str,
            *,
            eligible_source_count: int = 0,
            net_return: float | None = None,
        ) -> None:
            self.db.execute(
                """
                INSERT OR IGNORE INTO paper_source_attribution_attempts(
                    outcome_key,version,event_id,token_id,decision_id,cohort_id,status,reason,
                    eligible_source_count,buy_cost_usd,sell_net_usd,net_return,opened_at,closed_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    outcome_key,
                    self.PAPER_SOURCE_ATTRIBUTION_VERSION,
                    int(position.event_id),
                    str(position.token_id),
                    position.decision_id,
                    position.cohort_id,
                    str(status),
                    str(reason),
                    max(0, int(eligible_source_count)),
                    buy_cost if buy_cost > 0 else None,
                    sell_net if sell_net >= 0 else None,
                    net_return,
                    opened_at,
                    closed_at,
                ),
            )

        if buy_cost <= 0 or sell_net < 0:
            record_attempt("skipped", "invalid_cashflows")
            return
        net_return = (sell_net - buy_cost) / buy_cost
        if position.decision_id is None:
            record_attempt("skipped", "legacy_missing_decision", net_return=net_return)
            return
        if position.cohort_id is None:
            record_attempt("skipped", "missing_admitted_cohort", net_return=net_return)
            return
        cohort = self.db.execute(
            """
            SELECT id,decision_at FROM shadow_event_cohorts
            WHERE id=? AND decision_id=? AND event_id=? AND token_id=?
            """,
            (
                int(position.cohort_id),
                int(position.decision_id),
                int(position.event_id),
                str(position.token_id),
            ),
        ).fetchone()
        if cohort is None:
            record_attempt("skipped", "cohort_link_mismatch", net_return=net_return)
            return
        decision_at = str(cohort["decision_at"])
        leads = list(
            self.db.execute(
                """
                SELECT DISTINCT o.id,o.source,o.source_kind,o.role,o.observed_at,o.raw_json,
                       e.topic AS event_topic
                FROM observations o
                JOIN shadow_event_cohort_labels l ON l.source_observation_id=o.id
                JOIN events e ON e.id=?
                WHERE l.cohort_id=? AND o.capture_phase='live'
                  AND o.role IN ('feature','confirmation')
                  AND o.observed_at<=? AND o.ingested_at<=?
                  AND (o.published_at IS NULL OR o.published_at<=?)
                ORDER BY o.observed_at,o.id
                """,
                (int(position.event_id), int(position.cohort_id), decision_at, decision_at, decision_at),
            )
        )
        if not leads:
            record_attempt("skipped", "no_eligible_cohort_sources", net_return=net_return)
            return
        weight = 1.0 / len(leads)
        for row in leads:
            labels = self._source_learning_labels(row)
            platform = next((value for dimension, value in labels if dimension == "platform"), "")
            for dimension, value in labels:
                self.db.execute(
                    """
                    INSERT OR IGNORE INTO source_utility_outcomes(
                        outcome_key,event_id,token_id,decision_id,cohort_id,attribution_version,
                        source_observation_id,dimension,value,origin_platform,attribution_basis,
                        attribution_weight,net_return,opened_at,closed_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        outcome_key,
                        int(position.event_id),
                        str(position.token_id),
                        int(position.decision_id),
                        int(position.cohort_id),
                        self.PAPER_SOURCE_ATTRIBUTION_VERSION,
                        int(row["id"]),
                        dimension,
                        value,
                        platform,
                        "discovery_lead",
                        weight,
                        net_return,
                        opened_at,
                        closed_at,
                    ),
                )
        record_attempt(
            "attributed",
            "attributed_admitted_cohort",
            eligible_source_count=len(leads),
            net_return=net_return,
        )

    def source_learning_summary(self, **kwargs: Any) -> dict[str, Any]:
        with self._lock:
            return self.source_learning_summary_from_connection(self.db, **kwargs)

    @classmethod
    def source_learning_summary_from_connection(
        cls,
        connection: sqlite3.Connection,
        *,
        lookback_days: int = 90,
        min_closed_outcomes: float = 20,
        min_event_days: int = 10,
        min_losing_outcomes: int = 5,
        entity_min_closed_outcomes: float = 30,
        entity_min_event_days: int = 15,
        entity_min_platforms: int = 2,
    ) -> dict[str, Any]:
        """Describe forward source usefulness; only mature closed-Paper outcomes activate rotation hints."""
        now = utcnow()
        start = iso(now - timedelta(days=max(1, min(3650, int(lookback_days)))))
        observation_rows = list(
                connection.execute(
                    """
                    SELECT o.id,o.source,o.source_kind,o.role,o.published_at,o.observed_at,
                           o.ingested_at,o.raw_json,eo.event_id,
                           e.topic AS event_topic
                    FROM observations o
                    LEFT JOIN event_observations eo ON eo.observation_id=o.id
                    LEFT JOIN events e ON e.id=eo.event_id
                    WHERE o.capture_phase='live' AND o.observed_at>=?
                    ORDER BY o.observed_at,o.id
                    """,
                    (start,),
                )
            )
        decision_rows = list(
                connection.execute(
                    "SELECT id,event_id,action,created_at FROM decisions WHERE created_at>=?",
                    (start,),
                )
            )
        has_outcomes = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='source_utility_outcomes'"
        ).fetchone() is not None
        outcome_rows = (
            list(
                connection.execute(
                    "SELECT * FROM source_utility_outcomes WHERE closed_at>=? ORDER BY closed_at,id",
                    (start,),
                )
            )
            if has_outcomes else []
        )
        exact_outcome_rows = [
            row for row in outcome_rows
            if str(row["attribution_version"] or "") == cls.PAPER_SOURCE_ATTRIBUTION_VERSION
        ]
        legacy_outcome_rows = [
            row for row in outcome_rows
            if str(row["attribution_version"] or "") != cls.PAPER_SOURCE_ATTRIBUTION_VERSION
        ]
        has_attribution_attempts = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='paper_source_attribution_attempts'"
        ).fetchone() is not None
        attribution_attempts = (
            list(
                connection.execute(
                    "SELECT * FROM paper_source_attribution_attempts "
                    "WHERE closed_at>=? ORDER BY closed_at,outcome_key",
                    (start,),
                )
            )
            if has_attribution_attempts else []
        )

        candidate_events = {
            int(row["event_id"]) for row in decision_rows
            if str(row["action"] or "").upper() == "CANDIDATE"
        }
        candidate_times: dict[int, Any] = {}
        for row in decision_rows:
            if str(row["action"] or "").upper() != "CANDIDATE":
                continue
            event_id = int(row["event_id"])
            created_at = parse_time(row["created_at"])
            previous = candidate_times.get(event_id)
            if previous is None or created_at < previous:
                candidate_times[event_id] = created_at
        event_first_eligible: dict[int, Any] = {}
        records: list[tuple[sqlite3.Row, list[tuple[str, str]], int | None, bool]] = []
        for row in observation_rows:
            event_id = int(row["event_id"]) if row["event_id"] is not None else None
            observed = parse_time(row["observed_at"])
            candidate_at = candidate_times.get(event_id) if event_id is not None else None
            eligible = bool(
                candidate_at is not None
                and str(row["role"] or "").lower() in {"feature", "confirmation"}
                and observed <= candidate_at
                and parse_time(row["ingested_at"]) <= candidate_at
                and (
                    row["published_at"] is None
                    or parse_time(row["published_at"]) <= candidate_at
                )
            )
            if event_id is not None and eligible:
                previous = event_first_eligible.get(event_id)
                if previous is None or observed < previous:
                    event_first_eligible[event_id] = observed
            records.append((row, cls._source_learning_labels(row), event_id, eligible))

        diagnostic: dict[tuple[str, str], dict[str, Any]] = {}
        for row, labels, event_id, eligible in records:
            observed = parse_time(row["observed_at"])
            role = str(row["role"] or "").lower()
            for key in labels:
                metric = diagnostic.setdefault(
                    key,
                    {
                        "observations": 0, "eligible_observations": 0, "context_observations": 0,
                        "feature_observations": 0, "confirmation_observations": 0,
                        "identity_observations": 0, "promotion_observations": 0,
                        "events": set(), "early_events": set(), "candidate_events": set(), "last_observed_at": None,
                    },
                )
                metric["observations"] += 1
                metric["eligible_observations" if eligible else "context_observations"] += 1
                role_key = f"{role}_observations"
                if role_key in metric:
                    metric[role_key] += 1
                metric["last_observed_at"] = max(str(metric["last_observed_at"] or ""), str(row["observed_at"]))
                if event_id is not None:
                    metric["events"].add(event_id)
                    if eligible and event_id in candidate_events:
                        metric["candidate_events"].add(event_id)
                    first = event_first_eligible.get(event_id)
                    if eligible and first is not None and (observed - first).total_seconds() <= 60:
                        metric["early_events"].add(event_id)

        outcomes: dict[tuple[str, str], dict[str, Any]] = {}
        decision_support_outcomes: dict[tuple[str, str], dict[str, Any]] = {}
        for row in exact_outcome_rows:
            key = (str(row["dimension"]), str(row["value"]))
            basis = str(row["attribution_basis"] or "discovery_lead")
            target = decision_support_outcomes if basis == "decision_support" else outcomes
            metric = target.setdefault(
                key,
                {
                    "weighted_closed": 0.0, "weighted_wins": 0.0, "weighted_losses": 0.0,
                    "weighted_downside": 0.0, "weighted_return": 0.0,
                    "outcome_keys": set(), "event_ids": set(), "event_days": set(),
                    "platforms": set(), "last_closed_at": None,
                },
            )
            weight = max(0.0, float(row["attribution_weight"] or 0))
            net_return = float(row["net_return"] or 0)
            metric["weighted_closed"] += weight
            metric["weighted_wins"] += weight if net_return > 0 else 0.0
            metric["weighted_losses"] += weight if net_return <= 0 else 0.0
            metric["weighted_downside"] += weight if net_return <= -0.25 else 0.0
            metric["weighted_return"] += weight * net_return
            metric["outcome_keys"].add(str(row["outcome_key"]))
            metric["event_ids"].add(int(row["event_id"]))
            metric["event_days"].add(str(row["opened_at"])[:10])
            if row["origin_platform"]:
                metric["platforms"].add(str(row["origin_platform"]))
            metric["last_closed_at"] = max(str(metric["last_closed_at"] or ""), str(row["closed_at"]))

        items: list[dict[str, Any]] = []
        all_keys = set(diagnostic) | set(outcomes) | set(decision_support_outcomes)
        for dimension, value in all_keys:
            observed = diagnostic.get((dimension, value), {})
            outcome = outcomes.get((dimension, value), {})
            decision_support = decision_support_outcomes.get((dimension, value), {})
            event_count = len(observed.get("events", set()))
            early_count = len(observed.get("early_events", set()))
            candidate_count = len(observed.get("candidate_events", set()))
            observations = int(observed.get("observations", 0))
            eligible_observations = int(observed.get("eligible_observations", 0))
            weighted_closed = float(outcome.get("weighted_closed", 0.0))
            mean_return = (
                float(outcome.get("weighted_return", 0.0)) / weighted_closed if weighted_closed > 0 else None
            )
            win_rate = (
                float(outcome.get("weighted_wins", 0.0)) / weighted_closed if weighted_closed > 0 else None
            )
            downside_rate = (
                float(outcome.get("weighted_downside", 0.0)) / weighted_closed if weighted_closed > 0 else None
            )
            required_closed = entity_min_closed_outcomes if dimension == "entity" else min_closed_outcomes
            required_days = entity_min_event_days if dimension == "entity" else min_event_days
            platform_count = len(outcome.get("platforms", set()))
            active = (
                weighted_closed >= required_closed
                and len(outcome.get("event_days", set())) >= required_days
                and float(outcome.get("weighted_losses", 0.0)) >= min_losing_outcomes
                and (dimension != "entity" or platform_count >= entity_min_platforms)
                and dimension in {"platform", "source_kind", "entity", "source"}
            )
            shrunk_utility = 0.0
            if mean_return is not None:
                shrunk_utility = weighted_closed / (weighted_closed + 20.0) * mean_return
            multiplier = 1.0 if not active else max(0.75, min(1.25, 1.0 + shrunk_utility * 0.5))
            confidence = min(1.0, weighted_closed / max(1.0, float(required_closed)))
            support_weighted_closed = float(decision_support.get("weighted_closed", 0.0))
            support_mean_return = (
                float(decision_support.get("weighted_return", 0.0)) / support_weighted_closed
                if support_weighted_closed > 0 else None
            )
            support_win_rate = (
                float(decision_support.get("weighted_wins", 0.0)) / support_weighted_closed
                if support_weighted_closed > 0 else None
            )
            items.append(
                {
                    "dimension": dimension,
                    "value": value,
                    "observations": observations,
                    "eligible_observations": eligible_observations,
                    "decision_eligible_observations": eligible_observations,
                    "context_observations": int(observed.get("context_observations", 0)),
                    "feature_observations": int(observed.get("feature_observations", 0)),
                    "confirmation_observations": int(observed.get("confirmation_observations", 0)),
                    "identity_observations": int(observed.get("identity_observations", 0)),
                    "promotion_observations": int(observed.get("promotion_observations", 0)),
                    "event_count": event_count,
                    "early_event_count": early_count,
                    "early_event_rate": round(early_count / event_count, 4) if event_count else None,
                    "eligible_observation_rate": round(eligible_observations / observations, 4) if observations else None,
                    "candidate_event_count": candidate_count if decision_rows else None,
                    "candidate_event_rate": round(candidate_count / event_count, 4) if event_count and decision_rows else None,
                    "weighted_closed_paper_outcomes": round(weighted_closed, 4),
                    "weighted_losing_paper_outcomes": round(float(outcome.get("weighted_losses", 0.0)), 4),
                    "distinct_closed_paper_outcomes": len(outcome.get("outcome_keys", set())),
                    "distinct_closed_event_count": len(outcome.get("event_ids", set())),
                    "paper_win_rate": round(win_rate, 4) if win_rate is not None else None,
                    "paper_mean_net_return": round(mean_return, 6) if mean_return is not None else None,
                    "paper_downside_rate": round(downside_rate, 4) if downside_rate is not None else None,
                    "decision_support_weighted_closed_paper_outcomes": round(support_weighted_closed, 4),
                    "decision_support_distinct_closed_paper_outcomes": len(
                        decision_support.get("outcome_keys", set())
                    ),
                    "decision_support_paper_win_rate": (
                        round(support_win_rate, 4) if support_win_rate is not None else None
                    ),
                    "decision_support_paper_mean_net_return": (
                        round(support_mean_return, 6) if support_mean_return is not None else None
                    ),
                    "event_day_count": len(outcome.get("event_days", set())),
                    "platform_count": platform_count,
                    "confidence": round(confidence, 4),
                    "maturity_progress": round(confidence, 4),
                    "rotation_active": active,
                    "rotation_multiplier": round(multiplier, 4),
                    "last_observed_at": observed.get("last_observed_at"),
                    "last_closed_at": outcome.get("last_closed_at"),
                }
            )
        items.sort(
            key=lambda item: (
                not bool(item["rotation_active"]),
                -float(item["rotation_multiplier"]),
                -float(item["confidence"]),
                -int(item["event_count"]),
                str(item["dimension"]),
                str(item["value"]).casefold(),
            )
        )
        return {
            "status": "learning_active" if any(item["rotation_active"] for item in items) else "collecting_samples",
            "lookback_days": int(lookback_days),
            "items": items[:500],
            "summary": {
                "observations": len(observation_rows),
                "decisions": len(decision_rows),
                "closed_paper_outcomes": len({
                    str(row["outcome_key"]) for row in exact_outcome_rows
                    if str(row["attribution_basis"] or "discovery_lead") != "decision_support"
                }),
                "decision_support_outcomes": len({
                    str(row["outcome_key"]) for row in exact_outcome_rows
                    if str(row["attribution_basis"] or "discovery_lead") == "decision_support"
                }),
                "legacy_event_window_outcomes": len({
                    str(row["outcome_key"]) for row in legacy_outcome_rows
                }),
                "closed_attribution_attempts": len(attribution_attempts),
                "attributed_closed_outcomes": sum(
                    1 for row in attribution_attempts if str(row["status"]) == "attributed"
                ),
                "unattributed_closed_outcomes": sum(
                    1 for row in attribution_attempts if str(row["status"]) != "attributed"
                ),
                "closed_attribution_coverage_rate": (
                    round(
                        sum(1 for row in attribution_attempts if str(row["status"]) == "attributed")
                        / len(attribution_attempts),
                        4,
                    )
                    if attribution_attempts else None
                ),
                "attribution_skip_reasons": [
                    {"reason": reason, "count": count}
                    for reason, count in sorted(
                        {
                            str(row["reason"]): sum(
                                1 for item in attribution_attempts
                                if str(item["status"]) != "attributed"
                                and str(item["reason"]) == str(row["reason"])
                            )
                            for row in attribution_attempts
                            if str(row["status"]) != "attributed"
                        }.items()
                    )
                ],
                "active_labels": sum(1 for item in items if item["rotation_active"]),
            },
            "activation_policy": {
                "minimum_closed_outcomes": float(min_closed_outcomes),
                "minimum_event_days": int(min_event_days),
                "minimum_losing_outcomes": int(min_losing_outcomes),
                "entity_minimum_closed_outcomes": float(entity_min_closed_outcomes),
                "entity_minimum_event_days": int(entity_min_event_days),
                "entity_minimum_platforms": int(entity_min_platforms),
                "maximum_rotation_multiplier": 1.25,
                "minimum_exploration_fraction": 0.40,
                "affects": "agent_watch_rotation_only",
                "rotation_basis": "discovery_lead",
                "paper_attribution_version": cls.PAPER_SOURCE_ATTRIBUTION_VERSION,
                "paper_attribution_scope": "selected_closed_paper_decision_cohort_only",
                "legacy_outcomes_affect_learning": False,
                "decision_support_affects": "descriptive_only",
            },
            "as_of": iso(now),
        }

    @classmethod
    def _shadow_strategy_labels(
        cls,
        decision: CandidateDecision,
        *,
        event: Mapping[str, Any],
        token: Mapping[str, Any],
        snapshot: Mapping[str, Any],
        leads: Iterable[Mapping[str, Any]],
    ) -> list[tuple[str, str]]:
        """Freeze coarse decision-time research strata; none of them changes strategy."""

        def number(row: Mapping[str, Any], name: str) -> float | None:
            try:
                value = row[name]
            except (KeyError, IndexError, TypeError):
                return None
            try:
                return float(value) if value is not None else None
            except (TypeError, ValueError):
                return None

        def bucket(value: float | None, cuts: tuple[float, ...], names: tuple[str, ...]) -> str:
            if value is None:
                return "unknown"
            for index, cut in enumerate(cuts):
                if value < cut:
                    return names[index]
            return names[-1]

        decision_at = parse_time(decision.created_at)
        first_seen = parse_time(event["first_seen_at"])
        token_created = parse_time(token["created_at"]) if token["created_at"] else None
        lead_rows = list(leads)
        origins: set[str] = set()
        feature_count = 0
        confirmation_count = 0
        public_figure_context = "none_observed"
        for row in lead_rows:
            labels = dict(cls._source_learning_labels(row))
            origin = labels.get("entity") or labels.get("source") or labels.get("source_kind")
            if origin:
                origins.add(origin)
            role = str(row["role"] or "").lower()
            feature_count += int(role == "feature")
            confirmation_count += int(role == "confirmation")
            account_type = labels.get("account_type", "")
            if account_type in {
                "public_figure", "politician", "celebrity", "executive", "institution",
                "official", "government",
            }:
                public_figure_context = "context_candidate"
            try:
                raw = json.loads(str(row["raw_json"] or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError):
                raw = {}
            if isinstance(raw, dict) and str(raw.get("verification_status") or "") == "browser_exact_entity_observation":
                public_figure_context = "verified_original_observation"

        buys = number(snapshot, "buys_5m") or 0.0
        sells = number(snapshot, "sells_5m") or 0.0
        transactions = buys + sells
        buy_ratio = buys / transactions if transactions > 0 else None
        safety = "unknown"
        if snapshot["honeypot"] is not None and bool(snapshot["honeypot"]):
            safety = "honeypot"
        elif snapshot["sellable"] is not None and not bool(snapshot["sellable"]):
            safety = "not_sellable"
        elif snapshot["honeypot"] is False and snapshot["sellable"] is True:
            safety = "checked_clear"
        elif snapshot["honeypot"] is False or snapshot["sellable"] is True:
            safety = "partially_checked"

        evidence_mix = (
            "feature_and_confirmation" if feature_count and confirmation_count
            else "feature_only" if feature_count
            else "confirmation_only" if confirmation_count
            else "none"
        )
        event_age_minutes = max(0.0, (decision_at - first_seen).total_seconds() / 60.0)
        token_age_minutes = (
            max(0.0, (decision_at - token_created).total_seconds() / 60.0)
            if token_created is not None else None
        )
        labels = [
            ("event_topic", str(event["topic"] or "unknown")),
            ("attention_bucket", bucket(number(event, "attention"), (50, 70, 85), ("lt50", "50_69", "70_84", "85_plus"))),
            ("event_age_bucket", bucket(event_age_minutes, (5, 30, 120), ("lt5m", "5_29m", "30_119m", "120m_plus"))),
            ("eligible_origin_bucket", bucket(float(len(origins)), (2, 3, 5), ("one", "two", "three_four", "five_plus"))),
            ("evidence_mix", evidence_mix),
            ("public_figure_context", public_figure_context),
            ("chain", str(token["chain"] or "unknown").lower()),
            ("token_age_bucket", bucket(token_age_minutes, (5, 30, 120), ("lt5m", "5_29m", "30_119m", "120m_plus"))),
            ("liquidity_bucket", bucket(number(snapshot, "liquidity_usd"), (5_000, 25_000, 100_000), ("lt5k", "5k_25k", "25k_100k", "100k_plus"))),
            ("market_cap_bucket", bucket(number(snapshot, "market_cap_usd"), (50_000, 250_000, 1_000_000), ("lt50k", "50k_250k", "250k_1m", "1m_plus"))),
            ("volume_5m_bucket", bucket(number(snapshot, "volume_5m_usd"), (1_000, 10_000, 50_000), ("lt1k", "1k_10k", "10k_50k", "50k_plus"))),
            ("buy_pressure_bucket", bucket(buy_ratio, (0.45, 0.55, 0.70), ("sell_dominant", "balanced", "buy_leaning", "buy_dominant"))),
            ("safety_state", safety),
            ("candidate_score_bucket", bucket(float(decision.score), (60, 75, 90), ("lt60", "60_74", "75_89", "90_plus"))),
            ("match_score_bucket", bucket(float(decision.match_score), (60, 80, 95), ("lt60", "60_79", "80_94", "95_plus"))),
            ("canonical_margin_bucket", bucket(float(decision.canonical_margin), (3, 8, 15), ("lt3", "3_7", "8_14", "15_plus"))),
            ("requested_position_bucket", bucket(float(decision.position_usd), (1, 10, 25), ("zero", "lt10", "10_24", "25_plus"))),
        ]
        labels.extend(
            ("decision_reason", re.sub(r"[^a-z0-9_-]", "_", str(reason).lower())[:120] or "unknown")
            for reason in decision.rejected_reasons
        )
        return list(dict.fromkeys(labels))

    def create_shadow_event_cohort(
        self,
        decision: CandidateDecision,
        *,
        decision_id: int,
        source_observation_ids: Iterable[int],
    ) -> int | None:
        """Freeze the first WAIT/REJECT/CANDIDATE per event without changing strategy."""
        action = str(decision.action).upper()
        admission_key = f"{self.SHADOW_EVENT_ADMISSION_VERSION}:{int(decision_id)}"
        cohort_key = hashlib.sha256(
            f"{self.SHADOW_EVENT_COHORT_VERSION}\n{int(decision.event_id)}\n{action}".encode("utf-8")
        ).hexdigest()
        decision_at = iso(decision.created_at)
        with self._lock, self.db:
            prior_admission = self.db.execute(
                "SELECT cohort_id FROM shadow_event_admission_attempts WHERE admission_key=?",
                (admission_key,),
            ).fetchone()
            if prior_admission is not None:
                return int(prior_admission["cohort_id"]) if prior_admission["cohort_id"] else None

            observation_ids: list[int] = []

            def record_admission(
                status: str,
                reason: str,
                *,
                cohort_id: int | None = None,
                eligible_source_count: int = 0,
            ) -> None:
                self.db.execute(
                    """
                    INSERT INTO shadow_event_admission_attempts(
                        admission_key,version,decision_id,event_id,token_id,requested_action,
                        status,reason,cohort_id,source_observation_count,eligible_source_count,attempted_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        admission_key,
                        self.SHADOW_EVENT_ADMISSION_VERSION,
                        int(decision_id),
                        int(decision.event_id),
                        str(decision.token_id or ""),
                        action,
                        str(status),
                        str(reason),
                        cohort_id,
                        len(observation_ids),
                        max(0, int(eligible_source_count)),
                        iso(),
                    ),
                )

            if action not in {"WAIT", "REJECT", "CANDIDATE"}:
                record_admission("skipped", "unsupported_action")
                return None
            if not decision.token_id:
                record_admission("skipped", "missing_token_id")
                return None
            observation_ids = sorted({
                int(value) for value in source_observation_ids if int(value) > 0
            })
            existing = list(
                self.db.execute(
                    "SELECT id,action FROM shadow_event_cohorts WHERE event_id=? ORDER BY id",
                    (int(decision.event_id),),
                )
            )
            same_action = next(
                (row for row in existing if str(row["action"]).upper() == action), None
            )
            if same_action:
                cohort_id = int(same_action["id"])
                record_admission(
                    "already_admitted", "already_admitted_same_action", cohort_id=cohort_id
                )
                return cohort_id
            if action == "WAIT":
                candidate = next(
                    (row for row in existing if str(row["action"]).upper() == "CANDIDATE"), None
                )
                if candidate:
                    cohort_id = int(candidate["id"])
                    record_admission(
                        "already_admitted", "wait_superseded_by_candidate", cohort_id=cohort_id
                    )
                    return cohort_id
            snapshot = self.db.execute(
                """
                SELECT * FROM token_snapshots
                WHERE token_id=? AND observed_at<=? AND ingested_at<=?
                  AND ingested_at>=observed_at AND price_usd>0
                ORDER BY observed_at DESC,id DESC LIMIT 1
                """,
                (decision.token_id, decision_at, decision_at),
            ).fetchone()
            if snapshot is None:
                record_admission("skipped", "missing_entry_snapshot")
                return None
            if not observation_ids:
                record_admission("skipped", "missing_observation_ids")
                return None
            placeholders = ",".join("?" for _ in observation_ids)
            eligible = list(
                self.db.execute(
                    f"""
                    SELECT o.id,o.source,o.source_kind,o.role,o.observed_at,o.raw_json,
                           e.topic AS event_topic
                    FROM observations o
                    JOIN event_observations eo ON eo.observation_id=o.id
                    JOIN events e ON e.id=eo.event_id
                    WHERE eo.event_id=? AND o.id IN ({placeholders})
                      AND o.capture_phase='live' AND o.role IN ('feature','confirmation')
                      AND o.observed_at<=? AND o.ingested_at<=?
                      AND (o.published_at IS NULL OR o.published_at<=?)
                    ORDER BY o.observed_at,o.id
                    """,
                    (int(decision.event_id), *observation_ids, decision_at, decision_at, decision_at),
                )
            )
            if not eligible:
                record_admission("skipped", "no_eligible_leads")
                return None
            first_at = parse_time(eligible[0]["observed_at"])
            leads = [
                row for row in eligible
                if (parse_time(row["observed_at"]) - first_at).total_seconds() <= 60
            ]
            if not leads:
                record_admission("skipped", "no_eligible_leads")
                return None
            event_row = self.db.execute(
                "SELECT * FROM events WHERE id=?", (int(decision.event_id),)
            ).fetchone()
            token_row = self.db.execute(
                "SELECT * FROM tokens WHERE token_id=?", (decision.token_id,)
            ).fetchone()
            if event_row is None or token_row is None:
                record_admission("skipped", "missing_event_or_token")
                return None
            cursor = self.db.execute(
                """
                INSERT INTO shadow_event_cohorts(
                    cohort_key,version,event_id,token_id,decision_id,action,decision_at,
                    entry_snapshot_id,entry_snapshot_at,entry_price,eligible_source_count,status,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,'pending',?)
                """,
                (
                    cohort_key, self.SHADOW_EVENT_COHORT_VERSION, int(decision.event_id), decision.token_id,
                    int(decision_id), action, decision_at, int(snapshot["id"]),
                    str(snapshot["observed_at"]), float(snapshot["price_usd"]), len(leads), iso(),
                ),
            )
            cohort_id = int(cursor.lastrowid)
            weight = 1.0 / len(leads)
            for row in leads:
                labels = self._source_learning_labels(row)
                platform = next((value for dimension, value in labels if dimension == "platform"), "")
                for dimension, value in labels:
                    self.db.execute(
                        """
                        INSERT INTO shadow_event_cohort_labels(
                            cohort_id,source_observation_id,dimension,value,origin_platform,attribution_weight
                        ) VALUES(?,?,?,?,?,?)
                        """,
                        (cohort_id, int(row["id"]), dimension, value, platform, weight),
                    )
            for dimension, value in self._shadow_strategy_labels(
                decision, event=event_row, token=token_row, snapshot=snapshot, leads=leads
            ):
                self.db.execute(
                    """
                    INSERT INTO shadow_event_cohort_labels(
                        cohort_id,source_observation_id,dimension,value,origin_platform,attribution_weight
                    ) VALUES(?,0,?,?,?,1)
                    """,
                    (cohort_id, dimension, value, ""),
                )
            record_admission(
                "created", "created", cohort_id=cohort_id,
                eligible_source_count=len(leads),
            )
            return cohort_id

    def finalize_shadow_event_outcomes(
        self,
        *,
        now: Any = None,
        horizons_minutes: Iterable[int] | None = None,
        max_lateness_minutes: int = 30,
    ) -> dict[str, int]:
        """Append fixed-horizon market follow-through using only snapshots already observed locally."""
        evaluated_at = parse_time(now or utcnow())
        horizons = tuple(
            sorted({max(1, int(value)) for value in (horizons_minutes or self.SHADOW_EVENT_HORIZONS_MINUTES)})
        )
        observed_count = 0
        missing_count = 0
        completed_count = 0
        with self._lock, self.db:
            cohorts = list(
                self.db.execute(
                    "SELECT * FROM shadow_event_cohorts WHERE status='pending' ORDER BY decision_at,id"
                )
            )
            for cohort in cohorts:
                existing = {
                    int(row["horizon_minutes"])
                    for row in self.db.execute(
                        "SELECT horizon_minutes FROM shadow_event_outcomes WHERE cohort_id=?",
                        (int(cohort["id"]),),
                    )
                }
                for horizon in horizons:
                    if horizon in existing:
                        continue
                    target = parse_time(cohort["decision_at"]) + timedelta(minutes=horizon)
                    if evaluated_at < target:
                        continue
                    deadline = target + timedelta(minutes=max(1, int(max_lateness_minutes)))
                    upper = min(evaluated_at, deadline)
                    snapshot = self.db.execute(
                        """
                        SELECT id,observed_at,ingested_at,price_usd FROM token_snapshots
                        WHERE token_id=? AND observed_at>=? AND observed_at<=?
                          AND ingested_at>=? AND ingested_at<=?
                          AND ingested_at>=observed_at AND price_usd>0
                        ORDER BY ingested_at,observed_at,id LIMIT 1
                        """,
                        (
                            str(cohort["token_id"]), iso(target), iso(upper),
                            iso(target), iso(upper),
                        ),
                    ).fetchone()
                    if snapshot is not None:
                        path = list(
                            self.db.execute(
                                """
                                SELECT price_usd FROM token_snapshots
                                WHERE token_id=? AND observed_at>=? AND observed_at<=?
                                  AND ingested_at IS NOT NULL AND ingested_at<=?
                                  AND ingested_at>=observed_at AND price_usd>0
                                ORDER BY observed_at,id
                                """,
                                (
                                    str(cohort["token_id"]), str(cohort["entry_snapshot_at"]),
                                    str(snapshot["observed_at"]), str(snapshot["ingested_at"]),
                                ),
                            )
                        )
                        entry_price = float(cohort["entry_price"])
                        returns = [float(row["price_usd"]) / entry_price - 1.0 for row in path]
                        raw_return = float(snapshot["price_usd"]) / entry_price - 1.0
                        self.db.execute(
                            """
                            INSERT INTO shadow_event_outcomes(
                                cohort_id,horizon_minutes,target_at,status,outcome_snapshot_id,
                                outcome_observed_at,outcome_price,raw_return,maximum_return,minimum_return,
                                snapshot_count,evaluated_at
                            ) VALUES(?,?,?,'observed',?,?,?,?,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), horizon, iso(target), int(snapshot["id"]),
                                str(snapshot["observed_at"]), float(snapshot["price_usd"]), raw_return,
                                max(returns) if returns else raw_return, min(returns) if returns else raw_return,
                                len(path), iso(evaluated_at),
                            ),
                        )
                        observed_count += 1
                    elif evaluated_at >= deadline:
                        self.db.execute(
                            """
                            INSERT INTO shadow_event_outcomes(
                                cohort_id,horizon_minutes,target_at,status,snapshot_count,evaluated_at
                            ) VALUES(?,?,?,'missing',0,?)
                            """,
                            (int(cohort["id"]), horizon, iso(target), iso(evaluated_at)),
                        )
                        missing_count += 1
                outcome_total = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM shadow_event_outcomes WHERE cohort_id=?",
                        (int(cohort["id"]),),
                    ).fetchone()[0]
                )
                if outcome_total >= len(horizons):
                    self.db.execute(
                        "UPDATE shadow_event_cohorts SET status='complete' WHERE id=?",
                        (int(cohort["id"]),),
                    )
                    completed_count += 1
        return {
            "cohorts_checked": len(cohorts),
            "outcomes_observed": observed_count,
            "outcomes_missing": missing_count,
            "cohorts_completed": completed_count,
        }

    @classmethod
    def _kol_token_addressability_definition(cls) -> dict[str, Any]:
        return {
            "version": cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
            "activation": "observation_id_strictly_after_registration",
            "eligible_episode": {
                "capture_phase": "live",
                "availability_proof": "local_receive",
                "roles": ["feature", "confirmation"],
                "minimum_configured_priority": cls.KOL_TOKEN_ADDRESSABILITY_MIN_PRIORITY,
                "maximum_event_attention": cls.KOL_TOKEN_ADDRESSABILITY_MAX_ATTENTION,
                "event_attention_operator": "lt",
                "maximum_source_age_minutes": cls.KOL_TOKEN_ADDRESSABILITY_MAX_SOURCE_AGE_MINUTES,
            },
            "event_attention_point": {
                "table": "event_attention_points",
                "definition_version": cls.EVENT_ATTENTION_TRAJECTORY_VERSION,
                "coverage_mode": "local_new_observation_arrivals_only",
                "join_key": ["event_id", "observation_id"],
                "required_trigger_decision_eligible": True,
                "required_exclusion_reason": None,
                "signal_clock": "max_observed_ingested_attention_recorded",
            },
            "main_denominator_includes": [
                "explicit_identifier_at_signal", "no_seed_at_signal",
            ],
            "query_policy": "exact_identifier_only_no_ticker_or_alias_search",
            "evm_chain_hints": {
                "ethereum": ["ethereum", " eth "],
                "bsc": ["bsc", "bnb chain", "bnbchain"],
                "base": ["base chain", "on base", "base ca"],
                "arbitrum": ["arbitrum"],
                "optimism": ["optimism"],
                "polygon": ["polygon"],
                "avalanche": ["avalanche", "avax"],
            },
            "ambiguous_evm_policy": "retain_in_denominator_no_unique_addressability",
            "append_only": True,
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "none",
        }

    @staticmethod
    def _canonical_solana_address(value: Any) -> str | None:
        address = str(value or "").strip()
        if not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", address):
            return None
        try:
            canonical = str(Pubkey.from_string(address))
        except ValueError:
            return None
        return canonical if canonical == address else None

    @classmethod
    def _extract_canonical_solana_addresses(cls, value: Any) -> set[str]:
        text = str(value or "")
        candidates = re.findall(
            r"(?<![1-9A-HJ-NP-Za-km-z])([1-9A-HJ-NP-Za-km-z]{32,44})"
            r"(?![1-9A-HJ-NP-Za-km-z])",
            text,
        )
        return {
            canonical for candidate in candidates
            if (canonical := cls._canonical_solana_address(candidate)) is not None
        }

    def _kol_token_addressability_route_definition(self) -> dict[str, Any]:
        base_registration = self.db.execute(
            "SELECT definition_json FROM kol_token_addressability_registrations "
            "WHERE definition_version=?",
            (self.KOL_TOKEN_ADDRESSABILITY_VERSION,),
        ).fetchone()
        base_definition_json = str(base_registration["definition_json"]) if base_registration else ""
        return {
            "version": self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            "compatible_base_definition_version": self.KOL_TOKEN_ADDRESSABILITY_VERSION,
            "compatible_base_definition_hash": hashlib.sha256(
                base_definition_json.encode("utf-8")
            ).hexdigest(),
            "activation": "cohort_id_strictly_after_registration",
            "router": "jupiter_quote_only",
            "input_mint": self.JUPITER_USDC_MINT,
            "input_amount_raw": str(self.KOL_TOKEN_ADDRESSABILITY_USDC_INPUT_AMOUNT_RAW),
            "slippage_bps": self.KOL_TOKEN_ADDRESSABILITY_SLIPPAGE_BPS,
            "route_deadline_seconds_after_signal": (
                self.KOL_TOKEN_ADDRESSABILITY_ROUTE_DEADLINE_SECONDS
            ),
            "confirmation_window_minutes": (
                self.KOL_TOKEN_ADDRESSABILITY_CONFIRMATION_WINDOW_MINUTES
            ),
            "surface_policy": [
                "single_hop_exact", "multi_hop_includes_frozen_pair", "unmapped",
            ],
            "canonical_identifier_policy": "solana_pubkey_32_bytes_exact_boundary",
            "timing_policy": [
                "pair_timely", "dex_pair_late", "dex_pair_missing_by_deadline",
                "request_timely", "queue_delay_expired", "response_timely",
                "route_response_late", "clock_invalid",
            ],
            "scheduler_policy": "shared_background_edf_three_requests_per_epoch",
            "attempt_first": True,
            "append_only": True,
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "none",
        }

    def create_kol_token_addressability_cohort(
        self,
        event_id: int,
        observation_id: int,
        *,
        account: Mapping[str, Any],
        identifiers: Mapping[str, Iterable[str]] | None = None,
        recorded_at: Any = None,
    ) -> int | None:
        """Freeze one post-signal addressability episode without network I/O.

        No-seed episodes are retained in the same main denominator. Only exact
        identifiers available in the triggering observation are frozen; ticker,
        alias, later price, and later token popularity are never consulted.
        """
        recorded = parse_time(recorded_at or utcnow())
        recorded_text = iso(recorded)
        admission_key = f"{self.KOL_TOKEN_ADDRESSABILITY_VERSION}:{int(observation_id)}"
        with self._lock, self.db:
            prior = self.db.execute(
                "SELECT cohort_id FROM kol_token_addressability_admission_attempts "
                "WHERE admission_key=?",
                (admission_key,),
            ).fetchone()
            if prior is not None:
                return int(prior["cohort_id"]) if prior["cohort_id"] else None

            def record_admission(status: str, reason: str, cohort_id: int | None = None) -> None:
                self.db.execute(
                    """
                    INSERT INTO kol_token_addressability_admission_attempts(
                        admission_key,definition_version,observation_id,event_id,attempted_at,
                        status,reason,cohort_id,decision_eligible,affects
                    ) VALUES(?,?,?,?,?,?,?,?,0,'none')
                    """,
                    (
                        admission_key, self.KOL_TOKEN_ADDRESSABILITY_VERSION,
                        int(observation_id), int(event_id), recorded_text,
                        status, reason, cohort_id,
                    ),
                )

            registration = self.db.execute(
                "SELECT * FROM kol_token_addressability_registrations WHERE definition_version=?",
                (self.KOL_TOKEN_ADDRESSABILITY_VERSION,),
            ).fetchone()
            if registration is None:
                record_admission("skipped", "registration_missing")
                return None
            try:
                definition = json.loads(str(registration["definition_json"]))
                episode = definition["eligible_episode"]
                attention_contract = definition["event_attention_point"]
                if (
                    definition.get("version") != self.KOL_TOKEN_ADDRESSABILITY_VERSION
                    or definition.get("query_policy") != "exact_identifier_only_no_ticker_or_alias_search"
                    or episode.get("event_attention_operator") != "lt"
                    or not isinstance(episode.get("roles"), list)
                    or not isinstance(definition.get("evm_chain_hints"), dict)
                    or attention_contract.get("definition_version")
                        != self.EVENT_ATTENTION_TRAJECTORY_VERSION
                    or attention_contract.get("coverage_mode")
                        != "local_new_observation_arrivals_only"
                    or attention_contract.get("join_key") != ["event_id", "observation_id"]
                    or attention_contract.get("required_trigger_decision_eligible") is not True
                    or attention_contract.get("required_exclusion_reason") is not None
                    or attention_contract.get("signal_clock")
                        != "max_observed_ingested_attention_recorded"
                ):
                    raise ValueError("unsupported frozen definition")
                required_capture_phase = str(episode["capture_phase"]).casefold()
                required_availability = str(episode["availability_proof"]).casefold()
                allowed_roles = {str(value).casefold() for value in episode["roles"]}
                minimum_priority = int(episode["minimum_configured_priority"])
                maximum_attention = float(episode["maximum_event_attention"])
                maximum_source_age_minutes = float(episode["maximum_source_age_minutes"])
                attention_definition_version = str(attention_contract["definition_version"])
                attention_coverage_mode = str(attention_contract["coverage_mode"])
                evm_chain_hints = {
                    str(chain).casefold(): [str(value).casefold() for value in values]
                    for chain, values in definition["evm_chain_hints"].items()
                    if isinstance(values, list)
                }
                if not allowed_roles or not evm_chain_hints:
                    raise ValueError("empty frozen definition")
            except (KeyError, TypeError, ValueError, json.JSONDecodeError):
                record_admission("skipped", "registration_definition_invalid")
                return None
            if int(observation_id) <= int(registration["activation_observation_id"]):
                record_admission("skipped", "before_activation_observation")
                return None
            row = self.db.execute(
                """
                SELECT o.*,ap.id AS attention_point_id,
                       ap.definition_version AS attention_definition_version,
                       ap.recorded_at AS attention_recorded_at,
                       ap.attention AS event_attention,
                       ap.trigger_role AS attention_trigger_role,
                       ap.trigger_decision_eligible AS attention_trigger_decision_eligible,
                       ap.exclusion_reason AS attention_exclusion_reason,
                       ap.coverage_mode AS attention_coverage_mode
                FROM observations o
                JOIN event_observations eo ON eo.observation_id=o.id
                JOIN event_attention_points ap
                  ON ap.event_id=eo.event_id AND ap.observation_id=o.id
                 AND ap.definition_version=?
                WHERE o.id=? AND eo.event_id=?
                """,
                (attention_definition_version, int(observation_id), int(event_id)),
            ).fetchone()
            if row is None:
                record_admission("skipped", "immutable_attention_point_missing")
                return None
            try:
                priority = int(account.get("priority") or 0)
            except (TypeError, ValueError):
                priority = 0
            if priority < minimum_priority:
                record_admission("skipped", "configured_priority_below_minimum")
                return None
            if str(row["capture_phase"] or "").casefold() != required_capture_phase:
                record_admission("skipped", "capture_phase_not_live")
                return None
            if str(row["availability_proof"] or "").casefold() != required_availability:
                record_admission("skipped", "availability_not_local_receive")
                return None
            if str(row["role"] or "").casefold() not in allowed_roles:
                record_admission("skipped", "role_not_decision_information")
                return None
            if (
                str(row["attention_coverage_mode"] or "") != attention_coverage_mode
                or int(row["attention_trigger_decision_eligible"] or 0) != 1
                or row["attention_exclusion_reason"] is not None
                or str(row["attention_trigger_role"] or "").casefold() not in allowed_roles
            ):
                record_admission("skipped", "immutable_attention_point_ineligible")
                return None
            observed = parse_time(row["observed_at"])
            ingested = parse_time(row["ingested_at"])
            attention_recorded = parse_time(row["attention_recorded_at"])
            signal = max(observed, ingested, attention_recorded)
            if (
                observed > ingested
                or ingested > attention_recorded
                or attention_recorded < parse_time(registration["registered_at"])
                or signal > recorded + timedelta(seconds=5)
            ):
                record_admission("skipped", "invalid_local_time_order")
                return None
            if not row["published_at"]:
                record_admission("skipped", "source_published_at_missing")
                return None
            published = parse_time(row["published_at"])
            source_age = signal - published
            if source_age < timedelta(minutes=-5):
                record_admission("skipped", "source_published_in_future")
                return None
            if source_age > timedelta(minutes=maximum_source_age_minutes):
                record_admission("skipped", "source_too_old_at_signal")
                return None
            attention = float(row["event_attention"])
            if attention >= maximum_attention:
                record_admission("skipped", "event_attention_above_low_attention_gate")
                return None

            frozen_identifiers: list[dict[str, str]] = []
            supplied = identifiers if isinstance(identifiers, Mapping) else {}
            for value in supplied.get("solana", []):
                address = self._canonical_solana_address(value)
                if address is not None:
                    frozen_identifiers.append({"chain": "solana", "address": address})
            lead_text = " " + "\n".join(str(row[key] or "") for key in (
                "title", "text", "url", "source_item_id"
            )).casefold() + " "
            matched_evm_chains = sorted({
                chain for chain, hints in evm_chain_hints.items()
                if any(hint and hint in lead_text for hint in hints)
            })
            for value in supplied.get("evm", []):
                address = str(value or "").strip().lower()
                if re.fullmatch(r"0x[0-9a-f]{40}", address):
                    frozen_identifiers.append({
                        "chain": matched_evm_chains[0] if len(matched_evm_chains) == 1 else "evm_ambiguous",
                        "address": address,
                    })
            frozen_identifiers = [
                dict(item) for item in {
                    (item["chain"], item["address"]): item for item in frozen_identifiers
                }.values()
            ]
            frozen_identifiers.sort(key=lambda item: (item["chain"], item["address"]))
            seed_status = (
                "explicit_identifier_at_signal" if frozen_identifiers else "no_seed_at_signal"
            )
            frozen_queries = [
                {"kind": "exact_ca", "chain": item["chain"], "value": item["address"]}
                for item in frozen_identifiers
            ]
            cohort_key = hashlib.sha256(
                f"{self.KOL_TOKEN_ADDRESSABILITY_VERSION}\n{int(observation_id)}".encode("utf-8")
            ).hexdigest()
            cursor = self.db.execute(
                """
                INSERT INTO kol_token_addressability_cohorts(
                    cohort_key,definition_version,observation_id,event_id,platform,handle,
                    source_entity_id,configured_priority,signal_available_at,source_published_at,
                    source_observed_at,source_ingested_at,event_attention,seed_status,
                    attention_point_id,attention_definition_version,attention_recorded_at,
                    attention_coverage_mode,identifiers_json,frozen_queries_json,definition_hash,
                    decision_eligible,affects,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none',?)
                """,
                (
                    cohort_key, self.KOL_TOKEN_ADDRESSABILITY_VERSION, int(observation_id),
                    int(event_id), str(account.get("platform") or "")[:80],
                    str(account.get("handle") or "")[:120],
                    str(account.get("entity_id") or "")[:120], priority, iso(signal),
                    iso(published), iso(observed), iso(ingested), attention, seed_status,
                    int(row["attention_point_id"]), attention_definition_version,
                    iso(attention_recorded), attention_coverage_mode,
                    self._json(frozen_identifiers), self._json(frozen_queries),
                    hashlib.sha256(str(registration["definition_json"]).encode("utf-8")).hexdigest(),
                    recorded_text,
                ),
            )
            cohort_id = int(cursor.lastrowid)

            for item in frozen_identifiers:
                if item["chain"] != "evm_ambiguous":
                    continue
                ambiguity_key = hashlib.sha256(
                    f"{self.KOL_TOKEN_ADDRESSABILITY_VERSION}\n{cohort_id}\n"
                    f"{item['address']}\nambiguous-chain".encode("utf-8")
                ).hexdigest()
                self.db.execute(
                    """
                    INSERT INTO kol_token_addressability_ambiguities(
                        ambiguity_key,definition_version,cohort_id,identifier,status,
                        evidence_json,decision_eligible,affects,recorded_at
                    ) VALUES(?,?,?,?,'ambiguous_evm_chain_at_signal',?,0,'none',?)
                    """,
                    (
                        ambiguity_key, self.KOL_TOKEN_ADDRESSABILITY_VERSION, cohort_id,
                        item["address"], self._json({"matched_chain_hints": matched_evm_chains}),
                        recorded_text,
                    ),
                )

            def add_milestone(
                milestone: str,
                status: str,
                available_at: Any,
                *,
                chain: str = "",
                identifier: str = "",
                token_id: str | None = None,
                provider: str | None = None,
                surface_key: str | None = None,
                evidence: Mapping[str, Any] | None = None,
            ) -> None:
                key = hashlib.sha256(
                    f"{self.KOL_TOKEN_ADDRESSABILITY_VERSION}\n{cohort_id}\n{milestone}\n"
                    f"{chain}\n{identifier}\n{token_id or ''}\n{surface_key or ''}".encode("utf-8")
                ).hexdigest()
                self.db.execute(
                    """
                    INSERT INTO kol_token_addressability_milestones(
                        milestone_key,definition_version,cohort_id,milestone,status,available_at,
                        chain,identifier,token_id,provider,surface_key,evidence_json,
                        decision_eligible,affects,recorded_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,'none',?)
                    """,
                    (
                        key, self.KOL_TOKEN_ADDRESSABILITY_VERSION, cohort_id, milestone, status,
                        iso(available_at), chain, identifier, token_id, provider, surface_key,
                        self._json(evidence or {}), recorded_text,
                    ),
                )

            add_milestone(
                "signal", "observed", signal,
                evidence={"observation_id": int(observation_id), "event_id": int(event_id)},
            )
            if not frozen_identifiers:
                add_milestone(
                    "explicit_identifier", "missing_at_signal", signal,
                    evidence={"denominator_status": "no_seed_at_signal"},
                )
            for item in frozen_identifiers:
                identifier = item["address"]
                chain_hint = item["chain"]
                add_milestone(
                    "explicit_identifier", "observed", signal,
                    chain=chain_hint, identifier=identifier,
                    evidence={"basis": "trigger_observation_exact_ca"},
                )
                if chain_hint == "solana":
                    tokens = list(self.db.execute(
                        "SELECT * FROM tokens WHERE chain='solana' AND address=? ORDER BY token_id",
                        (identifier,),
                    ))
                elif chain_hint in self.TOKEN_UNIVERSE_EVM_CHAINS:
                    tokens = list(self.db.execute(
                        "SELECT * FROM tokens WHERE lower(chain)=? AND lower(address)=? "
                        "ORDER BY token_id",
                        (chain_hint, identifier),
                    ))
                else:
                    tokens = []
                for token in tokens:
                    snapshots = list(self.db.execute(
                        """
                        SELECT * FROM token_snapshots
                        WHERE token_id=? AND recorded_at<=?
                          AND observed_at<=ingested_at AND ingested_at<=recorded_at
                        ORDER BY recorded_at,id
                        """,
                        (str(token["token_id"]), recorded_text),
                    ))
                    if not snapshots:
                        continue
                    first_snapshot = snapshots[0]
                    local_available = max(signal, parse_time(first_snapshot["recorded_at"]))
                    add_milestone(
                        "local_token_discovery", "observed", local_available,
                        chain=str(token["chain"]), identifier=identifier,
                        token_id=str(token["token_id"]), provider=str(first_snapshot["provider"]),
                        evidence={
                            "basis": "token_snapshots.recorded_at",
                            "snapshot_id": int(first_snapshot["id"]),
                        },
                    )
                    for snapshot in snapshots:
                        surface = self._information_first_snapshot_surface(snapshot)
                        if surface is None:
                            continue
                        snapshot_available = max(
                            signal,
                            parse_time(snapshot["recorded_at"]),
                        )
                        add_milestone(
                            "dex_pair_available", "observed", snapshot_available,
                            chain=str(token["chain"]), identifier=identifier,
                            token_id=str(token["token_id"]), provider=str(snapshot["provider"]),
                            surface_key=surface["key"],
                            evidence={
                                "snapshot_id": int(snapshot["id"]),
                                "pair_address": surface["pair_address"],
                                "dex_id": surface["dex_id"],
                            },
                        )
                        break
            record_admission("created", seed_status, cohort_id)
            return cohort_id

    def _validated_kol_route_registration_locked(
        self,
    ) -> tuple[sqlite3.Row, dict[str, Any]] | None:
        registration = self.db.execute(
            "SELECT * FROM kol_token_addressability_route_registrations "
            "WHERE definition_version=?",
            (self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,),
        ).fetchone()
        base_registration = self.db.execute(
            "SELECT * FROM kol_token_addressability_registrations "
            "WHERE definition_version=?",
            (self.KOL_TOKEN_ADDRESSABILITY_VERSION,),
        ).fetchone()
        if registration is None or base_registration is None:
            return None
        try:
            definition = json.loads(str(registration["definition_json"]))
            expected_base_hash = hashlib.sha256(
                str(base_registration["definition_json"]).encode("utf-8")
            ).hexdigest()
            if (
                definition.get("version") != self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION
                or definition.get("compatible_base_definition_version")
                    != self.KOL_TOKEN_ADDRESSABILITY_VERSION
                or definition.get("compatible_base_definition_hash") != expected_base_hash
                or definition != self._kol_token_addressability_route_definition()
            ):
                return None
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            return None
        return registration, definition

    def refresh_kol_token_addressability_evidence(self, *, now: Any = None) -> dict[str, int]:
        """Append later local discovery, pair and exact independent-confirmation evidence."""
        evaluated = parse_time(now or utcnow())
        evaluated_text = iso(evaluated)
        counts = {"local_token": 0, "dex_pair": 0, "confirmation": 0, "terminal": 0}
        with self._lock, self.db:
            validated = self._validated_kol_route_registration_locked()
            route_definition = validated[1] if validated is not None else None
            confirmation_window_minutes = (
                int(route_definition["confirmation_window_minutes"])
                if route_definition is not None else 0
            )
            if validated is None:
                cohorts = []
            else:
                registration, route_definition = validated
                cohorts = list(self.db.execute(
                    """
                    SELECT c.* FROM kol_token_addressability_cohorts c
                    WHERE c.id>? AND c.definition_version=? AND c.definition_hash=?
                      AND (
                        NOT EXISTS (
                          SELECT 1 FROM kol_token_addressability_route_results r
                          WHERE r.definition_version=? AND r.cohort_id=c.id
                        )
                        OR NOT EXISTS (
                          SELECT 1 FROM kol_token_addressability_confirmation_results cr
                          WHERE cr.definition_version=? AND cr.cohort_id=c.id
                        )
                      )
                    ORDER BY c.id LIMIT 12
                    """,
                    (
                        int(registration["activation_cohort_id"]),
                        self.KOL_TOKEN_ADDRESSABILITY_VERSION,
                        str(route_definition["compatible_base_definition_hash"]),
                        self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                        self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                    ),
                ))

            def add_milestone(
                cohort_id: int, milestone: str, available_at: Any, *, chain: str,
                identifier: str, token_id: str, provider: str, surface_key: str = "",
                evidence: Mapping[str, Any] | None = None,
            ) -> bool:
                key = hashlib.sha256(
                    f"{self.KOL_TOKEN_ADDRESSABILITY_VERSION}\n{cohort_id}\n{milestone}\n"
                    f"{chain}\n{identifier}\n{token_id}\n{surface_key}".encode("utf-8")
                ).hexdigest()
                cursor = self.db.execute(
                    """
                    INSERT OR IGNORE INTO kol_token_addressability_milestones(
                        milestone_key,definition_version,cohort_id,milestone,status,available_at,
                        chain,identifier,token_id,provider,surface_key,evidence_json,
                        decision_eligible,affects,recorded_at
                    ) VALUES(?,?,?,?, 'observed',?,?,?,?,?,?,?,0,'none',?)
                    """,
                    (
                        key, self.KOL_TOKEN_ADDRESSABILITY_VERSION, cohort_id, milestone,
                        iso(available_at), chain, identifier, token_id, provider,
                        surface_key or None, self._json(evidence or {}), evaluated_text,
                    ),
                )
                return cursor.rowcount == 1

            for cohort in cohorts:
                signal = parse_time(cohort["signal_available_at"])
                identifiers = json.loads(str(cohort["identifiers_json"] or "[]"))
                identifiers = identifiers if isinstance(identifiers, list) else []
                for item in identifiers:
                    if not isinstance(item, dict):
                        continue
                    chain_hint = str(item.get("chain") or "")
                    identifier = str(item.get("address") or "")
                    if chain_hint == "solana":
                        tokens = list(self.db.execute(
                            "SELECT * FROM tokens WHERE token_id=? AND chain='solana' AND address=? "
                            "ORDER BY token_id LIMIT 1",
                            (f"solana:{identifier}", identifier),
                        ))
                    elif chain_hint in self.TOKEN_UNIVERSE_EVM_CHAINS:
                        tokens = list(self.db.execute(
                            "SELECT * FROM tokens WHERE lower(chain)=? AND lower(address)=? "
                            "ORDER BY token_id LIMIT 1",
                            (chain_hint, identifier.casefold()),
                        ))
                    else:
                        tokens = []
                    for token in tokens:
                        snapshots = list(self.db.execute(
                            """
                            SELECT * FROM token_snapshots
                            WHERE token_id=? AND recorded_at<=?
                              AND observed_at<=ingested_at AND ingested_at<=recorded_at
                            ORDER BY recorded_at,id LIMIT 20
                            """,
                            (str(token["token_id"]), evaluated_text),
                        ))
                        if not snapshots:
                            continue
                        first_snapshot = snapshots[0]
                        token_available = max(signal, parse_time(first_snapshot["recorded_at"]))
                        if add_milestone(
                            int(cohort["id"]), "local_token_discovery", token_available,
                            chain=str(token["chain"]), identifier=identifier,
                            token_id=str(token["token_id"]), provider=str(first_snapshot["provider"]),
                            evidence={
                                "basis": "token_snapshots.recorded_at",
                                "snapshot_id": int(first_snapshot["id"]),
                            },
                        ):
                            counts["local_token"] += 1
                        for snapshot in snapshots:
                            surface = self._information_first_snapshot_surface(snapshot)
                            if surface is None:
                                continue
                            available = max(
                                signal,
                                parse_time(snapshot["recorded_at"]),
                            )
                            if add_milestone(
                                int(cohort["id"]), "dex_pair_available", available,
                                chain=str(token["chain"]), identifier=identifier,
                                token_id=str(token["token_id"]), provider=str(snapshot["provider"]),
                                surface_key=surface["key"], evidence={
                                    "snapshot_id": int(snapshot["id"]),
                                    "pair_address": surface["pair_address"],
                                    "dex_id": surface["dex_id"],
                                },
                            ):
                                counts["dex_pair"] += 1
                            break

                if route_definition is None:
                    continue
                trigger = self.db.execute(
                    "SELECT * FROM observations WHERE id=?", (int(cohort["observation_id"]),)
                ).fetchone()
                trigger_origin = self._information_first_source_facts(trigger)[0] if trigger else ""
                deadline = signal + timedelta(
                    minutes=confirmation_window_minutes
                )
                if not identifiers:
                    key = hashlib.sha256(
                        f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(cohort['id'])}\n"
                        "no-seed-confirmation".encode("utf-8")
                    ).hexdigest()
                    cursor = self.db.execute(
                        """
                        INSERT OR IGNORE INTO kol_token_addressability_confirmation_results(
                            result_key,definition_version,cohort_id,identifier,status,observation_id,
                            source_origin,available_at,evaluated_at,evidence_json,decision_eligible,affects
                        ) VALUES(?,?,?,'','no_seed_at_signal',NULL,NULL,?,?,?,0,'none')
                        """,
                        (key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION, int(cohort["id"]),
                         iso(signal), evaluated_text, self._json({"seed_status": "no_seed_at_signal"})),
                    )
                    counts["terminal"] += int(cursor.rowcount == 1)
                    continue
                event_rows = list(self.db.execute(
                    """
                    SELECT o.* FROM observations o
                    JOIN event_observations eo ON eo.observation_id=o.id
                    WHERE eo.event_id=? AND o.id<>? AND o.observed_at<=? AND o.ingested_at<=?
                      AND lower(o.role) IN ('feature','confirmation')
                      AND lower(o.availability_proof) IN ('local_poll','local_receive')
                    ORDER BY max(o.observed_at,o.ingested_at),o.id LIMIT 100
                    """,
                    (int(cohort["event_id"]), int(cohort["observation_id"]), evaluated_text, evaluated_text),
                ))
                for item in identifiers:
                    identifier = str(item.get("address") or "")
                    matched_timely = False
                    for candidate in event_rows:
                        origin = self._information_first_source_facts(candidate)[0]
                        if not origin or origin == trigger_origin:
                            continue
                        haystack = "\n".join(str(candidate[key] or "") for key in (
                            "title", "text", "url", "source_item_id"
                        ))
                        exact = (
                            identifier in self._extract_canonical_solana_addresses(haystack)
                            if str(item.get("chain") or "") == "solana"
                            else bool(re.search(
                                rf"(?<![0-9a-f]){re.escape(identifier.casefold())}(?![0-9a-f])",
                                haystack.casefold(),
                            ))
                        )
                        if not exact:
                            continue
                        available = max(parse_time(candidate["observed_at"]), parse_time(candidate["ingested_at"]))
                        status = "observed" if available <= deadline else "late"
                        key = hashlib.sha256(
                            f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(cohort['id'])}\n"
                            f"{identifier}\n{int(candidate['id'])}".encode("utf-8")
                        ).hexdigest()
                        cursor = self.db.execute(
                            """
                            INSERT OR IGNORE INTO kol_token_addressability_confirmation_results(
                                result_key,definition_version,cohort_id,identifier,status,observation_id,
                                source_origin,available_at,evaluated_at,evidence_json,decision_eligible,affects
                            ) VALUES(?,?,?,?,?,?,?,?,?,?,0,'none')
                            """,
                            (
                                key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION, int(cohort["id"]),
                                identifier, status, int(candidate["id"]), origin, iso(available),
                                evaluated_text, self._json({"basis": "independent_event_observation_exact_ca"}),
                            ),
                        )
                        counts["confirmation"] += int(cursor.rowcount == 1)
                        matched_timely = matched_timely or status == "observed"
                    if not matched_timely and evaluated >= deadline:
                        key = hashlib.sha256(
                            f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(cohort['id'])}\n"
                            f"{identifier}\nmissing-confirmation".encode("utf-8")
                        ).hexdigest()
                        cursor = self.db.execute(
                            """
                            INSERT OR IGNORE INTO kol_token_addressability_confirmation_results(
                                result_key,definition_version,cohort_id,identifier,status,observation_id,
                                source_origin,available_at,evaluated_at,evidence_json,decision_eligible,affects
                            ) VALUES(?,?,?,?, 'missing_by_deadline',NULL,NULL,?,?,?,0,'none')
                            """,
                            (
                                key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION, int(cohort["id"]),
                                identifier, iso(deadline), evaluated_text,
                                self._json({"window_minutes": confirmation_window_minutes}),
                            ),
                        )
                        counts["terminal"] += int(cursor.rowcount == 1)
        return counts

    def due_kol_token_addressability_routes(
        self, *, now: Any = None, limit: int = 1
    ) -> list[dict[str, Any]]:
        evaluated = parse_time(now or utcnow())
        evaluated_text = iso(evaluated)
        due: list[dict[str, Any]] = []
        with self._lock, self.db:
            validated = self._validated_kol_route_registration_locked()
            if validated is None:
                return due
            registration, definition = validated
            compatible_hash = str(definition["compatible_base_definition_hash"])
            cohorts = list(self.db.execute(
                """
                SELECT c.* FROM kol_token_addressability_cohorts c
                WHERE c.id>? AND c.definition_version=? AND c.definition_hash=?
                  AND (
                    (json_array_length(c.identifiers_json)=0 AND NOT EXISTS (
                      SELECT 1 FROM kol_token_addressability_route_results r
                      WHERE r.definition_version=? AND r.cohort_id=c.id
                    ))
                    OR EXISTS (
                      SELECT 1 FROM json_each(c.identifiers_json) j
                      WHERE NOT EXISTS (
                        SELECT 1 FROM kol_token_addressability_route_results r
                        WHERE r.definition_version=? AND r.cohort_id=c.id
                          AND r.identifier=json_extract(j.value,'$.address')
                      )
                    )
                  )
                ORDER BY c.signal_available_at,c.id LIMIT 24
                """,
                (
                    int(registration["activation_cohort_id"]),
                    self.KOL_TOKEN_ADDRESSABILITY_VERSION, compatible_hash,
                    self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                    self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                ),
            ))
            for cohort in cohorts:
                identifiers = json.loads(str(cohort["identifiers_json"] or "[]"))
                identifiers = identifiers if isinstance(identifiers, list) else []
                if not identifiers:
                    self._record_kol_route_terminal(
                        cohort, "", "no_seed_at_signal", evaluated=evaluated,
                        evidence={"seed_status": "no_seed_at_signal"},
                    )
                    continue
                deadline = parse_time(cohort["signal_available_at"]) + timedelta(
                    seconds=int(definition["route_deadline_seconds_after_signal"])
                )
                for identifier_item in identifiers:
                    identifier = str(identifier_item.get("address") or "")
                    chain = str(identifier_item.get("chain") or "")
                    if self.db.execute(
                        "SELECT 1 FROM kol_token_addressability_route_results "
                        "WHERE definition_version=? AND cohort_id=? AND identifier=? LIMIT 1",
                        (
                            self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                            int(cohort["id"]), identifier,
                        ),
                    ).fetchone():
                        continue
                    attempt = self.db.execute(
                        "SELECT * FROM kol_token_addressability_route_attempts "
                        "WHERE definition_version=? AND cohort_id=? AND output_mint=? "
                        "ORDER BY id DESC LIMIT 1",
                        (
                            self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                            int(cohort["id"]), identifier,
                        ),
                    ).fetchone()
                    if attempt is not None:
                        if evaluated - parse_time(attempt["requested_at"]) >= timedelta(minutes=2):
                            self._record_kol_route_terminal(
                                cohort, identifier, "interrupted_after_request", evaluated=evaluated,
                                attempt_id=int(attempt["id"]), evidence={"attempt_id": int(attempt["id"])},
                            )
                        continue
                    if chain == "evm_ambiguous":
                        self._record_kol_route_terminal(
                            cohort, identifier, "ambiguous_chain", evaluated=evaluated,
                            evidence={"chain": chain},
                        )
                        continue
                    if chain != "solana":
                        self._record_kol_route_terminal(
                            cohort, identifier, "unsupported_chain", evaluated=evaluated,
                            evidence={"chain": chain},
                        )
                        continue
                    if self._canonical_solana_address(identifier) != identifier:
                        self._record_kol_route_terminal(
                            cohort, identifier, "quote_only_protocol_invalid", evaluated=evaluated,
                            evidence={"terminal_status_v2": "canonical_identifier_invalid"},
                            terminal_status_v2="canonical_identifier_invalid",
                        )
                        continue
                    pair = self.db.execute(
                        """
                        SELECT * FROM kol_token_addressability_milestones
                        WHERE definition_version=? AND cohort_id=?
                          AND milestone='dex_pair_available' AND identifier=?
                          AND token_id=?
                        ORDER BY available_at,id LIMIT 1
                        """,
                        (
                            self.KOL_TOKEN_ADDRESSABILITY_VERSION,
                            int(cohort["id"]), identifier, f"solana:{identifier}",
                        ),
                    ).fetchone()
                    if pair is None:
                        if evaluated >= deadline:
                            self._record_kol_route_terminal(
                                cohort, identifier, "dex_pair_missing_by_deadline", evaluated=evaluated,
                                evidence={"deadline": iso(deadline)},
                            )
                        continue
                    pair_available = parse_time(pair["available_at"])
                    if pair_available > deadline:
                        self._record_kol_route_terminal(
                            cohort, identifier, "dex_pair_missing_by_deadline", evaluated=evaluated,
                            milestone_id=int(pair["id"]), token_id=str(pair["token_id"] or ""),
                            surface_key=str(pair["surface_key"] or ""),
                            evidence={
                                "deadline": iso(deadline),
                                "pair_available_at": iso(pair_available),
                                "terminal_status_v2": "dex_pair_late",
                            },
                            terminal_status_v2="dex_pair_late",
                            pair_timing_status="dex_pair_late",
                        )
                        continue
                    if evaluated > deadline:
                        self._record_kol_route_terminal(
                            cohort, identifier, "queue_delay_expired", evaluated=evaluated,
                            milestone_id=int(pair["id"]), token_id=str(pair["token_id"] or ""),
                            surface_key=str(pair["surface_key"] or ""),
                            evidence={
                                "deadline": iso(deadline),
                                "pair_available_at": iso(pair_available),
                                "terminal_status_v2": "queue_delay_expired",
                            },
                            terminal_status_v2="queue_delay_expired",
                            pair_timing_status="pair_timely",
                            request_timing_status="request_late_or_not_requested",
                        )
                        continue
                    due.append({
                        "definition_version": self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                        "cohort_id": int(cohort["id"]), "milestone_id": int(pair["id"]),
                        "identifier": identifier, "token_id": str(pair["token_id"] or ""),
                        "input_mint": str(definition["input_mint"]), "output_mint": identifier,
                        "input_amount_raw": str(definition["input_amount_raw"]),
                        "slippage_bps": int(definition["slippage_bps"]),
                        "surface_key": str(pair["surface_key"] or ""), "deadline_at": iso(deadline),
                        "signal_at": str(cohort["signal_available_at"]),
                        "pair_available_at": str(pair["available_at"]),
                        "compatible_base_definition_version": self.KOL_TOKEN_ADDRESSABILITY_VERSION,
                        "compatible_base_definition_hash": compatible_hash,
                    })
                    if len(due) >= max(1, int(limit)):
                        return due
        return due

    def start_kol_token_addressability_route_attempt(
        self, task: Mapping[str, Any], *, requested_at: Any = None
    ) -> int | None:
        requested = parse_time(requested_at or utcnow())
        if requested > parse_time(task["deadline_at"]):
            return None
        attempt_key = hashlib.sha256(
            f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(task['cohort_id'])}\n"
            f"{str(task['identifier'])}".encode("utf-8")
        ).hexdigest()
        with self._lock, self.db:
            validated = self._validated_kol_route_registration_locked()
            if validated is None:
                return None
            registration, definition = validated
            cohort = self.db.execute(
                "SELECT * FROM kol_token_addressability_cohorts WHERE id=?",
                (int(task["cohort_id"]),),
            ).fetchone()
            milestone = self.db.execute(
                "SELECT * FROM kol_token_addressability_milestones WHERE id=?",
                (int(task["milestone_id"]),),
            ).fetchone()
            identifier = self._canonical_solana_address(task.get("identifier"))
            expected_hash = str(definition["compatible_base_definition_hash"])
            if (
                cohort is None or milestone is None or identifier is None
                or int(cohort["id"]) <= int(registration["activation_cohort_id"])
                or str(cohort["definition_version"])
                    != str(definition["compatible_base_definition_version"])
                or str(cohort["definition_hash"]) != expected_hash
                or int(milestone["cohort_id"]) != int(cohort["id"])
                or str(milestone["definition_version"])
                    != str(definition["compatible_base_definition_version"])
                or str(milestone["milestone"]) != "dex_pair_available"
                or str(milestone["identifier"]) != identifier
                or str(milestone["token_id"] or "") != f"solana:{identifier}"
                or str(task.get("token_id") or "") != f"solana:{identifier}"
                or str(task.get("input_mint") or "") != str(definition["input_mint"])
                or str(task.get("output_mint") or "") != identifier
                or str(task.get("input_amount_raw") or "")
                    != str(definition["input_amount_raw"])
                or int(task.get("slippage_bps") or -1) != int(definition["slippage_bps"])
                or str(task.get("surface_key") or "") != str(milestone["surface_key"] or "")
                or parse_time(task["pair_available_at"]) > parse_time(task["deadline_at"])
            ):
                return None
            cursor = self.db.execute(
                """
                INSERT OR IGNORE INTO kol_token_addressability_route_attempts(
                    attempt_key,definition_version,cohort_id,milestone_id,requested_at,input_mint,
                    output_mint,input_amount_raw,slippage_bps,surface_key,deadline_at,
                    compatible_base_definition_version,compatible_base_definition_hash,
                    decision_eligible,affects
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')
                """,
                (
                    attempt_key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                    int(task["cohort_id"]), int(task["milestone_id"]), iso(requested),
                    str(task["input_mint"]), str(task["output_mint"]),
                    str(task["input_amount_raw"]), int(task["slippage_bps"]),
                    str(task["surface_key"]), str(task["deadline_at"]),
                    self.KOL_TOKEN_ADDRESSABILITY_VERSION, expected_hash,
                ),
            )
            return int(cursor.lastrowid) if cursor.rowcount == 1 else None

    def record_kol_token_addressability_route_result(
        self, task: Mapping[str, Any], *, attempt_id: int, status: str,
        evaluated_at: Any = None, completed_at: Any = None,
        result: Mapping[str, Any] | None = None, error_type: str = "",
    ) -> int | None:
        evaluated = parse_time(evaluated_at or utcnow())
        completed = parse_time(completed_at or evaluated)
        result = result if isinstance(result, Mapping) else {}
        route_plan = result.get("route_plan") if isinstance(result.get("route_plan"), list) else []
        pair_address = ""
        try:
            pair_address = str(json.loads(str(task["surface_key"]))[3]).casefold()
        except (IndexError, TypeError, ValueError, json.JSONDecodeError):
            pass
        amm_keys = {
            str(item.get("amm_key") or "").casefold()
            for item in route_plan if isinstance(item, Mapping)
        }
        single_hop_exact = (
            len(route_plan) == 1
            and isinstance(route_plan[0], Mapping)
            and str(route_plan[0].get("amm_key") or "").casefold() == pair_address
            and int(route_plan[0].get("percent") or 0) == 100
            and str(route_plan[0].get("input_mint") or "") == str(task["input_mint"])
            and str(route_plan[0].get("output_mint") or "") == str(task["output_mint"])
        )
        surface_relation = (
            "single_hop_exact" if single_hop_exact
            else "multi_hop_includes_frozen_pair"
            if pair_address and pair_address in amm_keys
            else "unmapped"
        )
        surface_match = "exact" if single_hop_exact else "unmapped"
        final_status = status
        if status == "quoted":
            final_status = "quoted_surface_match" if surface_match == "exact" else "quoted_surface_unmapped"
        result_key = hashlib.sha256(
            f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(task['cohort_id'])}\n"
            f"{str(task['identifier'])}\nresult".encode("utf-8")
        ).hexdigest()
        with self._lock, self.db:
            validated = self._validated_kol_route_registration_locked()
            if validated is None:
                return None
            registration, definition = validated
            attempt = self.db.execute(
                "SELECT * FROM kol_token_addressability_route_attempts WHERE id=?",
                (int(attempt_id),),
            ).fetchone()
            cohort = self.db.execute(
                "SELECT * FROM kol_token_addressability_cohorts WHERE id=?",
                (int(task["cohort_id"]),),
            ).fetchone()
            milestone = self.db.execute(
                "SELECT * FROM kol_token_addressability_milestones WHERE id=?",
                (int(task["milestone_id"]),),
            ).fetchone()
            expected_hash = str(definition["compatible_base_definition_hash"])
            identifier = self._canonical_solana_address(task.get("identifier"))
            if (
                attempt is None or cohort is None or milestone is None or identifier is None
                or str(attempt["definition_version"])
                    != self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION
                or int(attempt["cohort_id"]) != int(task["cohort_id"])
                or int(attempt["milestone_id"]) != int(task["milestone_id"])
                or str(attempt["output_mint"]) != identifier
                or str(attempt["input_mint"]) != str(task["input_mint"])
                or str(attempt["input_amount_raw"]) != str(task["input_amount_raw"])
                or int(attempt["slippage_bps"]) != int(task["slippage_bps"])
                or str(attempt["surface_key"]) != str(task["surface_key"])
                or str(attempt["compatible_base_definition_version"] or "")
                    != self.KOL_TOKEN_ADDRESSABILITY_VERSION
                or str(attempt["compatible_base_definition_hash"] or "") != expected_hash
                or int(cohort["id"]) <= int(registration["activation_cohort_id"])
                or str(cohort["definition_version"])
                    != self.KOL_TOKEN_ADDRESSABILITY_VERSION
                or str(cohort["definition_hash"]) != expected_hash
                or int(milestone["cohort_id"]) != int(cohort["id"])
                or str(milestone["definition_version"])
                    != self.KOL_TOKEN_ADDRESSABILITY_VERSION
                or str(milestone["identifier"]) != identifier
                or str(milestone["token_id"] or "") != f"solana:{identifier}"
                or str(task.get("token_id") or "") != f"solana:{identifier}"
            ):
                return None
            requested = parse_time(attempt["requested_at"])
            deadline = parse_time(attempt["deadline_at"])
            terminal_status_v2 = final_status
            response_timing_status = "response_timely"
            if completed < requested:
                final_status = "quote_only_protocol_invalid"
                terminal_status_v2 = "clock_invalid"
                response_timing_status = "clock_invalid"
            elif completed > deadline:
                terminal_status_v2 = "route_response_late"
                response_timing_status = "response_late"
            elif status == "quoted":
                terminal_status_v2 = "route_quoted_timely"
            if status == "quoted" and (
                str(result.get("input_mint") or "") != str(task["input_mint"])
                or str(result.get("output_mint") or "") != identifier
                or str(result.get("in_amount") or "") != str(task["input_amount_raw"])
                or int(result.get("slippage_bps") or -1) != int(task["slippage_bps"])
            ):
                final_status = "quote_only_protocol_invalid"
                terminal_status_v2 = "quote_request_lineage_invalid"
            cursor = self.db.execute(
                """
                INSERT OR IGNORE INTO kol_token_addressability_route_results(
                    result_key,definition_version,cohort_id,milestone_id,attempt_id,identifier,
                    token_id,status,evaluated_at,completed_at,output_amount_raw,
                    other_amount_threshold_raw,router,route_plan_json,surface_key,
                    surface_match_status,error_type,evidence_json,terminal_status_v2,
                    pair_timing_status,request_timing_status,response_timing_status,
                    surface_relation,decision_eligible,affects
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')
                """,
                (
                    result_key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                    int(task["cohort_id"]), int(task["milestone_id"]), int(attempt_id),
                    str(task["identifier"]), str(task.get("token_id") or "") or None,
                    final_status, iso(evaluated), iso(completed),
                    result.get("output_amount_raw"), result.get("other_amount_threshold"),
                    str(result.get("router") or "") or None, self._json(route_plan),
                    str(task.get("surface_key") or "") or None, surface_match,
                    str(error_type or "")[:120], self._json({
                        "requested_at": str(result.get("requested_at") or attempt["requested_at"]),
                        "completed_at": str(result.get("completed_at") or iso(completed)),
                        "deadline_at": str(attempt["deadline_at"]),
                        "pair_address": pair_address,
                    }), terminal_status_v2, "pair_timely", "request_timely",
                    response_timing_status, surface_relation,
                ),
            )
            return int(cursor.lastrowid) if cursor.rowcount == 1 else None

    def _record_kol_route_terminal(
        self, cohort: sqlite3.Row, identifier: str, status: str, *, evaluated: Any,
        milestone_id: int | None = None, attempt_id: int | None = None,
        token_id: str = "", surface_key: str = "", evidence: Mapping[str, Any] | None = None,
        terminal_status_v2: str | None = None, pair_timing_status: str | None = None,
        request_timing_status: str | None = None,
        response_timing_status: str | None = None,
    ) -> int | None:
        key = hashlib.sha256(
            f"{self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION}\n{int(cohort['id'])}\n"
            f"{identifier}\nresult".encode("utf-8")
        ).hexdigest()
        cursor = self.db.execute(
            """
            INSERT OR IGNORE INTO kol_token_addressability_route_results(
                result_key,definition_version,cohort_id,milestone_id,attempt_id,identifier,
                token_id,status,evaluated_at,completed_at,output_amount_raw,
                other_amount_threshold_raw,router,route_plan_json,surface_key,
                surface_match_status,error_type,evidence_json,terminal_status_v2,
                pair_timing_status,request_timing_status,response_timing_status,
                surface_relation,decision_eligible,affects
            ) VALUES(?,?,?,?,?,?,?,?,?,NULL,NULL,NULL,NULL,'[]',?,'not_applicable','',?,?,?,?,?,NULL,0,'none')
            """,
            (
                key, self.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION, int(cohort["id"]),
                milestone_id, attempt_id, identifier, token_id or None, status, iso(evaluated),
                surface_key or None, self._json(evidence or {}),
                terminal_status_v2 or status, pair_timing_status,
                request_timing_status, response_timing_status,
            ),
        )
        return int(cursor.lastrowid) if cursor.rowcount == 1 else None

    @classmethod
    def kol_token_addressability_summary_from_connection(
        cls, connection: sqlite3.Connection,
    ) -> dict[str, Any]:
        connection.row_factory = sqlite3.Row
        registration = connection.execute(
            "SELECT * FROM kol_token_addressability_registrations WHERE definition_version=?",
            (cls.KOL_TOKEN_ADDRESSABILITY_VERSION,),
        ).fetchone()
        route_registration = connection.execute(
            "SELECT * FROM kol_token_addressability_route_registrations WHERE definition_version=?",
            (cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,),
        ).fetchone()

        def count(table: str, version: str | None = None) -> int:
            if version is None:
                return int(connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0])
            return int(connection.execute(
                f"SELECT COUNT(*) FROM {table} WHERE definition_version=?", (version,),
            ).fetchone()[0])

        def grouped(table: str, column: str, version: str | None = None) -> dict[str, int]:
            where = " WHERE definition_version=?" if version is not None else ""
            params = (version,) if version is not None else ()
            return {
                str(row[0]): int(row[1])
                for row in connection.execute(
                    f"SELECT {column},COUNT(*) FROM {table}{where} "
                    f"GROUP BY {column} ORDER BY {column}",
                    params,
                )
            }

        def grouped_non_null(table: str, column: str, version: str) -> dict[str, int]:
            return {
                str(row[0]): int(row[1])
                for row in connection.execute(
                    f"SELECT {column},COUNT(*) FROM {table} "
                    f"WHERE definition_version=? AND {column} IS NOT NULL "
                    f"GROUP BY {column} ORDER BY {column}",
                    (version,),
                )
            }

        cohorts = count("kol_token_addressability_cohorts", cls.KOL_TOKEN_ADDRESSABILITY_VERSION)
        definition_valid = False
        if registration is not None:
            try:
                definition = json.loads(str(registration["definition_json"]))
                attention_contract = definition["event_attention_point"]
                definition_valid = (
                    definition.get("version") == cls.KOL_TOKEN_ADDRESSABILITY_VERSION
                    and attention_contract.get("definition_version")
                        == cls.EVENT_ATTENTION_TRAJECTORY_VERSION
                    and attention_contract.get("join_key") == ["event_id", "observation_id"]
                )
            except (KeyError, TypeError, json.JSONDecodeError):
                definition_valid = False
        if registration is None:
            status = "not_registered"
        elif not definition_valid:
            status = "definition_invalid"
        else:
            status = "observed" if cohorts else "registered_waiting"
        route_status = "not_registered"
        route_disposition = None
        if route_registration is not None:
            try:
                route_definition = json.loads(str(route_registration["definition_json"]))
                expected_hash = hashlib.sha256(
                    str(registration["definition_json"]).encode("utf-8")
                ).hexdigest() if registration is not None else ""
                if route_definition.get("version") != cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION:
                    route_status = "definition_invalid"
                elif (
                    route_definition.get("compatible_base_definition_version")
                        != cls.KOL_TOKEN_ADDRESSABILITY_VERSION
                    or route_definition.get("compatible_base_definition_hash") != expected_hash
                ):
                    route_status = "incompatible"
                    if (
                        count(
                            "kol_token_addressability_route_attempts",
                            cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                        ) == 0
                        and count(
                            "kol_token_addressability_route_results",
                            cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                        ) == 0
                    ):
                        route_disposition = "registered_abandoned_before_first_attempt"
                else:
                    route_rows = count(
                        "kol_token_addressability_route_results",
                        cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                    )
                    route_status = "observed" if route_rows else "registered_waiting"
            except (TypeError, json.JSONDecodeError):
                route_status = "definition_invalid"
        versions = []
        registration_rows = list(connection.execute(
            "SELECT * FROM kol_token_addressability_registrations ORDER BY registered_at,definition_version"
        ))
        for item in registration_rows:
            version = str(item["definition_version"])
            version_cohorts = count("kol_token_addressability_cohorts", version)
            version_status = "observed" if version_cohorts else "registered_waiting"
            if version != cls.KOL_TOKEN_ADDRESSABILITY_VERSION and version_cohorts == 0:
                version_status = "registered_abandoned_before_first_cohort"
            versions.append({
                "version": version,
                "registered_at": str(item["registered_at"]),
                "activation_observation_id": int(item["activation_observation_id"]),
                "definition_hash": hashlib.sha256(
                    str(item["definition_json"]).encode("utf-8")
                ).hexdigest(),
                "status": version_status,
                "summary": {
                    "admission_attempts": count(
                        "kol_token_addressability_admission_attempts", version
                    ),
                    "cohorts": version_cohorts,
                    "milestones": count("kol_token_addressability_milestones", version),
                    "ambiguities": count("kol_token_addressability_ambiguities", version),
                },
            })
        route_versions = []
        for item in connection.execute(
            "SELECT * FROM kol_token_addressability_route_registrations "
            "ORDER BY registered_at,definition_version"
        ):
            version = str(item["definition_version"])
            attempts = count("kol_token_addressability_route_attempts", version)
            results = count("kol_token_addressability_route_results", version)
            confirmations = count("kol_token_addressability_confirmation_results", version)
            if version == cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION:
                version_status = route_disposition or route_status
            elif attempts == 0 and results == 0 and confirmations == 0:
                version_status = "registered_abandoned_before_first_attempt"
            else:
                version_status = "observed_legacy"
            route_versions.append({
                "version": version,
                "registered_at": str(item["registered_at"]),
                "activation_cohort_id": int(item["activation_cohort_id"]),
                "definition_hash": hashlib.sha256(
                    str(item["definition_json"]).encode("utf-8")
                ).hexdigest(),
                "status": version_status,
                "summary": {
                    "attempts": attempts, "results": results,
                    "confirmations": confirmations,
                },
            })
        return {
            "status": status,
            "version": cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
            "route_version": cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            "route_status": route_status,
            "route_disposition": route_disposition,
            "registered_at": str(registration["registered_at"]) if registration else None,
            "activation_observation_id": (
                int(registration["activation_observation_id"]) if registration else None
            ),
            "route_registered_at": (
                str(route_registration["registered_at"]) if route_registration else None
            ),
            "route_activation_cohort_id": (
                int(route_registration["activation_cohort_id"]) if route_registration else None
            ),
            "summary": {
                "admission_attempts": count(
                    "kol_token_addressability_admission_attempts",
                    cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
                ),
                "cohorts": cohorts,
                "milestones": count(
                    "kol_token_addressability_milestones", cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
                ),
                "ambiguities": count(
                    "kol_token_addressability_ambiguities", cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
                ),
                "route_attempts": count(
                    "kol_token_addressability_route_attempts",
                    cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                ),
                "route_results": count(
                    "kol_token_addressability_route_results",
                    cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                ),
                "confirmation_results": count(
                    "kol_token_addressability_confirmation_results",
                    cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
                ),
            },
            "admission_reasons": grouped(
                "kol_token_addressability_admission_attempts", "reason",
                cls.KOL_TOKEN_ADDRESSABILITY_VERSION,
            ),
            "route_statuses": grouped(
                "kol_token_addressability_route_results", "status",
                cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            ),
            "route_terminal_statuses": grouped_non_null(
                "kol_token_addressability_route_results", "terminal_status_v2",
                cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            ),
            "route_surface_relations": grouped_non_null(
                "kol_token_addressability_route_results", "surface_relation",
                cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            ),
            "confirmation_statuses": grouped(
                "kol_token_addressability_confirmation_results", "status",
                cls.KOL_TOKEN_ADDRESSABILITY_ROUTE_VERSION,
            ),
            "legacy_base_versions": grouped(
                "kol_token_addressability_cohorts", "definition_version"
            ),
            "versions": versions,
            "route_versions": route_versions,
            "decision_eligible": False,
            "affects": "none",
            "production_writes": [],
        }

    @staticmethod
    def _information_first_label(value: Any) -> str:
        return re.sub(r"\s+", " ", str(value or "").strip().casefold())[:160]

    @classmethod
    def _information_first_active_outcome_definition(cls) -> dict[str, Any]:
        return {
            "version": cls.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
            "activation": "shadow_cohort_id_strictly_after_registration",
            "horizons_minutes": list(cls.INFORMATION_FIRST_SHADOW_HORIZONS_MINUTES),
            "retry_offsets_seconds": list(cls.INFORMATION_FIRST_ACTIVE_OUTCOME_RETRY_SECONDS),
            "deadline_seconds": cls.INFORMATION_FIRST_ACTIVE_OUTCOME_DEADLINE_SECONDS,
            "provider": "dexscreener",
            "semantics": "descriptive_mark_not_executable_pnl",
            "writes_generic_token_snapshots": False,
            "uses_jupiter": False,
            "uses_agent": False,
            "append_only": True,
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "none",
        }

    @classmethod
    def _information_first_ilg_definition(cls) -> dict[str, Any]:
        return {
            "version": cls.INFORMATION_FIRST_ILG_VERSION,
            "activity": {
                "volume_5m_usd": cls.INFORMATION_FIRST_ILG_VOLUME_5M_USD,
                "transactions_5m": cls.INFORMATION_FIRST_ILG_TRANSACTIONS_5M,
                "operator": "strict_greater_than_any",
                "market_cap_excluded": True,
            },
            "window_minutes": cls.INFORMATION_FIRST_ILG_WINDOW_MINUTES,
            "terminal_grace_minutes": cls.INFORMATION_FIRST_ILG_TERMINAL_GRACE_MINUTES,
            "time_basis": "durable_recorded_at",
            "interval_censored": True,
            "same_surface_only": True,
            "affects": "none",
        }

    @staticmethod
    def _information_first_snapshot_surface(row: sqlite3.Row) -> dict[str, str] | None:
        try:
            raw = json.loads(str(row["raw_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            return None
        raw = raw if isinstance(raw, dict) else {}
        pair = raw.get("pair") if isinstance(raw.get("pair"), dict) else raw
        provider = str(row["provider"] or "").strip().casefold()
        chain_id = str(pair.get("chainId") or pair.get("chain_id") or "").strip().casefold()
        dex_id = str(pair.get("dexId") or pair.get("dex_id") or "").strip().casefold()
        pair_address = str(
            pair.get("pairAddress") or pair.get("pair_address") or ""
        ).strip().casefold()
        if not all((provider, chain_id, dex_id, pair_address)):
            return None
        key = json.dumps(
            [provider, chain_id, dex_id, pair_address],
            ensure_ascii=True,
            separators=(",", ":"),
        )
        return {
            "key": key,
            "provider": provider,
            "chain_id": chain_id,
            "dex_id": dex_id,
            "pair_address": pair_address,
        }

    def _create_information_first_ilg_cohort(
        self, shadow_cohort_id: int, *, enrolled_at: Any = None
    ) -> int | None:
        enrolled = parse_time(enrolled_at or utcnow())
        registration = self.db.execute(
            "SELECT * FROM information_first_ilg_registrations WHERE definition_version=?",
            (self.INFORMATION_FIRST_ILG_VERSION,),
        ).fetchone()
        shadow = self.db.execute(
            "SELECT * FROM information_first_shadow_cohorts WHERE id=?",
            (int(shadow_cohort_id),),
        ).fetchone()
        if registration is None or shadow is None:
            return None
        if parse_time(shadow["signal_available_at"]) < parse_time(registration["registered_at"]):
            return None
        try:
            definition = json.loads(str(registration["definition_json"]))
            activity = definition["activity"]
            volume_threshold = float(activity["volume_5m_usd"])
            transactions_threshold = int(activity["transactions_5m"])
            window_minutes = int(definition["window_minutes"])
            grace_minutes = int(definition["terminal_grace_minutes"])
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            return None
        existing = self.db.execute(
            "SELECT id FROM information_first_ilg_cohorts WHERE shadow_cohort_id=?",
            (int(shadow_cohort_id),),
        ).fetchone()
        if existing is not None:
            return int(existing["id"])

        signal = parse_time(shadow["signal_available_at"])
        baseline = self.db.execute(
            """
            SELECT * FROM token_snapshots
            WHERE token_id=? AND observed_at<=? AND ingested_at<=? AND recorded_at<=?
              AND observed_at<=ingested_at AND ingested_at<=recorded_at
              AND volume_5m_usd IS NOT NULL AND buys_5m IS NOT NULL AND sells_5m IS NOT NULL
            ORDER BY recorded_at DESC,observed_at DESC,id DESC LIMIT 1
            """,
            (str(shadow["token_id"]), iso(signal), iso(signal), iso(signal)),
        ).fetchone()
        eligibility = "ineligible_activity_baseline_missing"
        reason = "no_strictly_forward_complete_baseline"
        transactions = None
        surface = None
        if baseline is not None:
            transactions = int(baseline["buys_5m"]) + int(baseline["sells_5m"])
            surface = self._information_first_snapshot_surface(baseline)
            if surface is None:
                eligibility = "ineligible_activity_surface_unknown"
                reason = "provider_chain_dex_pair_required"
            elif (
                float(baseline["volume_5m_usd"]) > volume_threshold
                or transactions > transactions_threshold
            ):
                eligibility = "already_active_at_signal"
                reason = "baseline_strictly_above_activity_threshold"
            else:
                eligibility = "eligible_at_risk"
                reason = "baseline_at_or_below_both_activity_thresholds"
        window_end = signal + timedelta(minutes=window_minutes)
        terminal = window_end + timedelta(minutes=grace_minutes)
        cursor = self.db.execute(
            """
            INSERT INTO information_first_ilg_cohorts(
                definition_version,shadow_cohort_id,enrolled_at,signal_available_at,token_id,
                eligibility,eligibility_reason,window_end_at,terminal_at,baseline_snapshot_id,
                baseline_recorded_at,baseline_volume_5m_usd,baseline_transactions_5m,
                surface_key,surface_provider,surface_chain_id,surface_dex_id,surface_pair_address,
                definition_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                self.INFORMATION_FIRST_ILG_VERSION, int(shadow_cohort_id), iso(enrolled), iso(signal),
                str(shadow["token_id"]), eligibility, reason, iso(window_end), iso(terminal),
                int(baseline["id"]) if baseline is not None else None,
                str(baseline["recorded_at"]) if baseline is not None else None,
                float(baseline["volume_5m_usd"]) if baseline is not None else None,
                transactions, surface["key"] if surface else None,
                surface["provider"] if surface else None, surface["chain_id"] if surface else None,
                surface["dex_id"] if surface else None, surface["pair_address"] if surface else None,
                str(registration["definition_json"]),
            ),
        )
        return int(cursor.lastrowid)

    @staticmethod
    def _information_first_source_facts(row: sqlite3.Row) -> tuple[str, str, str]:
        try:
            raw = json.loads(str(row["raw_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            raw = {}
        raw = raw if isinstance(raw, dict) else {}
        browser = raw.get("browser") if isinstance(raw.get("browser"), dict) else {}
        source = str(row["source"] or "").strip().casefold()[:200]
        source_kind = str(row["source_kind"] or "").strip().casefold()[:80]
        entity_id = str(raw.get("source_entity_id") or "").strip().casefold()
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9_-]{0,62}[a-z0-9])?", entity_id):
            entity_id = ""
        if source_kind in {"social", "official_social"}:
            origin = f"entity:{entity_id}" if entity_id else source
        else:
            publisher_url = str(raw.get("publisher_url") or "")
            article_url = str(row["url"] or "")
            origin = (urlparse(publisher_url).netloc or urlparse(article_url).netloc or source).casefold()
        platform = str(browser.get("platform") or raw.get("platform") or "").strip().casefold()
        if not platform:
            platform = source_kind
        return origin[:240], platform[:80], entity_id

    def create_information_first_shadow_cohort(
        self,
        event_id: int,
        token_id: str,
        *,
        decision_id: int,
        accepted_observation_ids: Iterable[int],
        captured_at: Any = None,
        relation_available_at: Any = None,
        candidate_facts: Mapping[str, Any] | None = None,
    ) -> int | None:
        """Freeze one information-first cohort from a final decision's known inputs.

        This is descriptive only. It records contemporaneously available facts and never
        creates a cohort from a later token, snapshot, or observation.
        """
        captured = parse_time(captured_at or utcnow())
        if captured > utcnow() + timedelta(seconds=5):
            raise ValueError("information-first cohort cannot be future-dated")
        relation_available = parse_time(relation_available_at or captured)
        if relation_available > captured:
            raise ValueError("relation availability cannot be after its decision capture")
        captured_text = iso(captured)
        relation_text = iso(relation_available)
        observation_ids = sorted({int(value) for value in accepted_observation_ids if int(value) > 0})
        candidate_facts = candidate_facts if isinstance(candidate_facts, Mapping) else {}
        cohort_key = hashlib.sha256(
            f"{self.INFORMATION_FIRST_SHADOW_VERSION}\n{int(event_id)}\n{str(token_id)}".encode("utf-8")
        ).hexdigest()
        admission_key = f"{self.INFORMATION_FIRST_SHADOW_VERSION}:{int(decision_id)}"
        with self._lock, self.db:
            prior_admission = self.db.execute(
                "SELECT cohort_id FROM information_first_shadow_admission_attempts WHERE admission_key=?",
                (admission_key,),
            ).fetchone()
            if prior_admission is not None:
                return int(prior_admission["cohort_id"]) if prior_admission["cohort_id"] else None

            def record_admission(status: str, reason: str, cohort_id: int | None = None) -> None:
                self.db.execute(
                    """
                    INSERT INTO information_first_shadow_admission_attempts(
                        admission_key,version,decision_id,event_id,token_id,attempted_at,
                        relation_available_at,status,reason,cohort_id
                    ) VALUES(?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        admission_key, self.INFORMATION_FIRST_SHADOW_VERSION, int(decision_id),
                        int(event_id), str(token_id), captured_text, relation_text,
                        status, reason, cohort_id,
                    ),
                )

            existing = self.db.execute(
                "SELECT id FROM information_first_shadow_cohorts WHERE version=? AND event_id=? AND token_id=?",
                (self.INFORMATION_FIRST_SHADOW_VERSION, int(event_id), str(token_id)),
            ).fetchone()
            if existing is not None:
                cohort_id = int(existing["id"])
                record_admission("already_admitted", "first_write_wins_event_token", cohort_id)
                return cohort_id
            decision = self.db.execute(
                """
                SELECT created_at FROM decisions
                WHERE id=? AND event_id=? AND token_id=?
                """,
                (int(decision_id), int(event_id), str(token_id)),
            ).fetchone()
            if decision is None:
                record_admission("skipped", "missing_or_mismatched_final_decision")
                return None
            if parse_time(decision["created_at"]) > captured:
                record_admission("skipped", "final_decision_after_capture")
                return None
            event = self.db.execute(
                "SELECT attention FROM events WHERE id=?", (int(event_id),)
            ).fetchone()
            token = self.db.execute(
                """
                SELECT * FROM tokens WHERE token_id=? AND first_seen_at<=?
                """,
                (str(token_id), captured_text),
            ).fetchone()
            if event is None or token is None:
                record_admission("skipped", "missing_event_or_token")
                return None
            if not observation_ids:
                record_admission("skipped", "missing_accepted_observations")
                return None
            placeholders = ",".join("?" for _ in observation_ids)
            leads = list(
                self.db.execute(
                    f"""
                    SELECT o.* FROM observations o
                    JOIN event_observations eo ON eo.observation_id=o.id
                    WHERE eo.event_id=? AND o.capture_phase='live'
                      AND o.role IN ('feature','confirmation')
                      AND o.source_kind<>'onchain'
                      AND o.id IN ({placeholders})
                      AND o.observed_at<=? AND o.ingested_at<=?
                      AND o.ingested_at>=o.observed_at
                      AND (o.published_at IS NULL OR o.published_at<=?)
                    ORDER BY CASE WHEN o.observed_at>o.ingested_at THEN o.observed_at ELSE o.ingested_at END,o.id
                    """,
                    (int(event_id), *observation_ids, captured_text, captured_text, captured_text),
                )
            )
            if not leads:
                record_admission("skipped", "no_eligible_accepted_information_lead")
                return None
            lead = leads[0]
            signal_available = max(
                parse_time(lead["observed_at"]), parse_time(lead["ingested_at"]), relation_available
            )
            signal_text = iso(signal_available)
            entry = self.db.execute(
                """
                SELECT * FROM token_snapshots
                WHERE token_id=? AND observed_at<=? AND ingested_at<=?
                  AND ingested_at>=observed_at AND price_usd>0
                ORDER BY observed_at DESC,id DESC LIMIT 1
                """,
                (str(token_id), signal_text, signal_text),
            ).fetchone()
            target_name = self._information_first_label(token["name"])
            target_symbol = self._information_first_label(token["symbol"])
            peers = list(
                self.db.execute(
                    "SELECT token_id,name,symbol FROM tokens WHERE token_id<>? AND first_seen_at<=?",
                    (str(token_id), signal_text),
                )
            )
            same_name_count = sum(
                bool(target_name) and self._information_first_label(row["name"]) == target_name
                for row in peers
            )
            same_symbol_count = sum(
                bool(target_symbol) and self._information_first_label(row["symbol"]) == target_symbol
                for row in peers
            )
            origins: set[str] = set()
            platforms: set[str] = set()
            source_kinds: set[str] = set()
            entities: set[str] = set()
            for row in leads:
                origin, platform, entity_id = self._information_first_source_facts(row)
                if origin:
                    origins.add(origin)
                if platform:
                    platforms.add(platform)
                source_kinds.add(str(row["source_kind"] or "").casefold())
                if entity_id:
                    entities.add(entity_id)
            transactions = (
                int(entry["buys_5m"]) + int(entry["sells_5m"])
                if entry is not None and entry["buys_5m"] is not None and entry["sells_5m"] is not None else None
            )
            market_complete = (
                entry is not None
                and entry["market_cap_usd"] is not None
                and entry["volume_5m_usd"] is not None
                and transactions is not None
            )
            if not market_complete:
                market_label = "insufficient_market_data"
            elif (
                float(entry["market_cap_usd"]) <= self.INFORMATION_FIRST_SHADOW_QUIET_MARKET_CAP_USD
                and float(entry["volume_5m_usd"]) <= self.INFORMATION_FIRST_SHADOW_QUIET_VOLUME_5M_USD
                and transactions <= self.INFORMATION_FIRST_SHADOW_QUIET_TRANSACTIONS_5M
            ):
                market_label = "low_observed_market_activity"
            else:
                market_label = "observed_market_activity"
            created_at = str(token["created_at"] or "")
            first_seen_at = str(token["first_seen_at"] or "")
            lead_at = parse_time(lead["observed_at"])
            pair_preexistence = (
                "unknown" if not created_at else
                "preexisting" if parse_time(created_at) < lead_at else
                "contemporaneous" if parse_time(created_at) == lead_at else "post_event"
            )
            local_preexistence = (
                "locally_known_before_or_at_information_lead"
                if parse_time(first_seen_at) <= lead_at else "locally_first_seen_after_information_lead"
            )
            features = {
                "event_attention": float(event["attention"]),
                "market_state": {
                    "label": market_label,
                    "liquidity_usd": entry["liquidity_usd"] if entry is not None else None,
                    "market_cap_usd": entry["market_cap_usd"] if entry is not None else None,
                    "volume_5m_usd": entry["volume_5m_usd"] if entry is not None else None,
                    "buys_5m": entry["buys_5m"] if entry is not None else None,
                    "sells_5m": entry["sells_5m"] if entry is not None else None,
                    "transactions_5m": transactions,
                    "entry_snapshot_age_seconds": max(
                        0.0, (signal_available - parse_time(entry["observed_at"])).total_seconds()
                    ) if entry is not None else None,
                    "thresholds": {
                        "market_cap_usd": self.INFORMATION_FIRST_SHADOW_QUIET_MARKET_CAP_USD,
                        "volume_5m_usd": self.INFORMATION_FIRST_SHADOW_QUIET_VOLUME_5M_USD,
                        "transactions_5m": self.INFORMATION_FIRST_SHADOW_QUIET_TRANSACTIONS_5M,
                    },
                },
                "token_preexistence": {
                    "status": "not_available",
                    "reason": "chain_mint_time_not_collected",
                    "local_first_seen_at": first_seen_at,
                    "local_preexistence": local_preexistence,
                },
                "pair_preexistence_descriptive": {
                    "pair_created_at": created_at or None,
                    "status": pair_preexistence,
                    "provider": "token_created_at",
                },
                "same_name_competition": {
                    "normalized_name": target_name or None,
                    "normalized_symbol": target_symbol or None,
                    "preexisting_same_name_count": same_name_count,
                    "preexisting_same_symbol_count": same_symbol_count,
                },
                "candidate_ambiguity": {
                    "candidate_count": candidate_facts.get("candidate_count"),
                    "selected_rank": candidate_facts.get("selected_rank"),
                    "raw_score_margin": candidate_facts.get("raw_score_margin"),
                    "canonical_margin": candidate_facts.get("canonical_margin"),
                    "tie_break_used": bool(candidate_facts.get("tie_break_used")),
                    "mapping_basis": candidate_facts.get("mapping_basis") or "unknown",
                    "candidate_set_truncated": bool(candidate_facts.get("candidate_set_truncated")),
                },
                "attention_source_breadth": {
                    "mode": "descriptive_observed_origins_not_independence_claim",
                    "qualified_observation_count": len(leads),
                    "distinct_origin_count": len(origins),
                    "distinct_platform_count": len(platforms),
                    "distinct_source_kind_count": len(source_kinds),
                    "exact_source_entity_count": len(entities),
                },
                "not_available": ["unique_buyers", "image_similarity", "holder_clusters"],
            }
            cursor = self.db.execute(
                """
                INSERT INTO information_first_shadow_cohorts(
                    cohort_key,version,event_id,token_id,decision_id,captured_at,signal_available_at,
                    relation_available_at,lead_observation_id,
                    lead_observed_at,entry_snapshot_id,entry_snapshot_at,entry_snapshot_ingested_at,
                    entry_price,trackability,features_json,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    cohort_key, self.INFORMATION_FIRST_SHADOW_VERSION, int(event_id), str(token_id),
                    int(decision_id), captured_text, signal_text, relation_text, int(lead["id"]),
                    str(lead["observed_at"]), int(entry["id"]) if entry is not None else None,
                    str(entry["observed_at"]) if entry is not None else None,
                    str(entry["ingested_at"]) if entry is not None else None,
                    float(entry["price_usd"]) if entry is not None else None,
                    "trackable" if entry is not None else "baseline_missing_at_signal_available",
                    self._json(features), iso(),
                ),
            )
            cohort_id = int(cursor.lastrowid)
            self._enroll_information_first_active_outcomes_locked(cohort_id)
            self._create_information_first_ilg_cohort(cohort_id, enrolled_at=captured)
            record_admission(
                "created_baseline_missing" if entry is None else "created",
                "baseline_missing_at_signal_available" if entry is None else "created",
                cohort_id,
            )
            return cohort_id

    def _enroll_information_first_active_outcomes_locked(self, shadow_cohort_id: int) -> int:
        registration = self.db.execute(
            "SELECT * FROM information_first_active_outcome_registrations "
            "WHERE definition_version=?",
            (self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,),
        ).fetchone()
        if (
            registration is None
            or int(shadow_cohort_id) <= int(registration["activation_shadow_cohort_id"])
        ):
            return 0
        cohort = self.db.execute(
            "SELECT c.*,t.chain,t.address FROM information_first_shadow_cohorts c "
            "JOIN tokens t ON t.token_id=c.token_id WHERE c.id=? AND c.version=?",
            (int(shadow_cohort_id), self.INFORMATION_FIRST_SHADOW_VERSION),
        ).fetchone()
        if cohort is None or str(cohort["chain"] or "").casefold() not in {"solana", "bsc"}:
            return 0
        signal = parse_time(cohort["signal_available_at"])
        recorded_at = iso()
        inserted = 0
        for horizon in self.INFORMATION_FIRST_SHADOW_HORIZONS_MINUTES:
            target = signal + timedelta(minutes=int(horizon))
            deadline = target + timedelta(
                seconds=self.INFORMATION_FIRST_ACTIVE_OUTCOME_DEADLINE_SECONDS
            )
            target_key = hashlib.sha256(
                f"{self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION}\n{int(shadow_cohort_id)}\n{int(horizon)}".encode(
                    "utf-8"
                )
            ).hexdigest()
            cursor = self.db.execute(
                "INSERT OR IGNORE INTO information_first_active_outcome_targets("
                "target_key,definition_version,shadow_cohort_id,token_id,chain,address,"
                "horizon_minutes,target_at,deadline_at,registered_at,decision_eligible,affects) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,0,'none')",
                (
                    target_key,
                    self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
                    int(shadow_cohort_id),
                    str(cohort["token_id"]),
                    str(cohort["chain"]).casefold(),
                    str(cohort["address"]),
                    int(horizon),
                    iso(target),
                    iso(deadline),
                    recorded_at,
                ),
            )
            inserted += int(cursor.rowcount > 0)
        return inserted

    def due_information_first_active_outcome_targets(
        self, *, now: Any = None, limit: int = 4
    ) -> list[dict[str, Any]]:
        evaluated = parse_time(now or utcnow())
        due: list[dict[str, Any]] = []
        with self._lock:
            rows = list(
                self.db.execute(
                    """
                    SELECT t.*,COUNT(a.id) AS attempt_count
                    FROM information_first_active_outcome_targets t
                    LEFT JOIN information_first_active_outcome_attempts a ON a.target_id=t.id
                    LEFT JOIN information_first_active_outcome_terminals z ON z.target_id=t.id
                    WHERE t.definition_version=? AND z.id IS NULL
                      AND t.target_at<=? AND t.deadline_at>=?
                    GROUP BY t.id ORDER BY t.target_at,t.id
                    """,
                    (
                        self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
                        iso(evaluated),
                        iso(evaluated),
                    ),
                )
            )
        for row in rows:
            retry_index = int(row["attempt_count"])
            if retry_index >= len(self.INFORMATION_FIRST_ACTIVE_OUTCOME_RETRY_SECONDS):
                continue
            scheduled = parse_time(row["target_at"]) + timedelta(
                seconds=self.INFORMATION_FIRST_ACTIVE_OUTCOME_RETRY_SECONDS[retry_index]
            )
            if scheduled > evaluated:
                continue
            item = dict(row)
            item["retry_index"] = retry_index
            item["scheduled_at"] = iso(scheduled)
            due.append(item)
            if len(due) >= max(1, min(50, int(limit))):
                break
        return due

    def start_information_first_active_outcome_attempt(
        self,
        target_id: int,
        *,
        retry_index: int,
        scheduled_at: Any,
        requested_at: Any = None,
    ) -> int | None:
        requested = parse_time(requested_at or utcnow())
        scheduled = parse_time(scheduled_at)
        attempt_key = hashlib.sha256(
            f"{self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION}\n{int(target_id)}\n{int(retry_index)}".encode(
                "utf-8"
            )
        ).hexdigest()
        with self._lock, self.db:
            target = self.db.execute(
                "SELECT t.* FROM information_first_active_outcome_targets t "
                "LEFT JOIN information_first_active_outcome_terminals z ON z.target_id=t.id "
                "WHERE t.id=? AND t.definition_version=? AND z.id IS NULL",
                (int(target_id), self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION),
            ).fetchone()
            if (
                target is None
                or scheduled > requested
                or requested > parse_time(target["deadline_at"])
            ):
                return None
            self.db.execute(
                "INSERT OR IGNORE INTO information_first_active_outcome_attempts("
                "attempt_key,definition_version,target_id,retry_index,scheduled_at,requested_at,"
                "recorded_at,decision_eligible,affects) VALUES(?,?,?,?,?,?,?,0,'none')",
                (
                    attempt_key,
                    self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
                    int(target_id),
                    int(retry_index),
                    iso(scheduled),
                    iso(requested),
                    iso(),
                ),
            )
            row = self.db.execute(
                "SELECT id FROM information_first_active_outcome_attempts WHERE attempt_key=?",
                (attempt_key,),
            ).fetchone()
        return int(row["id"]) if row is not None else None

    def finish_information_first_active_outcome_attempt(
        self,
        attempt_id: int,
        *,
        status: str,
        reason_code: str,
        response_received_at: Any = None,
        snapshot: TokenSnapshot | None = None,
    ) -> int:
        allowed = {
            "observed_mark", "no_pair", "rate_limited", "http_error", "timeout",
            "protocol_invalid", "provider_empty", "late_response",
        }
        status = str(status).strip().casefold()
        if status not in allowed:
            raise ValueError("invalid information-first active outcome status")
        received = parse_time(response_received_at or utcnow())
        with self._lock, self.db:
            row = self.db.execute(
                "SELECT a.*,t.deadline_at FROM information_first_active_outcome_attempts a "
                "JOIN information_first_active_outcome_targets t ON t.id=a.target_id WHERE a.id=?",
                (int(attempt_id),),
            ).fetchone()
            if row is None:
                raise ValueError("information-first active outcome attempt missing")
            existing = self.db.execute(
                "SELECT id FROM information_first_active_outcome_results WHERE attempt_id=?",
                (int(attempt_id),),
            ).fetchone()
            if existing is not None:
                return int(existing["id"])
            if received > parse_time(row["deadline_at"]):
                status, reason_code = "late_response", "response_after_frozen_deadline"
                snapshot = None
            requested = parse_time(row["requested_at"])
            result_key = hashlib.sha256(
                f"{self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION}\n{int(attempt_id)}".encode("utf-8")
            ).hexdigest()
            cursor = self.db.execute(
                "INSERT INTO information_first_active_outcome_results("
                "result_key,definition_version,target_id,attempt_id,status,reason_code,"
                "response_received_at,latency_ms,observed_at,provider,price_usd,liquidity_usd,"
                "market_cap_usd,volume_5m_usd,buys_5m,sells_5m,recorded_at,decision_eligible,affects) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')",
                (
                    result_key,
                    self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
                    int(row["target_id"]),
                    int(attempt_id),
                    status,
                    str(reason_code)[:160],
                    iso(received),
                    max(0.0, (received - requested).total_seconds() * 1000),
                    iso(snapshot.observed_at) if snapshot is not None else None,
                    str(snapshot.provider) if snapshot is not None else None,
                    snapshot.price_usd if snapshot is not None else None,
                    snapshot.liquidity_usd if snapshot is not None else None,
                    snapshot.market_cap_usd if snapshot is not None else None,
                    snapshot.volume_5m_usd if snapshot is not None else None,
                    snapshot.buys_5m if snapshot is not None else None,
                    snapshot.sells_5m if snapshot is not None else None,
                    iso(),
                ),
            )
            result_id = int(cursor.lastrowid)
            if status in {"observed_mark", "no_pair", "late_response"}:
                self.db.execute(
                    "INSERT OR IGNORE INTO information_first_active_outcome_terminals("
                    "target_id,definition_version,status,reason_code,winning_result_id,"
                    "response_received_at,observed_at,provider,price_usd,liquidity_usd,market_cap_usd,"
                    "volume_5m_usd,buys_5m,sells_5m,finalized_at,decision_eligible,affects) "
                    "SELECT target_id,definition_version,status,reason_code,id,response_received_at,"
                    "observed_at,provider,price_usd,liquidity_usd,market_cap_usd,volume_5m_usd,"
                    "buys_5m,sells_5m,?,0,'none' FROM information_first_active_outcome_results WHERE id=?",
                    (iso(received), result_id),
                )
        return result_id

    def finalize_information_first_active_outcome_deadlines(
        self, *, now: Any = None
    ) -> dict[str, int]:
        evaluated = parse_time(now or utcnow())
        finalized = 0
        with self._lock, self.db:
            targets = list(
                self.db.execute(
                    "SELECT t.* FROM information_first_active_outcome_targets t "
                    "LEFT JOIN information_first_active_outcome_terminals z ON z.target_id=t.id "
                    "WHERE t.definition_version=? AND z.id IS NULL AND t.deadline_at<=? "
                    "ORDER BY t.deadline_at,t.id",
                    (self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION, iso(evaluated)),
                )
            )
            for target in targets:
                attempt_count = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM information_first_active_outcome_attempts WHERE target_id=?",
                        (int(target["id"]),),
                    ).fetchone()[0]
                )
                last_result = self.db.execute(
                    "SELECT * FROM information_first_active_outcome_results WHERE target_id=? "
                    "ORDER BY id DESC LIMIT 1",
                    (int(target["id"]),),
                ).fetchone()
                if attempt_count == 0:
                    status, reason = "scheduler_missed_deadline", "no_request_before_deadline"
                else:
                    status = "terminal_missing"
                    reason = (
                        f"last_{last_result['status']}:{last_result['reason_code']}"
                        if last_result is not None else "attempt_without_result"
                    )
                cursor = self.db.execute(
                    "INSERT OR IGNORE INTO information_first_active_outcome_terminals("
                    "target_id,definition_version,status,reason_code,finalized_at,"
                    "decision_eligible,affects) VALUES(?,?,?,?,?,0,'none')",
                    (
                        int(target["id"]),
                        self.INFORMATION_FIRST_ACTIVE_OUTCOME_VERSION,
                        status,
                        reason[:160],
                        iso(evaluated),
                    ),
                )
                finalized += int(cursor.rowcount > 0)
        return {"targets_checked": len(targets), "targets_finalized": finalized}

    def finalize_information_first_shadow_outcomes(
        self,
        *,
        now: Any = None,
        horizons_minutes: Iterable[int] | None = None,
        max_lateness_minutes: int = 30,
    ) -> dict[str, int]:
        """Append fixed-horizon descriptive outcomes without historical backfill."""
        evaluated_at = parse_time(now or utcnow())
        horizons = tuple(sorted({
            max(1, int(value))
            for value in (horizons_minutes or self.INFORMATION_FIRST_SHADOW_HORIZONS_MINUTES)
        }))
        observed_count = 0
        missing_count = 0
        with self._lock, self.db:
            cohorts = list(self.db.execute(
                "SELECT * FROM information_first_shadow_cohorts WHERE trackability='trackable' ORDER BY captured_at,id"
            ))
            for cohort in cohorts:
                existing = {
                    int(row["horizon_minutes"])
                    for row in self.db.execute(
                        "SELECT horizon_minutes FROM information_first_shadow_outcomes WHERE cohort_id=?",
                        (int(cohort["id"]),),
                    )
                }
                for horizon in horizons:
                    if horizon in existing:
                        continue
                    target = parse_time(cohort["signal_available_at"]) + timedelta(minutes=horizon)
                    if evaluated_at < target:
                        continue
                    deadline = target + timedelta(minutes=max(1, int(max_lateness_minutes)))
                    upper = min(evaluated_at, deadline)
                    snapshot = self.db.execute(
                        """
                        SELECT id,observed_at,ingested_at,price_usd FROM token_snapshots
                        WHERE token_id=? AND observed_at>=? AND observed_at<=?
                          AND ingested_at>=? AND ingested_at<=?
                          AND ingested_at>=observed_at AND price_usd>0
                        ORDER BY ingested_at,observed_at,id LIMIT 1
                        """,
                        (str(cohort["token_id"]), iso(target), iso(upper), iso(target), iso(upper)),
                    ).fetchone()
                    if snapshot is not None:
                        path = list(self.db.execute(
                            """
                            SELECT price_usd FROM token_snapshots
                            WHERE token_id=? AND observed_at>=? AND observed_at<=?
                              AND ingested_at IS NOT NULL AND ingested_at<=?
                              AND ingested_at>=observed_at AND price_usd>0
                            ORDER BY observed_at,id
                            """,
                            (
                                str(cohort["token_id"]), str(cohort["entry_snapshot_at"]),
                                str(snapshot["observed_at"]), str(snapshot["ingested_at"]),
                            ),
                        ))
                        entry_price = float(cohort["entry_price"])
                        returns = [float(row["price_usd"]) / entry_price - 1.0 for row in path]
                        raw_return = float(snapshot["price_usd"]) / entry_price - 1.0
                        self.db.execute(
                            """
                            INSERT INTO information_first_shadow_outcomes(
                                cohort_id,horizon_minutes,target_at,status,outcome_snapshot_id,
                                outcome_observed_at,outcome_price,raw_return,maximum_return,minimum_return,
                                snapshot_count,evaluated_at
                            ) VALUES(?,?,?,'observed',?,?,?,?,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), horizon, iso(target), int(snapshot["id"]),
                                str(snapshot["observed_at"]), float(snapshot["price_usd"]), raw_return,
                                max(returns) if returns else raw_return,
                                min(returns) if returns else raw_return,
                                len(path), iso(evaluated_at),
                            ),
                        )
                        observed_count += 1
                    elif evaluated_at >= deadline:
                        self.db.execute(
                            """
                            INSERT INTO information_first_shadow_outcomes(
                                cohort_id,horizon_minutes,target_at,status,snapshot_count,evaluated_at
                            ) VALUES(?,?,?,'missing',0,?)
                            """,
                            (int(cohort["id"]), horizon, iso(target), iso(evaluated_at)),
                        )
                        missing_count += 1
        outcome_total = int(self.db.execute(
            "SELECT COUNT(*) FROM information_first_shadow_outcomes"
        ).fetchone()[0])
        return {
            "cohorts_checked": len(cohorts),
            "outcomes_observed": observed_count,
            "outcomes_missing": missing_count,
            "pending_outcomes": max(0, len(cohorts) * len(horizons) - outcome_total),
        }

    def finalize_information_first_ilg_outcomes(self, *, now: Any = None) -> dict[str, int]:
        """Freeze the first durable same-surface activity crossing, or its terminal missing state."""
        evaluated = parse_time(now or utcnow())
        crossed_count = 0
        missing_count = 0
        with self._lock, self.db:
            cohorts = list(self.db.execute(
                """
                SELECT c.* FROM information_first_ilg_cohorts c
                LEFT JOIN information_first_ilg_outcomes o ON o.ilg_cohort_id=c.id
                WHERE c.eligibility='eligible_at_risk' AND o.id IS NULL
                ORDER BY c.signal_available_at,c.id
                """
            ))
            for cohort in cohorts:
                try:
                    definition = json.loads(str(cohort["definition_json"]))
                    activity = definition["activity"]
                    volume_threshold = float(activity["volume_5m_usd"])
                    transactions_threshold = int(activity["transactions_5m"])
                except (KeyError, TypeError, ValueError, json.JSONDecodeError):
                    continue
                signal = parse_time(cohort["signal_available_at"])
                window_end = parse_time(cohort["window_end_at"])
                terminal = parse_time(cohort["terminal_at"])
                upper = min(evaluated, window_end)
                rows = list(self.db.execute(
                    """
                    SELECT * FROM token_snapshots
                    WHERE token_id=? AND observed_at>=? AND observed_at<=?
                      AND ingested_at>=? AND ingested_at<=?
                      AND recorded_at>? AND recorded_at<=?
                      AND observed_at<=ingested_at AND ingested_at<=recorded_at
                      AND volume_5m_usd IS NOT NULL AND buys_5m IS NOT NULL AND sells_5m IS NOT NULL
                    ORDER BY recorded_at,observed_at,id
                    """,
                    (
                        str(cohort["token_id"]), iso(signal), iso(window_end),
                        iso(signal), iso(window_end), iso(signal), iso(upper),
                    ),
                )) if upper > signal else []
                valid = [
                    row for row in rows
                    if (
                        (surface := self._information_first_snapshot_surface(row)) is not None
                        and surface["key"] == str(cohort["surface_key"])
                    )
                ]
                crossing = None
                crossing_valid_count = 0
                dimensions: list[str] = []
                for valid_index, row in enumerate(valid, start=1):
                    transactions = int(row["buys_5m"]) + int(row["sells_5m"])
                    current_dimensions = []
                    if float(row["volume_5m_usd"]) > volume_threshold:
                        current_dimensions.append("volume_5m_usd")
                    if transactions > transactions_threshold:
                        current_dimensions.append("transactions_5m")
                    if current_dimensions:
                        crossing = row
                        crossing_valid_count = valid_index
                        dimensions = current_dimensions
                        break
                if crossing is not None:
                    transactions = int(crossing["buys_5m"]) + int(crossing["sells_5m"])
                    recorded = parse_time(crossing["recorded_at"])
                    self.db.execute(
                        """
                        INSERT INTO information_first_ilg_outcomes(
                            ilg_cohort_id,status,window_end_at,terminal_at,crossing_snapshot_id,
                            crossing_observed_at,crossing_ingested_at,crossing_recorded_at,ilg_seconds,
                            crossing_volume_5m_usd,crossing_transactions_5m,crossed_dimensions_json,
                            valid_snapshot_count,surface_key,evaluated_at
                        ) VALUES(?,'crossed',?,?,?,?,?,?,?,?,?,?,?,?,?)
                        """,
                        (
                            int(cohort["id"]), str(cohort["window_end_at"]), str(cohort["terminal_at"]),
                            int(crossing["id"]), str(crossing["observed_at"]),
                            str(crossing["ingested_at"]), str(crossing["recorded_at"]),
                            (recorded - signal).total_seconds(), float(crossing["volume_5m_usd"]),
                            transactions, self._json(dimensions), crossing_valid_count,
                            str(cohort["surface_key"]),
                            iso(evaluated),
                        ),
                    )
                    crossed_count += 1
                elif evaluated >= terminal:
                    status = (
                        "missing_not_crossed_by_240m"
                        if valid else "missing_no_valid_activity_snapshot"
                    )
                    self.db.execute(
                        """
                        INSERT INTO information_first_ilg_outcomes(
                            ilg_cohort_id,status,window_end_at,terminal_at,crossed_dimensions_json,
                            valid_snapshot_count,surface_key,evaluated_at
                        ) VALUES(?,?,?,?, '[]',?,?,?)
                        """,
                        (
                            int(cohort["id"]), status, str(cohort["window_end_at"]),
                            str(cohort["terminal_at"]), len(valid), str(cohort["surface_key"]),
                            iso(evaluated),
                        ),
                    )
                    missing_count += 1
        pending = int(self.db.execute(
            """
            SELECT COUNT(*) FROM information_first_ilg_cohorts c
            LEFT JOIN information_first_ilg_outcomes o ON o.ilg_cohort_id=c.id
            WHERE c.eligibility='eligible_at_risk' AND o.id IS NULL
            """
        ).fetchone()[0])
        return {
            "cohorts_checked": len(cohorts),
            "outcomes_crossed": crossed_count,
            "outcomes_missing": missing_count,
            "outcomes_pending": pending,
        }

    @classmethod
    def information_first_ilg_summary_from_connection(
        cls, connection: sqlite3.Connection, *, lookback_days: int = 90
    ) -> dict[str, Any]:
        definition = cls._information_first_ilg_definition()
        empty = {
            "version": cls.INFORMATION_FIRST_ILG_VERSION,
            "status": "not_observed",
            "mode": "strict_forward_interval_censored",
            "affects": "none",
            "definition": definition,
            "items": [],
            "summary": {
                "registered_cohorts": 0, "eligible_at_risk": 0, "already_active_at_signal": 0,
                "activity_baseline_missing": 0, "activity_surface_unknown": 0,
                "pre_registration_excluded": 0, "crossed": 0,
                "missing_not_crossed_by_240m": 0, "missing_no_valid_activity_snapshot": 0,
                "pending": 0, "crossing_rate": None, "median_ilg_seconds": None,
                "p25_ilg_seconds": None, "p75_ilg_seconds": None,
            },
        }
        tables = {
            str(row["name"])
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }
        required = {
            "information_first_ilg_registrations", "information_first_ilg_cohorts",
            "information_first_ilg_outcomes", "information_first_shadow_cohorts",
        }
        if not required.issubset(tables):
            return {**empty, "status": "unavailable"}
        registration = connection.execute(
            "SELECT * FROM information_first_ilg_registrations WHERE definition_version=?",
            (cls.INFORMATION_FIRST_ILG_VERSION,),
        ).fetchone()
        if registration is None:
            return {**empty, "status": "unavailable"}
        try:
            frozen_definition = json.loads(str(registration["definition_json"]))
        except (TypeError, json.JSONDecodeError):
            frozen_definition = definition
        start = iso(utcnow() - timedelta(days=max(1, min(3650, int(lookback_days)))))
        cohorts = list(connection.execute(
            "SELECT * FROM information_first_ilg_cohorts WHERE enrolled_at>=? ORDER BY enrolled_at,id",
            (start,),
        ))
        pre_registration = int(connection.execute(
            """
            SELECT COUNT(*) FROM information_first_shadow_cohorts s
            WHERE s.signal_available_at<? AND s.captured_at>=?
            """,
            (str(registration["registered_at"]), start),
        ).fetchone()[0])
        if not cohorts:
            result = dict(empty)
            result["definition"] = frozen_definition
            result["summary"] = {**empty["summary"], "pre_registration_excluded": pre_registration}
            result["registered_at"] = str(registration["registered_at"])
            return result
        ids = [int(row["id"]) for row in cohorts]
        placeholders = ",".join("?" for _ in ids)
        outcomes = list(connection.execute(
            f"SELECT * FROM information_first_ilg_outcomes WHERE ilg_cohort_id IN ({placeholders})",
            ids,
        ))
        by_cohort = {int(row["ilg_cohort_id"]): row for row in outcomes}
        eligible = [row for row in cohorts if str(row["eligibility"]) == "eligible_at_risk"]
        crossed = [row for row in outcomes if str(row["status"]) == "crossed"]
        values = sorted(float(row["ilg_seconds"]) for row in crossed if row["ilg_seconds"] is not None)

        def percentile(fraction: float) -> float | None:
            if not values:
                return None
            position = (len(values) - 1) * fraction
            lower = int(math.floor(position))
            upper = int(math.ceil(position))
            if lower == upper:
                return values[lower]
            return values[lower] + (values[upper] - values[lower]) * (position - lower)

        items = []
        for eligibility in sorted({str(row["eligibility"]) for row in cohorts}):
            rows = [row for row in cohorts if str(row["eligibility"]) == eligibility]
            row_outcomes = [by_cohort[int(row["id"])] for row in rows if int(row["id"]) in by_cohort]
            item_values = sorted(
                float(row["ilg_seconds"])
                for row in row_outcomes
                if str(row["status"]) == "crossed" and row["ilg_seconds"] is not None
            )
            items.append({
                "eligibility": eligibility,
                "cohorts": len(rows),
                "crossed": sum(str(row["status"]) == "crossed" for row in row_outcomes),
                "missing": sum(str(row["status"]).startswith("missing_") for row in row_outcomes),
                "pending": len(rows) - len(row_outcomes) if eligibility == "eligible_at_risk" else 0,
                "median_ilg_seconds": item_values[len(item_values) // 2] if item_values else None,
            })
        summary = {
            "registered_cohorts": len(cohorts),
            "eligible_at_risk": len(eligible),
            "already_active_at_signal": sum(str(row["eligibility"]) == "already_active_at_signal" for row in cohorts),
            "activity_baseline_missing": sum(str(row["eligibility"]) == "ineligible_activity_baseline_missing" for row in cohorts),
            "activity_surface_unknown": sum(str(row["eligibility"]) == "ineligible_activity_surface_unknown" for row in cohorts),
            "pre_registration_excluded": pre_registration,
            "crossed": len(crossed),
            "missing_not_crossed_by_240m": sum(str(row["status"]) == "missing_not_crossed_by_240m" for row in outcomes),
            "missing_no_valid_activity_snapshot": sum(str(row["status"]) == "missing_no_valid_activity_snapshot" for row in outcomes),
            "pending": len(eligible) - len(outcomes),
            "crossing_rate": round(len(crossed) / len(eligible), 6) if eligible else None,
            "median_ilg_seconds": percentile(0.5),
            "p25_ilg_seconds": percentile(0.25),
            "p75_ilg_seconds": percentile(0.75),
        }
        return {
            "version": cls.INFORMATION_FIRST_ILG_VERSION,
            "status": "collecting" if summary["pending"] else "observed",
            "mode": "strict_forward_interval_censored",
            "affects": "none",
            "definition": frozen_definition,
            "registered_at": str(registration["registered_at"]),
            "items": items,
            "summary": summary,
            "as_of": iso(),
        }

    @classmethod
    def information_first_shadow_summary_from_connection(
        cls,
        connection: sqlite3.Connection,
        *,
        lookback_days: int = 90,
    ) -> dict[str, Any]:
        empty = {
            "version": cls.INFORMATION_FIRST_SHADOW_VERSION,
            "status": "not_observed",
            "mode": "descriptive_forward_only_observation",
            "affects": "none",
            "items": [],
            "summary": {
                "cohorts": 0, "independent_events": 0, "independent_tokens": 0,
                "outcomes_observed": 0, "outcomes_missing": 0, "outcomes_pending": 0,
                "baseline_missing_at_signal_available": 0,
                "admission_attempts": 0, "admissions_created": 0, "admissions_skipped": 0,
            },
        }
        tables = {
            str(row["name"])
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }
        required = {"information_first_shadow_cohorts", "information_first_shadow_outcomes"}
        if not required.issubset(tables):
            return {**empty, "status": "unavailable"}
        start = iso(utcnow() - timedelta(days=max(1, min(3650, int(lookback_days)))))
        cohorts = list(connection.execute(
            "SELECT * FROM information_first_shadow_cohorts WHERE captured_at>=? ORDER BY captured_at,id",
            (start,),
        ))
        if not cohorts:
            return empty
        cohort_ids = [int(row["id"]) for row in cohorts]
        trackable_ids = {
            int(row["id"]) for row in cohorts if str(row["trackability"]) == "trackable"
        }
        placeholders = ",".join("?" for _ in cohort_ids)
        outcomes = list(connection.execute(
            f"SELECT * FROM information_first_shadow_outcomes WHERE cohort_id IN ({placeholders})",
            cohort_ids,
        ))
        attempts = list(connection.execute(
            """
            SELECT * FROM information_first_shadow_admission_attempts
            WHERE attempted_at>=? ORDER BY attempted_at,id
            """,
            (start,),
        )) if "information_first_shadow_admission_attempts" in tables else []
        by_cohort_horizon = {(int(row["cohort_id"]), int(row["horizon_minutes"])): row for row in outcomes}
        groups: dict[str, list[sqlite3.Row]] = {}
        for cohort in cohorts:
            try:
                features = json.loads(str(cohort["features_json"] or "{}"))
            except (TypeError, json.JSONDecodeError):
                features = {}
            market = features.get("market_state") if isinstance(features, dict) else {}
            label = str(market.get("label") or "insufficient_market_data") if isinstance(market, dict) else "insufficient_market_data"
            groups.setdefault(label, []).append(cohort)
        items = []
        for label, rows in sorted(groups.items()):
            trackable_count = sum(str(row["trackability"]) == "trackable" for row in rows)
            observed = []
            missing = []
            for row in rows:
                outcome = by_cohort_horizon.get((int(row["id"]), 60))
                if outcome is not None and str(outcome["status"]) == "observed":
                    observed.append(outcome)
                elif outcome is not None and str(outcome["status"]) == "missing":
                    missing.append(outcome)
            values = [float(row["raw_return"]) for row in observed if row and row["raw_return"] is not None]
            items.append({
                "market_state": label,
                "cohorts": len(rows),
                "trackable_cohorts": trackable_count,
                "baseline_missing_at_signal_available": sum(
                    str(row["trackability"]) == "baseline_missing_at_signal_available" for row in rows
                ),
                "observed_60m": len(observed),
                "missing_60m": len(missing),
                "pending_60m": trackable_count - len(observed) - len(missing),
                "mean_raw_return_60m": round(sum(values) / len(values), 6) if values else None,
            })
        observed_total = sum(str(row["status"]) == "observed" for row in outcomes)
        missing_total = sum(str(row["status"]) == "missing" for row in outcomes)
        return {
            "version": cls.INFORMATION_FIRST_SHADOW_VERSION,
            "status": "collecting" if len(outcomes) < len(trackable_ids) * len(cls.INFORMATION_FIRST_SHADOW_HORIZONS_MINUTES) else "observed",
            "mode": "descriptive_forward_only_observation",
            "affects": "none",
            "items": items,
            "summary": {
                "cohorts": len(cohorts),
                "independent_events": len({int(row["event_id"]) for row in cohorts}),
                "independent_tokens": len({str(row["token_id"]) for row in cohorts}),
                "outcomes_observed": observed_total,
                "outcomes_missing": missing_total,
                "outcomes_pending": max(0, len(trackable_ids) * len(cls.INFORMATION_FIRST_SHADOW_HORIZONS_MINUTES) - len(outcomes)),
                "baseline_missing_at_signal_available": len(cohorts) - len(trackable_ids),
                "admission_attempts": len(attempts),
                "admissions_created": sum(
                    str(row["status"]) in {"created", "created_baseline_missing"}
                    for row in attempts
                ),
                "admissions_skipped": sum(str(row["status"]) == "skipped" for row in attempts),
            },
            "not_available": ["unique_buyers", "image_similarity", "holder_clusters"],
            "as_of": iso(),
        }

    @staticmethod
    def shadow_event_admission_summary_from_connection(
        connection: sqlite3.Connection, *, lookback_days: int = 90
    ) -> dict[str, Any]:
        empty = {
            "status": "not_observed",
            "version": Store.SHADOW_EVENT_ADMISSION_VERSION,
            "items": [],
            "reasons": [],
            "summary": {
                "decision_count": 0,
                "instrumented_decisions": 0,
                "legacy_or_uninstrumented_decisions": 0,
                "attempts": 0,
                "created": 0,
                "already_admitted": 0,
                "skipped": 0,
                "candidate_decisions": 0,
                "candidate_instrumented": 0,
                "candidate_covered": 0,
                "candidate_skipped": 0,
                "candidate_legacy_or_uninstrumented": 0,
                "forward_candidate_coverage_rate": None,
                "overall_candidate_coverage_rate": None,
                "wait_decisions": 0,
                "reject_decisions": 0,
                "reject_covered": 0,
            },
            "mode": "forward_append_only_observation",
            "affects": "none",
        }
        tables = {
            str(row["name"])
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }
        ledger_available = "shadow_event_admission_attempts" in tables
        start = iso(utcnow() - timedelta(days=max(1, min(3650, int(lookback_days)))))
        attempts = (
            list(
                connection.execute(
                    """
                    SELECT * FROM shadow_event_admission_attempts
                    WHERE attempted_at>=? ORDER BY attempted_at DESC,id DESC
                    """,
                    (start,),
                )
            )
            if ledger_available
            else []
        )
        decisions: list[sqlite3.Row] = []
        if "decisions" in tables:
            decisions = list(
                connection.execute(
                    """
                    SELECT id,action FROM decisions
                    WHERE created_at>=? AND action IN ('WAIT','REJECT','CANDIDATE')
                    """,
                    (start,),
                )
            )
        decision_ids = {int(row["id"]) for row in decisions}
        candidate_ids = {
            int(row["id"]) for row in decisions if str(row["action"]).upper() == "CANDIDATE"
        }
        wait_ids = {
            int(row["id"]) for row in decisions if str(row["action"]).upper() == "WAIT"
        }
        reject_ids = {
            int(row["id"]) for row in decisions if str(row["action"]).upper() == "REJECT"
        }
        instrumented_ids = {int(row["decision_id"]) for row in attempts}
        candidate_attempts = [
            row for row in attempts if str(row["requested_action"]).upper() == "CANDIDATE"
        ]
        candidate_covered = sum(
            str(row["status"]) in {"created", "already_admitted"} and row["cohort_id"] is not None
            for row in candidate_attempts
        )
        reject_attempts = [
            row for row in attempts if str(row["requested_action"]).upper() == "REJECT"
        ]
        reject_covered = sum(
            str(row["status"]) in {"created", "already_admitted"} and row["cohort_id"] is not None
            for row in reject_attempts
        )
        reason_counts: dict[str, int] = {}
        for row in attempts:
            reason = str(row["reason"] or "unknown")
            reason_counts[reason] = reason_counts.get(reason, 0) + 1
        summary = {
            "decision_count": len(decisions),
            "instrumented_decisions": len(decision_ids & instrumented_ids),
            "legacy_or_uninstrumented_decisions": len(decision_ids - instrumented_ids),
            "attempts": len(attempts),
            "created": sum(str(row["status"]) == "created" for row in attempts),
            "already_admitted": sum(
                str(row["status"]) == "already_admitted" for row in attempts
            ),
            "skipped": sum(str(row["status"]) == "skipped" for row in attempts),
            "candidate_decisions": len(candidate_ids),
            "candidate_instrumented": len(candidate_attempts),
            "candidate_covered": candidate_covered,
            "candidate_skipped": sum(
                str(row["status"]) == "skipped" for row in candidate_attempts
            ),
            "candidate_legacy_or_uninstrumented": len(candidate_ids - instrumented_ids),
            "forward_candidate_coverage_rate": round(
                candidate_covered / len(candidate_attempts), 4
            ) if candidate_attempts else None,
            "overall_candidate_coverage_rate": round(
                candidate_covered / len(candidate_ids), 4
            ) if candidate_ids else None,
            "wait_decisions": len(wait_ids),
            "reject_decisions": len(reject_ids),
            "reject_instrumented": len(reject_attempts),
            "reject_covered": reject_covered,
            "reject_skipped": sum(
                str(row["status"]) == "skipped" for row in reject_attempts
            ),
            "tracking_started_at": min(
                (str(row["attempted_at"]) for row in attempts), default=None
            ),
        }
        recent = [
            {
                "id": int(row["id"]),
                "decision_id": int(row["decision_id"]),
                "event_id": int(row["event_id"]),
                "token_id": str(row["token_id"]),
                "requested_action": str(row["requested_action"]),
                "status": str(row["status"]),
                "reason": str(row["reason"]),
                "cohort_id": row["cohort_id"],
                "source_observation_count": int(row["source_observation_count"]),
                "eligible_source_count": int(row["eligible_source_count"]),
                "attempted_at": str(row["attempted_at"]),
            }
            for row in attempts[:30]
        ]
        return {
            "status": "observed" if attempts else (
                "not_instrumented" if decisions and not ledger_available else "not_observed"
            ),
            "version": Store.SHADOW_EVENT_ADMISSION_VERSION,
            "observed_versions": sorted({str(row["version"]) for row in attempts}),
            "items": recent,
            "reasons": [
                {"reason": reason, "count": count}
                for reason, count in sorted(reason_counts.items(), key=lambda item: (-item[1], item[0]))
            ],
            "summary": summary,
            "mode": "forward_append_only_observation",
            "affects": "none",
            "as_of": iso(),
        }

    @staticmethod
    def shadow_event_learning_summary_from_connection(
        connection: sqlite3.Connection,
        *,
        lookback_days: int = 90,
    ) -> dict[str, Any]:
        admission = Store.shadow_event_admission_summary_from_connection(
            connection, lookback_days=lookback_days
        )
        required_tables = {
            "shadow_event_cohorts", "shadow_event_cohort_labels", "shadow_event_outcomes"
        }
        tables = {
            str(row["name"])
            for row in connection.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            )
            if str(row["name"]) in required_tables
        }
        policy = {
            "minimum_distinct_events": 30,
            "minimum_event_days": 15,
            "minimum_weighted_negative_outcomes": 8,
            "entity_minimum_distinct_events": 50,
            "entity_minimum_event_days": 20,
            "entity_minimum_platforms": 2,
            "affects": "nothing_shadow_observation_only",
        }
        if tables != required_tables:
            return {
                "status": "not_observed", "items": [],
                "summary": {"cohorts": 0, "pending_cohorts": 0, "complete_cohorts": 0},
                "admission": admission,
                "review_policy": policy,
            }
        start = iso(utcnow() - timedelta(days=max(1, min(3650, int(lookback_days)))))
        cohorts = list(
            connection.execute(
                "SELECT id,version,event_id,action,decision_at,status FROM shadow_event_cohorts WHERE decision_at>=?",
                (start,),
            )
        )
        rows = list(
            connection.execute(
                """
                SELECT c.id AS cohort_id,c.event_id,c.action,c.decision_at,l.dimension,l.value,
                       l.origin_platform,l.attribution_weight,o.horizon_minutes,o.raw_return,
                       o.maximum_return,o.minimum_return
                FROM shadow_event_cohorts c
                JOIN shadow_event_cohort_labels l ON l.cohort_id=c.id
                JOIN shadow_event_outcomes o ON o.cohort_id=c.id
                WHERE c.decision_at>=? AND o.status='observed'
                  AND NOT EXISTS (
                    SELECT 1 FROM shadow_event_cohorts earlier
                    WHERE earlier.event_id=c.event_id
                      AND (
                        earlier.decision_at<c.decision_at
                        OR (earlier.decision_at=c.decision_at AND earlier.id<c.id)
                      )
                  )
                ORDER BY o.horizon_minutes,l.dimension,l.value,c.id
                """,
                (start,),
            )
        )
        metrics: dict[tuple[int, str, str], dict[str, Any]] = {}
        for row in rows:
            key = (int(row["horizon_minutes"]), str(row["dimension"]), str(row["value"]))
            metric = metrics.setdefault(
                key,
                {
                    "weight": 0.0, "weighted_return": 0.0, "weighted_positive": 0.0,
                    "weighted_negative": 0.0, "weighted_downside": 0.0,
                    "weighted_maximum": 0.0, "weighted_minimum": 0.0,
                    "cohorts": set(), "events": set(), "event_days": set(), "platforms": set(),
                    "wait_cohorts": set(), "reject_cohorts": set(), "candidate_cohorts": set(),
                },
            )
            weight = max(0.0, float(row["attribution_weight"] or 0))
            raw_return = float(row["raw_return"] or 0)
            metric["weight"] += weight
            metric["weighted_return"] += weight * raw_return
            metric["weighted_positive"] += weight if raw_return > 0 else 0.0
            metric["weighted_negative"] += weight if raw_return <= 0 else 0.0
            metric["weighted_downside"] += weight if raw_return <= -0.25 else 0.0
            metric["weighted_maximum"] += weight * float(row["maximum_return"] or 0)
            metric["weighted_minimum"] += weight * float(row["minimum_return"] or 0)
            metric["cohorts"].add(int(row["cohort_id"]))
            metric["events"].add(int(row["event_id"]))
            metric["event_days"].add(str(row["decision_at"])[:10])
            if row["origin_platform"]:
                metric["platforms"].add(str(row["origin_platform"]))
            metric[f"{str(row['action']).lower()}_cohorts"].add(int(row["cohort_id"]))
        items = []
        for (horizon, dimension, value), metric in metrics.items():
            weight = float(metric["weight"])
            event_count = len(metric["events"])
            event_days = len(metric["event_days"])
            platform_count = len(metric["platforms"])
            required_events = 50 if dimension == "entity" else 30
            required_days = 20 if dimension == "entity" else 15
            review_eligible = (
                event_count >= required_events
                and event_days >= required_days
                and float(metric["weighted_negative"]) >= policy["minimum_weighted_negative_outcomes"]
                and (dimension != "entity" or platform_count >= policy["entity_minimum_platforms"])
            )
            mean_return = float(metric["weighted_return"]) / weight if weight else None
            descriptive_score = None
            if review_eligible and mean_return is not None:
                descriptive_score = weight / (weight + 30.0) * mean_return
            items.append(
                {
                    "horizon_minutes": horizon,
                    "dimension": dimension,
                    "value": value,
                    "weighted_outcomes": round(weight, 4),
                    "distinct_cohort_count": len(metric["cohorts"]),
                    "distinct_event_count": event_count,
                    "event_day_count": event_days,
                    "platform_count": platform_count,
                    "wait_cohort_count": len(metric["wait_cohorts"]),
                    "reject_cohort_count": len(metric["reject_cohorts"]),
                    "candidate_cohort_count": len(metric["candidate_cohorts"]),
                    "positive_rate": round(float(metric["weighted_positive"]) / weight, 4) if weight else None,
                    "mean_raw_return": round(mean_return, 6) if mean_return is not None else None,
                    "downside_rate": round(float(metric["weighted_downside"]) / weight, 4) if weight else None,
                    "mean_maximum_return": round(float(metric["weighted_maximum"]) / weight, 6) if weight else None,
                    "mean_minimum_return": round(float(metric["weighted_minimum"]) / weight, 6) if weight else None,
                    "weighted_negative_outcomes": round(float(metric["weighted_negative"]), 4),
                    "shadow_review_eligible": review_eligible,
                    "shadow_descriptive_score": round(descriptive_score, 6) if descriptive_score is not None else None,
                    "rotation_active": False,
                }
            )
        items.sort(
            key=lambda item: (
                not bool(item["shadow_review_eligible"]), int(item["horizon_minutes"]) != 60,
                -int(item["distinct_event_count"]), str(item["dimension"]), str(item["value"]).casefold(),
            )
        )
        outcome_counts = {
            int(row["horizon_minutes"]): {"observed": 0, "missing": 0}
            for row in connection.execute(
                "SELECT DISTINCT horizon_minutes FROM shadow_event_outcomes"
            )
        }
        for row in connection.execute(
            """
            SELECT o.horizon_minutes,o.status,COUNT(*) AS value
            FROM shadow_event_outcomes o JOIN shadow_event_cohorts c ON c.id=o.cohort_id
            WHERE c.decision_at>=? GROUP BY o.horizon_minutes,o.status
            """,
            (start,),
        ):
            outcome_counts.setdefault(int(row["horizon_minutes"]), {"observed": 0, "missing": 0})[
                str(row["status"])
            ] = int(row["value"])
        entry_execution = {
            "attempts": 0,
            "filled": 0,
            "rejected": 0,
            "cohort_linked": 0,
            "unlinked": 0,
        }
        execution_columns = {
            str(row["name"])
            for row in connection.execute("PRAGMA table_info(paper_execution_attempts)")
        }
        if {"decision_id", "cohort_id"}.issubset(execution_columns):
            row = connection.execute(
                """
                SELECT COUNT(*) AS attempts,
                       SUM(CASE WHEN status='filled' THEN 1 ELSE 0 END) AS filled,
                       SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END) AS rejected,
                       SUM(CASE WHEN decision_id IS NOT NULL AND cohort_id IS NOT NULL THEN 1 ELSE 0 END)
                           AS cohort_linked,
                       SUM(CASE WHEN decision_id IS NULL OR cohort_id IS NULL THEN 1 ELSE 0 END)
                           AS unlinked
                FROM paper_execution_attempts
                WHERE side='BUY' AND requested_at>=?
                """,
                (start,),
            ).fetchone()
            entry_execution = {
                key: int(row[key] or 0) for key in entry_execution
            }
        return {
            "status": (
                "shadow_review_available"
                if any(item["shadow_review_eligible"] for item in items)
                else "collecting_followup"
                if cohorts
                else "not_observed"
            ),
            "version": Store.SHADOW_EVENT_COHORT_VERSION,
            "observed_versions": sorted({str(row["version"]) for row in cohorts}),
            "horizons_minutes": list(Store.SHADOW_EVENT_HORIZONS_MINUTES),
            "items": items[:500],
            "summary": {
                "cohorts": len(cohorts),
                "pending_cohorts": sum(str(row["status"]) == "pending" for row in cohorts),
                "complete_cohorts": sum(str(row["status"]) == "complete" for row in cohorts),
                "wait_cohorts": sum(str(row["action"]) == "WAIT" for row in cohorts),
                "reject_cohorts": sum(str(row["action"]) == "REJECT" for row in cohorts),
                "candidate_cohorts": sum(str(row["action"]) == "CANDIDATE" for row in cohorts),
                "outcomes_by_horizon": outcome_counts,
                "review_eligible_labels": sum(item["shadow_review_eligible"] for item in items),
                "entry_execution": entry_execution,
            },
            "admission": admission,
            "review_policy": policy,
            "analysis_unit": "earliest_forward_cohort_per_independent_event",
            "as_of": iso(),
        }

    def has_bought_token(self, token_id: str) -> bool:
        row = self.db.execute(
            "SELECT 1 FROM trades WHERE token_id=? AND side='BUY' LIMIT 1",
            (token_id,),
        ).fetchone()
        return row is not None

    def daily_buy_gross_usd(self) -> float:
        start = utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        row = self.db.execute(
            "SELECT COALESCE(SUM(gross_usd),0) AS total FROM trades WHERE side='BUY' AND created_at>=?",
            (iso(start),),
        ).fetchone()
        return float(row["total"] or 0.0)

    def record_runtime_timing(self, payload: Mapping[str, Any]) -> None:
        """Replace one small diagnostic snapshot, not an unbounded metrics ledger."""
        with self._lock, self.db:
            self.db.execute(
                "INSERT INTO runtime_timing_latest(id,recorded_at,payload_json) VALUES(1,?,?) "
                "ON CONFLICT(id) DO UPDATE SET recorded_at=excluded.recorded_at,"
                "payload_json=excluded.payload_json", (iso(), self._json(payload)),
            )

    def heartbeat(
        self, source: str, *, item: bool = False, error: str = "",
        error_detail: str = "",
    ) -> None:
        now_dt = utcnow()
        now = iso(now_dt)
        with self._lock, self.db:
            row = self.db.execute("SELECT source FROM source_health WHERE source=?", (source,)).fetchone()
            if row:
                self.db.execute(
                    """UPDATE source_health SET last_ok_at=CASE WHEN ?='' THEN ? ELSE last_ok_at END,
                       last_item_at=CASE WHEN ? THEN ? ELSE last_item_at END,
                       last_error_at=CASE WHEN ?<>'' THEN ? ELSE last_error_at END,
                       last_error=CASE WHEN ?<>'' THEN ? ELSE '' END WHERE source=?""",
                    (error,now,int(item),now,error,now,error,error,source),
                )
            else:
                self.db.execute(
                    "INSERT INTO source_health(source,last_ok_at,last_item_at,last_error_at,last_error) VALUES(?,?,?,?,?)",
                    (source, None if error else now, now if item else None, now if error else None, error),
                )
            if not error:
                transient_prefixes = (
                    "ConnectError", "ConnectTimeout", "ConnectionClosedError",
                    "NetworkError", "PoolTimeout", "ProxyError", "ReadError",
                    "ReadTimeout", "RemoteProtocolError", "TimeoutError",
                    "WriteTimeout",
                )
                recovered = self.db.execute(
                    "SELECT id,error_type,message_safe FROM system_error_cases "
                    "WHERE area='runtime' AND component=? AND status='new'",
                    (source,),
                ).fetchall()
                for case in recovered:
                    error_type = str(case["error_type"] or "")
                    message = str(case["message_safe"] or "")
                    is_transient = error_type.startswith(transient_prefixes) or (
                        error_type == "RuntimeError"
                        and message.startswith("held_account_subscription_rejected")
                    )
                    if is_transient:
                        self.update_system_error_case_from_connection(
                            self.db, int(case["id"]), status="fixed",
                            note="数据源后续成功，瞬时传输错误已自动恢复。",
                            evidence_safe=f"source={source}; recovered_at={now}",
                            actor="system",
                        )
            if error:
                debounce_key = f"{source}:{error}"
                previous = self._last_supervised_error_record_at.get(debounce_key)
                if previous is None or (now_dt - previous).total_seconds() >= 60.0:
                    self._record_system_error_locked(
                        area="runtime",
                        component=source,
                        error_type=str(error),
                        message_safe=str(error_detail or error),
                        severity=(
                            "high" if source in {
                                "chain-meme-trader", "chain-meme-market-marks"
                            } else "medium"
                        ),
                        context_safe={"source": source},
                        observed_at=now_dt,
                    )
                    self._last_supervised_error_record_at[debounce_key] = now_dt

    @staticmethod
    def _safe_error_text(value: Any, *, limit: int = 240) -> str:
        text = re.sub(r"[\x00-\x1f\x7f]+", " ", str(value or "")).strip()
        text = re.sub(
            r"(?i)(private[_ -]?key|secret|token|authorization|signature)\s*[:=]\s*\S+",
            r"\1=[redacted]",
            text,
        )
        return text[: max(1, int(limit))]

    def _record_system_error_locked(
        self, *, area: str, component: str, error_type: str,
        message_safe: str = "", severity: str = "medium",
        context_safe: Mapping[str, Any] | None = None, observed_at: Any = None,
    ) -> int:
        area_safe = self._safe_error_text(area, limit=80) or "system"
        component_safe = self._safe_error_text(component, limit=120) or "unknown"
        type_safe = self._safe_error_text(error_type, limit=120) or "Error"
        message = self._safe_error_text(message_safe or type_safe)
        level = severity if severity in {"low", "medium", "high"} else "medium"
        at = iso(observed_at or utcnow())
        context_json = self._bounded_json(dict(context_safe or {}), max_chars=4_000)
        fingerprint = hashlib.sha256(
            f"{area_safe}\n{component_safe}\n{type_safe}\n{message}".encode(
                "utf-8", errors="ignore"
            )
        ).hexdigest()
        existing = self.db.execute(
            "SELECT id,status FROM system_error_cases WHERE fingerprint=?",
            (fingerprint,),
        ).fetchone()
        if existing is None:
            cursor = self.db.execute(
                "INSERT INTO system_error_cases("
                "fingerprint,area,component,error_type,message_safe,severity,status,"
                "first_seen_at,last_seen_at,occurrence_count,last_context_json) "
                "VALUES(?,?,?,?,?,?,'new',?,?,1,?)",
                (
                    fingerprint, area_safe, component_safe, type_safe, message,
                    level, at, at, context_json,
                ),
            )
            case_id = int(cursor.lastrowid)
        else:
            case_id = int(existing["id"])
            was_fixed = str(existing["status"]) == "fixed"
            self.db.execute(
                "UPDATE system_error_cases SET last_seen_at=?,"
                "occurrence_count=occurrence_count+1,last_context_json=?,"
                "status=CASE WHEN status='fixed' THEN 'new' ELSE status END,"
                "resolved_at=CASE WHEN status='fixed' THEN NULL ELSE resolved_at END "
                "WHERE id=?",
                (at, context_json, case_id),
            )
            if was_fixed:
                self.db.execute(
                    "INSERT INTO system_error_resolution_reports("
                    "case_id,action,summary,evidence_safe,actor,recorded_at) "
                    "VALUES(?,'reopened','同一错误再次出现','','system',?)",
                    (case_id, at),
                )
        self.db.execute(
            "INSERT INTO system_error_occurrences(case_id,observed_at,context_safe_json) "
            "VALUES(?,?,?)",
            (case_id, at, context_json),
        )
        return case_id

    def record_system_error(
        self, *, area: str, component: str, error_type: str,
        message_safe: str = "", severity: str = "medium",
        context_safe: Mapping[str, Any] | None = None, observed_at: Any = None,
    ) -> int:
        with self._lock, self.db:
            return self._record_system_error_locked(
                area=area, component=component, error_type=error_type,
                message_safe=message_safe, severity=severity,
                context_safe=context_safe, observed_at=observed_at,
            )

    def update_system_error_case(
        self, case_id: int, *, status: str, note: str = "",
        evidence_safe: str = "", report_path: str = "", actor: str = "user",
    ) -> None:
        with self._lock, self.db:
            self.update_system_error_case_from_connection(
                self.db, case_id, status=status, note=note,
                evidence_safe=evidence_safe, report_path=report_path, actor=actor,
            )

    @classmethod
    def update_system_error_case_from_connection(
        cls, connection: sqlite3.Connection, case_id: int, *, status: str,
        note: str = "", evidence_safe: str = "", report_path: str = "",
        actor: str = "user",
    ) -> None:
        allowed = {"new", "in_progress", "fixed", "ignored"}
        if status not in allowed:
            raise ValueError("invalid error case status")
        recorded_at = iso()
        clean_note = cls._safe_error_text(note, limit=1_000)
        clean_evidence = cls._safe_error_text(evidence_safe, limit=2_000)
        clean_path = cls._safe_error_text(report_path, limit=500)
        action = (
            "diagnosis_draft" if status == "in_progress"
            else "reopened" if status == "new"
            else status
        )
        exists = connection.execute(
            "SELECT 1 FROM system_error_cases WHERE id=?", (int(case_id),),
        ).fetchone()
        if exists is None:
            raise ValueError("error case not found")
        connection.execute(
            "UPDATE system_error_cases SET status=?,resolution_note=?,"
            "resolved_at=? WHERE id=?",
            (
                status, clean_note,
                recorded_at if status in {"fixed", "ignored"} else None,
                int(case_id),
            ),
        )
        connection.execute(
            "INSERT INTO system_error_resolution_reports("
            "case_id,action,summary,evidence_safe,report_path,actor,recorded_at) "
            "VALUES(?,?,?,?,?,?,?)",
            (
                int(case_id), action, clean_note or f"状态更新为 {status}",
                clean_evidence, clean_path,
                cls._safe_error_text(actor, limit=80) or "user", recorded_at,
            ),
        )

    def source_health(self) -> list[sqlite3.Row]:
        return list(self.db.execute("SELECT * FROM source_health ORDER BY source"))

    def start_source_poll_attempt(
        self,
        *,
        collector_kind: str,
        source_key: str,
        platform: str,
        started_at: Any = None,
    ) -> int:
        clean = lambda value: re.sub(r"[^a-zA-Z0-9:._-]+", "-", str(value).strip())[:160]
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                INSERT INTO source_poll_attempts(
                    version,collector_kind,source_key,platform,status,started_at
                ) VALUES(?,?,?,?,?,?)
                """,
                (
                    self.SOURCE_POLL_EXPOSURE_VERSION,
                    clean(collector_kind) or "unknown",
                    clean(source_key) or "unknown",
                    clean(platform) or "unknown",
                    "running",
                    iso(started_at or utcnow()),
                ),
            )
            return int(cursor.lastrowid)

    def finish_source_poll_attempt(
        self,
        attempt_id: int,
        *,
        status: str,
        fetched_count: int = 0,
        new_observation_count: int = 0,
        new_event_count: int = 0,
        decision_eligible_count: int = 0,
        context_only_count: int = 0,
        duplicate_count: int = 0,
        filtered_count: int = 0,
        error_type: str = "",
        completed_at: Any = None,
    ) -> None:
        status = status if status in {"completed", "error", "quality_paused"} else "error"
        error_type = re.sub(r"[^a-zA-Z0-9_.-]+", "", str(error_type))[:80]
        counts = tuple(
            max(0, int(value or 0))
            for value in (
                fetched_count,
                new_observation_count,
                new_event_count,
                decision_eligible_count,
                context_only_count,
                duplicate_count,
                filtered_count,
            )
        )
        with self._lock, self.db:
            self.db.execute(
                """
                UPDATE source_poll_attempts SET
                    status=?,fetched_count=?,new_observation_count=?,new_event_count=?,
                    decision_eligible_count=?,context_only_count=?,duplicate_count=?,
                    filtered_count=?,error_type=?,completed_at=?
                WHERE id=? AND status='running'
                """,
                (status, *counts, error_type, iso(completed_at or utcnow()), int(attempt_id)),
            )

    @classmethod
    def source_poll_learning_summary_from_connection(
        cls,
        connection: sqlite3.Connection,
        *,
        lookback_days: int = 90,
    ) -> dict[str, Any]:
        exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='source_poll_attempts'"
        ).fetchone()
        if not exists:
            return {
                "status": "not_observed",
                "version": cls.SOURCE_POLL_EXPOSURE_VERSION,
                "items": [],
                "summary": {"attempts": 0, "completed": 0, "errors": 0, "completed_zero_yield": 0},
                "mode": "forward_append_only_observation",
                "affects": "review_only_no_schedule_or_trading_effect",
            }
        start = iso(utcnow() - timedelta(days=max(1, min(3650, int(lookback_days)))))
        rows = connection.execute(
            """
            SELECT collector_kind,source_key,platform,
                   COUNT(*) AS attempts,
                   SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) AS completed,
                   SUM(CASE WHEN status='error' THEN 1 ELSE 0 END) AS errors,
                   SUM(CASE WHEN status='running' THEN 1 ELSE 0 END) AS running,
                   SUM(CASE WHEN status='quality_paused' THEN 1 ELSE 0 END) AS quality_paused,
                   SUM(CASE WHEN status='completed' AND new_observation_count=0 THEN 1 ELSE 0 END)
                       AS completed_zero_yield,
                   SUM(fetched_count) AS fetched_count,
                   SUM(new_observation_count) AS new_observation_count,
                   SUM(new_event_count) AS new_event_count,
                   SUM(decision_eligible_count) AS decision_eligible_count,
                   SUM(context_only_count) AS context_only_count,
                   SUM(duplicate_count) AS duplicate_count,
                   SUM(filtered_count) AS filtered_count,
                   COUNT(DISTINCT substr(started_at,1,10)) AS poll_day_count,
                   MAX(started_at) AS last_started_at
            FROM source_poll_attempts WHERE started_at>=?
            GROUP BY collector_kind,source_key,platform
            ORDER BY completed DESC,attempts DESC,source_key
            """,
            (start,),
        ).fetchall()
        latest: dict[tuple[str, str, str], sqlite3.Row] = {}
        for row in connection.execute(
            """
            SELECT collector_kind,source_key,platform,status,error_type,started_at,completed_at
            FROM source_poll_attempts WHERE started_at>=? ORDER BY id DESC
            """,
            (start,),
        ):
            key = (str(row["collector_kind"]), str(row["source_key"]), str(row["platform"]))
            latest.setdefault(key, row)
        items = []
        for row in rows:
            key = (str(row["collector_kind"]), str(row["source_key"]), str(row["platform"]))
            last = latest[key]
            completed = int(row["completed"] or 0)
            days = int(row["poll_day_count"] or 0)
            items.append(
                {
                    "collector_kind": key[0],
                    "source_key": key[1],
                    "platform": key[2],
                    "attempts": int(row["attempts"] or 0),
                    "completed": completed,
                    "errors": int(row["errors"] or 0),
                    "running": int(row["running"] or 0),
                    "quality_paused": int(row["quality_paused"] or 0),
                    "completed_zero_yield": int(row["completed_zero_yield"] or 0),
                    "fetched_count": int(row["fetched_count"] or 0),
                    "new_observation_count": int(row["new_observation_count"] or 0),
                    "new_event_count": int(row["new_event_count"] or 0),
                    "decision_eligible_count": int(row["decision_eligible_count"] or 0),
                    "context_only_count": int(row["context_only_count"] or 0),
                    "duplicate_count": int(row["duplicate_count"] or 0),
                    "filtered_count": int(row["filtered_count"] or 0),
                    "poll_day_count": days,
                    "new_observations_per_completed_poll": (
                        round(float(row["new_observation_count"] or 0) / completed, 4)
                        if completed else None
                    ),
                    "review_eligible": completed >= 20 and days >= 5,
                    "last_status": str(last["status"]),
                    "last_error_type": str(last["error_type"] or "") or None,
                    "last_started_at": str(last["started_at"]),
                    "last_completed_at": last["completed_at"],
                }
            )
        summary = {
            name: sum(int(item[name] or 0) for item in items)
            for name in ("attempts", "completed", "errors", "running", "quality_paused", "completed_zero_yield", "fetched_count", "new_observation_count", "new_event_count")
        }
        summary["sources"] = len(items)
        summary["review_eligible_sources"] = sum(bool(item["review_eligible"]) for item in items)
        return {
            "status": "collecting" if items else "not_observed",
            "version": cls.SOURCE_POLL_EXPOSURE_VERSION,
            "items": items,
            "summary": summary,
            "mode": "forward_append_only_observation",
            "affects": "review_only_no_schedule_or_trading_effect",
            "as_of": iso(),
        }

    def token_discovery_known(self, token_id: str) -> bool:
        row = self.db.execute(
            """
            SELECT 1 FROM tokens WHERE token_id=?
            UNION ALL
            SELECT 1 FROM token_source_links WHERE token_id=? LIMIT 1
            """,
            (str(token_id), str(token_id)),
        ).fetchone()
        return row is not None

    @classmethod
    def _token_discovery_quote_attempt_definition(cls) -> dict[str, Any]:
        return {
            "version": cls.TOKEN_DISCOVERY_QUOTE_ATTEMPT_VERSION,
            "scope": "post_registration_token_universe_dexscreener_batch_quotes",
            "unit": "one_requested_token_per_batch_round",
            "request_unit": "one_provider_batch_round",
            "terminal_statuses": ["success", "no_pair", "error", "interrupted"],
            "error_retry": "bounded_exponential_with_deterministic_jitter",
            "deadline_miss": "completed_at_after_deadline",
            "retry_window_exhausted": "non_success_retry_after_at_after_deadline",
            "no_historical_backfill": True,
            "decision_eligible": False,
            "affects": "quote_scheduling_only",
        }

    def recover_interrupted_exposure_attempts(self, *, recovered_at: Any = None) -> None:
        recovered = parse_time(recovered_at or utcnow())
        completed_at = iso(recovered)
        retry_after_at = iso(recovered + timedelta(seconds=120))
        with self._lock, self.db:
            self.db.execute(
                """
                UPDATE source_poll_attempts
                SET status='error',error_type='ProcessRestart',completed_at=?
                WHERE status='running'
                """,
                (completed_at,),
            )
            self.db.execute(
                """
                UPDATE token_discovery_quote_attempts
                SET status='interrupted',reason_code='process_restart',error_type='ProcessRestart',
                    completed_at=?,
                    latency_ms=MAX(0,(julianday(?) - julianday(requested_at))*86400000.0),
                    retry_after_at=?,
                    deadline_miss=CASE WHEN deadline_at IS NOT NULL AND ? > deadline_at THEN 1 ELSE 0 END
                WHERE status='running'
                """,
                (completed_at, completed_at, retry_after_at, completed_at),
            )
            self.db.execute(
                """
                UPDATE token_discovery_rounds
                SET status='interrupted',error_type='ProcessRestart',completed_at=?
                WHERE status='running'
                """,
                (completed_at,),
            )
            self.db.execute(
                """
                UPDATE trend_lane_runs
                SET status='agent_error',error_type='ProcessRestart',finished_at=?,
                    observation_ingestion_status='error',
                    observation_ingestion_finalized_at=?
                WHERE status='running'
                """,
                (completed_at, completed_at),
            )
            self.db.execute(
                """
                UPDATE trend_lane_runs
                SET observation_ingestion_status='error',
                    observation_ingestion_finalized_at=?,
                    error_type=CASE WHEN error_type='' THEN 'ProcessRestartDuringIngestion' ELSE error_type END
                WHERE status='completed' AND observation_ingestion_status='pending'
                """,
                (completed_at,),
            )

    def start_token_discovery_round(
        self,
        *,
        provider: str,
        surface: str,
        mode: str,
        chain_scope: str,
        started_at: Any = None,
    ) -> int:
        clean = lambda value: re.sub(r"[^a-zA-Z0-9:._,-]+", "-", str(value).strip())[:160]
        with self._lock, self.db:
            cursor = self.db.execute(
                """
                INSERT INTO token_discovery_rounds(
                    version,provider,surface,mode,chain_scope,status,started_at
                ) VALUES(?,?,?,?,?,'running',?)
                """,
                (
                    self.TOKEN_DISCOVERY_EXPOSURE_VERSION,
                    clean(provider) or "unknown",
                    clean(surface) or "unknown",
                    clean(mode) or "unknown",
                    clean(chain_scope) or "unknown",
                    iso(started_at or utcnow()),
                ),
            )
            return int(cursor.lastrowid)

    def start_token_discovery_quote_attempts(
        self,
        round_id: int,
        items: Iterable[Mapping[str, Any]],
        *,
        requested_at: Any = None,
    ) -> dict[tuple[str, str], int]:
        requested = parse_time(requested_at or utcnow())
        requested_iso = iso(requested)
        clean = lambda value: re.sub(r"[^a-zA-Z0-9:._-]+", "-", str(value).strip())[:100]
        payloads = list(items)
        if not payloads:
            return {}
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT activation_round_id FROM token_discovery_quote_attempt_registrations "
                "WHERE definition_version=?",
                (self.TOKEN_DISCOVERY_QUOTE_ATTEMPT_VERSION,),
            ).fetchone()
            if registration is None or int(round_id) <= int(registration["activation_round_id"] or 0):
                return {}
            attempt_ids: dict[tuple[str, str], int] = {}
            for item in payloads:
                token_id = str(item.get("token_id") or "").strip()[:300]
                role = clean(item.get("role") or "quote") or "quote"
                if not token_id:
                    continue
                queue_due = parse_time(item.get("queue_due_at") or requested)
                deadline = item.get("deadline_at")
                retry_index = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM token_discovery_quote_attempts "
                        "WHERE definition_version=? AND token_id=? AND role=?",
                        (self.TOKEN_DISCOVERY_QUOTE_ATTEMPT_VERSION, token_id, role),
                    ).fetchone()[0]
                )
                self.db.execute(
                    """
                    INSERT OR IGNORE INTO token_discovery_quote_attempts(
                        definition_version,round_id,cohort_id,token_id,chain,role,status,
                        batch_size,retry_index,queue_due_at,deadline_at,requested_at,
                        queue_age_seconds,decision_eligible,affects
                    ) VALUES(?,?,?,?,?,?,'running',?,?,?,?,?,?,0,'none')
                    """,
                    (
                        self.TOKEN_DISCOVERY_QUOTE_ATTEMPT_VERSION, int(round_id),
                        int(item["cohort_id"]) if item.get("cohort_id") is not None else None,
                        token_id, clean(item.get("chain") or "unknown") or "unknown", role,
                        len(payloads), retry_index, iso(queue_due),
                        iso(parse_time(deadline)) if deadline else None, requested_iso,
                        max(0.0, (requested - queue_due).total_seconds()),
                    ),
                )
                row = self.db.execute(
                    "SELECT id FROM token_discovery_quote_attempts "
                    "WHERE round_id=? AND token_id=? AND role=?",
                    (int(round_id), token_id, role),
                ).fetchone()
                if row is not None:
                    attempt_ids[(token_id, role)] = int(row["id"])
            return attempt_ids

    def finish_token_discovery_quote_attempt(
        self,
        attempt_id: int,
        *,
        status: str,
        reason_code: str = "",
        error_type: str = "",
        http_status: int | None = None,
        completed_at: Any = None,
        base_retry_seconds: int = 120,
    ) -> str | None:
        if status not in {"success", "no_pair", "error", "interrupted"}:
            raise ValueError("invalid token quote attempt status")
        completed = parse_time(completed_at or utcnow())
        with self._lock, self.db:
            row = self.db.execute(
                "SELECT * FROM token_discovery_quote_attempts WHERE id=?",
                (int(attempt_id),),
            ).fetchone()
            if row is None or str(row["status"]) != "running":
                return row["retry_after_at"] if row is not None else None
            base = max(30, int(base_retry_seconds))
            retry_index = int(row["retry_index"] or 0)
            if status in {"error", "interrupted"}:
                retry_seconds = min(900, base * (2 ** min(retry_index, 3)))
                digest = hashlib.sha256(
                    f"{row['token_id']}:{row['role']}:{retry_index}".encode("utf-8")
                ).digest()
                retry_seconds = int(round(
                    retry_seconds * (1.0 + int.from_bytes(digest[:2], "big") / 65535.0 * 0.2)
                ))
            else:
                retry_seconds = base
            retry_after = completed + timedelta(seconds=retry_seconds)
            deadline_miss = bool(
                row["deadline_at"] and completed > parse_time(row["deadline_at"])
            )
            self.db.execute(
                """
                UPDATE token_discovery_quote_attempts
                SET status=?,reason_code=?,error_type=?,http_status=?,completed_at=?,
                    latency_ms=MAX(0,(julianday(?) - julianday(requested_at))*86400000.0),
                    retry_after_at=?,deadline_miss=?
                WHERE id=? AND status='running'
                """,
                (
                    status,
                    re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(reason_code))[:100],
                    re.sub(r"[^a-zA-Z0-9_.-]+", "", str(error_type))[:80],
                    int(http_status) if http_status is not None else None,
                    iso(completed), iso(completed), iso(retry_after), int(deadline_miss),
                    int(attempt_id),
                ),
            )
            return iso(retry_after)

    def add_token_discovery_exposure(
        self,
        round_id: int,
        *,
        token_id: str,
        chain: str,
        role: str = "discovery",
        first_local_discovery: bool = False,
        new_token: bool = False,
        occurrence_count: int = 1,
        source_link_count: int = 0,
        new_source_link_count: int = 0,
        snapshot_count: int = 0,
        no_pair: bool = False,
        observed_at: Any = None,
    ) -> int | None:
        token_id = str(token_id).strip()[:300]
        if not token_id:
            return None
        clean = lambda value: re.sub(r"[^a-zA-Z0-9:._-]+", "-", str(value).strip())[:100]
        exposure_observed_at = iso(observed_at or utcnow())
        exposure_recorded_at = iso()
        with self._lock, self.db:
            self.db.execute(
                """
                INSERT INTO token_discovery_exposures(
                    round_id,token_id,chain,role,first_local_discovery,new_token,
                    occurrence_count,source_link_count,new_source_link_count,snapshot_count,
                    no_pair,observed_at,recorded_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(round_id,token_id) DO UPDATE SET
                    first_local_discovery=MAX(first_local_discovery,excluded.first_local_discovery),
                    new_token=MAX(new_token,excluded.new_token),
                    occurrence_count=token_discovery_exposures.occurrence_count+excluded.occurrence_count,
                    source_link_count=token_discovery_exposures.source_link_count+excluded.source_link_count,
                    new_source_link_count=token_discovery_exposures.new_source_link_count+excluded.new_source_link_count,
                    snapshot_count=token_discovery_exposures.snapshot_count+excluded.snapshot_count,
                    no_pair=MAX(no_pair,excluded.no_pair)
                """,
                (
                    int(round_id), token_id, clean(chain) or "unknown", clean(role) or "discovery",
                    int(bool(first_local_discovery)), int(bool(new_token)),
                    max(1, int(occurrence_count or 1)), max(0, int(source_link_count or 0)),
                    max(0, int(new_source_link_count or 0)), max(0, int(snapshot_count or 0)),
                    int(bool(no_pair)), exposure_observed_at, exposure_recorded_at,
                ),
            )
            exposure_id = int(
                self.db.execute(
                    "SELECT id FROM token_discovery_exposures WHERE round_id=? AND token_id=?",
                    (int(round_id), token_id),
                ).fetchone()["id"]
            )
            if first_local_discovery:
                exposure = self.db.execute(
                    """
                    SELECT e.id,e.round_id,e.token_id,e.chain,e.role,e.observed_at,e.recorded_at,
                           r.provider,r.surface
                    FROM token_discovery_exposures e
                    JOIN token_discovery_rounds r ON r.id=e.round_id
                    WHERE e.round_id=? AND e.token_id=?
                    """,
                    (int(round_id), token_id),
                ).fetchone()
                registration = self.db.execute(
                    "SELECT registered_at FROM token_universe_forward_registrations "
                    "WHERE definition_version=?",
                    (self.TOKEN_UNIVERSE_FORWARD_VERSION,),
                ).fetchone()
                if (
                    exposure is not None
                    and registration is not None
                    and exposure["recorded_at"]
                    and parse_time(exposure["recorded_at"]) >= parse_time(registration["registered_at"])
                ):
                    discovered = parse_time(exposure["recorded_at"])
                    self.db.execute(
                        """
                        INSERT OR IGNORE INTO token_universe_forward_cohorts(
                            definition_version,exposure_id,round_id,token_id,chain,provider,surface,
                            discovery_role,discovery_observed_at,discovery_recorded_at,
                            baseline_deadline_at,decision_eligible,affects
                        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,'none')
                        """,
                        (
                            self.TOKEN_UNIVERSE_FORWARD_VERSION, int(exposure["id"]),
                            int(exposure["round_id"]), str(exposure["token_id"]),
                            str(exposure["chain"]), str(exposure["provider"]),
                            str(exposure["surface"]), str(exposure["role"]),
                            str(exposure["observed_at"]), str(exposure["recorded_at"]),
                            iso(discovered + timedelta(minutes=self.TOKEN_UNIVERSE_BASELINE_WINDOW_MINUTES)),
                        ),
                    )
            return exposure_id

    def finish_token_discovery_round(
        self,
        round_id: int,
        *,
        status: str,
        requested_count: int = 0,
        returned_count: int = 0,
        duplicate_token_count: int = 0,
        error_type: str = "",
        completed_at: Any = None,
    ) -> None:
        allowed = {"completed", "error", "interrupted"}
        status = status if status in allowed else "error"
        error_type = re.sub(r"[^a-zA-Z0-9_.-]+", "", str(error_type))[:80]
        with self._lock, self.db:
            totals = self.db.execute(
                """
                SELECT COUNT(*) AS exposed_token_count,
                       COALESCE(SUM(first_local_discovery),0) AS first_local_discovery_count,
                       COALESCE(SUM(new_token),0) AS new_token_count,
                       COALESCE(SUM(source_link_count),0) AS source_link_count,
                       COALESCE(SUM(new_source_link_count),0) AS new_source_link_count,
                       COALESCE(SUM(snapshot_count),0) AS snapshot_count,
                       COALESCE(SUM(no_pair),0) AS no_pair_count
                FROM token_discovery_exposures WHERE round_id=?
                """,
                (int(round_id),),
            ).fetchone()
            self.db.execute(
                """
                UPDATE token_discovery_rounds SET
                    status=?,requested_count=?,returned_count=?,exposed_token_count=?,
                    first_local_discovery_count=?,new_token_count=?,duplicate_token_count=?,
                    source_link_count=?,new_source_link_count=?,snapshot_count=?,no_pair_count=?,
                    error_type=?,completed_at=?
                WHERE id=? AND status='running'
                """,
                (
                    status, max(0, int(requested_count or 0)), max(0, int(returned_count or 0)),
                    int(totals["exposed_token_count"] or 0),
                    int(totals["first_local_discovery_count"] or 0),
                    int(totals["new_token_count"] or 0), max(0, int(duplicate_token_count or 0)),
                    int(totals["source_link_count"] or 0),
                    int(totals["new_source_link_count"] or 0),
                    int(totals["snapshot_count"] or 0), int(totals["no_pair_count"] or 0),
                    error_type, iso(completed_at or utcnow()), int(round_id),
                ),
            )

