    def record_token_universe_funnel_transition(
        self,
        token_id: str,
        *,
        definition_version: str | None = None,
        stage: str,
        status: str,
        reason_code: str,
        evaluation_key: str,
        observed_at: Any = None,
        ingested_at: Any = None,
        source_table: str = "",
        source_record_ids: Mapping[str, Any] | None = None,
        round_id: int | None = None,
        source_link_id: int | None = None,
        source_poll_attempt_id: int | None = None,
        admission_id: int | None = None,
        agent_run_id: str = "",
        assessment_id: int | None = None,
        observation_id: int | None = None,
        event_id: int | None = None,
        decision_id: int | None = None,
        snapshot_id: int | None = None,
        paper_execution_attempt_id: int | None = None,
        trade_id: int | None = None,
        metadata: Mapping[str, Any] | None = None,
    ) -> int | None:
        version = str(definition_version or self.TOKEN_UNIVERSE_FUNNEL_VERSION)
        allowed_stages = set(self._token_universe_funnel_definition()["recorded_transition_stages"])
        if stage not in allowed_stages:
            raise ValueError("invalid token universe funnel stage")
        token_id = str(token_id).strip()[:300]
        if not token_id:
            return None
        natural_key = str(evaluation_key).strip()[:500]
        if not natural_key:
            raise ValueError("token universe funnel evaluation_key is required")
        stage_status = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(status))[:80] or "unknown"
        reason = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(reason_code))[:120] or "unspecified"
        observed = parse_time(observed_at or utcnow())
        ingested = parse_time(ingested_at or observed)
        recorded = utcnow()
        source_name = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(source_table))[:100]
        safe_source_ids = {
            re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(key))[:80]: value
            for key, value in dict(source_record_ids or {}).items()
            if isinstance(value, (str, int, float, bool)) or value is None
        }
        safe_metadata = {
            re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(key))[:80]: value
            for key, value in dict(metadata or {}).items()
            if isinstance(value, (str, int, float, bool)) or value is None
        }
        if observed > ingested or ingested > recorded:
            safe_metadata["reported_status"] = stage_status
            safe_metadata["reported_reason_code"] = reason
            stage_status = "excluded_time_order"
            reason = "invalid_time_order"
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT activation_cohort_id FROM token_universe_funnel_registrations "
                "WHERE definition_version=?",
                (version,),
            ).fetchone()
            if registration is None:
                return None
            cohort = self.db.execute(
                "SELECT id FROM token_universe_forward_cohorts "
                "WHERE definition_version=? AND token_id=? AND id>?",
                (
                    self.TOKEN_UNIVERSE_FORWARD_VERSION,
                    token_id,
                    int(registration["activation_cohort_id"] or 0),
                ),
            ).fetchone()
            if cohort is None:
                return None
            source_json = self._bounded_json(safe_source_ids, max_chars=4000)
            metadata_json = self._bounded_json(safe_metadata, max_chars=8000)
            material = "\n".join((
                version,
                str(cohort["id"]), stage, natural_key,
            ))
            transition_key = hashlib.sha256(material.encode("utf-8", errors="ignore")).hexdigest()
            self.db.execute(
                """
                INSERT OR IGNORE INTO token_universe_funnel_transitions(
                    definition_version,transition_key,evaluation_key,cohort_id,token_id,stage,status,reason_code,
                    observed_at,ingested_at,recorded_at,source_table,source_record_ids_json,
                    round_id,source_link_id,source_poll_attempt_id,admission_id,agent_run_id,
                    assessment_id,observation_id,event_id,decision_id,
                    snapshot_id,paper_execution_attempt_id,trade_id,
                    metadata_json,decision_eligible,affects
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')
                """,
                (
                    version, transition_key, natural_key,
                    int(cohort["id"]),
                    token_id, stage, stage_status, reason, iso(observed), iso(ingested), iso(),
                    source_name, source_json, round_id, source_link_id, source_poll_attempt_id,
                    admission_id, str(agent_run_id)[:100], assessment_id,
                    observation_id, event_id, decision_id, snapshot_id,
                    paper_execution_attempt_id, trade_id, metadata_json,
                ),
            )
            row = self.db.execute(
                "SELECT id FROM token_universe_funnel_transitions WHERE transition_key=?",
                (transition_key,),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def process_agent_shadow_review_inputs(
        self,
        relation_ids: Iterable[int] | None = None,
        *,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        ids = list(dict.fromkeys(int(value) for value in (relation_ids or ())))
        where = ""
        params: list[Any] = [self.AGENT_SHADOW_REVIEW_VERSION]
        if ids:
            where = f" AND i.relation_id IN ({','.join('?' for _ in ids)})"
            params.extend(ids)
        params.append(max(1, min(1000, int(limit))))
        inputs = list(
            self.db.execute(
                f"""
                SELECT i.*,cr.relation_type,cr.resolution_status,cr.source_revision_id,
                       cr.target_revision_id,cr.temporal_exclusion_reason,
                       sr.anchor_observation_id AS source_observation_id,
                       tr.anchor_observation_id AS target_observation_id
                FROM agent_shadow_review_inputs i
                JOIN event_claim_relations cr ON cr.id=i.relation_id
                JOIN source_item_revisions sr ON sr.id=cr.source_revision_id
                LEFT JOIN source_item_revisions tr ON tr.id=cr.target_revision_id
                LEFT JOIN agent_shadow_review_results rr ON rr.input_id=i.id
                WHERE i.definition_version=? AND rr.id IS NULL {where}
                ORDER BY i.id LIMIT ?
                """,
                params,
            )
        )
        registration = self.db.execute(
            "SELECT activation_cohort_id FROM token_universe_funnel_registrations "
            "WHERE definition_version=?",
            (self.AGENT_SHADOW_REVIEW_VERSION,),
        ).fetchone()
        results: list[dict[str, Any]] = []
        for item in inputs:
            status = "ineligible"
            reason = "unsupported_relation"
            token_id = ""
            event_id = None
            decision_id = None
            buy_trade_id = None
            transition_id = None
            target_observation_id = item["target_observation_id"]
            target_events: list[sqlite3.Row] = []
            if target_observation_id is not None:
                target_events = list(self.db.execute(
                    "SELECT event_id FROM event_observations WHERE observation_id=? "
                    "ORDER BY event_id",
                    (int(target_observation_id),),
                ))
            if len(target_events) == 1:
                event_id = int(target_events[0]["event_id"])
            metadata = {
                "policy_version": self.AGENT_SHADOW_REVIEW_VERSION,
                "trigger_kind": str(item["trigger_kind"]),
                "window_minutes": self.AGENT_SHADOW_REVIEW_WINDOW_MINUTES,
                "dispatch_requested": 0,
                "dispatch_count": 0,
                "uses_agent_quota": 0,
            }
            if item["temporal_exclusion_reason"] is not None:
                reason = "temporal_exclusion"
            elif str(item["resolution_status"]) != "resolved":
                reason = f"relation_{item['resolution_status']}"
            elif len(target_events) > 1:
                status = "coverage_gap"
                reason = "ambiguous_target_event"
                metadata["target_event_count"] = len(target_events)
            elif event_id is None:
                status = "coverage_gap"
                reason = "no_token_binding"
            else:
                decision = self.db.execute(
                    "SELECT * FROM decisions WHERE event_id=? AND created_at<=? "
                    "ORDER BY created_at DESC,id DESC LIMIT 1",
                    (event_id, item["recorded_at"]),
                ).fetchone()
                if decision is not None:
                    token_id = str(decision["token_id"] or "")
                    decision_id = int(decision["id"])
                else:
                    linked_tokens = [
                        str(row["token_id"])
                        for row in self.db.execute(
                            "SELECT DISTINCT token_id FROM token_universe_funnel_transitions "
                            "WHERE definition_version=? AND stage='event_token_relation' "
                            "AND status='linked' AND event_id=? AND recorded_at<=? "
                            "ORDER BY token_id",
                            (
                                self.TOKEN_UNIVERSE_FUNNEL_VERSION,
                                event_id,
                                item["recorded_at"],
                            ),
                        )
                    ]
                    if len(linked_tokens) == 1:
                        token_id = linked_tokens[0]
                    elif len(linked_tokens) > 1:
                        status = "coverage_gap"
                        reason = "ambiguous_event_token_mapping"
                if not token_id:
                    if reason != "ambiguous_event_token_mapping":
                        status = "coverage_gap"
                        reason = "no_token_binding"
                else:
                    trade_balance = self.db.execute(
                        """
                        SELECT COALESCE(SUM(CASE WHEN side='BUY' THEN quantity ELSE -quantity END),0)
                                   AS remaining_quantity
                        FROM trades
                        WHERE token_id=? AND event_id=? AND created_at<=?
                        """,
                        (token_id, event_id, item["recorded_at"]),
                    ).fetchone()
                    buy_trade = self.db.execute(
                        """
                        SELECT id FROM trades
                        WHERE token_id=? AND event_id=? AND side='BUY' AND created_at<=?
                        ORDER BY created_at DESC,id DESC LIMIT 1
                        """,
                        (token_id, event_id, item["recorded_at"]),
                    ).fetchone()
                    position_open = bool(
                        buy_trade is not None
                        and float(trade_balance["remaining_quantity"] or 0) > 1e-12
                    )
                    buy_trade_id = int(buy_trade["id"]) if position_open else None
                    metadata["target_scope"] = "position" if position_open else "event_token"
                    metadata["position_open_at_trigger"] = int(position_open)
                    metadata["buy_trade_id"] = buy_trade_id
                    cohort = self.db.execute(
                        "SELECT id FROM token_universe_forward_cohorts "
                        "WHERE definition_version=? AND token_id=? ORDER BY id LIMIT 1",
                        (self.TOKEN_UNIVERSE_FORWARD_VERSION, token_id),
                    ).fetchone()
                    activation = int(registration["activation_cohort_id"] or 0) if registration else 0
                    if cohort is None:
                        status = "coverage_gap"
                        reason = "no_universe_cohort"
                    elif int(cohort["id"]) <= activation:
                        status = "coverage_gap"
                        reason = "cohort_before_overlay_activation"
                    else:
                        source_ids = {
                            "shadow_review_input_id": int(item["id"]),
                            "claim_relation_id": int(item["relation_id"]),
                            "source_revision_id": int(item["source_revision_id"]),
                            "target_revision_id": int(item["target_revision_id"]),
                        }
                        transition_id = self.record_token_universe_funnel_transition(
                            token_id,
                            definition_version=self.AGENT_SHADOW_REVIEW_VERSION,
                            stage="context_trigger_evaluation",
                            status="shadow_triggered",
                            reason_code=f"shadow_review_{item['trigger_kind']}",
                            evaluation_key=f"claim_relation:{int(item['relation_id'])}",
                            observed_at=item["observed_at"],
                            ingested_at=item["ingested_at"],
                            source_table="agent_shadow_review_inputs",
                            source_record_ids=source_ids,
                            observation_id=int(target_observation_id),
                            event_id=event_id,
                            decision_id=decision_id,
                            metadata=metadata,
                        )
                        if transition_id is None:
                            status = "coverage_gap"
                            reason = "transition_not_recorded"
                        else:
                            status = "shadow_triggered"
                            reason = f"shadow_review_{item['trigger_kind']}"
            with self._lock, self.db:
                self.db.execute(
                    """
                    INSERT OR IGNORE INTO agent_shadow_review_results(
                        definition_version,input_id,status,reason_code,token_id,event_id,
                        decision_id,buy_trade_id,transition_id,recorded_at,metadata_json,dispatch_count,
                        decision_eligible,affects
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0,'none')
                    """,
                    (
                        self.AGENT_SHADOW_REVIEW_VERSION,
                        int(item["id"]),
                        status,
                        reason,
                        token_id,
                        event_id,
                        decision_id,
                        buy_trade_id,
                        transition_id,
                        iso(),
                        self._bounded_json(metadata, max_chars=8000),
                    ),
                )
                result = self.db.execute(
                    "SELECT id,status,reason_code,transition_id FROM "
                    "agent_shadow_review_results WHERE input_id=?",
                    (int(item["id"]),),
                ).fetchone()
            results.append(
                {
                    "status": str(result["status"]),
                    "result_id": int(result["id"]),
                    "reason": str(result["reason_code"]),
                    "transition_id": result["transition_id"],
                }
            )
        return results

    def record_token_universe_candidate_evaluations(
        self,
        event_id: int,
        *,
        evaluated_at: Any,
        candidates: Iterable[Mapping[str, Any]],
        selected_token_id: str = "",
        selected_action: str = "",
        outcome_reasons: Iterable[str] = (),
    ) -> int:
        candidate_rows = [dict(item) for item in candidates if isinstance(item, Mapping)]
        candidate_by_token = {
            str(item.get("token_id") or ""): item
            for item in candidate_rows
            if str(item.get("token_id") or "")
        }
        related_tokens = {
            str(row["token_id"])
            for row in self.db.execute(
                "SELECT DISTINCT token_id FROM token_universe_funnel_transitions "
                "WHERE definition_version=? AND stage='event_token_relation' "
                "AND status='linked' AND event_id=?",
                (self.TOKEN_UNIVERSE_FUNNEL_VERSION, int(event_id)),
            )
        }
        token_ids = sorted({*candidate_by_token, *related_tokens})
        if not token_ids:
            return 0
        reasons = [str(value)[:120] for value in outcome_reasons if str(value).strip()]
        recorded = 0
        for token_id in token_ids:
            item = candidate_by_token.get(token_id)
            if item is None:
                stage = "candidate_evaluator_call"
                status = "evaluated_no_ranked_candidate"
                reason = reasons[0] if reasons else "not_in_ranked_candidate_set"
                metadata: dict[str, Any] = {"candidate_rank": None}
            elif item.get("filter_reason"):
                stage = "candidate_evaluation"
                status = "filtered"
                reason = str(item.get("filter_reason") or "filtered")
                metadata = {
                    "candidate_rank": None,
                    "probe_reason": item.get("probe_reason"),
                    "match_score": item.get("match_score"),
                }
            elif token_id == str(selected_token_id or ""):
                stage = "candidate_evaluation"
                action = re.sub(
                    r"[^a-zA-Z0-9_.-]+", "_", str(selected_action or "unknown").lower()
                )[:40]
                status = (
                    "selected_candidate" if action == "candidate" else f"top_rank_{action}"
                )
                rejected = item.get("rejected_reasons")
                rejected = rejected if isinstance(rejected, list) else []
                reason = str(rejected[0]) if rejected else str(selected_action or "selected").lower()
                metadata = {
                    "candidate_rank": item.get("rank"),
                    "candidate_score": item.get("candidate_score"),
                    "match_score": item.get("match_score"),
                    "canonical_margin": item.get("canonical_margin"),
                    "safety_status": (item.get("safety") or {}).get("status")
                    if isinstance(item.get("safety"), Mapping) else None,
                    "final_action": str(selected_action or ""),
                }
            else:
                stage = "candidate_evaluation"
                status = "considered_not_selected"
                reason = "lower_rank"
                metadata = {
                    "candidate_rank": item.get("rank"),
                    "candidate_score": item.get("candidate_score"),
                    "match_score": item.get("match_score"),
                    "score_gap_to_selected": item.get("score_gap_to_selected"),
                }
            if self.record_token_universe_funnel_transition(
                token_id,
                stage=stage,
                status=status,
                reason_code=reason,
                evaluation_key=f"event:{int(event_id)}:{iso(parse_time(evaluated_at))}",
                observed_at=evaluated_at,
                ingested_at=evaluated_at,
                source_table="candidate_ranking",
                source_record_ids={"event_id": int(event_id)},
                event_id=int(event_id),
                snapshot_id=int(item["snapshot_id"])
                if item is not None and item.get("snapshot_id") is not None else None,
                metadata=metadata,
            ) is not None:
                recorded += 1
        return recorded

    def register_token_universe_outcome_quality(
        self,
        *,
        reference_notional_usd: float,
        min_liquidity_usd: float,
        max_liquidity_impact_pct: float,
        slippage_rate: float,
        default_fee_bps: float,
        pump_fee_bps: float,
        max_quote_age_seconds: float,
        max_tax_pct: float,
    ) -> sqlite3.Row:
        """Freeze a forward-only quality overlay without changing TOKEN-003 v1."""
        notional = max(0.01, float(reference_notional_usd))
        impact = max(0.000001, float(max_liquidity_impact_pct))
        definition = {
            "version": self.TOKEN_UNIVERSE_OUTCOME_QUALITY_VERSION,
            "source": self.TOKEN_UNIVERSE_FORWARD_VERSION,
            "no_historical_backfill": True,
            "complete_denominator": ["observed", "baseline_missing", "missing"],
            "reference_notional_usd": notional,
            "min_liquidity_usd": max(0.0, float(min_liquidity_usd)),
            "max_liquidity_impact_pct": impact,
            "required_liquidity_usd": max(
                max(0.0, float(min_liquidity_usd)), notional / impact
            ),
            "slippage_rate_each_side": max(0.0, min(0.49, float(slippage_rate))),
            "default_fee_bps_each_side": max(0.0, float(default_fee_bps)),
            "pump_fee_bps_each_side": max(0.0, float(pump_fee_bps)),
            "max_quote_age_seconds": max(1.0, float(max_quote_age_seconds)),
            "max_tax_pct": max(0.0, float(max_tax_pct)),
            "near_zero_market_cap_usd": 100.0,
            "potential_opportunity_return": 0.25,
            "return_semantics": {
                "raw_fixed_horizon_return": "v1 first durable quote after target versus v1 baseline",
                "raw_token_path_return": "v1 mixed-token sampled path maximum; not tradability evidence",
                "same_pair_return": "sampled maximum restricted to the baseline chain and pair",
                "same_route_return": "sampled maximum restricted to provider, chain, dex, pair, base and quote",
                "migration_adjusted_return": "sampled maximum after a locally observed PumpPortal migration transition",
                "canonical_liquid_pair_return": "sampled maximum on one route whose entry and exit satisfy frozen liquidity",
                "estimated_net_return_after_costs": "canonical liquid route after frozen slippage and fees; unknown safety is flagged",
                "net_executable_return_after_costs": "estimated net return only when sellability, honeypot and taxes are known safe",
            },
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO token_universe_outcome_quality_registrations("
                "definition_version,registered_at,activation_outcome_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM token_universe_forward_outcomes),0),?)",
                (
                    self.TOKEN_UNIVERSE_OUTCOME_QUALITY_VERSION,
                    iso(),
                    self._json(definition),
                ),
            )
            return self.db.execute(
                "SELECT * FROM token_universe_outcome_quality_registrations "
                "WHERE definition_version=?",
                (self.TOKEN_UNIVERSE_OUTCOME_QUALITY_VERSION,),
            ).fetchone()

    @staticmethod
    def _token_universe_snapshot_route(row: sqlite3.Row | None) -> dict[str, Any]:
        if row is None:
            return {}
        try:
            raw = json.loads(str(row["raw_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            raw = {}
        raw = raw if isinstance(raw, dict) else {}
        pair = raw.get("pair") if isinstance(raw.get("pair"), dict) else raw
        base = pair.get("baseToken") if isinstance(pair.get("baseToken"), dict) else {}
        quote = pair.get("quoteToken") if isinstance(pair.get("quoteToken"), dict) else {}

        def text(*keys: str) -> str:
            for key in keys:
                value = pair.get(key)
                if value is not None and str(value).strip():
                    return str(value).strip().casefold()
            return ""

        route = {
            "provider": str(row["provider"] or "").strip().casefold(),
            "chain_id": text("chainId", "chain_id"),
            "dex_id": text("dexId", "dex_id"),
            "pair_address": text("pairAddress", "pair_address"),
            "base_address": str(base.get("address") or "").strip().casefold(),
            "quote_address": str(quote.get("address") or "").strip().casefold(),
            "liquidity_usd": row["liquidity_usd"],
            "market_cap_usd": row["market_cap_usd"],
            "price_usd": row["price_usd"],
            "buy_tax_pct": row["buy_tax_pct"],
            "sell_tax_pct": row["sell_tax_pct"],
            "honeypot": row["honeypot"],
            "sellable": row["sellable"],
            "observed_at": str(row["observed_at"] or ""),
            "recorded_at": str(row["recorded_at"] or ""),
            "snapshot_id": int(row["id"]),
        }
        route["pair_key"] = json.dumps(
            [route["chain_id"], route["pair_address"]], separators=(",", ":")
        ) if route["chain_id"] and route["pair_address"] else ""
        route["route_key"] = json.dumps(
            [
                route["provider"], route["chain_id"], route["dex_id"],
                route["pair_address"], route["base_address"], route["quote_address"],
            ],
            separators=(",", ":"),
        ) if all(
            route[key] for key in (
                "provider", "chain_id", "dex_id", "pair_address",
                "base_address", "quote_address",
            )
        ) else ""
        return route

    @staticmethod
    def _token_universe_net_return(
        entry: dict[str, Any],
        exit_: dict[str, Any],
        definition: Mapping[str, Any],
        *,
        require_known_safety: bool,
    ) -> float | None:
        entry_price = float(entry.get("price_usd") or 0.0)
        exit_price = float(exit_.get("price_usd") or 0.0)
        if entry_price <= 0 or exit_price <= 0:
            return None
        safety_values = (
            entry.get("honeypot"), exit_.get("honeypot"),
            entry.get("sellable"), exit_.get("sellable"),
            entry.get("buy_tax_pct"), exit_.get("sell_tax_pct"),
        )
        if require_known_safety and any(value is None for value in safety_values):
            return None
        if entry.get("honeypot") == 1 or exit_.get("honeypot") == 1:
            return None
        if entry.get("sellable") == 0 or exit_.get("sellable") == 0:
            return None
        max_tax = float(definition.get("max_tax_pct") or 0.0)
        buy_tax = float(entry.get("buy_tax_pct") or 0.0)
        sell_tax = float(exit_.get("sell_tax_pct") or 0.0)
        if buy_tax > max_tax or sell_tax > max_tax:
            return None
        slippage = float(definition.get("slippage_rate_each_side") or 0.0)
        pump_fee = float(definition.get("pump_fee_bps_each_side") or 0.0)
        default_fee = float(definition.get("default_fee_bps_each_side") or 0.0)
        entry_fee = pump_fee if "pump" in str(entry.get("dex_id") or "") else default_fee
        exit_fee = pump_fee if "pump" in str(exit_.get("dex_id") or "") else default_fee
        cost = entry_price * (1.0 + slippage) * (1.0 + entry_fee / 10_000.0)
        proceeds = (
            exit_price * (1.0 - slippage) * (1.0 - exit_fee / 10_000.0)
            * (1.0 - buy_tax / 100.0) * (1.0 - sell_tax / 100.0)
        )
        return proceeds / cost - 1.0 if cost > 0 else None

    @staticmethod
    def _token_universe_peak_tier(value: float) -> str:
        if value >= 3.0:
            return "gte_300pct"
        if value >= 1.0:
            return "gte_100pct"
        if value >= 0.5:
            return "gte_50pct"
        if value >= 0.25:
            return "gte_25pct"
        return "lt_25pct"

    @staticmethod
    def _token_universe_action_at_target(
        connection: sqlite3.Connection,
        *,
        token_id: str,
        discovered_at: str,
        target_at: str,
    ) -> tuple[str, int, int]:
        actions = {
            str(row["action"]).upper()
            for row in connection.execute(
                "SELECT action FROM decisions WHERE token_id=? AND created_at>=? AND created_at<=?",
                (token_id, discovered_at, target_at),
            )
        }
        candidate = int("CANDIDATE" in actions)
        paper_bought = int(
            connection.execute(
                "SELECT 1 FROM trades WHERE token_id=? AND side='BUY' "
                "AND created_at>=? AND created_at<=? LIMIT 1",
                (token_id, discovered_at, target_at),
            ).fetchone()
            is not None
        )
        if paper_bought:
            return "PAPER_BUY", candidate, paper_bought
        for action in ("CANDIDATE", "WAIT", "REJECT"):
            if action in actions:
                return action, candidate, paper_bought
        return "NONE", candidate, paper_bought

    def finalize_token_universe_forward_outcomes(self, *, now: Any = None) -> dict[str, int]:
        """Append immutable full-universe baselines and fixed-horizon outcomes."""
        evaluated = parse_time(now or utcnow())
        baseline_observed = baseline_missing = outcomes_observed = outcomes_missing = 0
        with self._lock, self.db:
            cohorts = list(
                self.db.execute(
                    """
                    SELECT c.* FROM token_universe_forward_cohorts c
                    WHERE (SELECT COUNT(*) FROM token_universe_forward_outcomes o
                           WHERE o.cohort_id=c.id) < ?
                    ORDER BY c.discovery_recorded_at,c.id
                    """,
                    (len(self.TOKEN_UNIVERSE_HORIZONS_MINUTES),),
                )
            )
            for cohort in cohorts:
                baseline = self.db.execute(
                    "SELECT * FROM token_universe_forward_baselines WHERE cohort_id=?",
                    (int(cohort["id"]),),
                ).fetchone()
                baseline_deadline = parse_time(cohort["baseline_deadline_at"])
                if baseline is None:
                    upper = min(evaluated, baseline_deadline)
                    snapshot = self.db.execute(
                        """
                        SELECT id,observed_at,ingested_at,recorded_at,price_usd,provider
                        FROM token_snapshots
                        WHERE token_id=? AND price_usd>0
                          AND observed_at>=? AND ingested_at>=observed_at
                          AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                        ORDER BY recorded_at,ingested_at,observed_at,id LIMIT 1
                        """,
                        (
                            str(cohort["token_id"]), str(cohort["discovery_recorded_at"]),
                            str(cohort["discovery_recorded_at"]), iso(upper),
                        ),
                    ).fetchone()
                    if snapshot is not None:
                        self.db.execute(
                            """
                            INSERT INTO token_universe_forward_baselines(
                                cohort_id,status,snapshot_id,observed_at,ingested_at,recorded_at,
                                price_usd,provider,reason,evaluated_at
                            ) VALUES(?,'observed',?,?,?,?,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), int(snapshot["id"]),
                                str(snapshot["observed_at"]), str(snapshot["ingested_at"]),
                                str(snapshot["recorded_at"]), float(snapshot["price_usd"]),
                                str(snapshot["provider"]), "first_durable_quote_within_5m",
                                iso(evaluated),
                            ),
                        )
                        baseline_observed += 1
                    elif evaluated >= baseline_deadline:
                        self.db.execute(
                            """
                            INSERT INTO token_universe_forward_baselines(
                                cohort_id,status,reason,evaluated_at
                            ) VALUES(?,'missing','no_durable_price_within_5m',?)
                            """,
                            (int(cohort["id"]), iso(evaluated)),
                        )
                        baseline_missing += 1
                    baseline = self.db.execute(
                        "SELECT * FROM token_universe_forward_baselines WHERE cohort_id=?",
                        (int(cohort["id"]),),
                    ).fetchone()
                for horizon in self.TOKEN_UNIVERSE_HORIZONS_MINUTES:
                    if self.db.execute(
                        "SELECT 1 FROM token_universe_forward_outcomes "
                        "WHERE cohort_id=? AND horizon_minutes=?",
                        (int(cohort["id"]), int(horizon)),
                    ).fetchone() is not None:
                        continue
                    target = parse_time(cohort["discovery_recorded_at"]) + timedelta(minutes=horizon)
                    if evaluated < target:
                        continue
                    action, candidate, bought = self._token_universe_action_at_target(
                        self.db,
                        token_id=str(cohort["token_id"]),
                        discovered_at=str(cohort["discovery_recorded_at"]),
                        target_at=iso(target),
                    )
                    if baseline is not None and str(baseline["status"]) != "observed":
                        self.db.execute(
                            """
                            INSERT INTO token_universe_forward_outcomes(
                                cohort_id,horizon_minutes,target_at,status,snapshot_count,
                                best_action_at_target,candidate_by_target,paper_bought_by_target,
                                evaluated_at
                            ) VALUES(?,?,?,'baseline_missing',0,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), horizon, iso(target), action,
                                candidate, bought, iso(evaluated),
                            ),
                        )
                        outcomes_missing += 1
                        continue
                    if baseline is None:
                        continue
                    deadline = target + timedelta(minutes=self.TOKEN_UNIVERSE_OUTCOME_GRACE_MINUTES)
                    upper = min(evaluated, deadline)
                    snapshot = self.db.execute(
                        """
                        SELECT id,observed_at,ingested_at,recorded_at,price_usd,provider
                        FROM token_snapshots
                        WHERE token_id=? AND price_usd>0
                          AND observed_at>=? AND ingested_at>=observed_at
                          AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                        ORDER BY recorded_at,ingested_at,observed_at,id LIMIT 1
                        """,
                        (str(cohort["token_id"]), iso(target), iso(target), iso(upper)),
                    ).fetchone()
                    if snapshot is not None:
                        path = list(
                            self.db.execute(
                                """
                                SELECT price_usd FROM token_snapshots
                                WHERE token_id=? AND price_usd>0
                                  AND observed_at>=? AND ingested_at>=observed_at
                                  AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                                ORDER BY recorded_at,observed_at,id
                                """,
                                (
                                    str(cohort["token_id"]), str(baseline["observed_at"]),
                                    str(baseline["recorded_at"]), str(snapshot["recorded_at"]),
                                ),
                            )
                        )
                        entry_price = float(baseline["price_usd"])
                        returns = [float(row["price_usd"]) / entry_price - 1.0 for row in path]
                        raw_return = float(snapshot["price_usd"]) / entry_price - 1.0
                        maximum = max(returns) if returns else raw_return
                        minimum = min(returns) if returns else raw_return
                        self.db.execute(
                            """
                            INSERT INTO token_universe_forward_outcomes(
                                cohort_id,horizon_minutes,target_at,status,outcome_snapshot_id,
                                outcome_observed_at,outcome_ingested_at,outcome_recorded_at,
                                outcome_price,raw_return,maximum_return,minimum_return,snapshot_count,
                                best_action_at_target,candidate_by_target,paper_bought_by_target,
                                peak_return_tier,evaluated_at
                            ) VALUES(?,?,?,'observed',?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), horizon, iso(target), int(snapshot["id"]),
                                str(snapshot["observed_at"]), str(snapshot["ingested_at"]),
                                str(snapshot["recorded_at"]), float(snapshot["price_usd"]),
                                raw_return, maximum, minimum, len(path), action, candidate, bought,
                                self._token_universe_peak_tier(maximum), iso(evaluated),
                            ),
                        )
                        outcomes_observed += 1
                    elif evaluated >= deadline:
                        self.db.execute(
                            """
                            INSERT INTO token_universe_forward_outcomes(
                                cohort_id,horizon_minutes,target_at,status,snapshot_count,
                                best_action_at_target,candidate_by_target,paper_bought_by_target,
                                evaluated_at
                            ) VALUES(?,?,?,'missing',0,?,?,?,?)
                            """,
                            (
                                int(cohort["id"]), horizon, iso(target), action,
                                candidate, bought, iso(evaluated),
                            ),
                        )
                        outcomes_missing += 1
        return {
            "cohorts_checked": len(cohorts),
            "baselines_observed": baseline_observed,
            "baselines_missing": baseline_missing,
            "outcomes_observed": outcomes_observed,
            "outcomes_missing": outcomes_missing,
        }

    def finalize_token_universe_outcome_quality(self) -> dict[str, int]:
        """Append route, liquidity and cost quality for new TOKEN-003 v1 outcomes."""
        assessed_at = iso()
        inserted = quality_valid = confirmed_tradable = 0
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM token_universe_outcome_quality_registrations "
                "WHERE definition_version=?",
                (self.TOKEN_UNIVERSE_OUTCOME_QUALITY_VERSION,),
            ).fetchone()
            if registration is None:
                return {"inserted": 0, "quality_valid": 0, "confirmed_tradable": 0}
            definition = json.loads(str(registration["definition_json"]))
            required_liquidity = float(definition["required_liquidity_usd"])
            reference_notional = float(definition["reference_notional_usd"])
            max_quote_age = float(definition["max_quote_age_seconds"])
            near_zero_market_cap = float(definition["near_zero_market_cap_usd"])
            rows = self.db.execute(
                """
                SELECT o.*,c.token_id,c.discovery_recorded_at,c.baseline_deadline_at,
                       b.snapshot_id AS baseline_snapshot_id,b.status AS baseline_status
                FROM token_universe_forward_outcomes o
                JOIN token_universe_forward_cohorts c ON c.id=o.cohort_id
                LEFT JOIN token_universe_forward_baselines b ON b.cohort_id=o.cohort_id
                LEFT JOIN token_universe_outcome_quality q ON q.outcome_id=o.id
                WHERE o.id>? AND q.id IS NULL
                ORDER BY o.id
                """,
                (int(registration["activation_outcome_id"]),),
            ).fetchall()

            for outcome in rows:
                payload: dict[str, Any] = {
                    "definition_version": self.TOKEN_UNIVERSE_OUTCOME_QUALITY_VERSION,
                    "outcome_id": int(outcome["id"]),
                    "cohort_id": int(outcome["cohort_id"]),
                    "token_id": str(outcome["token_id"]),
                    "horizon_minutes": int(outcome["horizon_minutes"]),
                    "target_at": str(outcome["target_at"]),
                    "outcome_status": str(outcome["status"]),
                    "baseline_snapshot_id": outcome["baseline_snapshot_id"],
                    "raw_peak_snapshot_id": None,
                    "target_snapshot_id": outcome["outcome_snapshot_id"],
                    "canonical_entry_snapshot_id": None,
                    "canonical_peak_snapshot_id": None,
                    "baseline_provider": None,
                    "baseline_chain_id": None,
                    "baseline_dex_id": None,
                    "baseline_pair_address": None,
                    "baseline_quote_address": None,
                    "peak_provider": None,
                    "peak_chain_id": None,
                    "peak_dex_id": None,
                    "peak_pair_address": None,
                    "peak_quote_address": None,
                    "target_provider": None,
                    "target_chain_id": None,
                    "target_dex_id": None,
                    "target_pair_address": None,
                    "target_quote_address": None,
                    "route_class": "not_evaluable",
                    "migration_evidence": "not_observed",
                    "quality_status": "not_evaluable_outcome",
                    "tradability_status": "unknown",
                    "quality_flags_json": "[]",
                    "pair_transitions_json": "[]",
                    "path_snapshot_count": int(outcome["snapshot_count"] or 0),
                    "distinct_route_count": 0,
                    "baseline_pair_snapshot_count": 0,
                    "baseline_liquidity_usd": None,
                    "peak_liquidity_usd": None,
                    "target_liquidity_usd": None,
                    "baseline_quote_age_seconds": None,
                    "target_quote_delay_seconds": None,
                    "raw_fixed_horizon_return": outcome["raw_return"],
                    "raw_token_path_return": outcome["maximum_return"],
                    "same_pair_return": None,
                    "same_route_return": None,
                    "migration_adjusted_return": None,
                    "canonical_liquid_pair_return": None,
                    "estimated_net_return_after_costs": None,
                    "net_executable_return_after_costs": None,
                    "assessed_at": assessed_at,
                }
                flags: list[str] = []
                if str(outcome["baseline_status"] or "") != "observed":
                    flags.extend(["baseline_liquidity_missing", "invalid_or_non_executable"])
                    payload["quality_status"] = "not_evaluable_baseline"
                elif str(outcome["status"]) != "observed":
                    flags.extend(["target_liquidity_missing", "invalid_or_non_executable"])
                    payload["quality_status"] = "not_evaluable_outcome"
                else:
                    baseline_row = self.db.execute(
                        "SELECT * FROM token_snapshots WHERE id=?",
                        (int(outcome["baseline_snapshot_id"]),),
                    ).fetchone()
                    target_row = self.db.execute(
                        "SELECT * FROM token_snapshots WHERE id=?",
                        (int(outcome["outcome_snapshot_id"]),),
                    ).fetchone()
                    if baseline_row is None or target_row is None:
                        flags.extend(["unknown", "invalid_or_non_executable"])
                        payload["quality_status"] = "metadata_unverifiable"
                    else:
                        path_rows = self.db.execute(
                            """
                            SELECT * FROM token_snapshots
                            WHERE token_id=? AND price_usd>0
                              AND observed_at>=? AND ingested_at>=observed_at
                              AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                            ORDER BY recorded_at,observed_at,id
                            """,
                            (
                                str(outcome["token_id"]), str(baseline_row["observed_at"]),
                                str(baseline_row["recorded_at"]), str(target_row["recorded_at"]),
                            ),
                        ).fetchall()
                        path = [self._token_universe_snapshot_route(row) for row in path_rows]
                        baseline = self._token_universe_snapshot_route(baseline_row)
                        target = self._token_universe_snapshot_route(target_row)
                        entry_price = float(baseline.get("price_usd") or 0.0)
                        peak = max(
                            path,
                            key=lambda item: float(item.get("price_usd") or 0.0),
                            default=target,
                        )
                        payload.update({
                            "raw_peak_snapshot_id": peak.get("snapshot_id"),
                            "baseline_provider": baseline.get("provider") or None,
                            "baseline_chain_id": baseline.get("chain_id") or None,
                            "baseline_dex_id": baseline.get("dex_id") or None,
                            "baseline_pair_address": baseline.get("pair_address") or None,
                            "baseline_quote_address": baseline.get("quote_address") or None,
                            "peak_provider": peak.get("provider") or None,
                            "peak_chain_id": peak.get("chain_id") or None,
                            "peak_dex_id": peak.get("dex_id") or None,
                            "peak_pair_address": peak.get("pair_address") or None,
                            "peak_quote_address": peak.get("quote_address") or None,
                            "target_provider": target.get("provider") or None,
                            "target_chain_id": target.get("chain_id") or None,
                            "target_dex_id": target.get("dex_id") or None,
                            "target_pair_address": target.get("pair_address") or None,
                            "target_quote_address": target.get("quote_address") or None,
                            "path_snapshot_count": len(path),
                            "baseline_liquidity_usd": baseline.get("liquidity_usd"),
                            "peak_liquidity_usd": peak.get("liquidity_usd"),
                            "target_liquidity_usd": target.get("liquidity_usd"),
                            "baseline_quote_age_seconds": max(
                                0.0,
                                (parse_time(baseline["recorded_at"]) - parse_time(baseline["observed_at"])).total_seconds(),
                            ),
                            "target_quote_delay_seconds": max(
                                0.0,
                                (parse_time(target["recorded_at"]) - parse_time(outcome["target_at"])).total_seconds(),
                            ),
                        })
                        route_keys = [item["route_key"] for item in path if item.get("route_key")]
                        payload["distinct_route_count"] = len(set(route_keys))
                        transitions: list[dict[str, Any]] = []
                        last_key = None
                        for item in path:
                            if not item.get("route_key") or item["route_key"] == last_key:
                                continue
                            transitions.append({
                                "provider": item["provider"], "chain_id": item["chain_id"],
                                "dex_id": item["dex_id"], "pair_address": item["pair_address"],
                                "quote_address": item["quote_address"],
                                "recorded_at": item["recorded_at"],
                            })
                            last_key = item["route_key"]
                        payload["pair_transitions_json"] = self._json(transitions)
                        same_pair = [
                            item for item in path
                            if baseline.get("pair_key") and item.get("pair_key") == baseline["pair_key"]
                        ]
                        same_route = [
                            item for item in path
                            if baseline.get("route_key") and item.get("route_key") == baseline["route_key"]
                        ]
                        payload["baseline_pair_snapshot_count"] = len(same_pair)
                        if entry_price > 0 and same_pair:
                            payload["same_pair_return"] = max(
                                float(item["price_usd"]) / entry_price - 1.0 for item in same_pair
                            )
                        if entry_price > 0 and same_route:
                            payload["same_route_return"] = max(
                                float(item["price_usd"]) / entry_price - 1.0 for item in same_route
                            )

                        migration = self.db.execute(
                            """
                            SELECT e.recorded_at FROM token_discovery_exposures e
                            JOIN token_discovery_rounds r ON r.id=e.round_id
                            WHERE e.token_id=? AND r.provider='pumpportal' AND r.surface='migration'
                              AND e.recorded_at>=? AND e.recorded_at<=?
                            ORDER BY e.recorded_at LIMIT 1
                            """,
                            (
                                str(outcome["token_id"]), str(baseline_row["recorded_at"]),
                                str(target_row["recorded_at"]),
                            ),
                        ).fetchone()
                        migrated_path = []
                        if migration is not None and baseline.get("dex_id") == "pumpfun":
                            migrated_path = [
                                item for item in path
                                if item.get("dex_id") == "pumpswap"
                                and item.get("base_address") == baseline.get("base_address")
                                and item.get("quote_address") == baseline.get("quote_address")
                                and parse_time(item["recorded_at"]) >= parse_time(migration["recorded_at"])
                            ]
                        if entry_price > 0 and migrated_path:
                            payload["migration_adjusted_return"] = max(
                                float(item["price_usd"]) / entry_price - 1.0 for item in migrated_path
                            )
                            payload["migration_evidence"] = "pumpportal_migration_observed_before_quote"

                        if baseline.get("route_key") and peak.get("route_key") == baseline["route_key"]:
                            payload["route_class"] = "same_pair"
                            flags.append("same_pair")
                        elif migrated_path and peak.get("dex_id") == "pumpswap":
                            payload["route_class"] = "launch_curve_to_amm_migration"
                            flags.append("launch_curve_to_amm_migration")
                        elif baseline.get("provider") and peak.get("provider") != baseline["provider"]:
                            payload["route_class"] = "provider_switch"
                            flags.append("provider_switch")
                        elif baseline.get("dex_id") and peak.get("dex_id") == baseline["dex_id"]:
                            payload["route_class"] = "same_dex_different_pair"
                            flags.append("same_dex_different_pair")
                        elif baseline.get("route_key") and peak.get("route_key"):
                            payload["route_class"] = "canonical_pair_switch"
                            flags.append("canonical_pair_switch")
                        else:
                            payload["route_class"] = "unknown"
                            flags.append("unknown")

                        baseline_liquidity = baseline.get("liquidity_usd")
                        peak_liquidity = peak.get("liquidity_usd")
                        target_liquidity = target.get("liquidity_usd")
                        if baseline_liquidity is None:
                            flags.append("baseline_liquidity_missing")
                        elif float(baseline_liquidity) < reference_notional:
                            flags.append("baseline_liquidity_below_stake")
                        if target_liquidity is None:
                            flags.append("target_liquidity_missing")
                        if (
                            baseline.get("market_cap_usd") is not None
                            and float(baseline["market_cap_usd"]) <= near_zero_market_cap
                        ):
                            flags.append("baseline_market_cap_near_zero")
                        if (
                            baseline_liquidity is not None and peak_liquidity is not None
                            and float(baseline_liquidity) < required_liquidity
                            <= float(peak_liquidity)
                        ):
                            flags.append("dust_pool_to_liquid_pool")
                        if (
                            baseline_liquidity is not None and target_liquidity is not None
                            and float(baseline_liquidity) >= required_liquidity
                            > float(target_liquidity)
                        ):
                            flags.append("liquid_pool_to_dust_pool")
                        if len(path) < 2:
                            flags.append("snapshot_count_too_small")
                        if float(payload["baseline_quote_age_seconds"] or 0.0) > max_quote_age:
                            flags.append("stale_quote")
                        for previous, current in zip(path, path[1:]):
                            if (
                                previous.get("route_key") and current.get("route_key")
                                and previous["route_key"] != current["route_key"]
                                and abs((parse_time(current["recorded_at"]) - parse_time(previous["recorded_at"])).total_seconds()) <= 30
                                and min(float(previous.get("price_usd") or 0.0), float(current.get("price_usd") or 0.0)) > 0
                                and max(float(previous["price_usd"]), float(current["price_usd"]))
                                / min(float(previous["price_usd"]), float(current["price_usd"])) >= 3.0
                            ):
                                flags.append("simultaneous_cross_pair_price_disagreement")
                                break

                        entry_rows = self.db.execute(
                            """
                            SELECT * FROM token_snapshots
                            WHERE token_id=? AND price_usd>0 AND liquidity_usd>=?
                              AND observed_at>=? AND ingested_at>=observed_at
                              AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                            ORDER BY liquidity_usd DESC,recorded_at,id
                            """,
                            (
                                str(outcome["token_id"]), required_liquidity,
                                str(outcome["discovery_recorded_at"]),
                                str(outcome["discovery_recorded_at"]),
                                str(outcome["baseline_deadline_at"]),
                            ),
                        ).fetchall()
                        canonical_entry = None
                        canonical_peak = None
                        if entry_rows:
                            canonical_entry = self._token_universe_snapshot_route(entry_rows[0])
                            canonical_path_rows = self.db.execute(
                                """
                                SELECT * FROM token_snapshots
                                WHERE token_id=? AND price_usd>0 AND liquidity_usd>=?
                                  AND observed_at>=? AND ingested_at>=observed_at
                                  AND recorded_at>=ingested_at AND recorded_at>=? AND recorded_at<=?
                                ORDER BY recorded_at,observed_at,id
                                """,
                                (
                                    str(outcome["token_id"]), required_liquidity,
                                    str(canonical_entry["observed_at"]),
                                    str(canonical_entry["recorded_at"]),
                                    str(target_row["recorded_at"]),
                                ),
                            ).fetchall()
                            canonical_path = [
                                item for item in map(self._token_universe_snapshot_route, canonical_path_rows)
                                if item.get("route_key") == canonical_entry.get("route_key")
                            ]
                            if canonical_path:
                                canonical_peak = max(
                                    canonical_path,
                                    key=lambda item: float(item.get("price_usd") or 0.0),
                                )
                                canonical_return = (
                                    float(canonical_peak["price_usd"])
                                    / float(canonical_entry["price_usd"]) - 1.0
                                )
                                payload.update({
                                    "canonical_entry_snapshot_id": canonical_entry["snapshot_id"],
                                    "canonical_peak_snapshot_id": canonical_peak["snapshot_id"],
                                    "canonical_liquid_pair_return": canonical_return,
                                    "estimated_net_return_after_costs": self._token_universe_net_return(
                                        canonical_entry, canonical_peak, definition,
                                        require_known_safety=False,
                                    ),
                                    "net_executable_return_after_costs": self._token_universe_net_return(
                                        canonical_entry, canonical_peak, definition,
                                        require_known_safety=True,
                                    ),
                                })

                        explicit_unsafe = any(
                            item.get("honeypot") == 1 or item.get("sellable") == 0
                            for item in (canonical_entry or {}, canonical_peak or {})
                        )
                        if explicit_unsafe:
                            payload["quality_status"] = "invalid_or_non_executable"
                            payload["tradability_status"] = "known_non_executable"
                            flags.append("invalid_or_non_executable")
                        elif canonical_entry and canonical_peak:
                            payload["quality_status"] = "same_route_liquidity_supported"
                            quality_valid += 1
                            if payload["net_executable_return_after_costs"] is not None:
                                payload["tradability_status"] = "confirmed_executable"
                                confirmed_tradable += 1
                            else:
                                payload["tradability_status"] = "liquidity_supported_safety_unknown"
                                flags.append("unknown")
                        elif payload["route_class"] == "launch_curve_to_amm_migration":
                            payload["quality_status"] = "migration_observed_execution_unknown"
                            flags.append("unknown")
                        elif payload["route_class"] != "same_pair":
                            payload["quality_status"] = "cross_pair_incomparable"
                            flags.append("unknown")
                        elif baseline_liquidity is None or target_liquidity is None:
                            payload["quality_status"] = "same_route_liquidity_metadata_unavailable"
                            flags.append("unknown")
                        elif min(float(baseline_liquidity), float(target_liquidity)) < required_liquidity:
                            payload["quality_status"] = "same_route_below_liquidity_floor"
                            payload["tradability_status"] = "insufficient_liquidity"
                            flags.append("invalid_or_non_executable")
                        else:
                            payload["quality_status"] = "same_route_activity_unverified"
                            flags.append("unknown")

                payload["quality_flags_json"] = self._json(sorted(set(flags)))
                self.db.execute(
                    """
                    INSERT INTO token_universe_outcome_quality(
                        definition_version,outcome_id,cohort_id,token_id,horizon_minutes,target_at,
                        outcome_status,baseline_snapshot_id,raw_peak_snapshot_id,target_snapshot_id,
                        canonical_entry_snapshot_id,canonical_peak_snapshot_id,
                        baseline_provider,baseline_chain_id,baseline_dex_id,baseline_pair_address,
                        baseline_quote_address,peak_provider,peak_chain_id,peak_dex_id,
                        peak_pair_address,peak_quote_address,target_provider,target_chain_id,
                        target_dex_id,target_pair_address,target_quote_address,route_class,
                        migration_evidence,quality_status,tradability_status,quality_flags_json,
                        pair_transitions_json,path_snapshot_count,distinct_route_count,
                        baseline_pair_snapshot_count,baseline_liquidity_usd,peak_liquidity_usd,
                        target_liquidity_usd,baseline_quote_age_seconds,target_quote_delay_seconds,
                        raw_fixed_horizon_return,raw_token_path_return,same_pair_return,
                        same_route_return,migration_adjusted_return,canonical_liquid_pair_return,
                        estimated_net_return_after_costs,net_executable_return_after_costs,
                        assessed_at,decision_eligible,affects
                    ) VALUES(
                        :definition_version,:outcome_id,:cohort_id,:token_id,:horizon_minutes,:target_at,
                        :outcome_status,:baseline_snapshot_id,:raw_peak_snapshot_id,:target_snapshot_id,
                        :canonical_entry_snapshot_id,:canonical_peak_snapshot_id,
                        :baseline_provider,:baseline_chain_id,:baseline_dex_id,:baseline_pair_address,
                        :baseline_quote_address,:peak_provider,:peak_chain_id,:peak_dex_id,
                        :peak_pair_address,:peak_quote_address,:target_provider,:target_chain_id,
                        :target_dex_id,:target_pair_address,:target_quote_address,:route_class,
                        :migration_evidence,:quality_status,:tradability_status,:quality_flags_json,
                        :pair_transitions_json,:path_snapshot_count,:distinct_route_count,
                        :baseline_pair_snapshot_count,:baseline_liquidity_usd,:peak_liquidity_usd,
                        :target_liquidity_usd,:baseline_quote_age_seconds,:target_quote_delay_seconds,
                        :raw_fixed_horizon_return,:raw_token_path_return,:same_pair_return,
                        :same_route_return,:migration_adjusted_return,:canonical_liquid_pair_return,
                        :estimated_net_return_after_costs,:net_executable_return_after_costs,
                        :assessed_at,0,'none'
                    )
                    """,
                    payload,
                )
                inserted += 1
        return {
            "inserted": inserted,
            "quality_valid": quality_valid,
            "confirmed_tradable": confirmed_tradable,
        }

    def register_token_universe_fixed_target_execution(
        self,
        *,
        paper_stake_usd: float,
        min_liquidity_usd: float,
        max_liquidity_impact_pct: float,
        slippage_rate: float,
        default_fee_bps: float,
        pump_fee_bps: float,
        max_tax_pct: float,
    ) -> sqlite3.Row:
        """Freeze a forward-only fixed-target synthetic Paper execution audit."""
        stake = max(0.01, float(paper_stake_usd))
        impact = max(0.000001, float(max_liquidity_impact_pct))
        definition = {
            "version": self.TOKEN_UNIVERSE_FIXED_TARGET_EXECUTION_VERSION,
            "source": self.TOKEN_UNIVERSE_FORWARD_VERSION,
            "no_historical_backfill": True,
            "denominator": "registered_after_activation_cohort_id_all_terminal_outcomes",
            "entry": "v1_baseline_snapshot_id",
            "exit": "v1_fixed_horizon_target_snapshot_id",
            "canonical_peak_used": False,
            "supported_chains": sorted(self.TOKEN_UNIVERSE_EVM_CHAINS),
            "paper_stake_usd": stake,
            "min_liquidity_usd": max(0.0, float(min_liquidity_usd)),
            "max_liquidity_impact_pct": impact,
            "required_liquidity_usd": max(max(0.0, float(min_liquidity_usd)), stake / impact),
            "slippage_rate_each_side": max(0.0, min(0.49, float(slippage_rate))),
            "default_fee_bps_each_side": max(0.0, float(default_fee_bps)),
            "pump_fee_bps_each_side": max(0.0, float(pump_fee_bps)),
            "max_tax_pct": max(0.0, float(max_tax_pct)),
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO token_universe_fixed_target_execution_registrations("
                "definition_version,registered_at,activation_cohort_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM token_universe_forward_cohorts),0),?)",
                (
                    self.TOKEN_UNIVERSE_FIXED_TARGET_EXECUTION_VERSION,
                    iso(),
                    self._json(definition),
                ),
            )
            return self.db.execute(
                "SELECT * FROM token_universe_fixed_target_execution_registrations "
                "WHERE definition_version=?",
                (self.TOKEN_UNIVERSE_FIXED_TARGET_EXECUTION_VERSION,),
            ).fetchone()

    @staticmethod
    def _token_universe_fixed_target_safety_evidence(row: sqlite3.Row) -> dict[str, Any]:
        try:
            raw = json.loads(str(row["raw_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            raw = {}
        raw = raw if isinstance(raw, dict) else {}
        reported = raw.get("execution_safety_reports")
        sources = [
            str(name)
            for name in reported
            if str(name) in {"goplus_evm", "honeypot_is", "goplus_solana", "rugcheck"}
        ] if isinstance(reported, list) else [
            name
            for name in ("goplus_evm", "honeypot_is", "goplus_solana", "rugcheck")
            if isinstance(raw.get(name), dict)
        ]
        return {
            "sources": list(dict.fromkeys(sources)),
            "observed_at": str(
                raw.get("execution_safety_checked_at")
                or raw.get("execution_safety_observed_at")
                or ""
            ) or None,
        }

    @staticmethod
    def _token_universe_fixed_target_execution_math(
        entry: dict[str, Any],
        target: dict[str, Any],
        definition: Mapping[str, Any],
    ) -> dict[str, float]:
        stake = float(definition["paper_stake_usd"])
        slippage = float(definition["slippage_rate_each_side"])
        default_fee = float(definition["default_fee_bps_each_side"])
        pump_fee = float(definition["pump_fee_bps_each_side"])
        buy_fee_bps = pump_fee if "pump" in str(entry.get("dex_id") or "") else default_fee
        sell_fee_bps = pump_fee if "pump" in str(target.get("dex_id") or "") else default_fee
        entry_price = float(entry["price_usd"])
        target_price = float(target["price_usd"])
        buy_execution = entry_price * (1.0 + slippage)
        buy_tax = stake * float(entry["buy_tax_pct"]) / 100.0
        quantity = (stake - buy_tax) / buy_execution
        buy_fee = stake * buy_fee_bps / 10_000.0
        buy_slippage = (stake / buy_execution) * (buy_execution - entry_price)
        sell_execution = target_price * (1.0 - slippage)
        sell_gross = quantity * sell_execution
        sell_fee = sell_gross * sell_fee_bps / 10_000.0
        sell_tax = sell_gross * float(target["sell_tax_pct"]) / 100.0
        sell_slippage = quantity * (target_price - sell_execution)
        sell_net = sell_gross - sell_fee - sell_tax
        pnl = sell_net - stake - buy_fee
        return {
            "buy_execution_price_usd": buy_execution,
            "buy_fee_bps": buy_fee_bps,
            "buy_fee_usd": buy_fee,
            "buy_slippage_usd": buy_slippage,
            "buy_tax_usd": buy_tax,
            "acquired_quantity": quantity,
            "sell_execution_price_usd": sell_execution,
            "sell_fee_bps": sell_fee_bps,
            "sell_fee_usd": sell_fee,
            "sell_slippage_usd": sell_slippage,
            "sell_tax_usd": sell_tax,
            "sell_gross_usd": sell_gross,
            "sell_net_usd": sell_net,
            "modeled_pnl_usd": pnl,
            "modeled_net_return": pnl / (stake + buy_fee),
        }

    def finalize_token_universe_fixed_target_execution(self) -> dict[str, int]:
        """Append terminal baseline-to-fixed-target synthetic execution records."""
        assessed_at = iso()
        inserted = modeled_executable = 0
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM token_universe_fixed_target_execution_registrations "
                "WHERE definition_version=?",
                (self.TOKEN_UNIVERSE_FIXED_TARGET_EXECUTION_VERSION,),
            ).fetchone()
            if registration is None:
                return {"inserted": 0, "modeled_executable": 0}
            definition = self._json_object(registration["definition_json"])
            rows = self.db.execute(
                """
                SELECT o.*,c.token_id,c.chain,b.snapshot_id AS baseline_snapshot_id,
                       b.status AS baseline_status
                FROM token_universe_forward_outcomes o
                JOIN token_universe_forward_cohorts c ON c.id=o.cohort_id
                LEFT JOIN token_universe_forward_baselines b ON b.cohort_id=c.id
                LEFT JOIN token_universe_fixed_target_execution_results x ON x.outcome_id=o.id
                WHERE c.id>? AND c.definition_version=? AND x.id IS NULL
                ORDER BY c.id,o.horizon_minutes,o.id
                """,
                (
                    int(registration["activation_cohort_id"]),
                    self.TOKEN_UNIVERSE_FORWARD_VERSION,
                ),
            ).fetchall()
            for outcome in rows:
                payload: dict[str, Any] = {
                    "definition_version": self.TOKEN_UNIVERSE_FIXED_TARGET_EXECUTION_VERSION,
                    "outcome_id": int(outcome["id"]),
                    "cohort_id": int(outcome["cohort_id"]),
                    "token_id": str(outcome["token_id"]),
                    "chain": str(outcome["chain"]).lower(),
                    "horizon_minutes": int(outcome["horizon_minutes"]),
                    "target_at": str(outcome["target_at"]),
                    "baseline_snapshot_id": outcome["baseline_snapshot_id"],
                    "target_snapshot_id": outcome["outcome_snapshot_id"],
                    "entry_observed_at": None, "entry_ingested_at": None, "entry_recorded_at": None,
                    "target_observed_at": None, "target_ingested_at": None, "target_recorded_at": None,
                    "entry_route_json": "{}", "target_route_json": "{}",
                    "safety_sources_json": "{}",
                    "entry_safety_observed_at": None, "target_safety_observed_at": None,
                    "entry_price_usd": None, "target_price_usd": None,
                    "entry_liquidity_usd": None, "target_liquidity_usd": None,
                    "entry_buy_tax_pct": None, "entry_sell_tax_pct": None,
                    "entry_honeypot": None, "entry_sellable": None,
                    "target_buy_tax_pct": None, "target_sell_tax_pct": None,
                    "target_honeypot": None, "target_sellable": None,
                    "terminal_status": "baseline_missing",
                    "paper_stake_usd": float(definition["paper_stake_usd"]),
                    "buy_execution_price_usd": None, "buy_fee_bps": None, "buy_fee_usd": None,
                    "buy_slippage_usd": None, "buy_tax_usd": None, "acquired_quantity": None,
                    "sell_execution_price_usd": None, "sell_fee_bps": None, "sell_fee_usd": None,
                    "sell_slippage_usd": None, "sell_tax_usd": None, "sell_gross_usd": None,
                    "sell_net_usd": None, "modeled_pnl_usd": None, "modeled_net_return": None,
                    "assessed_at": assessed_at,
                }
                if str(outcome["baseline_status"] or "") != "observed" or outcome["baseline_snapshot_id"] is None:
                    pass
                elif str(outcome["status"] or "") != "observed" or outcome["outcome_snapshot_id"] is None:
                    payload["terminal_status"] = "outcome_missing"
                else:
                    entry_row = self.db.execute(
                        "SELECT * FROM token_snapshots WHERE id=?", (int(outcome["baseline_snapshot_id"]),)
                    ).fetchone()
                    target_row = self.db.execute(
                        "SELECT * FROM token_snapshots WHERE id=?", (int(outcome["outcome_snapshot_id"]),)
                    ).fetchone()
                    if entry_row is None:
                        payload["terminal_status"] = "baseline_missing"
                    elif target_row is None:
                        payload["terminal_status"] = "outcome_missing"
                    else:
                        entry = self._token_universe_snapshot_route(entry_row)
                        target = self._token_universe_snapshot_route(target_row)
                        entry_safety = self._token_universe_fixed_target_safety_evidence(entry_row)
                        target_safety = self._token_universe_fixed_target_safety_evidence(target_row)
                        payload.update({
                            "entry_observed_at": entry_row["observed_at"],
                            "entry_ingested_at": entry_row["ingested_at"],
                            "entry_recorded_at": entry_row["recorded_at"],
                            "target_observed_at": target_row["observed_at"],
                            "target_ingested_at": target_row["ingested_at"],
                            "target_recorded_at": target_row["recorded_at"],
                            "entry_route_json": self._json(entry),
                            "target_route_json": self._json(target),
                            "safety_sources_json": self._json({
                                "entry": entry_safety["sources"],
                                "target": target_safety["sources"],
                            }),
                            "entry_safety_observed_at": entry_safety["observed_at"],
                            "target_safety_observed_at": target_safety["observed_at"],
                            "entry_price_usd": entry.get("price_usd"),
                            "target_price_usd": target.get("price_usd"),
                            "entry_liquidity_usd": entry.get("liquidity_usd"),
                            "target_liquidity_usd": target.get("liquidity_usd"),
                            "entry_buy_tax_pct": entry.get("buy_tax_pct"),
                            "entry_sell_tax_pct": entry.get("sell_tax_pct"),
                            "entry_honeypot": entry.get("honeypot"),
                            "entry_sellable": entry.get("sellable"),
                            "target_buy_tax_pct": target.get("buy_tax_pct"),
                            "target_sell_tax_pct": target.get("sell_tax_pct"),
                            "target_honeypot": target.get("honeypot"),
                            "target_sellable": target.get("sellable"),
                        })
                        try:
                            entry_time_valid = (
                                parse_time(entry_row["observed_at"]) <= parse_time(entry_row["ingested_at"])
                                <= parse_time(entry_row["recorded_at"])
                            )
                            target_time_valid = (
                                parse_time(target_row["observed_at"]) <= parse_time(target_row["ingested_at"])
                                <= parse_time(target_row["recorded_at"])
                            )
                            chronological = (
                                parse_time(entry_row["observed_at"]) <= parse_time(target_row["observed_at"])
                                and parse_time(entry_row["recorded_at"]) <= parse_time(target_row["recorded_at"])
                            )
                        except (TypeError, ValueError):
                            entry_time_valid = target_time_valid = chronological = False
                        if not entry_time_valid or not target_time_valid or not chronological:
                            payload["terminal_status"] = "time_order_invalid"
                        elif payload["chain"] not in self.TOKEN_UNIVERSE_EVM_CHAINS:
                            payload["terminal_status"] = "unsupported_chain"
                        elif not entry.get("route_key") or entry.get("route_key") != target.get("route_key"):
                            payload["terminal_status"] = "route_mismatch"
                        elif (
                            entry.get("liquidity_usd") is None or target.get("liquidity_usd") is None
                            or min(float(entry["liquidity_usd"]), float(target["liquidity_usd"]))
                            < float(definition["required_liquidity_usd"])
                        ):
                            payload["terminal_status"] = "insufficient_liquidity"
                        else:
                            safety_values = (
                                entry.get("buy_tax_pct"), entry.get("sell_tax_pct"),
                                entry.get("honeypot"), entry.get("sellable"),
                                target.get("buy_tax_pct"), target.get("sell_tax_pct"),
                                target.get("honeypot"), target.get("sellable"),
                            )
                            max_tax = float(definition["max_tax_pct"])
                            if (
                                not entry_safety["sources"] or not target_safety["sources"]
                                or entry_safety["observed_at"] is None
                                or target_safety["observed_at"] is None
                            ):
                                payload["terminal_status"] = "safety_unknown"
                            else:
                                try:
                                    safety_time_valid = (
                                        parse_time(entry_row["observed_at"])
                                        <= parse_time(entry_safety["observed_at"])
                                        <= parse_time(entry_row["recorded_at"])
                                        and parse_time(target_row["observed_at"])
                                        <= parse_time(target_safety["observed_at"])
                                        <= parse_time(target_row["recorded_at"])
                                    )
                                except (TypeError, ValueError):
                                    safety_time_valid = False
                                unsafe = (
                                    entry.get("honeypot") == 1 or target.get("honeypot") == 1
                                    or entry.get("sellable") == 0 or target.get("sellable") == 0
                                    or any(
                                        float(value) > max_tax
                                        for value in (
                                            entry.get("buy_tax_pct"), entry.get("sell_tax_pct"),
                                            target.get("buy_tax_pct"), target.get("sell_tax_pct"),
                                        )
                                        if value is not None
                                    )
                                )
                                if not safety_time_valid:
                                    payload["terminal_status"] = "time_order_invalid"
                                elif unsafe:
                                    payload["terminal_status"] = "known_non_executable"
                                elif any(value is None for value in safety_values):
                                    payload["terminal_status"] = "safety_unknown"
                                else:
                                    payload["terminal_status"] = "modeled_executable"
                                    payload.update(self._token_universe_fixed_target_execution_math(
                                        entry, target, definition,
                                    ))
                                    modeled_executable += 1
                columns = tuple(payload)
                self.db.execute(
                    "INSERT INTO token_universe_fixed_target_execution_results("
                    + ",".join(columns) + ") VALUES(" + ",".join("?" for _ in columns) + ")",
                    tuple(payload[column] for column in columns),
                )
                inserted += 1
        return {"inserted": inserted, "modeled_executable": modeled_executable}

    @classmethod
    def _onchain_only_shadow_definition(
        cls,
        *,
        momentum_threshold: float,
        paper_stake_usd: float,
        min_liquidity_usd: float,
        max_liquidity_impact_pct: float,
        slippage_rate: float,
        default_fee_bps: float,
        pump_fee_bps: float,
        max_tax_pct: float,
        max_quote_delay_seconds: float,
    ) -> dict[str, Any]:
        stake = max(0.01, float(paper_stake_usd))
        impact = max(0.000001, float(max_liquidity_impact_pct))
        return {
            "version": cls.ONCHAIN_ONLY_SHADOW_VERSION,
            "source": cls.TOKEN_UNIVERSE_FUNNEL_VERSION,
            "assignment": "first_post_registration_eligible_onchain_momentum_trigger_per_token",
            "absence_semantics": "no_eligible_event_relation_or_context_assessment_observed_locally_by_trigger",
            "no_historical_backfill": True,
            "horizons_minutes": list(cls.TOKEN_UNIVERSE_HORIZONS_MINUTES),
            "primary_horizon_minutes": 15,
            "target_grace_minutes": cls.TOKEN_UNIVERSE_OUTCOME_GRACE_MINUTES,
            "momentum_formula": "candidate_momentum_score/v1",
            "momentum_threshold": float(momentum_threshold),
            "max_quote_delay_seconds": max(1.0, float(max_quote_delay_seconds)),
            "paper_stake_usd": stake,
            "min_liquidity_usd": max(0.0, float(min_liquidity_usd)),
            "max_liquidity_impact_pct": impact,
            "required_liquidity_usd": max(max(0.0, float(min_liquidity_usd)), stake / impact),
            "slippage_rate_each_side": max(0.0, min(0.49, float(slippage_rate))),
            "default_fee_bps_each_side": max(0.0, float(default_fee_bps)),
            "pump_fee_bps_each_side": max(0.0, float(pump_fee_bps)),
            "max_tax_pct": max(0.0, float(max_tax_pct)),
            "evm_execution_semantics": "DexScreener spot plus frozen costs and time-valid safety; modeled only, not router quote",
            "solana_execution_semantics": "market snapshot only until a trigger-anchored Jupiter overlay exists",
            "maturity_gate": {
                "minimum_primary_terminal_tokens": 30,
                "minimum_independent_trigger_dates": 15,
                "minimum_positive_results": 5,
                "minimum_nonpositive_results": 5,
            },
            "decision_eligible": False,
            "affects": "none",
        }

    def register_onchain_only_shadow(
        self,
        *,
        momentum_threshold: float,
        paper_stake_usd: float,
        min_liquidity_usd: float,
        max_liquidity_impact_pct: float,
        slippage_rate: float,
        default_fee_bps: float,
        pump_fee_bps: float,
        max_tax_pct: float,
        max_quote_delay_seconds: float,
    ) -> sqlite3.Row:
        definition = self._onchain_only_shadow_definition(
            momentum_threshold=momentum_threshold,
            paper_stake_usd=paper_stake_usd,
            min_liquidity_usd=min_liquidity_usd,
            max_liquidity_impact_pct=max_liquidity_impact_pct,
            slippage_rate=slippage_rate,
            default_fee_bps=default_fee_bps,
            pump_fee_bps=pump_fee_bps,
            max_tax_pct=max_tax_pct,
            max_quote_delay_seconds=max_quote_delay_seconds,
        )
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_shadow_registrations("
                "definition_version,registered_at,activation_transition_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM token_universe_funnel_transitions),0),?)",
                (self.ONCHAIN_ONLY_SHADOW_VERSION, iso(), self._json(definition)),
            )
            return self.db.execute(
                "SELECT * FROM onchain_only_shadow_registrations WHERE definition_version=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION,),
            ).fetchone()

    def enroll_onchain_only_shadow(self, transition_id: int) -> int | None:
        """Freeze a post-registration on-chain trigger and its locally known prior context."""
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_shadow_registrations WHERE definition_version=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION,),
            ).fetchone()
            transition = self.db.execute(
                "SELECT * FROM token_universe_funnel_transitions WHERE id=?",
                (int(transition_id),),
            ).fetchone()
            if (
                registration is None or transition is None
                or int(transition["id"]) <= int(registration["activation_transition_id"] or 0)
                or str(transition["definition_version"]) != self.TOKEN_UNIVERSE_FUNNEL_VERSION
                or str(transition["stage"]) != "context_trigger_evaluation"
                or str(transition["status"]) != "eligible"
                or str(transition["reason_code"]) != "onchain_momentum"
                or transition["snapshot_id"] is None
                or any(transition[key] is not None for key in (
                    "event_id", "decision_id", "observation_id", "source_link_id"
                ))
            ):
                return None
            existing = self.db.execute(
                "SELECT id FROM onchain_only_shadow_cohorts WHERE definition_version=? AND token_id=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION, str(transition["token_id"])),
            ).fetchone()
            if existing is not None:
                return int(existing["id"])
            snapshot = self.db.execute(
                "SELECT * FROM token_snapshots WHERE id=? AND token_id=?",
                (int(transition["snapshot_id"]), str(transition["token_id"])),
            ).fetchone()
            cohort = self.db.execute(
                "SELECT * FROM token_universe_forward_cohorts WHERE id=? AND token_id=?",
                (int(transition["cohort_id"]), str(transition["token_id"])),
            ).fetchone()
            if snapshot is None or cohort is None:
                return None
            trigger_recorded = parse_time(transition["recorded_at"])
            event_counts = self.db.execute(
                """
                SELECT COUNT(*) AS relation_count,
                       SUM(CASE WHEN o.role IN ('feature','confirmation')
                                     AND o.observed_at<=? AND o.ingested_at<=?
                                THEN 1 ELSE 0 END) AS eligible_count
                FROM token_universe_funnel_transitions t
                LEFT JOIN observations o ON o.id=t.observation_id
                WHERE t.definition_version=? AND t.cohort_id=? AND t.id<?
                  AND t.stage='event_token_relation' AND t.status='linked'
                  AND t.recorded_at<=?
                """,
                (
                    iso(trigger_recorded), iso(trigger_recorded),
                    self.TOKEN_UNIVERSE_FUNNEL_VERSION, int(transition["cohort_id"]),
                    int(transition["id"]), iso(trigger_recorded),
                ),
            ).fetchone()
            context_count = int(self.db.execute(
                "SELECT COUNT(*) FROM token_context_assessments WHERE token_id=? AND assessed_at<=?",
                (str(transition["token_id"]), iso(trigger_recorded)),
            ).fetchone()[0])
            eligible_relations = int(event_counts["eligible_count"] or 0)
            if eligible_relations or context_count:
                return None
            definition = self._json_object(registration["definition_json"])
            try:
                observed = parse_time(snapshot["observed_at"])
                ingested = parse_time(snapshot["ingested_at"])
                recorded = parse_time(snapshot["recorded_at"])
                time_valid = observed <= ingested <= recorded <= trigger_recorded
                delay = max(0.0, (recorded - observed).total_seconds())
            except (TypeError, ValueError):
                observed = ingested = recorded = trigger_recorded
                time_valid = False
                delay = 0.0
            if not time_valid:
                baseline_status = "time_order_invalid"
            elif delay > float(definition["max_quote_delay_seconds"]):
                baseline_status = "quote_delay_expired"
            else:
                baseline_status = "valid"
            metadata = self._json_object(transition["metadata_json"])
            momentum = float(metadata.get("momentum_score") or 0.0)
            self.db.execute(
                """
                INSERT OR IGNORE INTO onchain_only_shadow_cohorts(
                    definition_version,trigger_transition_id,universe_cohort_id,token_id,chain,
                    trigger_snapshot_id,trigger_observed_at,trigger_ingested_at,trigger_recorded_at,
                    trigger_snapshot_delay_seconds,baseline_status,momentum_score,momentum_threshold,
                    prior_event_relation_count,prior_eligible_event_relation_count,
                    prior_context_assessment_count,enrolled_at,decision_eligible,affects
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')
                """,
                (
                    self.ONCHAIN_ONLY_SHADOW_VERSION, int(transition["id"]), int(cohort["id"]),
                    str(transition["token_id"]), str(cohort["chain"]), int(snapshot["id"]),
                    str(transition["observed_at"]), str(transition["ingested_at"]),
                    str(transition["recorded_at"]), delay, baseline_status, momentum,
                    float(definition["momentum_threshold"]), int(event_counts["relation_count"] or 0),
                    0, 0, iso(),
                ),
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_shadow_cohorts WHERE definition_version=? AND token_id=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION, str(transition["token_id"])),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def due_onchain_only_shadow_quotes(
        self,
        *,
        now: Any = None,
        limit: int = 60,
    ) -> list[dict[str, Any]]:
        current = parse_time(now or utcnow())
        registration = self.db.execute(
            "SELECT * FROM onchain_only_shadow_registrations WHERE definition_version=?",
            (self.ONCHAIN_ONLY_SHADOW_VERSION,),
        ).fetchone()
        if registration is None:
            return []
        definition = self._json_object(registration["definition_json"])
        grace = timedelta(minutes=int(definition["target_grace_minutes"]))
        due: list[dict[str, Any]] = []
        rows = self.db.execute(
            "SELECT * FROM onchain_only_shadow_cohorts WHERE definition_version=? "
            "AND baseline_status='valid' ORDER BY trigger_recorded_at,id",
            (self.ONCHAIN_ONLY_SHADOW_VERSION,),
        ).fetchall()
        for row in rows:
            trigger = parse_time(row["trigger_recorded_at"])
            for horizon in self.TOKEN_UNIVERSE_HORIZONS_MINUTES:
                target = trigger + timedelta(minutes=horizon)
                deadline = target + grace
                role = f"onchain_shadow_{horizon}m"
                if not target <= current <= deadline:
                    continue
                if self.db.execute(
                    "SELECT 1 FROM onchain_only_shadow_results WHERE definition_version=? "
                    "AND cohort_id=? AND horizon_minutes=?",
                    (self.ONCHAIN_ONLY_SHADOW_VERSION, int(row["id"]), horizon),
                ).fetchone() is not None:
                    continue
                if self.db.execute(
                    "SELECT 1 FROM token_discovery_quote_attempts WHERE token_id=? AND role=? LIMIT 1",
                    (str(row["token_id"]), role),
                ).fetchone() is not None:
                    continue
                due.append({
                    "cohort_id": int(row["universe_cohort_id"]),
                    "shadow_cohort_id": int(row["id"]),
                    "token_id": str(row["token_id"]),
                    "chain": str(row["chain"]),
                    "role": role,
                    "horizon_minutes": horizon,
                    "queue_due_at": iso(target),
                    "deadline_at": iso(deadline),
                    "lane": self.ONCHAIN_ONLY_SHADOW_VERSION,
                })
        due.sort(key=lambda item: (
            parse_time(item["deadline_at"]), parse_time(item["queue_due_at"]),
            int(item["shadow_cohort_id"]), int(item["horizon_minutes"]),
        ))
        return due[:max(1, int(limit))]

    def record_onchain_only_shadow_result(
        self,
        item: Mapping[str, Any],
        *,
        terminal_status: str,
        quote_attempt_id: int | None = None,
        target_snapshot_id: int | None = None,
        recorded_at: Any = None,
    ) -> int | None:
        allowed = {
            "observed", "baseline_invalid", "no_pair", "error", "deadline_missing",
            "time_order_invalid", "target_late",
        }
        if terminal_status not in allowed:
            raise ValueError("invalid onchain-only Shadow terminal status")
        now = parse_time(recorded_at or utcnow())
        with self._lock, self.db:
            cohort = self.db.execute(
                "SELECT * FROM onchain_only_shadow_cohorts WHERE id=? AND definition_version=?",
                (int(item["shadow_cohort_id"]), self.ONCHAIN_ONLY_SHADOW_VERSION),
            ).fetchone()
            registration = self.db.execute(
                "SELECT * FROM onchain_only_shadow_registrations WHERE definition_version=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION,),
            ).fetchone()
            if cohort is None or registration is None:
                return None
            horizon = int(item["horizon_minutes"])
            if horizon not in self.TOKEN_UNIVERSE_HORIZONS_MINUTES:
                raise ValueError("invalid onchain-only Shadow horizon")
            existing = self.db.execute(
                "SELECT id FROM onchain_only_shadow_results WHERE definition_version=? "
                "AND cohort_id=? AND horizon_minutes=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION, int(cohort["id"]), horizon),
            ).fetchone()
            if existing is not None:
                return int(existing["id"])
            definition = self._json_object(registration["definition_json"])
            entry_row = self.db.execute(
                "SELECT * FROM token_snapshots WHERE id=?",
                (int(cohort["trigger_snapshot_id"]),),
            ).fetchone()
            target_row = self.db.execute(
                "SELECT * FROM token_snapshots WHERE id=?",
                (int(target_snapshot_id),),
            ).fetchone() if target_snapshot_id is not None else None
            target_at = parse_time(item.get("queue_due_at") or (
                parse_time(cohort["trigger_recorded_at"]) + timedelta(minutes=horizon)
            ))
            deadline_at = parse_time(item.get("deadline_at") or (
                target_at + timedelta(minutes=int(definition["target_grace_minutes"]))
            ))
            route_status = "unavailable"
            execution_status = "market_snapshot_only"
            entry_route = self._token_universe_snapshot_route(entry_row)
            target_route: dict[str, Any] = {}
            entry_safety = self._token_universe_fixed_target_safety_evidence(entry_row) if entry_row else {"sources": [], "observed_at": None}
            target_safety = {"sources": [], "observed_at": None}
            safety_disagreement = False
            target_observed_at = target_ingested_at = target_recorded_at = None
            target_delay = entry_price = target_price = entry_liquidity = target_liquidity = None
            raw_return = modeled_return = None
            status = terminal_status
            if terminal_status == "observed" and entry_row is not None and target_row is not None:
                target_route = self._token_universe_snapshot_route(target_row)
                target_safety = self._token_universe_fixed_target_safety_evidence(target_row)
                try:
                    entry_observed = parse_time(entry_row["observed_at"])
                    entry_ingested = parse_time(entry_row["ingested_at"])
                    entry_recorded = parse_time(entry_row["recorded_at"])
                    target_observed = parse_time(target_row["observed_at"])
                    target_ingested = parse_time(target_row["ingested_at"])
                    target_recorded = parse_time(target_row["recorded_at"])
                    valid_order = (
                        entry_observed <= entry_ingested <= entry_recorded
                        <= parse_time(cohort["trigger_recorded_at"])
                        <= target_observed <= target_ingested <= target_recorded
                    )
                except (TypeError, ValueError):
                    valid_order = False
                    target_observed = target_ingested = target_recorded = now
                target_observed_at, target_ingested_at, target_recorded_at = (
                    str(target_row["observed_at"]), str(target_row["ingested_at"]),
                    str(target_row["recorded_at"]),
                )
                target_delay = max(0.0, (target_recorded - target_at).total_seconds())
                entry_price = entry_route.get("price_usd")
                target_price = target_route.get("price_usd")
                entry_liquidity = entry_route.get("liquidity_usd")
                target_liquidity = target_route.get("liquidity_usd")
                if not valid_order or target_observed < target_at:
                    status = "time_order_invalid"
                elif target_recorded > deadline_at:
                    status = "target_late"
                else:
                    if entry_price and target_price:
                        raw_return = float(target_price) / float(entry_price) - 1.0
                    if entry_route.get("route_key") and entry_route.get("route_key") == target_route.get("route_key"):
                        route_status = "same_route"
                    elif entry_route.get("route_key") and target_route.get("route_key"):
                        route_status = "route_mismatch"
                    if str(cohort["chain"]).lower() not in self.TOKEN_UNIVERSE_EVM_CHAINS:
                        execution_status = "unsupported_chain"
                    elif target_delay > float(definition["max_quote_delay_seconds"]):
                        execution_status = "target_delay_expired"
                    elif route_status != "same_route":
                        execution_status = "route_mismatch"
                    elif (
                        entry_liquidity is None or target_liquidity is None
                        or min(float(entry_liquidity), float(target_liquidity))
                        < float(definition["required_liquidity_usd"])
                    ):
                        execution_status = "insufficient_liquidity"
                    else:
                        entry_raw = self._json_object(entry_row["raw_json"])
                        target_raw = self._json_object(target_row["raw_json"])
                        safety_disagreement = bool(
                            entry_raw.get("execution_safety_disagreement")
                            or target_raw.get("execution_safety_disagreement")
                        )
                        sources = set(entry_safety["sources"]) | set(target_safety["sources"])
                        values = (
                            entry_route.get("buy_tax_pct"), entry_route.get("sell_tax_pct"),
                            entry_route.get("honeypot"), entry_route.get("sellable"),
                            target_route.get("buy_tax_pct"), target_route.get("sell_tax_pct"),
                            target_route.get("honeypot"), target_route.get("sellable"),
                        )
                        try:
                            safety_time_valid = (
                                entry_safety["observed_at"] is not None
                                and target_safety["observed_at"] is not None
                                and parse_time(entry_row["observed_at"])
                                <= parse_time(entry_safety["observed_at"])
                                <= parse_time(entry_row["recorded_at"])
                                and parse_time(target_row["observed_at"])
                                <= parse_time(target_safety["observed_at"])
                                <= parse_time(target_row["recorded_at"])
                            )
                        except (TypeError, ValueError):
                            safety_time_valid = False
                        unsafe = (
                            entry_route.get("honeypot") == 1 or target_route.get("honeypot") == 1
                            or entry_route.get("sellable") == 0 or target_route.get("sellable") == 0
                            or any(
                                float(value) > float(definition["max_tax_pct"])
                                for value in (
                                    entry_route.get("buy_tax_pct"), entry_route.get("sell_tax_pct"),
                                    target_route.get("buy_tax_pct"), target_route.get("sell_tax_pct"),
                                ) if value is not None
                            )
                        )
                        if not sources or any(value is None for value in values) or not safety_time_valid:
                            execution_status = "safety_unknown"
                        elif safety_disagreement:
                            execution_status = "safety_disagreement"
                        elif unsafe:
                            execution_status = "known_non_executable"
                        else:
                            modeled_return = self._token_universe_fixed_target_execution_math(
                                entry_route, target_route, definition,
                            )["modeled_net_return"]
                            execution_status = (
                                "modeled_only_multi_source" if len(sources) >= 2
                                else "modeled_only_single_source"
                            )
            trigger_recorded = str(cohort["trigger_recorded_at"])
            post_event = int(self.db.execute(
                "SELECT COUNT(*) FROM token_universe_funnel_transitions WHERE definition_version=? "
                "AND cohort_id=? AND id>? AND stage='event_token_relation' AND status='linked' "
                "AND recorded_at<=?",
                (
                    self.TOKEN_UNIVERSE_FUNNEL_VERSION, int(cohort["universe_cohort_id"]),
                    int(cohort["trigger_transition_id"]), iso(now),
                ),
            ).fetchone()[0])
            post_context = int(self.db.execute(
                "SELECT COUNT(*) FROM token_context_assessments WHERE token_id=? "
                "AND assessed_at>? AND assessed_at<=?",
                (str(cohort["token_id"]), trigger_recorded, iso(now)),
            ).fetchone()[0])
            self.db.execute(
                """
                INSERT INTO onchain_only_shadow_results(
                    definition_version,cohort_id,horizon_minutes,target_at,deadline_at,
                    quote_attempt_id,baseline_snapshot_id,target_snapshot_id,terminal_status,
                    route_status,execution_evidence_status,entry_route_json,target_route_json,
                    safety_sources_json,safety_disagreement,entry_safety_observed_at,
                    target_safety_observed_at,target_observed_at,target_ingested_at,
                    target_recorded_at,target_delay_seconds,entry_price_usd,target_price_usd,
                    entry_liquidity_usd,target_liquidity_usd,raw_return,modeled_net_return,
                    post_trigger_event_relation_count,post_trigger_context_assessment_count,
                    recorded_at,decision_eligible,affects
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')
                """,
                (
                    self.ONCHAIN_ONLY_SHADOW_VERSION, int(cohort["id"]), horizon,
                    iso(target_at), iso(deadline_at), int(quote_attempt_id) if quote_attempt_id else None,
                    int(cohort["trigger_snapshot_id"]), int(target_snapshot_id) if target_snapshot_id else None,
                    status, route_status, execution_status, self._json(entry_route),
                    self._json(target_route), self._json({
                        "entry": entry_safety["sources"], "target": target_safety["sources"]
                    }), int(safety_disagreement), entry_safety["observed_at"],
                    target_safety["observed_at"], target_observed_at, target_ingested_at,
                    target_recorded_at, target_delay, entry_price, target_price,
                    entry_liquidity, target_liquidity, raw_return, modeled_return,
                    post_event, post_context, iso(now),
                ),
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_shadow_results WHERE definition_version=? "
                "AND cohort_id=? AND horizon_minutes=?",
                (self.ONCHAIN_ONLY_SHADOW_VERSION, int(cohort["id"]), horizon),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def finalize_onchain_only_shadow_gaps(self, *, now: Any = None) -> dict[str, int]:
        current = parse_time(now or utcnow())
        registration = self.db.execute(
            "SELECT * FROM onchain_only_shadow_registrations WHERE definition_version=?",
            (self.ONCHAIN_ONLY_SHADOW_VERSION,),
        ).fetchone()
        if registration is None:
            return {"inserted": 0}
        definition = self._json_object(registration["definition_json"])
        inserted = 0
        cohorts = self.db.execute(
            "SELECT * FROM onchain_only_shadow_cohorts WHERE definition_version=? ORDER BY id",
            (self.ONCHAIN_ONLY_SHADOW_VERSION,),
        ).fetchall()
        for cohort in cohorts:
            trigger = parse_time(cohort["trigger_recorded_at"])
            for horizon in self.TOKEN_UNIVERSE_HORIZONS_MINUTES:
                if self.db.execute(
                    "SELECT 1 FROM onchain_only_shadow_results WHERE definition_version=? "
                    "AND cohort_id=? AND horizon_minutes=?",
                    (self.ONCHAIN_ONLY_SHADOW_VERSION, int(cohort["id"]), horizon),
                ).fetchone() is not None:
                    continue
                target = trigger + timedelta(minutes=horizon)
                deadline = target + timedelta(minutes=int(definition["target_grace_minutes"]))
                if str(cohort["baseline_status"]) != "valid":
                    status = "baseline_invalid"
                elif current <= deadline:
                    continue
                else:
                    role = f"onchain_shadow_{horizon}m"
                    attempt = self.db.execute(
                        "SELECT * FROM token_discovery_quote_attempts WHERE token_id=? AND role=? "
                        "ORDER BY id DESC LIMIT 1",
                        (str(cohort["token_id"]), role),
                    ).fetchone()
                    if attempt is None:
                        status = "deadline_missing"
                    elif str(attempt["status"]) == "no_pair":
                        status = "no_pair"
                    else:
                        status = "error"
                before = self.db.total_changes
                self.record_onchain_only_shadow_result(
                    {
                        "shadow_cohort_id": int(cohort["id"]),
                        "horizon_minutes": horizon,
                        "queue_due_at": iso(target),
                        "deadline_at": iso(deadline),
                    },
                    terminal_status=status,
                    quote_attempt_id=int(attempt["id"]) if str(cohort["baseline_status"]) == "valid" and attempt is not None else None,
                    recorded_at=current,
                )
                inserted += int(self.db.total_changes > before)
        return {"inserted": inserted}

    def register_onchain_only_jupiter_quote(
        self,
        *,
        usdc_mint: str = JUPITER_USDC_MINT,
        usdc_input_amount_raw: int | str = 35_000_000,
        slippage_bps: int = 400,
        max_queue_delay_seconds: float = 30,
        max_total_delay_seconds: float = 45,
    ) -> sqlite3.Row:
        """Freeze a trigger-anchored, quote-only Solana execution overlay."""
        amount = str(int(usdc_input_amount_raw))
        if int(amount) <= 0:
            raise ValueError("usdc_input_amount_raw must be positive")
        mint = str(usdc_mint).strip()[:128]
        if not mint:
            raise ValueError("usdc_mint is required")
        queue_limit = max(1.0, float(max_queue_delay_seconds))
        total_limit = max(queue_limit, float(max_total_delay_seconds))
        definition = {
            "version": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
            "source": self.ONCHAIN_ONLY_SHADOW_VERSION,
            "no_historical_backfill": True,
            "chain": "solana",
            "baseline_anchor": "onchain_trigger_recorded_at",
            "target_anchor": "onchain_shadow_frozen_target_at",
            "baseline_phase": "USDC_to_token_quote_only",
            "target_phase": "baseline_minimum_token_output_to_USDC_quote_only",
            "round_trip_semantics": "minimum_output_lower_bound_not_fill_or_profit",
            "api_contract": "swap_v2_order_without_taker",
            "forbidden_request_fields": ["taker", "payer", "receiver", "referralAccount"],
            "forbidden_response_fields": ["transaction", "requestId"],
            "usdc_mint": mint,
            "usdc_input_amount_raw": amount,
            "swap_mode": "ExactIn",
            "slippage_bps": max(1, min(5_000, int(slippage_bps))),
            "max_queue_delay_seconds": queue_limit,
            "max_total_delay_seconds": total_limit,
            "horizons_minutes": list(self.TOKEN_UNIVERSE_HORIZONS_MINUTES),
            "maturity_gate": {
                "minimum_valid_round_trips": 30,
                "minimum_independent_trigger_dates": 15,
                "minimum_positive_results": 5,
                "minimum_nonpositive_results": 5,
            },
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_jupiter_quote_registrations("
                "definition_version,registered_at,activation_shadow_cohort_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM onchain_only_shadow_cohorts),0),?)",
                (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION, iso(), self._json(definition)),
            )
            return self.db.execute(
                "SELECT * FROM onchain_only_jupiter_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
            ).fetchone()

    @staticmethod
    def _onchain_only_jupiter_quote_key(
        shadow_cohort_id: int,
        horizon_minutes: int,
        phase: str,
    ) -> str:
        return (
            f"onchain-jupiter:{int(shadow_cohort_id)}:"
            f"{int(horizon_minutes)}:{str(phase)}"
        )

    @staticmethod
    def onchain_only_jupiter_preflight_reason(
        task: Mapping[str, Any],
        *,
        evaluated_at: Any = None,
    ) -> str | None:
        explicit = str(task.get("preflight_reason") or "")
        if explicit:
            return explicit
        anchor = parse_time(task["anchor_at"])
        evaluated = parse_time(evaluated_at or utcnow())
        if evaluated < anchor:
            return "queue_delay_expired"
        if (evaluated - anchor).total_seconds() > float(task["max_queue_delay_seconds"]):
            return "queue_delay_expired"
        return None

    def due_onchain_only_jupiter_quotes(
        self,
        *,
        now: Any = None,
        limit: int = 10_000,
    ) -> list[dict[str, Any]]:
        """Return new trigger-anchored baseline/target quote legs, including ITT gaps."""
        current = parse_time(now or utcnow())
        with self._lock:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_jupiter_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
            ).fetchone()
            if registration is None:
                return []
            definition = self._json_object(registration["definition_json"])
            activation = int(registration["activation_shadow_cohort_id"])
            common = {
                "lane": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                "usdc_mint": str(definition["usdc_mint"]),
                "slippage_bps": int(definition["slippage_bps"]),
                "max_queue_delay_seconds": float(definition["max_queue_delay_seconds"]),
                "max_total_delay_seconds": float(definition["max_total_delay_seconds"]),
            }
            tasks: list[dict[str, Any]] = []
            rows = self.db.execute(
                """
                SELECT c.*,a.id AS attempt_id
                FROM onchain_only_shadow_cohorts c
                LEFT JOIN onchain_only_jupiter_quote_attempts a
                  ON a.definition_version=? AND a.shadow_cohort_id=c.id
                 AND a.phase='baseline_buy' AND a.horizon_minutes=0
                LEFT JOIN onchain_only_jupiter_quote_results q
                  ON q.definition_version=? AND q.shadow_cohort_id=c.id
                 AND q.phase='baseline_buy' AND q.horizon_minutes=0
                WHERE c.definition_version=? AND c.id>? AND lower(c.chain)='solana'
                  AND q.id IS NULL
                ORDER BY c.trigger_recorded_at,c.id
                """,
                (
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                    self.ONCHAIN_ONLY_SHADOW_VERSION,
                    activation,
                ),
            ).fetchall()
            for row in rows:
                token_id = str(row["token_id"])
                if ":" not in token_id:
                    continue
                tasks.append({
                    **common,
                    "quote_key": self._onchain_only_jupiter_quote_key(
                        int(row["id"]), 0, "baseline_buy"
                    ),
                    "shadow_cohort_id": int(row["id"]),
                    "attempt_id": int(row["attempt_id"]) if row["attempt_id"] else None,
                    "baseline_result_id": None,
                    "phase": "baseline_buy",
                    "horizon_minutes": 0,
                    "baseline_snapshot_id": int(row["trigger_snapshot_id"]),
                    "target_at": None,
                    "anchor_at": str(row["trigger_recorded_at"]),
                    "input_mint": str(definition["usdc_mint"]),
                    "output_mint": token_id.split(":", 1)[1],
                    "input_amount_raw": str(definition["usdc_input_amount_raw"]),
                    "preflight_reason": (
                        "request_evidence_missing" if row["attempt_id"] is not None
                        else "trigger_baseline_invalid"
                        if str(row["baseline_status"]) != "valid" else None
                    ),
                })
            cohorts = self.db.execute(
                """
                SELECT c.* FROM onchain_only_shadow_cohorts c
                WHERE c.definition_version=? AND c.id>? AND lower(c.chain)='solana'
                ORDER BY c.trigger_recorded_at,c.id
                """,
                (
                    self.ONCHAIN_ONLY_SHADOW_VERSION,
                    activation,
                ),
            ).fetchall()
            existing_targets = {
                (int(row["shadow_cohort_id"]), int(row["horizon_minutes"]))
                for row in self.db.execute(
                    "SELECT shadow_cohort_id,horizon_minutes "
                    "FROM onchain_only_jupiter_quote_results "
                    "WHERE definition_version=? AND phase='target_sell'",
                    (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
                )
            }
            target_attempts = {
                (int(row["shadow_cohort_id"]), int(row["horizon_minutes"])): int(row["id"])
                for row in self.db.execute(
                    "SELECT id,shadow_cohort_id,horizon_minutes "
                    "FROM onchain_only_jupiter_quote_attempts "
                    "WHERE definition_version=? AND phase='target_sell'",
                    (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
                )
            }
            baselines = {
                int(row["shadow_cohort_id"]): row
                for row in self.db.execute(
                    "SELECT * FROM onchain_only_jupiter_quote_results "
                    "WHERE definition_version=? AND phase='baseline_buy' AND horizon_minutes=0",
                    (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
                )
            }
            for row in cohorts:
                token_id = str(row["token_id"])
                if ":" not in token_id:
                    continue
                trigger = parse_time(row["trigger_recorded_at"])
                baseline = baselines.get(int(row["id"]))
                baseline_valid = bool(
                    baseline is not None
                    and baseline["validity_status"] == "valid"
                    and baseline["quote_terminal_status"] == "quoted"
                    and baseline["other_amount_threshold_raw"] is not None
                    and int(baseline["other_amount_threshold_raw"]) > 0
                )
                for horizon in self.TOKEN_UNIVERSE_HORIZONS_MINUTES:
                    target = trigger + timedelta(minutes=horizon)
                    key = (int(row["id"]), int(horizon))
                    if target > current or key in existing_targets:
                        continue
                    attempt_id = target_attempts.get(key)
                    tasks.append({
                        **common,
                        "quote_key": self._onchain_only_jupiter_quote_key(
                            int(row["id"]), horizon, "target_sell"
                        ),
                        "shadow_cohort_id": int(row["id"]),
                        "attempt_id": attempt_id,
                        "baseline_result_id": int(baseline["id"]) if baseline_valid else None,
                        "phase": "target_sell",
                        "horizon_minutes": horizon,
                        "baseline_snapshot_id": int(row["trigger_snapshot_id"]),
                        "target_at": iso(target),
                        "anchor_at": iso(target),
                        "input_mint": token_id.split(":", 1)[1],
                        "output_mint": str(definition["usdc_mint"]),
                        "input_amount_raw": (
                            str(baseline["other_amount_threshold_raw"])
                            if baseline_valid else "0"
                        ),
                        "preflight_reason": (
                            "request_evidence_missing" if attempt_id is not None
                            else "baseline_not_valid" if not baseline_valid else None
                        ),
                    })
            tasks.sort(key=lambda item: (
                parse_time(item["anchor_at"])
                + timedelta(seconds=float(item["max_queue_delay_seconds"])),
                0 if item["phase"] == "target_sell" else 1,
                int(item["shadow_cohort_id"]),
                int(item["horizon_minutes"]),
            ))
            return tasks[:max(1, int(limit))]

    def start_onchain_only_jupiter_quote_attempt(
        self,
        task: Mapping[str, Any],
        *,
        requested_at: Any = None,
    ) -> int | None:
        """Persist provider exposure before the quote-only request starts."""
        requested = parse_time(requested_at or utcnow())
        if self.onchain_only_jupiter_preflight_reason(task, evaluated_at=requested):
            return None
        values = {
            "definition_version": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
            "quote_key": str(task["quote_key"]),
            "shadow_cohort_id": int(task["shadow_cohort_id"]),
            "phase": str(task["phase"]),
            "horizon_minutes": int(task["horizon_minutes"]),
            "baseline_snapshot_id": int(task["baseline_snapshot_id"]),
            "baseline_result_id": task.get("baseline_result_id"),
            "target_at": task.get("target_at"),
            "anchor_at": str(task["anchor_at"]),
            "input_mint": str(task["input_mint"]),
            "output_mint": str(task["output_mint"]),
            "input_amount_raw": str(task["input_amount_raw"]),
            "requested_at": iso(requested),
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_jupiter_quote_attempts("
                + ",".join(values)
                + ",decision_eligible,affects) VALUES("
                + ",".join(f":{name}" for name in values)
                + ",0,'none')",
                values,
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_jupiter_quote_attempts WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def record_onchain_only_jupiter_quote(
        self,
        task: Mapping[str, Any],
        *,
        status: str,
        out_amount_raw: int | str | None = None,
        other_amount_threshold_raw: int | str | None = None,
        slippage_bps: int | None = None,
        signature_fee_lamports: int | None = None,
        prioritization_fee_lamports: int | None = None,
        rent_fee_lamports: int | None = None,
        router: str = "",
        mode: str = "",
        fee_bps: float | None = None,
        platform_fee_bps: float | None = None,
        price_impact_pct: float | None = None,
        price_impact_bps: float | None = None,
        price_impact_source: str = "",
        context_slot: int | None = None,
        time_taken_ms: float | None = None,
        route_plan: Iterable[Mapping[str, Any]] | None = None,
        error_type: str = "",
        attempt_id: int | None = None,
        requested_at: Any = None,
        completed_at: Any = None,
        evaluated_at: Any = None,
        apply_legacy_exploration: bool = True,
    ) -> int | None:
        statuses = {
            "not_requested", "quoted", "no_route", "error",
            "quote_only_protocol_invalid", "interrupted_after_request",
        }
        if status not in statuses:
            raise ValueError("invalid onchain-only Jupiter quote status")
        requested = parse_time(requested_at) if requested_at is not None else None
        completed = parse_time(completed_at) if completed_at is not None else None
        evaluated = parse_time(evaluated_at or completed_at or requested_at or utcnow())
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_jupiter_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,),
            ).fetchone()
            if (
                registration is None
                or int(task["shadow_cohort_id"])
                <= int(registration["activation_shadow_cohort_id"])
            ):
                return None
            existing = self.db.execute(
                "SELECT id FROM onchain_only_jupiter_quote_results WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            if existing is not None:
                return None
            attempt_id = attempt_id or task.get("attempt_id")
            attempt = None
            if attempt_id is not None:
                attempt = self.db.execute(
                    "SELECT * FROM onchain_only_jupiter_quote_attempts WHERE id=?",
                    (int(attempt_id),),
                ).fetchone()
                if attempt is None or str(attempt["quote_key"]) != str(task["quote_key"]):
                    raise ValueError("invalid onchain-only Jupiter attempt")
                requested = requested or parse_time(attempt["requested_at"])
            if status == "not_requested" and attempt is not None:
                raise ValueError("not_requested result cannot reference an attempt")
            if status != "not_requested" and attempt is None:
                raise ValueError("provider result requires a persisted attempt")
            anchor = parse_time(task["anchor_at"])
            preflight = self.onchain_only_jupiter_preflight_reason(
                task,
                evaluated_at=requested or evaluated,
            )
            validity_status = (
                "request_evidence_missing"
                if status == "interrupted_after_request" else preflight or "valid"
            )
            queue_at = requested or evaluated
            queue_delay = max(0.0, (queue_at - anchor).total_seconds())
            request_duration = (
                (completed - requested).total_seconds()
                if requested is not None and completed is not None else None
            )
            total_delay = (
                (completed - anchor).total_seconds() if completed is not None else None
            )
            if (
                status not in {"not_requested", "interrupted_after_request"}
                and (requested is None or completed is None)
            ):
                raise ValueError("requested and completed timestamps are required")
            if (
                validity_status == "valid"
                and (requested is None or completed is None or requested > completed)
            ):
                validity_status = "request_evidence_missing"
            if (
                validity_status == "valid"
                and (total_delay is None or total_delay > float(task["max_total_delay_seconds"]))
            ):
                validity_status = "total_delay_expired"
            output = None if out_amount_raw is None else str(int(out_amount_raw))
            threshold = (
                None if other_amount_threshold_raw is None
                else str(int(other_amount_threshold_raw))
            )
            if status == "quoted" and (
                output is None or int(output) <= 0 or threshold is None or int(threshold) <= 0
                or int(threshold) > int(output)
            ):
                raise ValueError("quoted Jupiter result requires a valid minimum output")
            if status != "quoted":
                output = threshold = None
            round_trip_min_return = None
            included = 0
            if (
                str(task["phase"]) == "target_sell"
                and status == "quoted"
                and validity_status == "valid"
            ):
                buy = self.db.execute(
                    """
                    SELECT id,input_amount_raw,other_amount_threshold_raw
                    FROM onchain_only_jupiter_quote_results
                    WHERE definition_version=? AND shadow_cohort_id=? AND id=?
                      AND phase='baseline_buy' AND horizon_minutes=0
                      AND validity_status='valid' AND quote_terminal_status='quoted'
                    """,
                    (
                        self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                        int(task["shadow_cohort_id"]),
                        int(task.get("baseline_result_id") or 0),
                    ),
                ).fetchone()
                if (
                    buy is None
                    or int(buy["input_amount_raw"]) <= 0
                    or str(buy["other_amount_threshold_raw"]) != str(task["input_amount_raw"])
                ):
                    validity_status = "baseline_not_valid"
                else:
                    round_trip_min_return = int(threshold) / int(buy["input_amount_raw"]) - 1.0
                    included = 1
            normalized_route: list[dict[str, Any]] = []
            for item in route_plan or ():
                if not isinstance(item, Mapping):
                    continue
                swap = item.get("swapInfo") if isinstance(item.get("swapInfo"), Mapping) else item
                text_value = lambda *keys: next((
                    str(swap[key]).strip()[:128] for key in keys
                    if swap.get(key) is not None and str(swap.get(key)).strip()
                ), "")
                percent = item.get("percent")
                normalized_route.append({
                    "amm_key": text_value("ammKey", "amm_key"),
                    "label": text_value("label"),
                    "input_mint": text_value("inputMint", "input_mint"),
                    "output_mint": text_value("outputMint", "output_mint"),
                    "in_amount_raw": text_value("inAmount", "in_amount_raw", "in_amount"),
                    "out_amount_raw": text_value("outAmount", "out_amount_raw", "out_amount"),
                    "fee_amount_raw": text_value("feeAmount", "fee_amount_raw", "fee_amount"),
                    "fee_mint": text_value("feeMint", "fee_mint"),
                    "percent": float(percent) if percent is not None else None,
                })
            clean = lambda value, limit: re.sub(
                r"[^a-zA-Z0-9_.-]+", "_", str(value or "")
            )[:limit]
            values = {
                "definition_version": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                "quote_key": str(task["quote_key"]),
                "shadow_cohort_id": int(task["shadow_cohort_id"]),
                "attempt_id": int(attempt_id) if attempt_id is not None else None,
                "baseline_result_id": (
                    int(task["baseline_result_id"])
                    if task.get("baseline_result_id") is not None else None
                ),
                "phase": str(task["phase"]),
                "horizon_minutes": int(task["horizon_minutes"]),
                "baseline_snapshot_id": int(task["baseline_snapshot_id"]),
                "target_at": task.get("target_at"),
                "anchor_at": iso(anchor),
                "input_mint": str(task["input_mint"]),
                "output_mint": str(task["output_mint"]),
                "input_amount_raw": str(task["input_amount_raw"]),
                "output_amount_raw": output,
                "other_amount_threshold_raw": threshold,
                "quote_terminal_status": status,
                "validity_status": validity_status,
                "requested_at": iso(requested) if requested is not None else None,
                "completed_at": iso(completed) if completed is not None else None,
                "queue_delay_seconds": queue_delay,
                "request_duration_seconds": request_duration,
                "total_delay_seconds": total_delay,
                "max_queue_delay_seconds": float(task["max_queue_delay_seconds"]),
                "max_total_delay_seconds": float(task["max_total_delay_seconds"]),
                "slippage_bps": int(slippage_bps) if slippage_bps is not None else None,
                "signature_fee_lamports": (
                    int(signature_fee_lamports) if signature_fee_lamports is not None else None
                ),
                "prioritization_fee_lamports": (
                    int(prioritization_fee_lamports)
                    if prioritization_fee_lamports is not None else None
                ),
                "rent_fee_lamports": int(rent_fee_lamports) if rent_fee_lamports is not None else None,
                "router": clean(router, 80),
                "mode": clean(mode, 40),
                "fee_bps": fee_bps,
                "platform_fee_bps": platform_fee_bps,
                "price_impact_pct": price_impact_pct,
                "price_impact_bps": price_impact_bps,
                "price_impact_source": clean(price_impact_source, 80),
                "context_slot": int(context_slot) if context_slot is not None else None,
                "time_taken_ms": time_taken_ms,
                "route_json": self._json(normalized_route),
                "error_type": clean(error_type, 80),
                "round_trip_min_return": round_trip_min_return,
                "included_in_round_trip": included,
                "recorded_at": iso(),
            }
            columns = list(values)
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_jupiter_quote_results("
                + ",".join(columns)
                + ",decision_eligible,affects) VALUES("
                + ",".join(f":{name}" for name in columns)
                + ",0,'none')",
                values,
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_jupiter_quote_results WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            result_id = int(row["id"]) if row is not None else None
            if result_id is not None and apply_legacy_exploration:
                self._apply_onchain_paper_exploration_quote_locked(result_id)
            return result_id

    def record_robinhood_stock_token_registry(
        self,
        result: Mapping[str, Any],
    ) -> int:
        """Append one official chain-4663 Stock Token registry snapshot."""
        source_url = str(result.get("source_url") or "")
        requested = parse_time(result["requested_at"])
        completed = parse_time(result["completed_at"])
        payload_hash = str(result.get("payload_sha256") or "").lower()
        entries = result.get("entries")
        if (
            source_url != "https://api.robinhood.com/rhj/assets"
            or requested > completed
            or re.fullmatch(r"[0-9a-f]{64}", payload_hash) is None
            or not isinstance(entries, list)
            or not entries
        ):
            raise ValueError("invalid Robinhood Stock Token registry snapshot")
        normalized: dict[str, dict[str, Any]] = {}
        for item in entries:
            if not isinstance(item, Mapping):
                raise ValueError("invalid Robinhood Stock Token registry entry")
            address = str(item.get("contract_address") or "").lower()
            if (
                re.fullmatch(r"0x[0-9a-f]{40}", address) is None
                or int(item.get("chain_id") or 0) != 4663
            ):
                raise ValueError("invalid Robinhood Stock Token deployment")
            normalized[address] = {
                "asset_id": str(item.get("asset_id") or "")[:80],
                "token_symbol": str(item.get("token_symbol") or "")[:40],
                "token_name": str(item.get("token_name") or "")[:200],
                "contract_address": address,
                "chain_id": 4663,
                "asset_status": str(item.get("asset_status") or "")[:60],
            }
        recorded_at = iso()
        with self._lock, self.db:
            cursor = self.db.execute(
                "INSERT INTO robinhood_stock_token_registry_runs("
                "source_url,requested_at,completed_at,payload_sha256,asset_count,"
                "deployment_count,recorded_at) VALUES(?,?,?,?,?,?,?)",
                (
                    source_url, iso(requested), iso(completed), payload_hash,
                    max(0, int(result.get("asset_count") or 0)), len(normalized),
                    recorded_at,
                ),
            )
            run_id = int(cursor.lastrowid)
            self.db.executemany(
                "INSERT INTO robinhood_stock_token_registry_entries("
                "run_id,asset_id,token_symbol,token_name,contract_address,chain_id,"
                "asset_status,recorded_at) VALUES(?,?,?,?,?,?,?,?)",
                [
                    (
                        run_id, item["asset_id"], item["token_symbol"],
                        item["token_name"], item["contract_address"], 4663,
                        item["asset_status"], recorded_at,
                    )
                    for item in normalized.values()
                ],
            )
        return run_id

    @classmethod
    def robinhood_stock_token_registry_summary_from_connection(
        cls,
        connection: sqlite3.Connection,
    ) -> dict[str, Any]:
        tables = {
            str(row["name"])
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }
        if not {
            "robinhood_stock_token_registry_runs",
            "robinhood_stock_token_registry_entries",
        }.issubset(tables):
            return {"status": "not_observed", "exclusion_ready": False, "entry_count": 0}
        run = connection.execute(
            "SELECT * FROM robinhood_stock_token_registry_runs "
            "ORDER BY completed_at DESC,id DESC LIMIT 1"
        ).fetchone()
        if run is None:
            return {"status": "not_observed", "exclusion_ready": False, "entry_count": 0}
        return {
            "status": "active",
            "exclusion_ready": True,
            "run_id": int(run["id"]),
            "source_url": str(run["source_url"]),
            "requested_at": str(run["requested_at"]),
            "completed_at": str(run["completed_at"]),
            "payload_sha256": str(run["payload_sha256"]),
            "asset_count": int(run["asset_count"]),
            "entry_count": int(run["deployment_count"]),
            "classification": "official_stock_token_rwa_excluded",
            "decision_eligible": False,
            "affects": "route_admission_only",
        }

    def register_onchain_only_evm_aggregator_price(
        self,
        networks: Mapping[str, Mapping[str, Any]],
        *,
        paper_stake_usd: float = 20,
        slippage_bps: int = 400,
        max_queue_delay_seconds: float = 30,
        max_total_delay_seconds: float = 45,
    ) -> sqlite3.Row:
        """Freeze a credential-backed, indicative 0x price observer at activation."""
        stake = Decimal(str(paper_stake_usd))
        if stake <= 0:
            raise ValueError("paper_stake_usd must be positive")
        clean: dict[str, dict[str, Any]] = {}
        amounts: dict[str, str] = {}
        for chain in ("bsc", "robinhood"):
            item = networks.get(chain)
            if not isinstance(item, Mapping):
                raise ValueError(f"missing 0x network definition: {chain}")
            token = str(item.get("accounting_token") or "").strip().lower()
            decimals = int(item.get("accounting_decimals") or 0)
            chain_id = int(item.get("chain_id") or 0)
            if not re.fullmatch(r"0x[0-9a-f]{40}", token) or not 0 <= decimals <= 36:
                raise ValueError(f"invalid 0x network definition: {chain}")
            clean[chain] = {
                "chain_id": chain_id,
                "accounting_token": token,
                "accounting_symbol": str(item.get("accounting_symbol") or "")[:20],
                "accounting_decimals": decimals,
                "native_symbol": str(item.get("native_symbol") or "")[:20],
            }
            amounts[chain] = str(int(stake * (10 ** decimals)))
        queue_limit = max(1.0, float(max_queue_delay_seconds))
        total_limit = max(queue_limit, float(max_total_delay_seconds))
        definition = {
            "version": self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,
            "source": self.ONCHAIN_ONLY_SHADOW_VERSION,
            "provider": "0x_swap_v2_price",
            "no_historical_backfill": True,
            "networks": clean,
            "paper_stake_usd": float(stake),
            "input_amount_raw_by_chain": amounts,
            "slippage_bps": max(1, min(5_000, int(slippage_bps))),
            "max_queue_delay_seconds": queue_limit,
            "max_total_delay_seconds": total_limit,
            "execution_scope": "amount_specific_aggregator_indicative_price",
            "firm_quote": False,
            "transaction_built": False,
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_evm_aggregator_price_registrations("
                "definition_version,registered_at,activation_shadow_cohort_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM onchain_only_shadow_cohorts),0),?)",
                (self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION, iso(), self._json(definition)),
            )
            return self.db.execute(
                "SELECT * FROM onchain_only_evm_aggregator_price_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,),
            ).fetchone()

    @staticmethod
    def _onchain_only_evm_aggregator_price_key(shadow_cohort_id: int) -> str:
        return f"onchain-evm-0x-price:{int(shadow_cohort_id)}"

    def due_onchain_only_evm_aggregator_prices(
        self, *, now: Any = None, limit: int = 12
    ) -> list[dict[str, Any]]:
        current = parse_time(now or utcnow())
        with self._lock:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_evm_aggregator_price_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,),
            ).fetchone()
            if registration is None:
                return []
            definition = self._json_object(registration["definition_json"])
            registry = self.db.execute(
                "SELECT id FROM robinhood_stock_token_registry_runs "
                "ORDER BY completed_at DESC,id DESC LIMIT 1"
            ).fetchone()
            rows = self.db.execute(
                """
                SELECT c.*,a.id AS attempt_id,a.requested_at AS attempt_requested_at
                FROM onchain_only_shadow_cohorts c
                LEFT JOIN onchain_only_evm_aggregator_price_attempts a
                  ON a.definition_version=? AND a.shadow_cohort_id=c.id
                LEFT JOIN onchain_only_evm_aggregator_price_results r
                  ON r.definition_version=? AND r.shadow_cohort_id=c.id
                WHERE c.definition_version=? AND c.id>? AND lower(c.chain) IN ('bsc','robinhood')
                  AND r.id IS NULL
                ORDER BY c.trigger_recorded_at,c.id
                """,
                (
                    self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,
                    self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,
                    self.ONCHAIN_ONLY_SHADOW_VERSION,
                    int(registration["activation_shadow_cohort_id"]),
                ),
            ).fetchall()
            tasks: list[dict[str, Any]] = []
            for row in rows:
                chain = str(row["chain"]).lower()
                token_id = str(row["token_id"])
                output = token_id.split(":", 1)[1].lower() if ":" in token_id else ""
                if not re.fullmatch(r"0x[0-9a-f]{40}", output):
                    continue
                if chain == "robinhood":
                    if registry is None:
                        continue
                    if self.db.execute(
                        "SELECT 1 FROM robinhood_stock_token_registry_entries "
                        "WHERE run_id=? AND contract_address=?",
                        (int(registry["id"]), output),
                    ).fetchone() is not None:
                        continue
                network = definition["networks"][chain]
                anchor = parse_time(row["trigger_recorded_at"])
                age = (current - anchor).total_seconds()
                preflight = (
                    "request_evidence_missing" if row["attempt_id"] is not None
                    else "trigger_baseline_invalid" if str(row["baseline_status"]) != "valid"
                    else "queue_delay_expired" if age > float(definition["max_queue_delay_seconds"])
                    else None
                )
                tasks.append({
                    "quote_key": self._onchain_only_evm_aggregator_price_key(int(row["id"])),
                    "shadow_cohort_id": int(row["id"]),
                    "attempt_id": int(row["attempt_id"]) if row["attempt_id"] else None,
                    "attempt_requested_at": str(row["attempt_requested_at"] or ""),
                    "token_id": token_id, "chain": chain, "anchor_at": iso(anchor),
                    "sell_token": str(network["accounting_token"]), "buy_token": output,
                    "sell_amount_raw": str(definition["input_amount_raw_by_chain"][chain]),
                    "slippage_bps": int(definition["slippage_bps"]),
                    "max_queue_delay_seconds": float(definition["max_queue_delay_seconds"]),
                    "max_total_delay_seconds": float(definition["max_total_delay_seconds"]),
                    "preflight_reason": preflight,
                })
            return tasks[:max(1, int(limit))]

    def start_onchain_only_evm_aggregator_price_attempt(
        self, task: Mapping[str, Any], *, requested_at: Any = None
    ) -> int | None:
        requested = parse_time(requested_at or utcnow())
        if task.get("preflight_reason"):
            return None
        values = {
            "definition_version": self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,
            "quote_key": str(task["quote_key"]), "shadow_cohort_id": int(task["shadow_cohort_id"]),
            "token_id": str(task["token_id"]), "chain": str(task["chain"]),
            "anchor_at": str(task["anchor_at"]), "sell_token": str(task["sell_token"]),
            "buy_token": str(task["buy_token"]), "sell_amount_raw": str(task["sell_amount_raw"]),
            "slippage_bps": int(task["slippage_bps"]), "requested_at": iso(requested),
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_evm_aggregator_price_attempts("
                + ",".join(values) + ",decision_eligible,affects) VALUES("
                + ",".join(f":{name}" for name in values) + ",0,'none')", values,
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_evm_aggregator_price_attempts WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            return int(row["id"]) if row else None

    def record_onchain_only_evm_aggregator_price(
        self,
        task: Mapping[str, Any],
        *,
        terminal_status: str,
        result: Mapping[str, Any] | None = None,
        attempt_id: int | None = None,
        requested_at: Any = None,
        completed_at: Any = None,
        error_type: str = "",
    ) -> int | None:
        allowed_statuses = {
            "not_requested", "priced", "no_route", "error", "protocol_invalid",
            "interrupted_after_request",
        }
        if terminal_status not in allowed_statuses:
            raise ValueError("invalid 0x terminal status")
        payload = dict(result or {})
        forbidden = {"transaction", "zid", "api_key", "raw_json", "request_id"}
        if forbidden.intersection(payload):
            raise ValueError("sensitive 0x fields are forbidden")
        requested = parse_time(requested_at or task.get("attempt_requested_at") or utcnow())
        completed = parse_time(completed_at or utcnow())
        anchor = parse_time(task["anchor_at"])
        queue_delay = max(0.0, (requested - anchor).total_seconds())
        duration = max(0.0, (completed - requested).total_seconds())
        if terminal_status == "interrupted_after_request":
            validity = "request_evidence_missing"
        elif task.get("preflight_reason"):
            validity = str(task["preflight_reason"])
        elif (completed - anchor).total_seconds() > float(task["max_total_delay_seconds"]):
            validity = "total_delay_expired"
        else:
            validity = "valid"
        if terminal_status == "not_requested":
            requested = completed
            duration = 0.0
        if terminal_status == "priced":
            required = {"minimum_buy_amount_raw", "gas", "gas_price_raw", "total_network_fee_native_raw"}
            if not required.issubset(payload) or payload.get("firm_quote") is not False:
                raise ValueError("priced 0x result is incomplete or not indicative")
        clean_error = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(error_type or ""))[:80]
        normalized = payload if terminal_status in {"priced", "no_route"} else {}
        with self._lock, self.db:
            if self.db.execute(
                "SELECT 1 FROM onchain_only_evm_aggregator_price_results WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone():
                return None
            if terminal_status == "not_requested":
                attempt_value = None
            else:
                attempt_value = int(attempt_id or task.get("attempt_id") or 0)
                if attempt_value <= 0:
                    raise ValueError("0x provider result requires persisted attempt")
            self.db.execute(
                "INSERT INTO onchain_only_evm_aggregator_price_results("
                "definition_version,quote_key,shadow_cohort_id,attempt_id,token_id,chain,anchor_at,"
                "terminal_status,validity_status,requested_at,completed_at,queue_delay_seconds,"
                "request_duration_seconds,normalized_result_json,error_type,recorded_at,decision_eligible,affects) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,'none')",
                (
                    self.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION, str(task["quote_key"]),
                    int(task["shadow_cohort_id"]), attempt_value, str(task["token_id"]),
                    str(task["chain"]), iso(anchor), terminal_status, validity, iso(requested),
                    iso(completed), queue_delay, duration, self._json(normalized), clean_error, iso(),
                ),
            )
            return int(self.db.execute("SELECT last_insert_rowid()").fetchone()[0])

    @classmethod
    def onchain_only_evm_aggregator_price_summary_from_connection(
        cls, connection: sqlite3.Connection
    ) -> dict[str, Any]:
        if connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='onchain_only_evm_aggregator_price_registrations'"
        ).fetchone() is None:
            return {"status": "not_registered", "configured": False, "attempts": 0, "results": 0}
        registration = connection.execute(
            "SELECT * FROM onchain_only_evm_aggregator_price_registrations "
            "WHERE definition_version=?",
            (cls.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,),
        ).fetchone()
        if registration is None:
            return {"status": "not_registered", "configured": False, "attempts": 0, "results": 0}
        rows = connection.execute(
            "SELECT terminal_status,validity_status,COUNT(*) count "
            "FROM onchain_only_evm_aggregator_price_results WHERE definition_version=? "
            "GROUP BY terminal_status,validity_status",
            (cls.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,),
        ).fetchall()
        counts = {str(row["terminal_status"]): int(row["count"]) for row in rows}
        attempts = int(connection.execute(
            "SELECT COUNT(*) FROM onchain_only_evm_aggregator_price_attempts WHERE definition_version=?",
            (cls.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,),
        ).fetchone()[0])
        return {
            "status": "active", "configured": True,
            "version": cls.ONCHAIN_ONLY_EVM_AGGREGATOR_PRICE_VERSION,
            "registered_at": str(registration["registered_at"]),
            "definition": cls._json_object(registration["definition_json"]),
            "attempts": attempts, "results": sum(counts.values()),
            "terminal_counts": counts, "pending": max(0, attempts - sum(counts.values())),
            "decision_eligible": False, "affects": "none",
        }

    def register_onchain_only_evm_route_quote(
        self,
        networks: Mapping[str, Mapping[str, Any]],
        *,
        paper_stake_usd: float = 35,
        slippage_bps: int = 400,
        max_queue_delay_seconds: float = 30,
        max_total_delay_seconds: float = 45,
    ) -> sqlite3.Row:
        """Freeze a no-key, fixed-block EVM Quoter research overlay."""
        stake = Decimal(str(paper_stake_usd))
        if stake <= 0:
            raise ValueError("paper_stake_usd must be positive")
        clean_networks: dict[str, dict[str, Any]] = {}
        amounts: dict[str, str] = {}
        address_pattern = re.compile(r"0x[0-9a-fA-F]{40}")
        for chain in sorted(self.EVM_ROUTE_RESEARCH_CHAINS):
            item = networks.get(chain)
            if not isinstance(item, Mapping):
                raise ValueError(f"missing EVM route network definition: {chain}")
            normalized = {
                "chain_id": int(item["chain_id"]),
                "rpc_url": str(item["rpc_url"]).strip(),
                "factory": str(item["factory"]).strip().lower(),
                "quoter": str(item["quoter"]).strip().lower(),
                "accounting_token": str(item["accounting_token"]).strip().lower(),
                "accounting_symbol": str(item["accounting_symbol"]).strip()[:20],
                "accounting_decimals": int(item["accounting_decimals"]),
                "wrapped_native": str(item["wrapped_native"]).strip().lower(),
                "native_symbol": str(item["native_symbol"]).strip()[:20],
                "fee_tiers": sorted({int(value) for value in item.get("fee_tiers", ())}),
            }
            if (
                normalized["chain_id"] <= 0
                or not normalized["rpc_url"].startswith("https://")
                or normalized["accounting_decimals"] < 0
                or normalized["accounting_decimals"] > 36
                or not normalized["fee_tiers"]
                or any(
                    address_pattern.fullmatch(normalized[name]) is None
                    for name in ("factory", "quoter", "accounting_token", "wrapped_native")
                )
            ):
                raise ValueError(f"invalid EVM route network definition: {chain}")
            clean_networks[chain] = normalized
            amounts[chain] = str(int(stake * (10 ** normalized["accounting_decimals"])))
        queue_limit = max(1.0, float(max_queue_delay_seconds))
        total_limit = max(queue_limit, float(max_total_delay_seconds))
        definition = {
            "version": self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
            "source": self.ONCHAIN_ONLY_SHADOW_VERSION,
            "provider": "uniswap_v3_quoter_v2",
            "no_historical_backfill": True,
            "networks": clean_networks,
            "paper_stake_usd": float(stake),
            "input_amount_raw_by_chain": amounts,
            "slippage_bps": max(1, min(5_000, int(slippage_bps))),
            "max_queue_delay_seconds": queue_limit,
            "max_total_delay_seconds": total_limit,
            "execution_scope": "pool_math_quote_only",
            "venue_fee_semantics": "uniswap_v3_fee_tier_embedded_in_amount_out",
            "fee_completeness": "quote_only_no_full_transaction_network_fee",
            "economic_status": "cost_unknown",
            "transfer_semantics_checked": False,
            "router_transaction_simulated": False,
            "decision_eligible": False,
            "affects": "none",
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_evm_route_quote_registrations("
                "definition_version,registered_at,activation_shadow_cohort_id,definition_json) "
                "VALUES(?,?,COALESCE((SELECT MAX(id) FROM onchain_only_shadow_cohorts),0),?)",
                (
                    self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
                    iso(),
                    self._json(definition),
                ),
            )
            return self.db.execute(
                "SELECT * FROM onchain_only_evm_route_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,),
            ).fetchone()

    @staticmethod
    def _onchain_only_evm_route_quote_key(shadow_cohort_id: int) -> str:
        return f"onchain-evm-route:{int(shadow_cohort_id)}"

    @staticmethod
    def onchain_only_evm_route_preflight_reason(
        task: Mapping[str, Any],
        *,
        evaluated_at: Any = None,
    ) -> str | None:
        explicit = str(task.get("preflight_reason") or "")
        if explicit:
            return explicit
        anchor = parse_time(task["anchor_at"])
        evaluated = parse_time(evaluated_at or utcnow())
        if evaluated < anchor:
            return "queue_delay_expired"
        if (evaluated - anchor).total_seconds() > float(task["max_queue_delay_seconds"]):
            return "queue_delay_expired"
        return None

    def due_onchain_only_evm_route_quotes(
        self,
        *,
        now: Any = None,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        current = parse_time(now or utcnow())
        with self._lock:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_evm_route_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,),
            ).fetchone()
            if registration is None:
                return []
            definition = self._json_object(registration["definition_json"])
            robinhood_registry = self.db.execute(
                "SELECT id FROM robinhood_stock_token_registry_runs "
                "ORDER BY completed_at DESC,id DESC LIMIT 1"
            ).fetchone()
            rows = self.db.execute(
                """
                SELECT c.*,a.id AS attempt_id
                FROM onchain_only_shadow_cohorts c
                LEFT JOIN onchain_only_evm_route_quote_attempts a
                  ON a.definition_version=? AND a.shadow_cohort_id=c.id
                LEFT JOIN onchain_only_evm_route_quote_results r
                  ON r.definition_version=? AND r.shadow_cohort_id=c.id
                WHERE c.definition_version=? AND c.id>?
                  AND lower(c.chain) IN ('bsc','base','robinhood')
                  AND r.id IS NULL
                ORDER BY c.trigger_recorded_at,c.id
                """,
                (
                    self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
                    self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
                    self.ONCHAIN_ONLY_SHADOW_VERSION,
                    int(registration["activation_shadow_cohort_id"]),
                ),
            ).fetchall()
            tasks: list[dict[str, Any]] = []
            for row in rows:
                chain = str(row["chain"]).lower()
                token_id = str(row["token_id"])
                if chain not in self.EVM_ROUTE_RESEARCH_CHAINS or ":" not in token_id:
                    continue
                network = definition["networks"][chain]
                output_token = token_id.split(":", 1)[1].lower()
                if chain == "robinhood":
                    if robinhood_registry is None:
                        continue
                    if self.db.execute(
                        "SELECT 1 FROM robinhood_stock_token_registry_entries "
                        "WHERE run_id=? AND contract_address=?",
                        (int(robinhood_registry["id"]), output_token),
                    ).fetchone() is not None:
                        continue
                tasks.append({
                    "lane": self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
                    "quote_key": self._onchain_only_evm_route_quote_key(int(row["id"])),
                    "shadow_cohort_id": int(row["id"]),
                    "attempt_id": int(row["attempt_id"]) if row["attempt_id"] else None,
                    "baseline_snapshot_id": int(row["trigger_snapshot_id"]),
                    "token_id": token_id,
                    "chain": chain,
                    "anchor_at": str(row["trigger_recorded_at"]),
                    "input_token": str(network["accounting_token"]),
                    "output_token": output_token,
                    "accounting_symbol": str(network["accounting_symbol"]),
                    "accounting_decimals": int(network["accounting_decimals"]),
                    "input_amount_raw": str(definition["input_amount_raw_by_chain"][chain]),
                    "slippage_bps": int(definition["slippage_bps"]),
                    "max_queue_delay_seconds": float(definition["max_queue_delay_seconds"]),
                    "max_total_delay_seconds": float(definition["max_total_delay_seconds"]),
                    "preflight_reason": (
                        "request_evidence_missing" if row["attempt_id"] is not None
                        else "trigger_baseline_invalid"
                        if str(row["baseline_status"]) != "valid" else None
                    ),
                })
            tasks.sort(key=lambda item: (
                parse_time(item["anchor_at"])
                + timedelta(seconds=float(item["max_queue_delay_seconds"])),
                int(item["shadow_cohort_id"]),
            ))
            return tasks[:max(1, int(limit))]

    def start_onchain_only_evm_route_quote_attempt(
        self,
        task: Mapping[str, Any],
        *,
        requested_at: Any = None,
    ) -> int | None:
        requested = parse_time(requested_at or utcnow())
        if self.onchain_only_evm_route_preflight_reason(task, evaluated_at=requested):
            return None
        values = {
            "definition_version": self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
            "quote_key": str(task["quote_key"]),
            "shadow_cohort_id": int(task["shadow_cohort_id"]),
            "baseline_snapshot_id": int(task["baseline_snapshot_id"]),
            "token_id": str(task["token_id"]),
            "chain": str(task["chain"]).lower(),
            "anchor_at": str(task["anchor_at"]),
            "input_token": str(task["input_token"]).lower(),
            "output_token": str(task["output_token"]).lower(),
            "input_amount_raw": str(task["input_amount_raw"]),
            "slippage_bps": int(task["slippage_bps"]),
            "requested_at": iso(requested),
        }
        with self._lock, self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_evm_route_quote_attempts("
                + ",".join(values)
                + ",decision_eligible,affects) VALUES("
                + ",".join(f":{name}" for name in values)
                + ",0,'none')",
                values,
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_evm_route_quote_attempts WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def record_onchain_only_evm_route_quote(
        self,
        task: Mapping[str, Any],
        *,
        status: str,
        result: Mapping[str, Any] | None = None,
        error_type: str = "",
        attempt_id: int | None = None,
        requested_at: Any = None,
        completed_at: Any = None,
        evaluated_at: Any = None,
    ) -> int | None:
        statuses = {
            "not_requested", "quoted", "no_official_pool",
            "buy_quote_unavailable", "sell_quote_unavailable", "error",
            "quote_only_protocol_invalid", "interrupted_after_request",
        }
        if status not in statuses:
            raise ValueError("invalid onchain-only EVM route quote status")
        payload = dict(result or {})
        requested = parse_time(requested_at) if requested_at is not None else None
        completed = parse_time(completed_at) if completed_at is not None else None
        evaluated = parse_time(evaluated_at or completed_at or requested_at or utcnow())
        with self._lock, self.db:
            registration = self.db.execute(
                "SELECT * FROM onchain_only_evm_route_quote_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,),
            ).fetchone()
            if (
                registration is None
                or int(task["shadow_cohort_id"])
                <= int(registration["activation_shadow_cohort_id"])
            ):
                return None
            definition = self._json_object(registration["definition_json"])
            chain = str(task["chain"]).lower()
            network = (definition.get("networks") or {}).get(chain) or {}
            if (
                chain not in self.EVM_ROUTE_RESEARCH_CHAINS
                or str(task["input_amount_raw"])
                != str((definition.get("input_amount_raw_by_chain") or {}).get(chain))
                or str(task["input_token"]).lower()
                != str(network.get("accounting_token") or "").lower()
                or int(task["slippage_bps"]) != int(definition.get("slippage_bps") or 0)
            ):
                raise ValueError("EVM route task does not match frozen registration")
            if self.db.execute(
                "SELECT 1 FROM onchain_only_evm_route_quote_results WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone() is not None:
                return None
            attempt_id = attempt_id or task.get("attempt_id")
            attempt = None
            if attempt_id is not None:
                attempt = self.db.execute(
                    "SELECT * FROM onchain_only_evm_route_quote_attempts WHERE id=?",
                    (int(attempt_id),),
                ).fetchone()
                if attempt is None or str(attempt["quote_key"]) != str(task["quote_key"]):
                    raise ValueError("invalid onchain-only EVM route attempt")
                requested = requested or parse_time(attempt["requested_at"])
            if status == "not_requested" and attempt is not None:
                raise ValueError("not_requested result cannot reference an attempt")
            if status != "not_requested" and attempt is None:
                raise ValueError("provider result requires a persisted attempt")
            if status not in {"not_requested", "interrupted_after_request"} and (
                requested is None or completed is None
            ):
                raise ValueError("requested and completed timestamps are required")
            anchor = parse_time(task["anchor_at"])
            preflight = self.onchain_only_evm_route_preflight_reason(
                task, evaluated_at=requested or evaluated
            )
            validity = (
                "request_evidence_missing"
                if status == "interrupted_after_request" else preflight or "valid"
            )
            queue_at = requested or evaluated
            queue_delay = max(0.0, (queue_at - anchor).total_seconds())
            request_duration = (
                (completed - requested).total_seconds()
                if requested is not None and completed is not None else None
            )
            total_delay = (
                (completed - anchor).total_seconds() if completed is not None else None
            )
            if validity == "valid" and (
                requested is None or completed is None or requested > completed
            ):
                validity = "request_evidence_missing"
            if validity == "valid" and (
                total_delay is None
                or total_delay > float(task["max_total_delay_seconds"])
            ):
                validity = "total_delay_expired"
            integer_field = lambda name: (
                str(int(payload[name])) if payload.get(name) is not None else None
            )
            buy_output = integer_field("buy_output_raw")
            buy_minimum = integer_field("buy_minimum_output_raw")
            sell_output = integer_field("sell_output_raw")
            sell_minimum = integer_field("sell_minimum_output_raw")
            ratio = payload.get("immediate_round_trip_stable_ratio")
            if status == "quoted" and (
                buy_output is None or int(buy_output) <= 0
                or buy_minimum is None or not 0 < int(buy_minimum) <= int(buy_output)
                or sell_output is None or int(sell_output) <= 0
                or sell_minimum is None or not 0 < int(sell_minimum) <= int(sell_output)
                or ratio is None or float(ratio) <= 0
            ):
                raise ValueError("quoted EVM route result requires valid bidirectional output")
            if status == "quoted" and (
                int(payload.get("chain_id") or 0) != int(network.get("chain_id") or -1)
                or completed is None
                or payload.get("block_timestamp") is None
                or parse_time(payload["block_timestamp"]) > completed
            ):
                raise ValueError("quoted EVM route result has invalid fixed-block provenance")
            if status != "quoted":
                buy_output = buy_minimum = sell_output = sell_minimum = None
                ratio = None
            clean_error = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(error_type or ""))[:80]
            values = {
                "definition_version": self.ONCHAIN_ONLY_EVM_ROUTE_QUOTE_VERSION,
                "quote_key": str(task["quote_key"]),
                "shadow_cohort_id": int(task["shadow_cohort_id"]),
                "attempt_id": int(attempt_id) if attempt_id is not None else None,
                "baseline_snapshot_id": int(task["baseline_snapshot_id"]),
                "token_id": str(task["token_id"]),
                "chain": str(task["chain"]).lower(),
                "anchor_at": iso(anchor),
                "provider": "uniswap_v3_quoter_v2",
                "chain_id": int(payload["chain_id"]) if payload.get("chain_id") is not None else None,
                "block_number": int(payload["block_number"]) if payload.get("block_number") is not None else None,
                "block_hash": str(payload.get("block_hash") or "")[:80] or None,
                "block_timestamp": str(payload.get("block_timestamp") or "")[:80] or None,
                "input_token": str(task["input_token"]).lower(),
                "output_token": str(task["output_token"]).lower(),
                "accounting_symbol": str(task["accounting_symbol"])[:20],
                "accounting_decimals": int(task["accounting_decimals"]),
                "input_amount_raw": str(task["input_amount_raw"]),
                "slippage_bps": int(task["slippage_bps"]),
                "buy_output_raw": buy_output,
                "buy_minimum_output_raw": buy_minimum,
                "sell_output_raw": sell_output,
                "sell_minimum_output_raw": sell_minimum,
                "buy_path_json": self._json(payload.get("buy_path") or []),
                "sell_path_json": self._json(payload.get("sell_path") or []),
                "buy_quoter_gas_estimate": int(payload["buy_quoter_gas_estimate"]) if payload.get("buy_quoter_gas_estimate") is not None else None,
                "sell_quoter_gas_estimate": int(payload["sell_quoter_gas_estimate"]) if payload.get("sell_quoter_gas_estimate") is not None else None,
                "quote_terminal_status": status,
                "validity_status": validity,
                "requested_at": iso(requested) if requested is not None else None,
                "completed_at": iso(completed) if completed is not None else None,
                "queue_delay_seconds": queue_delay,
                "request_duration_seconds": request_duration,
                "total_delay_seconds": total_delay,
                "max_queue_delay_seconds": float(task["max_queue_delay_seconds"]),
                "max_total_delay_seconds": float(task["max_total_delay_seconds"]),
                "immediate_round_trip_stable_ratio": float(ratio) if ratio is not None else None,
                "venue_fee_semantics": "uniswap_v3_fee_tier_embedded_in_amount_out",
                "fee_completeness": "quote_only_no_full_transaction_network_fee",
                "economic_status": "cost_unknown",
                "execution_scope": "pool_math_quote_only",
                "transfer_semantics_checked": 0,
                "router_transaction_simulated": 0,
                "error_type": clean_error,
                "recorded_at": iso(),
            }
            columns = list(values)
            self.db.execute(
                "INSERT OR IGNORE INTO onchain_only_evm_route_quote_results("
                + ",".join(columns)
                + ",decision_eligible,affects) VALUES("
                + ",".join(f":{name}" for name in columns)
                + ",0,'none')",
                values,
            )
            row = self.db.execute(
                "SELECT id FROM onchain_only_evm_route_quote_results WHERE quote_key=?",
                (str(task["quote_key"]),),
            ).fetchone()
            return int(row["id"]) if row is not None else None

    def register_onchain_paper_exploration(
        self,
        *,
        starting_cash_usd: float,
        max_open_positions: int = 0,
        estimated_network_fee_usd_each_side: float = 0.01,
    ) -> sqlite3.Row:
        """Enable a separate, forward-only Paper ledger backed by Jupiter quotes."""
        definition = {
            "version": self.ONCHAIN_PAPER_EXPLORATION_VERSION,
            "source": self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
            "no_historical_backfill": True,
            "entry": "new_valid_baseline_minimum_output_after_registration",
            "exit": "first_valid_15_60_240m_minimum_output_or_240m_writeoff",
            "max_open_positions": max(0, int(max_open_positions)),
            "estimated_network_fee_usd_each_side": max(
                0.0, float(estimated_network_fee_usd_each_side)
            ),
            "fee_model": "flat_usdc_per_economic_fill",
            "fixed_execution_fee_usd_each_side": max(
                0.0, float(estimated_network_fee_usd_each_side)
            ),
            "maximum_adverse_price_impact_bps": -1_000.0,
            "minimum_positive_net_exit_usd": 0.0,
            "route_fees_and_slippage": "included_in_jupiter_minimum_output",
            "economic_execution": (
                "entry_requires_normalized_price_impact_within_frozen_limit; "
                "exit requires minimum USDC output above network cost"
            ),
            "simulated": True,
            "live_execution": False,
            "affects_main_strategy": False,
        }
        starting_cash = max(0.01, float(starting_cash_usd))
        self._onchain_paper_max_open_positions = max(0, int(max_open_positions))
        with self._lock, self.db:
            self.db.execute(
                """
                INSERT OR IGNORE INTO onchain_paper_exploration_registrations(
                    definition_version,registered_at,activation_quote_result_id,definition_json
                ) VALUES(?,?,COALESCE((
                    SELECT MAX(id) FROM onchain_only_jupiter_quote_results
                ),0),?)
                """,
                (self.ONCHAIN_PAPER_EXPLORATION_VERSION, iso(), self._json(definition)),
            )
            self.db.execute(
                """
                INSERT OR IGNORE INTO onchain_paper_exploration_account(
                    definition_version,starting_cash_usd,cash_usd,realized_pnl_usd,updated_at
                ) VALUES(?,?,?,?,?)
                """,
                (
                    self.ONCHAIN_PAPER_EXPLORATION_VERSION,
                    starting_cash,
                    starting_cash,
                    0.0,
                    iso(),
                ),
            )
            return self.db.execute(
                "SELECT * FROM onchain_paper_exploration_registrations "
                "WHERE definition_version=?",
                (self.ONCHAIN_PAPER_EXPLORATION_VERSION,),
            ).fetchone()

    def _record_onchain_paper_execution_assessment_locked(
        self,
        *,
        result_id: int,
        cohort_id: int,
        phase: str,
        horizon_minutes: int,
        quote_status: str,
        economic_status: str,
        paper_effect: str,
        reason: str,
        gross_usd: float | None = None,
        network_fee_usd: float | None = None,
        net_cash_flow_usd: float | None = None,
    ) -> None:
        self.db.execute(
            """
            INSERT OR IGNORE INTO onchain_paper_exploration_execution_assessments(
                definition_version,quote_result_id,shadow_cohort_id,phase,horizon_minutes,
                quote_status,economic_status,paper_effect,gross_usd,network_fee_usd,
                net_cash_flow_usd,reason,recorded_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                self.ONCHAIN_PAPER_EXPLORATION_VERSION, int(result_id), int(cohort_id),
                str(phase), int(horizon_minutes), str(quote_status), str(economic_status),
                str(paper_effect), gross_usd, network_fee_usd, net_cash_flow_usd,
                str(reason)[:240], iso(),
            ),
        )

    def _apply_onchain_paper_exploration_quote_locked(self, result_id: int) -> None:
        version = self.ONCHAIN_PAPER_EXPLORATION_VERSION
        registration = self.db.execute(
            "SELECT * FROM onchain_paper_exploration_registrations "
            "WHERE definition_version=?",
            (version,),
        ).fetchone()
        if registration is None or int(result_id) <= int(registration["activation_quote_result_id"]):
            return
        result = self.db.execute(
            """
            SELECT q.*,c.token_id
            FROM onchain_only_jupiter_quote_results q
            JOIN onchain_only_shadow_cohorts c ON c.id=q.shadow_cohort_id
            WHERE q.id=? AND q.definition_version=?
            """,
            (int(result_id), self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION),
        ).fetchone()
        if result is None:
            return
        definition = self._json_object(registration["definition_json"])
        network_fee = float(definition["estimated_network_fee_usd_each_side"])
        cohort_id = int(result["shadow_cohort_id"])
        token_id = str(result["token_id"])
        phase = str(result["phase"])
        valid_quote = (
            str(result["validity_status"]) == "valid"
            and str(result["quote_terminal_status"]) == "quoted"
            and result["other_amount_threshold_raw"] is not None
            and int(result["other_amount_threshold_raw"]) > 0
        )
        position = self.db.execute(
            "SELECT * FROM onchain_paper_exploration_positions "
            "WHERE definition_version=? AND shadow_cohort_id=?",
            (version, cohort_id),
        ).fetchone()
        if phase == "baseline_buy":
            if position is not None:
                return
            focus = self.db.execute(
                "SELECT * FROM strategy_focus_registrations WHERE definition_version=?",
                (self.STRATEGY_FOCUS_VERSION,),
            ).fetchone()
            if focus is not None and int(result_id) > int(focus["activation_quote_result_id"]):
                surface = self.db.execute(
                    "SELECT status,facts_json FROM market_surface_safety_observations "
                    "WHERE definition_version=? AND lane=? AND quote_key=?",
                    (
                        self.MARKET_SURFACE_SAFETY_VERSION,
                        self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                        str(result["quote_key"]),
                    ),
                ).fetchone()
                route_rows = self.db.execute(
                    "SELECT direction,status,classification_json FROM execution_route_observations "
                    "WHERE definition_version=? AND lane=? AND quote_key=?",
                    (
                        self.EXECUTION_ROUTE_OBSERVATION_VERSION,
                        self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                        str(result["quote_key"]),
                    ),
                ).fetchall()
                routes = {str(row["direction"]): str(row["status"]) for row in route_rows}
                route_facts = {
                    str(row["direction"]): self._json_object(row["classification_json"])
                    for row in route_rows
                }
                focus_reasons = []
                if surface is None or str(surface["status"]) != "PASS":
                    focus_reasons.append(
                        "surface_missing" if surface is None
                        else "surface_" + str(surface["status"]).lower()
                    )
                if surface is not None:
                    surface_facts = self._json_object(surface["facts_json"])
                    pool_facts = surface_facts.get("solana_pool_rpc") if isinstance(
                        surface_facts.get("solana_pool_rpc"), Mapping
                    ) else {}
                    pool_address = str(
                        pool_facts.get("pool_address") or surface_facts.get("pool_address") or ""
                    )
                    if pool_address and self.db.execute(
                        "SELECT 1 FROM onchain_dead_market_surfaces WHERE chain='solana' "
                        "AND mint=? AND pool_address=? AND policy_version=? LIMIT 1",
                        (token_id.split(":", 1)[1], pool_address,
                         self.ONCHAIN_PAPER_EXIT_CHALLENGER_VERSION),
                    ).fetchone() is not None:
                        focus_reasons.append("confirmed_dead_surface_no_reentry")
                for direction in ("BUY", "SELL"):
                    if routes.get(direction) != "PASS":
                        focus_reasons.append(
                            f"{direction.lower()}_route_" + routes.get(direction, "missing").lower()
                        )
                migration = self.db.execute(
                    "SELECT * FROM token_launch_facts WHERE token_id=? "
                    "AND launch_event_type='migration' AND create_signature<>'' "
                    "AND ingested_at<=? ORDER BY source_observed_at DESC,id DESC LIMIT 1",
                    (token_id, str(result["anchor_at"])),
                ).fetchone()
                pool_age_seconds = None
                if migration is not None:
                    pool_age_seconds = (
                        parse_time(result["anchor_at"]) - parse_time(migration["source_observed_at"])
                    ).total_seconds()
                sell_facts = route_facts.get("SELL") or {}
                quoted_ratio = sell_facts.get("quoted_net_recovery_ratio")
                stress_ratio = sell_facts.get("stress_min_recovery_ratio")
                focus_open = int(self.db.execute(
                    "SELECT COUNT(*) FROM onchain_paper_exploration_positions "
                    "WHERE definition_version=? AND status='open' AND baseline_quote_result_id>?",
                    (version, int(focus["activation_quote_result_id"])),
                ).fetchone()[0])
                daily_exposure = float(self.db.execute(
                    "SELECT COALESCE(SUM(gross_usd),0) FROM onchain_paper_exploration_trades "
                    "WHERE definition_version=? AND side='BUY' AND id>? "
                    "AND substr(created_at,1,10)=substr(?,1,10)",
                    (version, int(focus["activation_s2_buy_trade_id"]), str(result["completed_at"])),
                ).fetchone()[0])
                pending_alert = self.db.execute(
                    "SELECT 1 FROM onchain_paper_exit_challenger_positions p "
                    "JOIN onchain_paper_exit_challenger_marks m ON m.id=p.pending_mark_id "
                    "WHERE p.definition_version=? AND p.status='open' "
                    "AND m.action IN ('LIQUIDITY_EXIT','HARD_STOP','TRAILING','TAKE_PROFIT','TERMINAL') "
                    "LIMIT 1",
                    (self.ONCHAIN_PAPER_EXIT_CHALLENGER_VERSION,),
                ).fetchone()
                focus_reasons.extend(self.onchain_primary_scalar_gate_reasons(
                    pool_age_seconds=pool_age_seconds,
                    queue_delay_seconds=(
                        float(result["queue_delay_seconds"])
                        if result["queue_delay_seconds"] is not None else None
                    ),
                    total_delay_seconds=(
                        float(result["total_delay_seconds"])
                        if result["total_delay_seconds"] is not None else None
                    ),
                    quoted_recovery_ratio=(
                        float(quoted_ratio) if quoted_ratio is not None else None
                    ),
                    stress_recovery_ratio=(
                        float(stress_ratio) if stress_ratio is not None else None
                    ),
                    open_positions=focus_open, daily_exposure_usd=daily_exposure,
                    new_exposure_usd=int(result["input_amount_raw"]) / 1_000_000.0,
                    exit_alert_pending=pending_alert is not None,
                ))
                if focus_reasons:
                    self._record_onchain_paper_execution_assessment_locked(
                        result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                        quote_status=str(result["quote_terminal_status"]),
                        economic_status="not_applicable", paper_effect="entry_rejected",
                        reason="strategy_focus_gate:" + ",".join(focus_reasons),
                    )
                    return
            rug_registration = self.db.execute(
                "SELECT * FROM pretrade_rug_safety_registrations WHERE definition_version=?",
                (self.PRETRADE_RUG_SAFETY_VERSION,),
            ).fetchone()
            rug = self.db.execute(
                "SELECT * FROM pretrade_rug_safety_assessments "
                "WHERE definition_version=? AND lane=? AND quote_key=?",
                (
                    self.PRETRADE_RUG_SAFETY_VERSION,
                    self.ONCHAIN_ONLY_JUPITER_QUOTE_VERSION,
                    str(result["quote_key"]),
                ),
            ).fetchone()
            rug_gate_active = bool(
                rug_registration is not None
                and int(result_id) > int(rug_registration["activation_quote_result_id"])
            )
            rug_fresh = bool(
                rug is not None
                and parse_time(rug["assessed_at"]) >= parse_time(result["completed_at"])
                and (
                    parse_time(rug["assessed_at"]) - parse_time(result["anchor_at"])
                ).total_seconds() <= float(result["max_total_delay_seconds"])
            )
            if rug_gate_active and (
                rug is None or str(rug["status"]) != "PASS" or not rug_fresh
            ):
                reason = "pretrade_rug_safety_missing"
                if rug is not None:
                    reasons = self._json_list(rug["reasons_json"])
                    reason = (
                        "pretrade_rug_safety_stale"
                        if not rug_fresh else
                        "pretrade_rug_safety_" + str(rug["status"]).lower()
                    )
                    if reasons:
                        reason += ":" + ",".join(str(value) for value in reasons[:4])
                self._record_onchain_paper_execution_assessment_locked(
                    result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                    quote_status=str(result["quote_terminal_status"]),
                    economic_status="not_applicable", paper_effect="entry_rejected",
                    reason=reason,
                )
                return
            impact = result["price_impact_bps"]
            max_adverse = float(definition["maximum_adverse_price_impact_bps"])
            if not valid_quote:
                self._record_onchain_paper_execution_assessment_locked(
                    result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                    quote_status=str(result["quote_terminal_status"]),
                    economic_status="not_applicable", paper_effect="entry_rejected",
                    reason="entry_quote_not_structurally_valid",
                )
                return
            if impact is None:
                self._record_onchain_paper_execution_assessment_locked(
                    result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                    quote_status="quoted", economic_status="cost_unknown",
                    paper_effect="entry_rejected", reason="normalized_price_impact_missing",
                )
                return
            if float(impact) < max_adverse:
                self._record_onchain_paper_execution_assessment_locked(
                    result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                    quote_status="quoted", economic_status="quoted_but_uneconomic",
                    paper_effect="entry_rejected", reason="price_impact_below_frozen_limit",
                )
                return
            open_count = int(self.db.execute(
                "SELECT COUNT(*) FROM onchain_paper_exploration_positions "
                "WHERE definition_version=? AND status='open'", (version,),
            ).fetchone()[0])
            max_open_positions = int(getattr(
                self, "_onchain_paper_max_open_positions",
                definition.get("max_open_positions", 0),
            ))
            stake = int(result["input_amount_raw"]) / 1_000_000.0
            debit = stake + network_fee
            account = self.db.execute(
                "SELECT * FROM onchain_paper_exploration_account WHERE definition_version=?",
                (version,),
            ).fetchone()
            if max_open_positions > 0 and open_count >= max_open_positions:
                reject_reason = "maximum_open_positions_reached"
            elif account is None or float(account["cash_usd"]) + 1e-9 < debit:
                reject_reason = "insufficient_paper_cash"
            else:
                reject_reason = ""
            if reject_reason:
                self._record_onchain_paper_execution_assessment_locked(
                    result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                    quote_status="quoted", economic_status="economic",
                    paper_effect="entry_rejected", reason=reject_reason,
                    gross_usd=stake, network_fee_usd=network_fee,
                    net_cash_flow_usd=-debit,
                )
                return
            opened_at = str(result["recorded_at"])
            self.db.execute(
                "UPDATE onchain_paper_exploration_account "
                "SET cash_usd=cash_usd-?,updated_at=? WHERE definition_version=?",
                (debit, opened_at, version),
            )
            self.db.execute(
                """
                INSERT INTO onchain_paper_exploration_positions(
                    definition_version,shadow_cohort_id,token_id,baseline_quote_result_id,
                    stake_usd,acquired_amount_raw,entry_network_fee_usd,opened_at,status
                ) VALUES(?,?,?,?,?,?,?,?, 'open')
                """,
                (
                    version, cohort_id, token_id, int(result["id"]), stake,
                    str(result["other_amount_threshold_raw"]), network_fee, opened_at,
                ),
            )
            self.db.execute(
                """
                INSERT OR IGNORE INTO onchain_paper_exploration_trades(
                    definition_version,shadow_cohort_id,token_id,quote_result_id,side,
                    horizon_minutes,gross_usd,network_fee_usd,net_cash_flow_usd,
                    realized_pnl_usd,reason,created_at
                ) VALUES(?,?,?,?, 'BUY',0,?,?,?,NULL,?,?)
                """,
                (
                    version, cohort_id, token_id, int(result["id"]), stake,
                    network_fee, -debit, "jupiter_minimum_output_entry", opened_at,
                ),
            )
            self._record_onchain_paper_execution_assessment_locked(
                result_id=result_id, cohort_id=cohort_id, phase="entry", horizon_minutes=0,
                quote_status="quoted", economic_status="economic",
                paper_effect="entry_admitted", reason="normalized_price_impact_within_limit",
                gross_usd=stake, network_fee_usd=network_fee, net_cash_flow_usd=-debit,
            )
            return
        if phase != "target_sell" or position is None or str(position["status"]) != "open":
            return
        if (
            result["baseline_result_id"] is None
            or int(result["baseline_result_id"]) != int(position["baseline_quote_result_id"])
        ):
            return
        horizon = int(result["horizon_minutes"])
        gross = (
            int(result["other_amount_threshold_raw"]) / 1_000_000.0
            if valid_quote else None
        )
        credit = gross - network_fee if gross is not None else None
        economic = bool(
            valid_quote and credit is not None
            and credit > float(definition["minimum_positive_net_exit_usd"])
        )
        if economic:
            economic_status = "economic"
            effect = "simulated_fill"
            reason = f"first_economic_jupiter_exit_{horizon}m"
        elif valid_quote:
            economic_status = "quoted_but_uneconomic"
            effect = "exit_deferred"
            reason = "minimum_output_not_above_network_cost"
        else:
            economic_status = "not_applicable"
            effect = "exit_deferred"
            reason = "exit_quote_not_structurally_valid"
        if not economic and horizon < max(self.TOKEN_UNIVERSE_HORIZONS_MINUTES):
            self._record_onchain_paper_execution_assessment_locked(
                result_id=result_id, cohort_id=cohort_id, phase="exit",
                horizon_minutes=horizon, quote_status=str(result["quote_terminal_status"]),
                economic_status=economic_status, paper_effect=effect, reason=reason,
                gross_usd=gross, network_fee_usd=network_fee if valid_quote else None,
                net_cash_flow_usd=credit,
            )
            return
        closed_at = str(result["recorded_at"])
        if economic:
            final_credit = float(credit)
            final_gross = float(gross)
            final_fee = network_fee
            status = "closed"
            final_effect = "simulated_fill"
        else:
            final_credit = final_gross = final_fee = 0.0
            status = "written_off"
            final_effect = "terminal_writeoff"
            reason = "no_economic_jupiter_exit_by_240m_writeoff"
        cost = float(position["stake_usd"]) + float(position["entry_network_fee_usd"])
        pnl = final_credit - cost
        self.db.execute(
            "UPDATE onchain_paper_exploration_account "
            "SET cash_usd=cash_usd+?,realized_pnl_usd=realized_pnl_usd+?,updated_at=? "
            "WHERE definition_version=?", (final_credit, pnl, closed_at, version),
        )
        self.db.execute(
            """
            UPDATE onchain_paper_exploration_positions
            SET status=?,exit_quote_result_id=?,exit_horizon_minutes=?,exit_usdc=?,
                realized_pnl_usd=?,closed_at=?,close_reason=?
            WHERE definition_version=? AND shadow_cohort_id=? AND status='open'
            """,
            (
                status, int(result["id"]), horizon, final_credit, pnl, closed_at, reason,
                version, cohort_id,
            ),
        )
        self.db.execute(
            """
            INSERT OR IGNORE INTO onchain_paper_exploration_trades(
                definition_version,shadow_cohort_id,token_id,quote_result_id,side,
                horizon_minutes,gross_usd,network_fee_usd,net_cash_flow_usd,
                realized_pnl_usd,reason,created_at
            ) VALUES(?,?,?,?, 'SELL',?,?,?,?,?,?,?)
            """,
            (
                version, cohort_id, token_id, int(result["id"]), horizon, final_gross,
                final_fee, final_credit, pnl, reason, closed_at,
            ),
        )
        self._record_onchain_paper_execution_assessment_locked(
            result_id=result_id, cohort_id=cohort_id, phase="exit",
            horizon_minutes=horizon, quote_status=str(result["quote_terminal_status"]),
            economic_status=("economic" if economic else economic_status),
            paper_effect=final_effect, reason=reason, gross_usd=gross,
            network_fee_usd=network_fee if valid_quote else None,
            net_cash_flow_usd=credit,
        )

    @classmethod
    def onchain_paper_exploration_summary_from_connection(
        cls,
        connection: sqlite3.Connection,
        *,
        trade_limit: int = 100,
        max_liquidity_impact_pct: float = 0.0025,
    ) -> dict[str, Any]:
        version = cls.ONCHAIN_PAPER_EXPLORATION_VERSION
        tables = {str(row[0]) for row in connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        )}
        required = {
            "onchain_paper_exploration_registrations",
            "onchain_paper_exploration_account",
            "onchain_paper_exploration_positions",
            "onchain_paper_exploration_trades",
        }
        if not required.issubset(tables):
            return {"status": "not_enabled", "simulated": True, "live": False,
                    "account": None, "positions": [], "trades": []}
        registration = connection.execute(
            "SELECT * FROM onchain_paper_exploration_registrations "
            "WHERE definition_version=?", (version,),
        ).fetchone()
        account = connection.execute(
            "SELECT * FROM onchain_paper_exploration_account WHERE definition_version=?",
            (version,),
        ).fetchone()
        if registration is None or account is None:
            return {"status": "not_enabled", "simulated": True, "live": False,
                    "account": None, "positions": [], "trades": []}
        positions = [dict(row) for row in connection.execute(
            "SELECT * FROM onchain_paper_exploration_positions "
            "WHERE definition_version=? ORDER BY opened_at DESC", (version,),
        )]
        valuation_at = utcnow()
        liquidity_impact = max(0.0, float(max_liquidity_impact_pct))
        for position in positions:
            position.update({
                "entry_signal_price_usd": None,
                "current_price_usd": None,
                "mark_as_of": None,
                "market_value_usd": None,
                "unrealized_pnl_usd": None,
                "unrealized_pnl_pct": None,
                "indicative_market_value_usd": None,
                "indicative_unrealized_pnl_usd": None,
                "indicative_unrealized_pnl_pct": None,
                "mark_liquidity_capped": False,
                "valuation_basis": None,
                "valuation_status": "unpriced_no_amount_specific_sell_quote",
            })
            if position["status"] != "open":
                continue
            entry_snapshot = connection.execute(
                """
                SELECT s.*
                FROM onchain_only_jupiter_quote_results q
                JOIN token_snapshots s ON s.id=q.baseline_snapshot_id
                WHERE q.id=? AND q.phase='baseline_buy'
                """,
                (int(position["baseline_quote_result_id"]),),
            ).fetchone()
            current_snapshot = connection.execute(
                """
                SELECT * FROM token_snapshots
                WHERE token_id=? AND observed_at<=?
                ORDER BY observed_at DESC,id DESC LIMIT 1
                """,
                (str(position["token_id"]), iso(valuation_at)),
            ).fetchone()
            if entry_snapshot is None or current_snapshot is None:
                continue
            observed = parse_time(current_snapshot["observed_at"])
            ingested = parse_time(current_snapshot["ingested_at"] or current_snapshot["observed_at"])
            recorded = parse_time(
                current_snapshot["recorded_at"]
                or current_snapshot["ingested_at"]
                or current_snapshot["observed_at"]
            )
            entry_price = float(entry_snapshot["price_usd"] or 0.0)
            current_price = float(current_snapshot["price_usd"] or 0.0)
            if not (observed <= ingested <= recorded <= valuation_at) or entry_price <= 0 or current_price <= 0:
                continue
            headline_value = float(position["stake_usd"]) * current_price / entry_price
            liquidity = current_snapshot["liquidity_usd"]
            capacity = (
                max(0.0, float(liquidity)) * liquidity_impact
                if liquidity is not None else None
            )
            remaining_cost = float(position["stake_usd"]) + float(position["entry_network_fee_usd"])
            indicative_value = (
                min(headline_value, capacity)
                if capacity is not None and capacity > 0 else None
            )
            indicative_unrealized = (
                indicative_value - remaining_cost if indicative_value is not None else None
            )
            position.update({
                "entry_signal_price_usd": entry_price,
                "current_price_usd": current_price,
                "mark_as_of": str(current_snapshot["observed_at"]),
                "indicative_market_value_usd": indicative_value,
                "indicative_unrealized_pnl_usd": indicative_unrealized,
                "indicative_unrealized_pnl_pct": (
                    indicative_unrealized / remaining_cost
                    if indicative_unrealized is not None and remaining_cost else None
                ),
                "mark_liquidity_capped": (
                    indicative_value is not None and indicative_value < headline_value
                ),
                "valuation_basis": "non_executable_dex_price_capped_by_liquidity_capacity",
                "valuation_status": (
                    "indicative_only_non_executable"
                    if indicative_value is not None else "unpriced_zero_or_unknown_liquidity"
                ),
            })
        trades = [dict(row) for row in connection.execute(
            "SELECT * FROM onchain_paper_exploration_trades "
            "WHERE definition_version=? ORDER BY id DESC LIMIT ?",
            (version, max(1, int(trade_limit))),
        )]
        all_trades = [dict(row) for row in connection.execute(
            "SELECT * FROM onchain_paper_exploration_trades "
            "WHERE definition_version=? ORDER BY id ASC",
            (version,),
        )]
        assessments = []
        if "onchain_paper_exploration_execution_assessments" in tables:
            assessments = [dict(row) for row in connection.execute(
                "SELECT * FROM onchain_paper_exploration_execution_assessments "
                "WHERE definition_version=? ORDER BY id DESC LIMIT ?",
                (version, max(1, int(trade_limit))),
            )]
        assessment_counts: dict[str, int] = {}
        if "onchain_paper_exploration_execution_assessments" in tables:
            for row in connection.execute(
                "SELECT economic_status,paper_effect,COUNT(*) AS count "
                "FROM onchain_paper_exploration_execution_assessments "
                "WHERE definition_version=? GROUP BY economic_status,paper_effect",
                (version,),
            ):
                assessment_counts[
                    f"{row['economic_status']}:{row['paper_effect']}"
                ] = int(row["count"])
        open_cost = sum(
            float(row["stake_usd"]) + float(row["entry_network_fee_usd"])
            for row in positions if row["status"] == "open"
        )
        starting_cash = float(account["starting_cash_usd"])
        running_cash = starting_cash
        running_realized_pnl = 0.0
        cash_peak = starting_cash
        max_cash_drawdown = 0.0
        cash_curve = [{
            "recorded_at": registration["registered_at"],
            "cash_usd": starting_cash,
            "realized_pnl_usd": 0.0,
            "side": "START",
        }]
        for trade in all_trades:
            running_cash += float(trade["net_cash_flow_usd"])
            if trade["realized_pnl_usd"] is not None:
                running_realized_pnl += float(trade["realized_pnl_usd"])
            cash_peak = max(cash_peak, running_cash)
            max_cash_drawdown = max(max_cash_drawdown, cash_peak - running_cash)
            cash_curve.append({
                "recorded_at": trade["created_at"],
                "cash_usd": running_cash,
                "realized_pnl_usd": running_realized_pnl,
                "side": trade["side"],
            })
        closed_pnls = sorted(
            float(row["realized_pnl_usd"])
            for row in positions
            if row["status"] != "open" and row["realized_pnl_usd"] is not None
        )
        closed_count = len(closed_pnls)
        midpoint = closed_count // 2
        median_closed_pnl = (
            None if not closed_pnls else closed_pnls[midpoint]
            if closed_count % 2 else (closed_pnls[midpoint - 1] + closed_pnls[midpoint]) / 2
        )
        winning_count = sum(1 for value in closed_pnls if value > 0)
        losing_count = sum(1 for value in closed_pnls if value < 0)
        open_count = sum(1 for row in positions if row["status"] == "open")
        open_positions = [row for row in positions if row["status"] == "open"]
        indicative_positions = [
            row for row in open_positions if row["indicative_market_value_usd"] is not None
        ]
        indicative_value = sum(
            float(row["indicative_market_value_usd"]) for row in indicative_positions
        )
        indicative_unrealized = sum(
            float(row["indicative_unrealized_pnl_usd"]) for row in indicative_positions
        )
        fully_marked = not open_positions
        current_cash = float(account["cash_usd"])
        realized_pnl = float(account["realized_pnl_usd"])
        account_payload = dict(account)
        account_payload.update({
            "reserved_open_cost_usd": open_cost,
            "equity_lower_bound_usd": current_cash,
            "marked_value_usd": 0.0 if fully_marked else None,
            "known_marked_value_usd": 0.0,
            "equity_usd": current_cash if fully_marked else None,
            "unrealized_pnl_usd": 0.0 if fully_marked else None,
            "known_unrealized_pnl_usd": 0.0,
            "total_pnl_usd": realized_pnl if fully_marked else None,
            "indicative_marked_value_usd": indicative_value,
            "indicative_unrealized_pnl_usd": indicative_unrealized,
            "indicative_position_count": len(indicative_positions),
            "equity_is_fully_marked": fully_marked,
            "valuation_status": (
                "cash_only_no_open_positions" if fully_marked
                else "incomplete_no_amount_specific_sell_marks"
            ),
            "priced_position_count": 0,
            "unpriced_position_count": len(open_positions),
            "mark_as_of": min(
                (str(row["mark_as_of"]) for row in indicative_positions), default=None
            ),
            "valuation_basis": "amount_specific_sell_quote_required_for_account_pnl",
            "pnl_is_executable": fully_marked,
            "open_position_count": open_count,
            "closed_position_count": closed_count,
            "trade_count": len(all_trades),
            "buy_count": sum(1 for row in all_trades if row["side"] == "BUY"),
            "sell_count": sum(1 for row in all_trades if row["side"] == "SELL"),
            "winning_position_count": winning_count,
            "losing_position_count": losing_count,
            "break_even_position_count": closed_count - winning_count - losing_count,
            "win_rate": winning_count / closed_count if closed_count else None,
            "average_closed_pnl_usd": (
                sum(closed_pnls) / closed_count if closed_count else None
            ),
            "median_closed_pnl_usd": median_closed_pnl,
            "max_cash_drawdown_usd": max_cash_drawdown,
            "max_cash_drawdown_pct": (
                max_cash_drawdown / starting_cash if starting_cash > 0 else None
            ),
            "total_network_fee_usd": sum(
                float(row["network_fee_usd"]) for row in all_trades
            ),
            "cash_curve": cash_curve,
        })
        return {
            "status": "running", "simulated": True, "live": False,
            "definition": cls._json_object(registration["definition_json"]),
            "registered_at": registration["registered_at"],
            "activation_quote_result_id": int(registration["activation_quote_result_id"]),
            "account": account_payload, "positions": positions, "trades": trades,
            "execution_assessments": assessments,
            "execution_assessment_counts": assessment_counts,
        }

